export default {"1":{"html":"<p>تصور کریں کہ آپ کسی فروخت میں جاتے ہیں اور کچھ تلاش کرتے ہیں جو آپ چاہتے ہیں، لیکن آپ خریدنے کے لئے بالکل تیار نہیں ہیں۔ لہذا آپ بیچنے والے سے ایک چھوٹا سا احسان پوچھیں۔ آپ قیمت کو مقفل کرنے کے لیے آج تھوڑی سی رقم حوالے کرتے ہیں، اور آپ اس چھوٹی ادائیگی کے علاوہ کچھ بھی نہیں دیتے۔ اگر آپ واپس آکر خریدتے ہیں تو قیمت پہلے سے طے شدہ ہے۔ اگر آپ اپنا ارادہ بدلتے ہیں، تو آپ بس چلے جاتے ہیں اور آپ صرف اس چھوٹی سی ادائیگی سے محروم ہوجاتے ہیں جو آپ نے حوالے کی تھی۔ وہ چھوٹا، یکطرفہ معاہدہ ایک آپشن کے پیچھے پورا خیال ہے۔ ایک بار جب آپ اسے روزمرہ کے لحاظ سے دیکھتے ہیں، تو کالز، پوٹس اور پریمیم کا لفظ خوفناک ہونا بند کر دیتا ہے اور سمجھ میں آنے لگتا ہے۔</p>\n<h2 id=\"an-option-is-a-right-not-a-duty\">اختیار ایک حق ہے، فرض نہیں۔</h2>\n<p>ایک <strong>اختیار</strong> ایک معاہدہ ہے جو آپ کو دیتا ہے۔ <strong>صحیح</strong>، لیکن نہیں <strong>ذمہ داری</strong>کسی چیز کو خریدنے یا بیچنے کے لیے اس قیمت پر جو آپ آج طے کرتے ہیں، مستقبل کی میعاد ختم ہونے کی تاریخ پر طے شدہ آپ بھی آج ہی طے کرتے ہیں۔ اس جملے کو دو بار پڑھیں، کیونکہ دو چھوٹے الفاظ \"ذمہ داری نہیں\" پورے معنی رکھتے ہیں۔ آپ کو ایک انتخاب ہے. آپ کو کبھی عمل کرنے پر مجبور نہیں کیا جاتا۔</p>\n<p>زیادہ تر معاہدوں کے ساتھ اس کا موازنہ کریں جو آپ جانتے ہیں۔ اگر آپ فلیٹ خریدنے کے لیے دستخط کرتے ہیں، تو آپ کو خریداری مکمل کرنا ہوگی یا اپنی جمع شدہ رقم کھونا ہوگی اور پریشانی کا سامنا کرنا ہوگا۔ ایک آپشن اس کو پلٹتا ہے۔ آپ سامنے ایک چھوٹی سی رقم ادا کرتے ہیں اور بدلے میں، آپ کو بعد میں فیصلہ کرنا پڑتا ہے کہ آیا یہ معاہدہ کرنے کے قابل ہے یا نہیں۔ اگر ایسا ہے تو آپ عمل کریں۔ اگر ایسا نہیں ہے تو، آپ معاہدہ ختم ہونے دیتے ہیں اور صرف وہی رقم جو آپ نے خرچ کی ہے وہ چھوٹی پیشگی ادائیگی ہے۔</p>\n<p>اس چھوٹی سی ادائیگی کا ایک نام ہے۔ یہ ہے <strong>پریمیم</strong>، حق کے انعقاد کی قیمت. پریمیم وہ ہے جو آپشن کی قیمت ہے، اور خریدار کے لیے یہ سب سے زیادہ ہے جسے آپ کبھی کھو سکتے ہیں۔ ہم بار بار اس خیال پر واپس جائیں گے، کیونکہ یہ واحد سب سے اہم سکون ہے جو اختیارات خریدار کو دیتے ہیں۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>اختیار ایک حق ہے، فرض نہیں۔ آپ قیمت کو مقفل کرنے کے لیے آج ہی ایک چھوٹا سا پریمیم ادا کرتے ہیں، اور آپ بعد میں جانے کے لیے آزاد ہیں۔ پریمیم سب سے زیادہ ہے جو خریدار کھو سکتا ہے۔</p>\n</div></div>\n<h2 id=\"the-token-money-story\">ٹوکن منی کی کہانی</h2>\n<p>اسے محسوس کرنے کا صاف ترین طریقہ یہ ہے۔ فرض کریں کہ آپ کو پچاس لاکھ روپے کا فلیٹ ملتا ہے۔ آپ کو یہ پسند ہے، لیکن آپ کو رقم کا بندوبست کرنے اور یقینی بنانے کے لیے تین ماہ درکار ہیں۔ آپ بلڈر سے سودا مانگتے ہیں۔ آپ آج ایک لاکھ روپے بطور ٹوکن ادا کریں۔ بدلے میں، بلڈر اگلے تین مہینوں میں کسی بھی وقت آپ کو وہی فلیٹ پچاس لاکھ روپے میں فروخت کرنے پر راضی ہوتا ہے، چاہے جائیداد کی قیمتوں میں کچھ بھی ہو۔</p>\n<p>اب دونوں سروں کو چلائیں۔</p>\n<ul>\n<li>قیمتوں میں اضافہ۔ تین ماہ بعد وہی فلیٹ ساٹھ لاکھ کا ہے۔ آپ اپنی مقفل قیمت استعمال کرتے ہیں، پچاس لاکھ ادا کرتے ہیں، اور ساٹھ مالیت کے فلیٹ کے مالک ہیں۔ آپ کے ایک لاکھ ٹوکن نے آپ کو دس لاکھ کا ہیڈ اسٹارٹ خریدا۔</li>\n<li>قیمتیں گر جاتی ہیں، یا آپ محض اپنا خیال بدل لیتے ہیں۔ فلیٹ کی قیمت اب پینتالیس لاکھ ہے، یا آپ کا پلان بدل گیا ہے۔ تم چلے جاؤ۔ آپ اپنا ایک لاکھ ٹوکن کھو دیتے ہیں اور اس سے زیادہ کچھ نہیں۔ آپ کو خریدنے کے لیے کبھی مجبور نہیں کیا گیا۔</li>\n</ul>\n<p>وہ ٹوکن پریمیم ہے۔ جس کی قیمت پچاس لاکھ روپے ہے۔ <strong>ہڑتال</strong>، وہ قیمت جس پر معاہدہ آپ کو لین دین کرنے دیتا ہے۔ تین ماہ کی ونڈو ہے۔ <strong>میعاد ختم</strong>، آخری تاریخ جس کے بعد حق غائب ہو جاتا ہے۔ اور فلیٹ خود ہی ہے۔ <strong>بنیادی</strong>، اصل چیز جس پر آپشن لکھا ہوا ہے۔</p>\n<p>ہر آپشن جس سے آپ کبھی ملیں گے اس کے ساتھ یہی تین نمبر منسلک ہوتے ہیں: ایک پریمیم جو آپ ادا کرتے ہیں، ایک اسٹرائیک جسے آپ لاک کرتے ہیں، اور ایک ختم ہونے کی مدت جس کے بارے میں آپ کو فیصلہ کرنا ہوگا۔ ان تینوں کو تلاش کرنا سیکھیں اور آپ کسی بھی آپشن کو پڑھ سکتے ہیں۔</p>\n\n<div class=\"callout example\"><span class=\"callout-tag\">حقیقی مثال</span><div><p>RELIANCE 25 جون 2026 کو 1,318 روپے پر بند ہوا۔ فرض کریں کہ آپ 28 جولائی 2026 کو ختم ہونے پر 1320 کی اسٹرائیک پر RELIANCE خریدنے کا حق خریدتے ہیں۔ اس حق کی فی حصص فی حصص تقریباً 31 روپے کی لاگت ہے۔ انڈرلائننگ RELIANCE ہے، ہڑتال 1320 ہے، اور میعاد 28 جولائی 2026 ہے۔</p>\n</div></div>\n<h2 id=\"why-would-anyone-pay-for-a-right\">کیوں کوئی حق ادا کرے گا؟</h2>\n<p>ایک منصفانہ سوال۔ کسی ایسے انتخاب کے لیے پیسے کیوں حوالے کریں جو آپ کبھی استعمال نہیں کر سکتے؟ دو وجوہات، اور وہ تقریباً ہر اس شخص کا احاطہ کرتے ہیں جو اختیارات کی تجارت کرتا ہے۔</p>\n<p>پہلی وجہ یہ ہے۔ <strong>ایک نقطہ نظر پر فائدہ اٹھانا</strong>. اگر آپ کو یقین ہے کہ اگلے مہینے میں RELIANCE بڑھ جائے گا، تو آپ براہ راست شیئرز خرید سکتے ہیں، جو کہ ایک بڑی رقم کو جوڑ دیتے ہیں۔ یا آپ 1320 پر خریدنے کے حق کے لیے ایک چھوٹا پریمیم ادا کر سکتے ہیں، اور اگر آپ صحیح ہیں تو زیادہ سے زیادہ فائدہ اٹھا سکتے ہیں، جبکہ اگر آپ غلط ہیں تو صرف اسی پریمیم کو خطرے میں ڈال سکتے ہیں۔ بڑے، غیر یقینی انعام کے بدلے ایک چھوٹا، مقررہ، معلوم خطرہ بہت سے تاجروں کے لیے ایک پرکشش شکل ہے۔</p>\n<p>دوسری وجہ یہ ہے۔ <strong>تحفظ</strong>، جسے اکثر انشورنس کہا جاتا ہے۔ اگر آپ کے پاس پہلے سے ہی RELIANCE حصص ہیں اور آپ گرنے سے پریشان ہیں، تو آپ ایک مقررہ قیمت پر فروخت کے حق کے لیے پریمیم ادا کر سکتے ہیں۔ اگر سٹاک کریش ہو جاتا ہے، تو زیادہ بند قیمت پر فروخت کرنے کا آپ کا حق دھچکے کو نرم کر دیتا ہے۔ آپ نے ذہنی سکون کے لیے ایک چھوٹا پریمیم ادا کیا، بالکل اسی طرح جس طرح آپ کسی بیمہ کے لیے ادائیگی کرتے ہیں۔</p>\n<p>لہذا پریمیم پیسہ ضائع نہیں ہوتا ہے۔ یہ آپ کو یا تو کسی منظر کی پشت پناہی کرنے کا ایک سستا طریقہ خریدتا ہے، یا نقصان کے خلاف کشن خریدتا ہے۔ آیا یہ اس کے قابل ہے اس کا انحصار اس بات پر ہے کہ بنیادی ختم ہونے سے پہلے کیا کرتا ہے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>محدود خطرے کے آرام کا مطلب یہ نہیں ہے کہ اختیارات آسان رقم ہیں۔ زیادہ تر آپشن خریدار کھو دیتے ہیں، کیونکہ بنیادی کو کافی منتقل ہونا چاہیے، اور وقت کے ساتھ، اس سے پہلے کہ حق ادا کیے گئے پریمیم سے زیادہ ہو۔ ہم پورے کورس میں اس کے بارے میں ایماندار رہیں گے۔</p>\n</div></div>\n<h2 id=\"options-against-futures-in-one-line\">مستقبل کے خلاف اختیارات، ایک لائن میں</h2>\n<p>آپ نے سنا ہوگا۔ <strong>مستقبل</strong>. فرق آسان ہے اور جلد درست کرنے کے قابل ہے۔ مستقبل ایک معاہدہ ہے جو دونوں فریقوں کو ایک مقررہ تاریخ پر مقررہ قیمت پر لین دین کرنے کا پابند کرتا ہے۔ کوئی چارہ نہیں ہے۔ اگر قیمت آپ کے خلاف چلتی ہے، تو آپ اب بھی معاہدے کے پابند ہیں اور آپ کا نقصان زیادہ ہو سکتا ہے۔</p>\n<p>ایک آپشن ایک طرف کو انتخاب دیتا ہے۔ مستقبل کی ذمہ داری ہے، ایک آپشن آپ کو منتخب کرنے دیتا ہے۔ یہ واحد فرق یہی ہے کہ فیوچر خریدار اس سے کہیں زیادہ کھو سکتا ہے جتنا کہ وہ ڈالتا ہے، جبکہ ایک آپشن خریدار صرف پریمیم کھو سکتا ہے۔ انتخاب بالکل وہی ہے جس کی آپ ادائیگی کر رہے ہیں۔</p>\n<p>دوسرے طریقے سے، مستقبل ایک مضبوط مصافحہ ہے کہ دونوں فریقوں کو جو کچھ بھی ہو اس کا احترام کرنا چاہیے۔ ایک آپشن ڈیل پر ڈپازٹ کی طرح ہوتا ہے جسے آپ مکمل کر سکتے ہیں یا نہیں کر سکتے۔ دونوں آلات آپ کو کسی سٹاک کو مکمل طور پر مالک بنائے بغیر اس کا نظارہ کرنے دیتے ہیں، لیکن صرف آپشن ہی آپ کو بھاگنے کا راستہ فراہم کرتا ہے۔ فرار کا وہ راستہ کبھی آزاد نہیں ہوتا۔ اس کی قیمت پریمیم ہے، اور اس کورس کا باقی حصہ واقعی یہ سمجھنے کے بارے میں ہے کہ وہ چھوٹی سی ادائیگی آپ کو کیا خریدتی ہے اور یہ کب ادا کرنے کے قابل ہے۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-basics/images/diagram-right-not-obligation.png\" alt=\"آپشن خریدار کے پاس حق ہے اور وہ صرف پریمیم کھو کر چلا جا سکتا ہے، جبکہ بیچنے والا اس پریمیم کے بدلے کوئی ذمہ داری قبول کرتا ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>آپشن خریدار کے پاس حق ہے اور وہ صرف پریمیم کھو کر چلا جا سکتا ہے، جبکہ بیچنے والا اس پریمیم کے بدلے کوئی ذمہ داری قبول کرتا ہے۔</figcaption></figure>\n<h2 id=\"the-two-basic-types-call-and-put\">دو بنیادی اقسام: کال اور ڈالیں۔</h2>\n<p>اختیارات صرف دو ذائقوں میں آتے ہیں، اور دنیا کی ہر حکمت عملی ان دو ٹکڑوں سے بنتی ہے۔</p>\n<ul>\n<li>اے <strong>کال</strong> ہڑتال پر بنیادی خریدنے کا حق ہے. جب آپ کو لگتا ہے کہ قیمت بڑھ جائے گی تو آپ کال خریدتے ہیں، جس طرح فلیٹ خریدار پچاس لاکھ لاک کرنے کے بعد قیمتوں میں اضافہ چاہتا تھا۔</li>\n<li>اے <strong>ڈال</strong> ہڑتال پر بنیادی فروخت کرنے کا حق ہے. آپ پوٹ خریدتے ہیں جب آپ کو لگتا ہے کہ قیمت کم ہو جائے گی، یا جب آپ کسی ایسی چیز پر انشورنس چاہتے ہیں جس کا آپ پہلے سے مالک ہو۔</li>\n</ul>\n<p>یہ پوری حروف تہجی ہے۔ خریدنے کے لیے کال کریں، بیچنے کے لیے ڈالیں۔ اگلا باب ان دونوں کو تفصیل سے الگ کرتا ہے اور آپ کو میموری کی مدد فراہم کرتا ہے تاکہ آپ ان کو کبھی ملا نہ سکیں۔ ابھی کے لیے، بنیادی تصویر کو اپنے ذہن میں رکھیں۔</p>\n<p>ہندوستانی مارکیٹ میں یہ دونوں قسمیں آپشن سمبل میں ہی دکھائی دیتی ہیں۔ خطوط <strong>CE</strong> ایک کال کے لئے کھڑے ہو جاؤ اور <strong>PE</strong> ایک ڈال کے لئے کھڑے ہو جاؤ. تو <code>RELIANCE28JUL261320CE</code> RELIANCE 1320 کال 28 جولائی 2026 کو ختم ہو رہی ہے، اور <code>RELIANCE28JUL261320PE</code> مماثل ڈال ہے. آپ اس علامت کا زیادہ تر حصہ پہلے ہی پڑھ سکتے ہیں: بنیادی نام، تاریخ، ہڑتال، اور قسم۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>جب آپ CE دیکھتے ہیں تو تھنک کال، خریدنے کا حق۔ جب آپ PE دیکھتے ہیں تو سوچیں کہ بیچنے کا حق ہے۔ وہ ایک عادت آپ کو بعد میں مہنگے اختلاط سے بچائے گی۔</p>\n</div></div>\n<h2 id=\"what-to-carry-forward\">آگے کیا لے جانا ہے۔</h2>\n<p>اب آپ اس فاؤنڈیشن کو تھامے ہوئے ہیں جس پر باقی کورس بناتا ہے۔ ایک آپشن حق ہے، فرض نہیں، ایک فکسڈ سٹرائیک پر ایک فکسڈ ایکسپائری پر خرید یا فروخت کرنا، ایک پریمیم کے لیے خریدا گیا جو خریدار کا زیادہ سے زیادہ نقصان ہے۔ بالکل دو قسمیں ہیں، کال ٹو خرید اور پوٹ ٹو سیل۔ مستقبل کی ذمہ داری؛ ایک آپشن آپ کو منتخب کرنے دیتا ہے۔</p>\n<p>فلیٹ ٹوکن کہانی ہاتھ میں رکھیں۔ آپشنز کے بارے میں تقریباً ہر مبہم چیز اس وقت واضح ہو جاتی ہے جب آپ اس کہانی کے پیچھے ایک سادہ سا سوال پوچھتے ہیں: کیا میں آج ایک چھوٹی سی رقم ادا کر رہا ہوں ایک قیمت کو لاک کرنے کے لیے، بعد میں جانے کی آزادی کے ساتھ؟ اگر ہاں، تو آپ ایک آپشن دیکھ رہے ہیں، اور آپ پہلے ہی سمجھ گئے ہیں کہ یہ کس چیز کے لیے ہے۔</p>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">کیا آپ جانتے ہیں؟</span><div><p>ایک RELIANCE آپشن کنٹریکٹ 500 شیئرز کی ایک مقررہ لاٹ پر محیط ہے۔ لہذا ایک لاٹ کے لیے تقریباً 31 روپے فی شیئر کا پریمیم تقریباً 15,590 روپے ادا کیا جاتا ہے۔ ہم پریمیم، اسٹرائیک اور ایکسپائری کو کھولیں گے، اور اس فی شیئر کو فی لاٹ پوائنٹ کے مقابلے میں، اگلے ابواب میں۔</p>\n</div></div>\n","toc":[{"level":2,"text":"اختیار ایک حق ہے، فرض نہیں۔","id":"an-option-is-a-right-not-a-duty"},{"level":2,"text":"ٹوکن منی کی کہانی","id":"the-token-money-story"},{"level":2,"text":"کیوں کوئی حق ادا کرے گا؟","id":"why-would-anyone-pay-for-a-right"},{"level":2,"text":"مستقبل کے خلاف اختیارات، ایک لائن میں","id":"options-against-futures-in-one-line"},{"level":2,"text":"دو بنیادی اقسام: کال اور ڈالیں۔","id":"the-two-basic-types-call-and-put"},{"level":2,"text":"آگے کیا لے جانا ہے۔","id":"what-to-carry-forward"}],"imgCount":1,"hasContent":true},"2":{"html":"<p>اب آپ جان چکے ہیں کہ کال اور پوٹ کیا ہوتا ہے۔ فطری اگلا سوال یہ ہے کہ کسی نے پہلی جگہ یہ معاہدے کیوں بنائے۔ اسٹاک آسان ہے، آپ کسی کمپنی کے ایک ٹکڑے کے مالک ہیں اور آپ اس کے عروج و زوال میں شریک ہیں۔ مستقبل ایک لیوریجڈ شرط ہے کہ قیمت کہاں جا رہی ہے۔ اختیارات ایک وجہ سے ان دونوں کے ساتھ بیٹھتے ہیں، کیونکہ وہ چار الگ الگ کام کرتے ہیں جو کہ ایک سادہ اسٹاک یا مستقبل صاف طور پر نہیں کر سکتا۔ ایک بار جب آپ ان چار ملازمتوں کو نام دے سکتے ہیں، تو پوری آپشنز مارکیٹ سمجھ میں آنے لگتی ہے۔ اس سے بھی بہتر، جب آپ خرید پر کلک کرتے ہیں تو آپ یہ دیکھنا شروع کر دیتے ہیں کہ آپ اصل میں کون سا کام کر رہے ہیں، اور خود آگاہی کا وہ واحد ٹکڑا ان تاجروں کو الگ کر دیتا ہے جو خاموشی سے ختم ہونے والے ابتدائیوں سے ختم ہو جاتے ہیں۔</p>\n<h2 id=\"four-jobs-in-one-instrument\">ایک آلے میں چار کام</h2>\n<p>چار حقیقی مقاصد کی تکمیل کے لیے اختیارات موجود ہیں۔ بالکل وہی RELIANCE 1320 کال یا پوٹ ان میں سے ایک سے زیادہ کام کرسکتا ہے اس پر منحصر ہے کہ اسے کون رکھتا ہے اور کیوں۔ یہاں وہ ایک نظر میں ہیں، اور پھر ہم ان میں سے ہر ایک کو اصلی RELIANCE نمبروں کے ساتھ دیکھتے ہیں جو آپ پہلے سے جانتے ہیں۔</p>\n<table>\n<thead>\n<tr>\n<th>نوکری</th>\n<th>یہ آپ کے لیے کیا کرتا ہے۔</th>\n<th>عام ٹول</th>\n<th>جو خطرہ آپ اٹھاتے ہیں۔</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>ہیجنگ</td>\n<td>آپ کے پاس پہلے سے موجود کسی چیز کا بیمہ کرتا ہے۔</td>\n<td>ایک پٹ خریدیں۔</td>\n<td>پریمیم ادا کیا گیا۔</td>\n</tr>\n<tr>\n<td>قیاس آرائی</td>\n<td>معلوم، محدود نقصان کے ساتھ سمت پر شرط لگانا</td>\n<td>کال یا پٹ خریدیں۔</td>\n<td>پریمیم ادا کیا گیا۔</td>\n</tr>\n<tr>\n<td>آمدنی</td>\n<td>ڈیوٹی لینے کے لیے آپ کو پریمیم ادا کرتا ہے۔</td>\n<td>کال یا پوٹ بیچیں۔</td>\n<td>بڑا، کبھی کبھی لامحدود</td>\n</tr>\n<tr>\n<td>فائدہ اٹھانا</td>\n<td>چھوٹے اخراجات کے لیے ایک بڑی نمائش کو کنٹرول کرتا ہے۔</td>\n<td>کال یا پٹ خریدیں۔</td>\n<td>پریمیم ادا کیا گیا۔</td>\n</tr>\n</tbody></table>\n<p>غور کریں کہ چار میں سے تین کام ایک خریدار کی طرف سے کیے گئے ہیں، اور ان میں سے ہر ایک میں خریدار کا خطرہ وہی پرسکون اعداد و شمار ہے، جو ادا کیا گیا پریمیم ہے۔ صرف آمدنی کا کام بیچنے والے کے ذریعہ کیا جاتا ہے، اور یہی وہ کام ہے جہاں خطرہ بڑھ جاتا ہے۔ جاتے وقت اس تضاد کو ذہن میں رکھیں، کیونکہ یہ اس کورس میں ہر چیز کی ریڑھ کی ہڈی ہے۔</p>\n<h2 id=\"job-one-insurance-on-what-you-own\">کام ایک: آپ کی ملکیت پر انشورنس</h2>\n<p>پہلا کام ہے۔ <strong>ہیجنگ</strong>جس کا سیدھا مطلب ہے کسی ایسی چیز کی حفاظت کرنا جو آپ کے پاس پہلے سے ہے۔ کہو کہ آپ کے پاس 500 حصص RELIANCE کے ہیں، جو موجودہ قیمت 1,318 روپے کے قریب خریدے گئے ہیں۔ ان حصص کی مالیت 500 گنا 1,318 ہے جو کہ تقریباً 6,59,000 روپے ہے۔ آپ کو کمپنی طویل مدت کے لیے پسند ہے، لیکن آپ اگلے مہینے کے بارے میں گھبرائے ہوئے ہیں۔ آپ بیچنا نہیں چاہتے، پھر بھی آپ حادثے میں سوار ہونا بھی نہیں چاہتے۔</p>\n<p>یہ بالکل وہی ہے جو ایک ڈال کے لئے ہے. آپ ایک 1320 پوٹ تقریباً 31 روپے فی شیئر میں خریدتے ہیں، جو کہ 500 کے لاٹ کے لیے تقریباً 15,590 روپے ہے۔ اب اگر RELIANCE مشکل پڑتی ہے، تو حصص کے کھونے کے ساتھ ہی پوٹ کی قیمت بڑھ جاتی ہے، اور آپ کا منفی پہلو تکیا جاتا ہے۔ اگر RELIANCE اس کے بجائے چڑھتا ہے، تو آپ صرف پوٹ کی میعاد ختم ہونے دیتے ہیں اور آپ صرف پریمیم سے باہر ہیں، اسی طرح ایک غیر استعمال شدہ ہوم انشورنس پالیسی آپ کو سال کا پریمیم خرچ کرتی ہے اور اس سے زیادہ کچھ نہیں۔ آپ نے اگلے مہینے میں ذہنی سکون کے لیے ادائیگی کی، اور یہ خریدنے کے لیے بالکل معقول چیز ہے۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>آپ کی ملکیت کے حصص کے خلاف خریدا جانے والا پوٹ انشورنس ہے۔ اس نقصان کو پورا کرنے کے لیے آپ آج ایک معلوم پریمیم ادا کرتے ہیں جس کے بارے میں آپ پریشان ہیں۔ اگر خوف زدہ زوال کبھی نہیں آتا ہے تو، پریمیم اچھی طرح سے سونے کی قیمت ہے، اس سے زیادہ کچھ نہیں۔</p>\n</div></div>\n<h2 id=\"job-two-a-defined-risk-bet-on-direction\">کام دو: سمت پر ایک متعین خطرے کی شرط</h2>\n<p>دوسرا کام ہے۔ <strong>قیاس آرائی</strong>جس کا یہاں مطلب ہے سمت کے بارے میں جان بوجھ کر نظریہ لینا۔ اس لفظ کی ساکھ بری ہے، لیکن اختیارات اسے ایک ایسی خصوصیت دیتے ہیں جس سے کوئی اسٹاک یا مستقبل مماثل نہیں ہوسکتا: نقصان آپ کے داخل ہونے سے پہلے ہی معلوم اور محدود ہوجاتا ہے۔</p>\n<p>فرض کریں کہ آپ کو لگتا ہے کہ اگلے مہینے میں RELIANCE بڑھے گا۔ 1320 کال تقریباً 15,590 روپے میں خریدیں۔ یہ اعداد و شمار صرف آپ کی قیمت نہیں ہے، یہ وہ سارا نقصان ہے جو آپ کبھی بھی تجارت پر اٹھا سکتے ہیں، چاہے اسٹاک کتنی ہی بری طرح گر جائے۔ اگر RELIANCE 1,200 یا 1,100 یا اس سے کم ہو جاتا ہے، تو آپ کا نقصان پریمیم پر رک جاتا ہے۔ اس کا مستقبل کے ساتھ موازنہ کریں، جہاں ہر روپیہ گرتا ہے اسٹاک آپ کے اکاؤنٹ کو ختم کرتا رہتا ہے۔ محدود، طے شدہ خطرے کا نقصان ایک آپشن خریدنے کی سرخی کی خصوصیت ہے، اور یہی وجہ ہے کہ ایک محتاط مبتدی یہاں سے شروع ہوتا ہے بجائے اس کے کہ مستقبل میں۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>جب آپ کوئی آپشن خریدتے ہیں تو داخل ہونے سے پہلے پریمیم روپے میں لکھ دیں۔ یہ تعداد پوری تجارت کے لیے آپ کا زیادہ سے زیادہ نقصان ہے۔ اسے پہلے سے جاننا ہی ایک آپشن کو ایک نقطہ نظر کی پشت پناہی کرنے کا ایک متعین خطرے کا طریقہ بناتا ہے۔</p>\n</div></div>\n<h2 id=\"job-three-getting-paid-to-wait\">کام تین: انتظار کرنے کے لیے ادائیگی کرنا</h2>\n<p>تیسری نوکری تجارت کے دوسرے حصے سے تعلق رکھتی ہے۔ <strong>بیچنے والا</strong>، اور کام ہے <strong>آمدنی</strong>. جب آپ کوئی آپشن بیچتے ہیں، تو آپ پہلے سے پریمیم جمع کرتے ہیں۔ پہلے دن اپنے اکاؤنٹ میں RELIANCE 1320 کال اور تقریباً 15,590 روپے فروخت کریں۔ 1320 کا پوٹ بیچیں اور اتنی ہی رقم آجائے۔ ہر روز اسٹاک ایک بڑا اقدام کرنے میں ناکام ہوجاتا ہے، آپ نے جو وقت کی قیمت فروخت کی ہے وہ آپ کے حق میں پگھل جاتی ہے، اور آپ جو جمع کرتے ہیں اسے برقرار رکھنے کا آپ کا مقصد ہے۔</p>\n<p>یہ بہت اچھا لگتا ہے، اور یہ بالکل وہی ہے جہاں بہت سے نئے آنے والوں کو تکلیف پہنچتی ہے، تو آئیے ہم دو ٹوک رہیں۔ آپشن بیچنا مفت آمدنی نہیں ہے۔ اس پریمیم کے بدلے میں آپ ڈیوٹی قبول کرتے ہیں، اور غلط طرف سے خطرہ بڑا ہوتا ہے۔ اگر اسٹاک چڑھتا رہتا ہے تو فروخت شدہ کال بغیر کسی واضح حد کے کھو سکتی ہے۔ اگر اسٹاک گر جاتا ہے تو فروخت شدہ پوٹ بہت زیادہ کھو سکتا ہے۔ ایکسچینج آپ کو یہ ثابت کرنے کے لیے کہ آپ ادائیگی کر سکتے ہیں ایک قابل قدر مارجن پوسٹ کرتا ہے۔ ہم بعد کا ایک مکمل باب فروخت اور اس کے حقیقی خطرات کے لیے وقف کرتے ہیں۔ ابھی کے لیے، اسے صحیح طریقے سے درج کریں: آمدنی ایک حقیقی ملازمت کے اختیارات ہے، لیکن یہ ادا شدہ خطرہ ہے، کبھی بھی مفت تحفہ نہیں۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>اختیارات بیچ کر پریمیم جمع کرنا مفت رقم نہیں ہے۔ آپ کو حقیقی ذمہ داری نبھانے کے لیے پیشگی ادائیگی کی جاتی ہے، مسدود کردہ مارجن بڑا ہے، اور غلط طرف سے ہونے والا نقصان آپ کو موصول ہونے والے پریمیم کو کم کر سکتا ہے۔ اس کام کی کوشش کرنے سے پہلے اس کا احترام کریں۔</p>\n</div></div>\n<h2 id=\"job-four-a-big-position-for-a-small-outlay\">کام چار: چھوٹے اخراجات کے لئے ایک بڑی پوزیشن</h2>\n<p>چوتھا کام ہے۔ <strong>بیعانہ</strong>، جس کا مطلب ہے کہ ایک چھوٹی سی رقم کے ساتھ ایک بڑی نمائش کو کنٹرول کرنا۔ RELIANCE بڑھنے کے دو طریقوں کو دوبارہ دیکھیں۔ 500 شیئرز خریدنے کی لاگت تقریباً 6,59,000 روپے ہے۔ 1320 کال لاٹ خریدنے پر تقریباً 15,590 روپے لاگت آتی ہے، جو کہ شیئر کی قیمت کا تقریباً ایک چالیس سیکنڈ ہے، پھر بھی یہ آپ کو سٹرائیک کے اوپر انہی 500 شیئرز کے اوپر ایک دعویٰ فراہم کرتا ہے۔ اسٹاک میں ایک چھوٹی سی حرکت اس چھوٹے پریمیم میں ایک بڑا فیصد جھول پیدا کر سکتی ہے۔ یہ بیعانہ ہے، اور یہ نشہ آور ہے۔</p>\n<p>یہ ایک دو دھاری ٹول بھی ہے، اور یہاں ایمانداری اہمیت رکھتی ہے۔ وہی بیعانہ جو ایک چھوٹے پریمیم کو ضرب دے سکتا ہے اسے بخارات بھی بنا سکتا ہے۔ اگر RELIANCE ایک طرف بڑھتا ہے یا کم ہوتا ہے، تو وہ 15,590 روپے صفر کی طرف گر سکتا ہے جب کہ آپ کے ساتھ والے شیئر ہولڈر، جو صرف چند فیصد نیچے ہے، بمشکل نوٹس لیتے ہیں۔ لیوریج دونوں سمتوں کو بڑا کرتا ہے، اور چونکہ خریدے گئے آپشن سے وقت کی قدر ختم ہوتی رہتی ہے، اس لیے لیوریجڈ بیٹ پر کل نقصان کے امکانات بہت حقیقی ہیں۔ بیعانہ کو ایک ناپے ہوئے انتخاب کے طور پر استعمال کریں، کبھی بھی پیسے ڈالنے کے طریقے کے طور پر جو آپ میز پر نہیں کھو سکتے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>بیعانہ دونوں طریقوں سے کاٹتا ہے۔ پریمیم جو ایک اچھے اقدام پر دوگنا ہو سکتا ہے وہ فلیٹ یا غلط اقدام پر بھی صفر پر جا سکتا ہے۔ کبھی بھی کسی آپشن پر شرط نہ لگائیں گویا صرف اچھا نتیجہ موجود ہے۔</p>\n</div></div>\n<h2 id=\"who-uses-options-and-how\">کون اختیارات استعمال کرتا ہے، اور کیسے</h2>\n<p>وہی چار ملازمتیں مارکیٹ میں دو بڑے گروپوں کی طرف سے بہت مختلف طریقے سے استعمال کی جاتی ہیں، اور اس فرق کو دیکھ کر بہت پر سکون ہوتا ہے۔</p>\n<p>بڑے ادارے، فنڈز اور ڈیسک جو سنجیدہ سائز میں منتقل ہوتے ہیں، زیادہ تر پہلی اور تیسری ملازمتوں پر جھکاؤ رکھتے ہیں۔ وہ پورٹ فولیوز کو ہیج کرنے کے لیے پوٹس خریدتے ہیں جو وہ آسانی سے نہیں بیچ سکتے، وہ پریمیم کو ناپے ہوئے، مارجنڈ، رسک مینیجڈ طریقے سے فروخت کرتے ہیں، اور وہ جیک پاٹ کا پیچھا کرنے کی بجائے شکل دینے اور خطرے کو کم کرنے کے لیے اختیارات استعمال کرتے ہیں۔ ان کے لیے اختیارات بنیادی طور پر رسک مینجمنٹ ٹول ہیں۔</p>\n<p>خوردہ سرگرمی کا ایک بہت بڑا سودا مخالف سرے پر بیٹھتا ہے۔ یہ لاٹری کی ادائیگی کے لیے خالصتاً خریدے گئے سستے، پیسے سے باہر کے اختیارات پر توجہ مرکوز کرتا ہے، ایک چھوٹا سا پریمیم ایک بہت بڑا، غیر متوقع اقدام پر لگا ہوا ہے۔ اب اور پھر ایک شاندار ادائیگی کرتا ہے اور کہانی پھیل جاتی ہے۔ زیادہ کثرت سے پریمیم صرف میعاد ختم ہونے سے کچھ بھی نہیں ہوتا ہے۔ آلہ ایک ہی ہے، لیکن ایک گروہ زیادہ تر بیمہ اور انتظام کر رہا ہے، جبکہ دوسرا زیادہ تر لانگ شاٹس پر جوا کھیل رہا ہے۔</p>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">کیا آپ جانتے ہیں؟</span><div><p>زیادہ تر پیسے سے باہر کے اختیارات کے خریدار وقت کے ساتھ پیسے کھو دیتے ہیں، کیونکہ وہ خالص امید کی ادائیگی کر رہے ہوتے ہیں اور وقت کا زوال اسے ہر روز ختم کر دیتا ہے۔ معاہدہ اس سے ملتا جلتا ہے جسے کوئی ادارہ ہیج کرنے کے لیے استعمال کرتا ہے۔ نتائج میں فرق اس کام سے آتا ہے جو آپ واقعی کر رہے ہیں۔</p>\n</div></div>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-basics/images/diagram-calls-and-puts.png\" alt=\"کالز اور ساتھ ساتھ رکھتا ہے، دو سادہ بلڈنگ بلاکس جن سے ان چاروں میں سے ہر ایک کام کو جمع کیا جاتا ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>کالز اور ساتھ ساتھ رکھتا ہے، دو سادہ بلڈنگ بلاکس جن سے ان چاروں میں سے ہر ایک کام کو جمع کیا جاتا ہے۔</figcaption></figure>\n<h2 id=\"what-to-carry-forward\">آگے کیا لے جانا ہے</h2>\n<p>اختیارات موجود ہیں کیونکہ وہ چار کام کرتے ہیں جو کہ کوئی اور چیز اتنی صفائی سے نہیں کرتی۔ وہ ایک ہولڈنگ کا بیمہ کرتے ہیں، وہ آپ کو محدود نقصان کے ساتھ سمت پر شرط لگانے دیتے ہیں، وہ بیچنے والے کو خطرہ مول لینے کے لیے پریمیم کمانے دیتے ہیں، اور وہ ایک چھوٹے سے اخراجات کو ایک بڑی نمائش کو کنٹرول کرنے دیتے ہیں۔ ان میں سے تین ملازمتیں خریدار کو ایک معروف، محدود نقصان پہنچاتی ہیں، جو کہ ابتدائی طور پر کھڑے ہونے کے لیے سب سے نرم جگہ ہے۔ چوتھا، آمدنی کے لیے بیچنا، آپ کو پہلے سے ادائیگی کرتا ہے لیکن آپ کو حقیقی خطرہ اور بھاری مارجن کے ساتھ لادتا ہے۔</p>\n<p>کسی بھی تجارت سے پہلے، اپنے آپ سے صاف صاف پوچھیں کہ آپ چار میں سے کون سی نوکری کر رہے ہیں۔ کیا میں کسی چیز کی حفاظت کر رہا ہوں، ایک متعین خطرے کا نقطہ نظر لے رہا ہوں، خطرے کے لیے پریمیم جمع کر رہا ہوں، یا فائدہ اٹھانے کے لیے پہنچ رہا ہوں۔ اگر آپ کا ایماندارانہ جواب ان میں سے کوئی بھی نہیں ہے، اور آپ صرف ایک سستا فاور آؤٹ آپشن خرید رہے ہیں کیونکہ یہ پھٹ سکتا ہے، تو آپ جوا کھیل رہے ہیں جس سے زیادہ تر خوردہ کھاتوں کو ختم کر دیا جاتا ہے۔ ملازمت کا نام دینا اختیارات کا پہلا نظم ہے، اور اس پر عمل کرنے کے لیے آپ کو کچھ خرچ نہیں کرنا پڑتا۔</p>\n","toc":[{"level":2,"text":"ایک آلے میں چار کام","id":"four-jobs-in-one-instrument"},{"level":2,"text":"کام ایک: آپ کی ملکیت پر انشورنس","id":"job-one-insurance-on-what-you-own"},{"level":2,"text":"کام دو: سمت پر ایک متعین خطرے کی شرط","id":"job-two-a-defined-risk-bet-on-direction"},{"level":2,"text":"کام تین: انتظار کرنے کے لیے ادائیگی کرنا","id":"job-three-getting-paid-to-wait"},{"level":2,"text":"کام چار: چھوٹے اخراجات کے لئے ایک بڑی پوزیشن","id":"job-four-a-big-position-for-a-small-outlay"},{"level":2,"text":"کون اختیارات استعمال کرتا ہے، اور کیسے","id":"who-uses-options-and-how"},{"level":2,"text":"آگے کیا لے جانا ہے","id":"what-to-carry-forward"}],"imgCount":1,"hasContent":true},"3":{"html":"<p>تصور کریں کہ آپ کو یقین ہے کہ RELIANCE اپنے موجودہ 1,318 روپے سے بڑھنے والا ہے۔ آپ کے پاس اس واحد نقطہ نظر کو واپس کرنے کے تین طریقے ہیں۔ آپ حصص خرید سکتے ہیں، آپ مستقبل خرید سکتے ہیں، یا آپ کال خرید سکتے ہیں۔ اسکرین پر وہ سب ایک ہی اسٹاک پر ایک ہی شرط کی طرح نظر آسکتے ہیں، اور ایک ابتدائی شخص اکثر ان کے ساتھ تبادلہ خیال کرتا ہے، جو بھی کم سے کم نقدی کی ضرورت ہو اسے چنتا ہے۔ وہ قابل تبادلہ نہیں ہیں۔ تینوں کا برتاؤ اتنا مختلف ہے کہ ایک ہی صحیح نظریہ آپ کو ایک میں پیسہ کما سکتا ہے اور دوسرے میں آپ کا پیسہ کھو سکتا ہے۔ یہ باب انہیں ساتھ ساتھ لائن کرتا ہے تاکہ آپ بالکل دیکھ سکیں کہ آپ کس کے درمیان انتخاب کر رہے ہیں، اور یہ ایک سب سے مہنگی خرافات کو ختم کر دیتا ہے جو ایک نیا تاجر رکھتا ہے، کہ ایک آپشن صرف ایک سستا مستقبل ہے۔</p>\n<h2 id=\"three-ways-to-back-the-same-view\">ایک ہی نقطہ نظر کو واپس کرنے کے تین طریقے</h2>\n<p>تینوں آلات آپ کو RELIANCE حرکت پذیر ہونے کی نمائش فراہم کرتے ہیں۔ کیا فرق ہے کہ آپ کو کتنا خرچ کرنا چاہیے، آپ کا نفع اور نقصان کیا شکل اختیار کرتا ہے، اور اگر آپ غلط ہیں تو آپ کتنا کھو سکتے ہیں۔ ان تینوں چیزوں کو ہر ایک کے لیے سیدھا حاصل کریں اور آپ انہیں دوبارہ کبھی الجھائیں گے۔</p>\n<h2 id=\"the-stock-simplest-linear-full-price\">اسٹاک: سب سے آسان، لکیری، پوری قیمت</h2>\n<p>اسٹاک خریدنا تینوں میں سب سے سادہ ہے۔ آپ پوری قیمت ادا کرتے ہیں اور آپ حصص کے مالک ہیں۔ ایک آپشن لاٹ سے ملنے کے لیے آپ 1,318 روپے میں 500 شیئرز خریدیں گے، جس کی قیمت 500 گنا 1,318، تقریباً 6,59,000 روپے ہے۔ وہ پوری رقم آپ کے اکاؤنٹ سے نکل جاتی ہے۔</p>\n<p>بدلے میں آپ کا نفع نقصان ہوتا ہے۔ <strong>لکیری</strong>، ایک کے لیے ایک صاف سطر۔ ہر روپیہ RELIANCE بڑھنے سے آپ کی پوزیشن میں 500 روپے کا اضافہ ہوتا ہے، اور ہر روپیہ جو گرتا ہے وہ 500 لے جاتا ہے۔ کوئی میعاد ختم نہیں ہوتی، کوئی وقت کا دباؤ نہیں ہوتا، اور کچھ بھی خراب نہیں ہوتا۔ آپ سالوں تک روک سکتے ہیں۔ آپ کا زیادہ سے زیادہ نقصان بہت زیادہ ہے، پورے 6,59,000 روپے اگر کمپنی صفر پر چلی جائے، لیکن یہ ایک دور دراز، سست خطرہ ہے اور آپ کو کبھی بھی راستے میں ٹاپ اپ کرنے کو نہیں کہا جاتا ہے۔ اسٹاک تینوں میں سب سے پرسکون، سب سے بھاری، سب سے زیادہ معاف کرنے والا ہے۔</p>\n<h2 id=\"the-future-leverage-still-linear-marked-daily\">مستقبل: بیعانہ، اب بھی لکیری، روزانہ نشان زد</h2>\n<p>اے <strong>مستقبل</strong> اسی 500 حصص کو آج طے شدہ قیمت پر طے کرنے کا معاہدہ ہے، اس فرق کے ساتھ جو میعاد ختم ہونے پر ادا کی جائے گی۔ اسٹاک سے اہم تبدیلی یہ ہے کہ آپ پورے 6,59,000 روپے ادا نہیں کرتے ہیں۔ آپ پوسٹ a <strong>مارجن</strong>, پوری قیمت کا ایک حصہ، اکثر پانچویں کے قریب، نیک نیتی سے جمع کے طور پر۔ یہ چھوٹا سا خرچہ 500 حصص کی مکمل نمائش کو کنٹرول کرتا ہے، جو کہ لیوریج ہے۔</p>\n<p>لیکن خطرے کی شکل اب بھی ہے <strong>لکیری</strong>، اور وہ پھندا ہے. مستقبل بڑھتا اور گرتا ہے اسٹاک کے ساتھ، پورے 500 حصص پر، حالانکہ آپ نے صرف ایک ٹکڑا لگایا ہے۔ لہذا آپ کے خلاف اقدام آپ کا مارجن جلدی کھا جاتا ہے، اور ایکسچینج ہر ایک دن مارکیٹ میں آپ کی پوزیشن کو نشان زد کرتا ہے۔ اگر نقصان آپ کے ڈپازٹ کو ختم کر دیتا ہے، تو آپ کو اسی دن مزید نقد رقم جمع کرنے یا بند کرنے کے لیے کال موصول ہوتی ہے۔ مستقبل کا کوئی محدود نقصان نہیں ہوتا اور نہ ہی وقت کا زوال ہوتا ہے۔ یہ روزانہ کی تصفیہ اور نقصان کے ساتھ نقد کے ایک حصے پر اسٹاک کی نمائش ہے جو آپ کی پہلی جمع کردہ رقم سے اچھی طرح چل سکتا ہے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>ایک مستقبل لیوریجڈ لیکن لکیری ہے۔ یہ پوری لاٹ پر اسٹاک کے ساتھ ایک کے بدلے منتقل ہوتا ہے، اسے روزانہ مارکیٹ کرنے کے لیے نشان زد کیا جاتا ہے، اور آپ کے خلاف اقدام اسی دن تازہ نقدی کا مطالبہ کر سکتا ہے۔ نقصان پر کوئی بلٹ ان چھت نہیں ہے۔</p>\n</div></div>\n<h2 id=\"the-option-bent-and-asymmetric\">اختیار: جھکا ہوا اور غیر متناسب</h2>\n<p>ایک لمبی <strong>اختیار</strong>، کہتے ہیں کہ 1320 کال، عجیب و غریب ہے، اور اس کا فرق پورا نقطہ ہے۔ آپ صرف پریمیم ادا کرتے ہیں، تقریباً 31 روپے فی شیئر، جو کہ لاٹ کے لیے تقریباً 15,590 روپے ہے۔ وہ پریمیم پوری لاگت ہے، اور اہم طور پر یہ پورا خطرہ ہے۔ اس سے کوئی فرق نہیں پڑتا ہے کہ RELIANCE کتنی ہی دور ہو جائے، آپ اس سے 15,590 روپے سے زیادہ کبھی نہیں کھو سکتے۔ کوئی بھی آپ کو زیادہ کے لیے مارکیٹ کرنے کے لیے نشان زد نہیں کرتا، کوئی بھی آپ کو اضافی نقد رقم کے لیے نہیں بلاتا۔</p>\n<p>اس آرام کی قیمت دو گنا ہے۔ سب سے پہلے، آپ کا منافع اور نقصان اب ایک سیدھی لائن نہیں ہے، یہ ہے <strong>جھکا</strong>. ہڑتال کے نیچے نقصان فلیٹ ہے، پریمیم پر محدود ہے۔ سٹرائیک کے اوپر لائن اوپر ہو جاتی ہے اور آپ کو فائدہ ہونا شروع ہو جاتا ہے، لیکن سٹاک کے سٹرائیک کے علاوہ پریمیم کو کلیئر کرنے کے بعد، یہاں تقریباً 1351 کا بریک ایون۔ وہ جھکی ہوئی، یک طرفہ شکل وہی ہے جس کا مطلب ایک سے ہے۔ <strong>غیر متناسب</strong> ادائیگی، چھوٹا اور منفی پہلو پر جانا جاتا ہے، الٹا کھلا ہے۔ دوسرا، آپشن میں وقت کی قدر ہوتی ہے جو ہر روز پگھل جاتی ہے، لہٰذا اگر حرکت بہت چھوٹی یا بہت سست ہو تو درست نظریہ بھی کھو جاتا ہے۔ آپ یومیہ کرایہ کے لیے ممکنہ ٹاپ اپ کال ٹریڈ کر رہے ہیں۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>ایک طویل آپشن کی وضاحتی خصوصیت اس کی جھکی ہوئی، غیر متناسب ادائیگی ہے۔ نقصان فلیٹ ہے اور اسٹرائیک کے نیچے پریمیم پر محدود ہے، جبکہ فائدہ اس کے اوپر کھلتا ہے۔ ایک اسٹاک اور مستقبل دونوں اس کے بجائے ایک سیدھی، سڈول لائن کھینچتے ہیں۔</p>\n</div></div>\n<h2 id=\"the-three-way-table\">تین طرفہ میز</h2>\n<p>یہاں بھی وہی نظریہ ہے، RELIANCE نے 1,318 سے بڑھتے ہوئے 500 حصص کی ایک لاٹ کے لیے تین طریقوں کا اظہار کیا۔ یہ محسوس کرنے کے لیے ہر کالم کو پڑھیں کہ یہ واقعی کتنے مختلف ہیں۔</p>\n<table>\n<thead>\n<tr>\n<th>فیچر</th>\n<th>اسٹاک خریدیں۔</th>\n<th>مستقبل خریدیں۔</th>\n<th>1320 کال خریدیں۔</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>جو آپ نے لگایا</td>\n<td>پوری قیمت</td>\n<td>مارجن ڈپازٹ</td>\n<td>صرف پریمیم</td>\n</tr>\n<tr>\n<td>نقد رقم خرچ کرنا</td>\n<td>تقریباً 6,59,000 روپے</td>\n<td>ایک حصہ، اکثر پانچویں کے قریب</td>\n<td>تقریباً 15,590 روپے</td>\n</tr>\n<tr>\n<td>خطرے کی شکل</td>\n<td>لکیری، سڈول</td>\n<td>لکیری، ہم آہنگ</td>\n<td>جھکا ہوا، غیر متناسب</td>\n</tr>\n<tr>\n<td>روزانہ مارک ٹو مارکیٹ</td>\n<td>نہیں</td>\n<td>جی ہاں، ہر روز آباد</td>\n<td>نہیں</td>\n</tr>\n<tr>\n<td>کیا آپ سے مزید نقد رقم طلب کی جا سکتی ہے؟</td>\n<td>نہیں</td>\n<td>ہاں، مارجن کالز</td>\n<td>نہیں، کبھی نہیں۔</td>\n</tr>\n<tr>\n<td>وقت کا زوال</td>\n<td>کوئی نہیں۔</td>\n<td>کوئی نہیں۔</td>\n<td>جی ہاں، روزانہ نالیوں</td>\n</tr>\n<tr>\n<td>زیادہ سے زیادہ نقصان</td>\n<td>بڑا، پوری قدر</td>\n<td>بڑے، جمع سے تجاوز کر سکتے ہیں</td>\n<td>پریمیم پر کیپڈ</td>\n</tr>\n<tr>\n<td>ختم</td>\n<td>کوئی نہیں، سالوں تک پکڑو</td>\n<td>مقررہ میعاد</td>\n<td>مقررہ میعاد</td>\n</tr>\n</tbody></table>\n<p>صرف نقدی قطار کے نمبر ہی بتاتے ہیں کہ ابتدائی افراد آپشن تک کیوں پہنچتے ہیں، یہ سب سے سستا دروازہ ہے۔ آپشن کم سے کم نقد رقم مانگتا ہے اور صرف محدود نقصان دیتا ہے، پھر بھی یہ تینوں میں سے واحد ہے جو خاموشی سے آپ کے انتظار کے دوران کچھ بھی نہیں کر سکتا۔</p>\n<h2 id=\"busting-the-myth-an-option-is-not-just-a-cheaper-future\">افسانہ کو ختم کرنا: ایک آپشن صرف ایک سستا مستقبل نہیں ہے۔</h2>\n<p>چونکہ کال کی قیمت مستقبل کے تقریباً ایک پانچویں مارجن کے مقابلے میں تقریباً 15,590 روپے ہے، بہت سے نئے آنے والے یہ نتیجہ اخذ کرتے ہیں کہ ایک آپشن صرف ایک سستا، چھوٹا مستقبل ہے۔ یہ غلط ہے، اور اس پر یقین کرنے سے حقیقی نقصان ہوتا ہے۔ دونوں مختلف جانور ہیں۔</p>\n<p>مستقبل لکیری اور ہم آہنگ ہے۔ یہ دونوں سمتوں میں ایک کے بدلے حاصل کرتا ہے اور کھوتا ہے، یہ کبھی نہیں زوال پذیر ہوتا ہے، اور اسے مارجن کالز کے خطرے کے ساتھ روزانہ مارکیٹ کرنے کے لیے نشان زد کیا جاتا ہے۔ اس کے نقصان میں کوئی بلٹ ان فلور نہیں ہے۔ ایک طویل اختیار جھکا ہوا اور غیر متناسب ہے۔ اس کا نقصان پریمیم پر محدود ہوتا ہے، اسے کبھی بھی آپ کے خلاف مارکیٹ کرنے کے لیے نشان زد نہیں کیا جاتا، اور اس میں وقت کی خرابی ہوتی ہے جو ہر روز آپ کے خلاف کام کرتی ہے۔ مستقبل گھڑی سے کچھ نہیں پوچھتا، آپشن اسے کرایہ ادا کرتا ہے۔</p>\n<p>لہذا مستقبل اور آپشن دو قیمت پوائنٹس پر ایک ہی تجارت نہیں ہیں۔ مستقبل آپ کو مارجن کے لیے مکمل لکیری اقدام خریدتا ہے جس کا آپ کو روزانہ دفاع کرنا چاہیے۔ آپشن پگھلنے والے پریمیم کے بدلے میں آپ کو ایک محدود نقصان، اقدام پر یک طرفہ دعوی خریدتا ہے۔ ایک پر دوسرے کا انتخاب کرنا بالکل مختلف خطرے کا انتخاب کرنا ہے، نہ کہ صرف ایک چھوٹا بل۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>اگر آپ کبھی اپنے آپ کو یہ سوچتے ہیں کہ آپشن صرف ایک سستا مستقبل ہے تو رک جائیں۔ آپ ایک ہی چیز کا چھوٹا ورژن نہیں خرید رہے ہیں، آپ خطرے کی مختلف شکل خرید رہے ہیں، جس میں ایک محدود نقصان ہے، کوئی روزانہ مارجن کال نہیں ہے، اور آپ کے خلاف گھڑی کی ٹک ٹک ہے۔</p>\n</div></div>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-basics/images/diagram-options-vs-futures-vs-stocks.png\" alt=\"RELIANCE پر ایک ہی شرط نے تین طریقوں کا اظہار کیا، جس میں اسٹاک کی سیدھی، ہم آہنگ لائن اور ایک طویل آپشن کے مڑے ہوئے، غیر متناسب، محدود نقصان کی ادائیگی کے خلاف مستقبل دکھایا گیا ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>RELIANCE پر ایک ہی شرط نے تین طریقوں کا اظہار کیا، جس میں اسٹاک کی سیدھی، ہم آہنگ لائن اور ایک طویل آپشن کے مڑے ہوئے، غیر متناسب، محدود نقصان کی ادائیگی کے خلاف مستقبل دکھایا گیا ہے۔</figcaption></figure>\n<h2 id=\"what-to-carry-forward\">آگے کیا لے جانا ہے۔</h2>\n<p>تین آلات، ایک نظارہ، تین بہت مختلف سفر۔ اسٹاک بھاری اور پرسکون ہے، سامنے مکمل کیش، سیدھی لائن، کوئی گھڑی نہیں۔ مستقبل کا فائدہ اٹھایا گیا ہے لیکن پھر بھی ایک سیدھی لکیر ہے، جو روزانہ مارکیٹ کے لیے نشان زد ہوتی ہے، اس نقصان کے ساتھ جو آپ کے ڈپازٹ کو پیچھے چھوڑ سکتا ہے اور مزید مانگ کر سکتا ہے۔ لمبا آپشن صرف ایک محدود، معلوم نقصان کے ساتھ ایک چھوٹا سا پریمیم کے لئے خریدا گیا ہے، لیکن یہ ہڑتال کے ارد گرد جھک جاتا ہے اور وقت کی کمی پر روزانہ کرایہ ادا کرتا ہے۔</p>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">کیا آپ جانتے ہیں؟</span><div><p>ایک طویل آپشن میں محدود خطرہ اور پگھلنے والی وقت کی قدر ہوتی ہے۔ مستقبل میں لکیری خطرہ، روزانہ مارک ٹو مارکیٹ، اور کوئی زوال نہیں ہے۔ یہ جاننا کہ ان دونوں میں سے آپ کس کے پاس ہیں یہ فیصلہ کرتا ہے کہ آیا ایک فلیٹ مارکیٹ خاموشی سے آپ کو کچھ نہیں دیتی یا خاموشی سے آپ کی ہر وہ چیز خرچ کرتی ہے جو آپ نے ادا کی تھی۔</p>\n</div></div>\n<p>جب کوئی آپ کو اسٹاک پر ٹپ پیش کرتا ہے، تو آپ کا اصل انتخاب نہ صرف یہ ہوتا ہے کہ کیا تجارت کرنی ہے بلکہ کیسے۔ ایک ہی درست سمت مستقبل کے طور پر جیت سکتی ہے اور ایک آپشن کے طور پر ہار سکتی ہے اگر حرکت چھوٹی اور سست ہے، یا ایک آپشن کے طور پر تیز ڈپ سے بچ سکتی ہے جبکہ مستقبل کو مارجن کال پر روک دیا جاتا ہے۔ آلہ کو اپنے نقطہ نظر، اپنے اعصاب، اور نقد رقم سے جوڑیں جو آپ واقعی کھونے کے متحمل ہوسکتے ہیں، اور آپ نے پہلے ہی زیادہ تر مارکیٹ سے زیادہ سوچ بچار کر لی ہے۔</p>\n","toc":[{"level":2,"text":"ایک ہی نقطہ نظر کو واپس کرنے کے تین طریقے","id":"three-ways-to-back-the-same-view"},{"level":2,"text":"اسٹاک: سب سے آسان، لکیری، پوری قیمت","id":"the-stock-simplest-linear-full-price"},{"level":2,"text":"مستقبل: بیعانہ، اب بھی لکیری، روزانہ نشان زد","id":"the-future-leverage-still-linear-marked-daily"},{"level":2,"text":"اختیار: جھکا ہوا اور غیر متناسب","id":"the-option-bent-and-asymmetric"},{"level":2,"text":"تین طرفہ میز","id":"the-three-way-table"},{"level":2,"text":"افسانہ کو ختم کرنا: ایک آپشن صرف ایک سستا مستقبل نہیں ہے۔","id":"busting-the-myth-an-option-is-not-just-a-cheaper-future"},{"level":2,"text":"آگے کیا لے جانا ہے۔","id":"what-to-carry-forward"}],"imgCount":1,"hasContent":true},"4":{"html":"<p>تجارتی اسکرین پر عجیب و غریب ناموں اور نمبروں کی دیوار کی وجہ سے اختیارات باہر سے پیچیدہ نظر آتے ہیں۔ سچائی نرم ہے۔ پوری مارکیٹ میں صرف دو قسم کے آپشن ہیں، کال اور پوٹ، باقی سب کچھ ان دو اینٹوں سے بنایا گیا ہے۔ Strangle, straddle, spread, condor، ہر وہ فینسی نام جس کے بارے میں آپ نے کبھی پڑھا ہو گا وہ صرف ایک مٹھی بھر کالز اور پوٹس ایک ساتھ رکھے ہوئے ہیں۔ لہذا اگر آپ واقعی ان دو عمارتی بلاکس کو سمجھتے ہیں، تو آپ ہر حکمت عملی کے خام مال کو سمجھتے ہیں۔ یہ باب اس بات کو یقینی بناتا ہے کہ آپ انہیں دوبارہ کبھی الجھائیں نہیں۔</p>\n<h2 id=\"the-call-the-right-to-buy\">کال: خریدنے کا حق</h2>\n<p>اے <strong>کال</strong> ایکسپائری پر سٹرائیک پرائس پر انڈرلائننگ خریدنا حق ہے، لیکن فرض نہیں۔ جب آپ قیمت بڑھنا چاہتے ہیں تو آپ کال کرتے ہیں۔</p>\n<p>RELIANCE کے ساتھ اس کے ذریعے چلیں۔ اسٹاک 25 جون 2026 کو 1,318 روپے پر بند ہوا۔ فرض کریں کہ آپ 1320 کال خریدتے ہیں، مکمل طور پر لکھا ہوا <code>RELIANCE28JUL261320CE</code>تقریباً 31 روپے فی شیئر کے پریمیم کے لیے۔ اب آپ 28 جولائی 2026 کو ختم ہونے پر 1320 پر RELIANCE خریدنے کا حق رکھتے ہیں، اس سے کوئی فرق نہیں پڑتا ہے کہ اس وقت تک اسٹاک کتنا ہی اونچا ہو جائے۔</p>\n<ul>\n<li>اگر RELIANCE 1400 تک پہنچ جاتا ہے، تو آپ کا 1320 پر خریدنے کا حق قیمتی ہے۔ آپ 1320 پر خرید سکتے ہیں اور مارکیٹ 1400 ادا کر رہی ہے، ہر شیئر پر واضح فائدہ۔</li>\n<li>اگر RELIANCE گھٹ کر 1280 پر آجاتا ہے، تو 1320 پر خریدنے کا آپ کا حق بیکار ہے، کیونکہ کوئی بھی 1280 کی قیمت کے لیے 1320 ادا نہیں کرتا ہے۔ آپ کال ختم ہونے دیتے ہیں اور آپ صرف وہی پریمیم کھو دیتے ہیں جو آپ نے ادا کیا تھا۔</li>\n</ul>\n<p>وہ عدم توازن کال کا دل ہے۔ اسٹاک کے بڑھنے کے ساتھ ہی آپ کا فائدہ بڑھتا ہے، جب کہ آپ کا نقصان پریمیم پر محدود ہوجاتا ہے چاہے اسٹاک کتنی ہی دور گرے۔ ایک کال خریدار نیچے کی طرف باڑ لگانے کے دوران الٹا ادائیگی کر رہا ہے۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>ہڑتال پر کال خریدنے کا حق ہے۔ جب آپ قیمت بڑھنے کی توقع کرتے ہیں تو آپ کالز خریدتے ہیں۔ آپ کا منافع اسٹاک کے ساتھ بڑھتا ہے، اور آپ کا نقصان پریمیم تک محدود ہے۔</p>\n</div></div>\n<h2 id=\"the-put-the-right-to-sell\">ڈال: بیچنے کا حق</h2>\n<p>اے <strong>ڈال</strong> ختم ہونے پر سٹرائیک پرائس پر بنیادی کو بیچنا حق ہے، لیکن فرض نہیں۔ جب آپ چاہتے ہیں کہ قیمت کم ہو، یا جب آپ کسی چیز کی حفاظت کرنا چاہتے ہیں تو آپ ایک پوٹ رکھتے ہیں۔</p>\n<p>ایک ہی RELIANCE مثال، دوسری سمت۔ فرض کریں کہ آپ لکھا ہوا 1320 پوٹ خریدتے ہیں۔ <code>RELIANCE28JUL261320PE</code>ایک بار پھر تقریباً 31 روپے فی شیئر کے پریمیم کے لیے۔ اب آپ کے پاس 28 جولائی 2026 کو ختم ہونے پر 1320 پر RELIANCE فروخت کرنے کا حق ہے، چاہے اس وقت تک اسٹاک کتنا ہی کم ہوجائے۔</p>\n<ul>\n<li>اگر RELIANCE 1250 پر آتا ہے، تو آپ کا 1320 پر فروخت کرنے کا حق قیمتی ہے۔ مارکیٹ کی قیمت صرف 1250 ہے، لیکن آپ پھر بھی 1320 پر فروخت کر سکتے ہیں، ہر شیئر پر واضح فائدہ۔</li>\n<li>اگر RELIANCE بڑھ کر 1360 ہو جاتا ہے، تو آپ کا 1320 پر فروخت کرنے کا حق بیکار ہے، کیونکہ آپ 1360 پر کھلی مارکیٹ میں فروخت کرنا پسند کریں گے۔ آپ پوٹ کی میعاد ختم ہونے دیتے ہیں اور آپ صرف پریمیم کھو دیتے ہیں۔</li>\n</ul>\n<p>پوٹ کال کی آئینہ دار تصویر ہے۔ جب اسٹاک بڑھتا ہے تو کال خریدار کو منافع ہوتا ہے۔ جب اسٹاک گرتا ہے تو خریدار کا منافع ہوتا ہے۔ دونوں کے پاس یکساں سکون ہے، پریمیم کے حساب سے نقصان۔</p>\n\n<div class=\"callout example\"><span class=\"callout-tag\">حقیقی مثال</span><div><p>ایک ہی اسٹاک، وہی ہڑتال، وہی ایکسپائری، ایک ہی پریمیم تقریباً 31 روپے فی شیئر۔ اگر RELIANCE ہڑتال کے اوپر چڑھ جائے تو 1320 کال ادا ہو جاتی ہے۔ اگر RELIANCE اس سے نیچے گرتا ہے تو 1320 پوٹ ادا کرتا ہے۔ صرف ایک چیز جس کا آپ نے انتخاب کیا ہے وہ ہے سمت۔</p>\n</div></div>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>ہندوستانی ایکسچینج ٹریڈڈ اختیارات یورپی طرز کے ہیں۔ خریدار کا حق ختم ہونے پر طے ہوتا ہے، جلد استعمال نہیں کیا جاتا۔ میعاد ختم ہونے سے پہلے آپ منافع لینے کے لیے ورزش نہیں کرتے۔ آپ اپنے خریدے ہوئے آپشن کو بیچ کر، یا جو آپ نے بیچا ہے اسے واپس خرید کر آپ صرف مارکیٹ میں پوزیشن کو بند کر دیتے ہیں۔ لہذا \"ایکسپائری کے وقت\" بیان کرتا ہے جب حق کا تصفیہ ہوتا ہے، جب کہ آپ اس سے پہلے کسی بھی وقت آپشن کے اندر اور باہر تجارت کرنے کے لیے آزاد رہتے ہیں۔</p>\n</div></div>\n<h2 id=\"a-memory-aid-you-will-never-forget\">ایک میموری امداد جسے آپ کبھی نہیں بھولیں گے۔</h2>\n<p>مبتدی کالوں کو ملاتے ہیں اور لگاتار کرتے ہیں، عام طور پر تیز بازار کی گرمی میں جب یہ سب سے اہم ہوتا ہے۔ ان ایڈز میں سے ایک کو نیچے رکھیں اور الجھن ختم ہو جاتی ہے۔</p>\n<ul>\n<li>الفاظ پر غور کریں۔ آپ <strong>کال کریں</strong> ایک دوست، تو ایک <strong>کال</strong> آپ کی شرط ہے کہ قیمت جاتی ہے <strong>اوپر</strong>. آپ <strong>نیچے رکھو</strong> ایک پارسل، تو ایک <strong>ڈال</strong> آپ کی شرط ہے کہ قیمت جاتی ہے <strong>نیچے</strong>. کال کریں، نیچے رکھیں۔</li>\n<li>عمل کے بارے میں سوچو۔ ایک کال آپ کو حصص خریدنے کے لیے کال کرنے دیتی ہے۔ ایک پوٹ آپ کو حصص کو فروخت کرنے کے لیے، دور رکھنے دیتا ہے۔</li>\n<li>علامت کے بارے میں سوچو۔ <strong>CE</strong> کال کی علامت کو ختم کرتا ہے، <strong>PE</strong> پوٹ کی علامت کو ختم کرتا ہے۔ کال کے لیے C، پوٹ کے لیے P، اور خرید و فروخت وہاں سے ہوتی ہے۔</li>\n</ul>\n<p>جو بھی لاٹھی استعمال کریں۔ زیادہ تر تاجر کال اپ پر طے پاتے ہیں، ایک دن کے اندر اندر رکھ دیتے ہیں اور کبھی پیچھے مڑ کر نہیں دیکھتے ہیں۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-basics/images/diagram-calls-and-puts.png\" alt=\"کال قیمت بڑھنے پر خریدنے اور منافع حاصل کرنے کا حق ہے، جب کہ پوٹ فروخت کرنے کا حق ہے اور قیمت گرنے پر منافع، ساتھ ساتھ دکھایا گیا ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>کال قیمت بڑھنے پر خریدنے اور منافع حاصل کرنے کا حق ہے، جب کہ پوٹ فروخت کرنے کا حق ہے اور قیمت گرنے پر منافع، ساتھ ساتھ دکھایا گیا ہے۔</figcaption></figure>\n<h2 id=\"when-would-you-want-each\">آپ ہر ایک کو کب چاہیں گے؟</h2>\n<p>تعریفیں جاننا ایک چیز ہے۔ یہ جاننا کہ ہر ایک تک کب پہنچنا ہے وہی چیز انہیں مفید بناتی ہے۔ یہاں سادہ زبان کا گائیڈ ہے۔</p>\n<p>آپ ایک خریدتے ہیں <strong>کال</strong> جب:</p>\n<ul>\n<li>آپ کو یقین ہے کہ میعاد ختم ہونے سے پہلے بنیادی معنی میں اضافہ ہوگا۔</li>\n<li>آپ حصص کی پوری قیمت ادا کیے بغیر اس اضافے کی نمائش چاہتے ہیں۔</li>\n<li>آپ اپنے خطرے کو طے کرنا چاہتے ہیں اور پہلے سے معلوم ہونا چاہتے ہیں، پریمیم کی حد تک۔</li>\n</ul>\n<p>آپ ایک خریدتے ہیں۔ <strong>ڈال</strong> جب:</p>\n<ul>\n<li>آپ کو یقین ہے کہ بنیادی ختم ہونے سے پہلے معنی خیز طور پر گر جائے گا۔</li>\n<li>آپ پہلے سے ہی حصص کے مالک ہیں اور ایک ڈراپ کے خلاف انشورنس چاہتے ہیں، جس طرح سے آپ گاڑی کا بیمہ کرواتے ہیں آپ اب بھی چلاتے ہیں۔</li>\n<li>آپ اس تحفظ کے لیے ایک متعین، محدود لاگت چاہتے ہیں۔</li>\n</ul>\n<p>نوٹ کریں کہ ہر قسم کے تحت دونوں وجوہات انہی دو مقاصد پر واپس آتی ہیں جن سے ہم پہلے باب میں ملے تھے: سستے دشاتمک نظارے کی حمایت کرنا، اور تحفظ خریدنا۔ کال ایک اپ ویو کا بیک اپ کرتی ہے یا مختصر پوزیشن کا بیمہ کرتی ہے۔ ایک پوٹ نیچے کے نظارے کی پشت پناہی کرتا ہے یا آپ کے پاس موجود حصص کی بیمہ کرتا ہے۔ دو اوزار، چار عام کام۔</p>\n<p>یہ سادہ نمبروں میں ہم آہنگی کو دیکھنے میں بھی مدد کرتا ہے۔ RELIANCE 1320 کال اور 1320 پوٹ دونوں کی قیمت ایک ہی پریمیم کے لگ بھگ ہے، تقریباً 31 روپے فی شیئر، جب اسٹاک ان کے درمیان 1,318 پر بیٹھتا ہے۔ یہ کوئی اتفاق نہیں ہے۔ موجودہ قیمت کے قریب سٹرائیک متوازن ہونے کے ساتھ، مارکیٹ اگلے 32 دنوں میں اوپر کی حرکت اور نیچے کی حرکت کا اندازہ لگاتی ہے، اس لیے یہ ہر حق کے لیے ایک جیسی قیمت وصول کرتی ہے۔ اس لیے پوٹ پر کال کا انتخاب سمت کا خالص بیان ہے، قدر کا نہیں۔ آپ سستا ٹکٹ نہیں لے رہے ہیں۔ آپ یہ انتخاب کر رہے ہیں کہ آپ کے خیال میں 28 جولائی سے پہلے RELIANCE کا سفر کیا ہے۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>اختیارات کو اچھی طرح استعمال کرنے کے لیے آپ کو کرسٹل گیند سے سمت کا اندازہ لگانے کی ضرورت نہیں ہے۔ آپ کو صرف ایک نقطہ نظر کی ضرورت ہے، نیز ایک ایماندارانہ احساس کی ضرورت ہے کہ یہ اقدام کتنی دور اور کتنی تیزی سے آسکتا ہے، کیونکہ آپ جو پریمیم پہلے سے ہی کچھ متوقع حرکت میں ادا کرتے ہیں</p>\n</div></div>\n<h2 id=\"two-bricks-every-building\">دو اینٹیں، ہر عمارت</h2>\n<p>یہ دہرانے کے قابل ہے کہ یہ دو ٹکڑے کیوں اتنے اہم ہیں۔ وجود میں موجود ہر آپشن پوزیشن کالز خریدنے، کالز فروخت کرنے، پوٹس خریدنے اور پوٹس کی فروخت کا کچھ مجموعہ ہے۔ یہ پورا ٹول باکس ہے۔ جب آپ بعد میں کسی ڈرانے والے نام کے ساتھ حکمت عملی کے بارے میں پڑھتے ہیں، تو آپ اسے ہمیشہ ان چار بنیادی کاموں میں الگ کر سکتے ہیں اور اسے سمجھ سکتے ہیں۔</p>\n<ul>\n<li>ایک حفاظتی پوزیشن حصص پلس ایک ڈال ہے.</li>\n<li>ایک ایسی پوزیشن جو کسی بھی سمت میں ایک بڑی حرکت سے فائدہ اٹھاتی ہے کال پلس پوٹ ہے۔</li>\n<li>ایک ایسی پوزیشن جو پرسکون مارکیٹ میں پریمیم حاصل کرتی ہے وہ سیلڈ کال یا سیلڈ پوٹ ہے۔</li>\n</ul>\n<p>اس کے بعد آنے والے حکمت عملی کورس میں آپ ان سب کو مناسب طریقے سے پورا کریں گے۔ یہاں بات یہ ہے کہ آپ درجنوں غیر متعلقہ چیزیں نہیں سیکھ رہے ہیں۔ آپ دو سیکھ رہے ہیں، کال اور پوٹ، اور پھر ان کو ترتیب دینے کا طریقہ سیکھ رہے ہیں۔ اینٹوں میں مہارت حاصل کریں اور عمارتیں آسانی سے آتی ہیں۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>کال یا پوٹ خریدنا سب سے آسان تجارت ہے اور آہستہ آہستہ پیسہ کھونے کا سب سے آسان طریقہ۔ اسٹاک کو کافی حد تک منتقل ہونا پڑے گا، اور جلد ہی، آپ کے ادا کردہ پریمیم کو شکست دینے کے لیے، جب کہ وقت خاموشی سے آپ کے خلاف کام کرتا ہے۔ سستے، دور دراز کے اختیارات کے زیادہ تر خریدار ہار جاتے ہیں۔ ہم بعد کے ابواب میں بالکل کیوں مطالعہ کریں گے، تاکہ آپ کھلی آنکھوں کے ساتھ اندر جائیں۔</p>\n</div></div>\n<h2 id=\"what-to-carry-forward\">آگے کیا لے جانا ہے</h2>\n<p>اب آپ کے پاس پوری آپشنز کی دنیا کے دو بلڈنگ بلاکس ہیں۔</p>\n<ul>\n<li>اے <strong>کال</strong> ہڑتال پر خریدنے کا حق ہے. جب آپ کو قیمت بڑھنے کی توقع ہو تو کالز خریدیں۔ CE ایک کال کو نشان زد کرتا ہے۔</li>\n<li>اے <strong>ڈال</strong> ہڑتال پر فروخت کرنے کا حق ہے. جب آپ کو قیمت گرنے کی توقع ہو، یا آپ کے اپنے حصص کی بیمہ کرنے کے لیے پوٹس خریدیں۔ PE ایک پوٹ کو نشان زد کرتا ہے۔</li>\n<li>دونوں پریمیم پر خریدار کے نقصان کو پورا کرتے ہیں، ہماری چل رہی مثال میں RELIANCE 1320 اختیارات کے لیے تقریباً 31 روپے فی شیئر۔</li>\n<li>کال کریں، نیچے رکھیں۔ اس چھوٹی سی شاعری کو ہر بار سمت طے کرنے دو۔</li>\n</ul>\n<p>اگلے باب میں ہم سست کرتے ہیں اور تین نمبروں پر سختی سے نظر ڈالتے ہیں جو کسی بھی آپشن کی وضاحت کرتے ہیں: پریمیم جو آپ ادا کرتے ہیں، اسٹرائیک جو آپ لاک کرتے ہیں، اور ایکسپائری جس کے بارے میں آپ کو فیصلہ کرنا ہوگا۔ آپ تینوں سے مل چکے ہیں۔ اب ہم انہیں درست بناتے ہیں، اور ہم ایک حقیقی RELIANCE علامت کو ٹکڑے ٹکڑے کرکے پڑھتے ہیں۔</p>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">کیا آپ جانتے ہیں؟</span><div><p>ہندوستانی اسٹاک کے اختیارات کا تصفیہ انڈرلائننگ کے مقابلے میں نقد میں کیا جاتا ہے، اور ہر معاہدہ ایک مقررہ لاٹ پر محیط ہوتا ہے، RELIANCE کے لیے 500 شیئرز۔ لہٰذا ایک پریمیم تقریباً 31 روپے فی شیئر کے طور پر ادا کیا جاتا ہے جو کہ ایک لاٹ کال یا پوٹ کے لیے تقریباً 15,590 روپے ادا کیا جاتا ہے۔ اس فی شیئر کو فی لاٹ کے فرق کو ذہن میں رکھیں۔ یہ تقریباً ہر ابتدائی کو ایک بار ٹرپ کرتا ہے۔</p>\n</div></div>\n","toc":[{"level":2,"text":"کال: خریدنے کا حق","id":"the-call-the-right-to-buy"},{"level":2,"text":"ڈال: بیچنے کا حق","id":"the-put-the-right-to-sell"},{"level":2,"text":"ایک میموری امداد جسے آپ کبھی نہیں بھولیں گے۔","id":"a-memory-aid-you-will-never-forget"},{"level":2,"text":"آپ ہر ایک کو کب چاہیں گے؟","id":"when-would-you-want-each"},{"level":2,"text":"دو اینٹیں، ہر عمارت","id":"two-bricks-every-building"},{"level":2,"text":"آگے کیا لے جانا ہے","id":"what-to-carry-forward"}],"imgCount":1,"hasContent":true},"5":{"html":"<p>کسی بھی اسٹاک پر، کسی بھی مارکیٹ میں تجارت کی جانے والی ہر آپشن کو صرف تین نمبروں سے پِن کیا جاتا ہے۔ یہ تین حاصل کریں اور آپ کسی بھی معاہدے کو پڑھ سکتے ہیں، کسی بھی دو اختیارات کا موازنہ کر سکتے ہیں، اور اسکرین پر موجود کسی بھی اقتباس کو سمجھ سکتے ہیں۔ یہ وہ پریمیم ہیں جو آپ ادا کرتے ہیں، وہ ہڑتال جسے آپ لاک کرتے ہیں، اور وہ میعاد ختم ہوتی ہے جس کے بارے میں آپ کو فیصلہ کرنا ہوگا۔ آپ فلیٹ اور ٹوکن کی کہانی میں پہلے ہی گزرتے ہوئے تینوں سے مل چکے ہیں۔ اب ہم ان کو درست بناتے ہیں، کیونکہ ان تینوں کی مبہم گرفت وہیں سے ہوتی ہے جہاں سے زیادہ تر ابتدائی غلطیاں شروع ہوتی ہیں۔ اس باب کے اختتام تک آپ ایک حقیقی RELIANCE اختیار کی علامت لے سکیں گے اور اسے اس طرح پڑھ سکیں گے جس طرح آپ تاریخ پڑھتے ہیں۔</p>\n<h2 id=\"premium-the-price-of-the-right\">پریمیم: حق کی قیمت</h2>\n<p>دی <strong>پریمیم</strong> وہ قیمت ہے جسے آپ اختیار رکھنے کے لیے ادا کرتے ہیں۔ یہ فلیٹ کی کہانی سے ٹوکن منی ہے، انتخاب کی قیمت۔ خریدار کے لیے، پریمیم بھی سب سے زیادہ ہے جسے آپ کبھی کھو سکتے ہیں، جو کہ تمام اختیارات میں واحد سب سے زیادہ یقین دلانے والی حقیقت ہے۔</p>\n<p>ایک پریمیم ہمیشہ حوالہ دیا جاتا ہے۔ <strong>فی شیئر</strong>، لیکن آپ اسے ادا کرتے ہیں۔ <strong>فی لاٹ</strong>. یہ وہ کیچ ہے جو ہر نئے آنے والے کو حیران کر دیتا ہے، تو آئیے اب اسے کیل دیں۔ ہماری چل رہی مثال میں RELIANCE 1320 کال تقریباً 31 روپے فی شیئر کا پریمیم رکھتی ہے۔ ایک RELIANCE معاہدہ 500 حصص کی ایک مقررہ لاٹ ہے۔ لہذا اصل نقد جو آپ کے اکاؤنٹ میں ایک لاٹ کے لیے چھوڑتا ہے وہ ہے 31 روپے گنا 500، جو کہ تقریباً 15,590 روپے ہے۔</p>\n<ul>\n<li>سکرین 31 روپے دکھاتی ہے۔ یعنی فی شیئر۔</li>\n<li>آپ کا اصل خرچہ 15,590 روپے ہے۔ یہ فی لاٹ ہے، اور یہ وہی ہے جو آپ کھو سکتے ہیں۔</li>\n</ul>\n<p>پریمیم ایک مقررہ اسٹیکر قیمت نہیں ہے۔ جیسے جیسے سٹاک حرکت کرتا ہے، جیسے جیسے ایکسپائری قریب آتی ہے، اور جیسے جیسے مارکیٹ کی نقل و حرکت کی تبدیلی کی توقع ہوتی ہے، یہ دوسرے کے ساتھ آگے بڑھتا ہے۔ ہم بعد کا ایک پورا باب اس بات کے لیے وقف کرتے ہیں کہ پریمیم میں اضافہ اور زوال کیا ہوتا ہے۔ ابھی کے لیے، بنیادی معنی کو پکڑیں: پریمیم وہی ہے جو آپ ادا کرتے ہیں، اور خریدار کے لیے یہ نقصان کی حد ہے۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>پریمیم آپشن کی قیمت ہے۔ یہ فی شیئر کا حوالہ دیا جاتا ہے لیکن فی لاٹ ادا کیا جاتا ہے۔ RELIANCE 1320 آپشن کے لیے تقریباً 31 روپے فی شیئر کا مطلب ہے 500 شیئرز کی ایک لاٹ کے لیے تقریباً 15,590 روپے، اور یہ خریدار کا زیادہ سے زیادہ نقصان ہے۔</p>\n</div></div>\n<h2 id=\"strike-the-locked-price\">ہڑتال: مقفل قیمت</h2>\n<p>دی <strong>ہڑتال</strong>، جسے اسٹرائیک پرائس یا ورزش کی قیمت بھی کہا جاتا ہے، وہ قیمت ہے جس پر معاہدہ آپ کو لین دین کرنے دیتا ہے۔ کال کے لیے یہ وہ قیمت ہے جس پر آپ خرید سکتے ہیں۔ ایک ڈال کے لئے یہ وہ قیمت ہے جس پر آپ بیچ سکتے ہیں۔ فلیٹ کی کہانی میں یہ پچاس لاکھ ہے، جو آپ نے آج طے کیا ہے اور بعد میں جو بھی مارکیٹ کرتا ہے اس پر بھروسہ کر سکتے ہیں۔</p>\n<p>ہماری مثال میں اسٹرائیک 1320 ہے۔ RELIANCE 1,318 روپے پر بند ہوا، اس لیے 1320 اسٹرائیک موجودہ قیمت کے بالکل ساتھ بیٹھتی ہے۔ وہ قربت کوئی حادثہ نہیں ہے۔ موجودہ قیمت کے قریب ترین اسٹرائیک وہ ہے جس سے سب سے زیادہ شروعات کرنے والے شروع کرتے ہیں، اور اس کا ایک نام ہے، جسے ہم پیسے کے باب میں دیکھتے ہیں۔</p>\n<p>ہڑتال کبھی بھی معاہدے کی زندگی میں تبدیل نہیں ہوتی۔ اسٹاک اوپر اور نیچے گھومتا ہے، لیکن 1320 1320 رہتا ہے۔ آپشن کی پوری قیمت اسٹاک کے ختم ہونے اور اس مقررہ ہڑتال کے درمیان فرق سے آتی ہے۔</p>\n<ul>\n<li>ایک 1320 کال صرف اس صورت میں استعمال کرنے کے قابل ہے جب RELIANCE 1320 سے اوپر ختم ہو جائے، کیونکہ تب آپ کی مقفل خرید قیمت مارکیٹ کو ہرا دیتی ہے۔</li>\n<li>1320 پوٹ صرف اس صورت میں استعمال کرنے کے قابل ہے جب RELIANCE 1320 سے نیچے ختم ہو جائے، کیونکہ تب آپ کی بند فروخت کی قیمت مارکیٹ کو ہرا دیتی ہے۔</li>\n</ul>\n<p>سٹرائیکس کی ایک پوری سیڑھی دستیاب ہے، نہ صرف 1320۔ آپ 1300، 1340، 1360 اور بہت کچھ پر ڈیل کرنے کا حق خرید سکتے ہیں۔ ہر ہڑتال ایک مختلف پریمیم کے ساتھ ایک مختلف آپشن ہے، کیونکہ ہر ایک مختلف ڈیل کی نمائندگی کرتا ہے۔ آپ جس ہڑتال کا انتخاب کرتے ہیں اس سے ظاہر ہوتا ہے کہ آپ کا نظریہ کتنا جارحانہ یا محتاط ہے۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>موجودہ قیمت سے کہیں زیادہ ہڑتال سستی ہے، کیونکہ اسے ادائیگی کے لیے بڑے اقدام کی ضرورت ہے۔ موجودہ قیمت کے قریب ہڑتال کی قیمت زیادہ ہے، کیونکہ یہ مفید ہونے کے قریب ہے۔ پریمیم ہمیشہ اس بات کی عکاسی کرتا ہے کہ اس وقت ہڑتال کتنی اچھی ڈیل ہے۔</p>\n</div></div>\n<h2 id=\"expiry-the-deadline\">میعاد ختم: آخری تاریخ</h2>\n<p>دی <strong>میعاد ختم</strong> آپشن کے مرنے کی تاریخ ہے۔ اس کے بعد حق صرف ختم ہو جاتا ہے۔ یہ فلیٹ اسٹوری میں تین ماہ کی کھڑکی ہے، آخری تاریخ جس کے ذریعے آپ کو عمل کرنے یا وہاں سے جانے کا فیصلہ کرنا ہوگا۔</p>\n<p>ہماری مثال میں ایکسپائری 28 جولائی 2026 ہے۔ 25 جون 2026 کی مثال کے ساتھ، یہ تقریباً 32 دن دور ہے۔ آپشن ان 32 دنوں تک زندہ رہتا ہے اور ایک لمحہ بھی زیادہ نہیں۔ میعاد ختم ہونے کے دن، معاہدہ طے پا جاتا ہے اور ختم ہو جاتا ہے۔</p>\n<p>NSE اختیارات، جہاں RELIANCE، NIFTY اور BANKNIFTY تجارت کرتے ہیں، اب ایک پر طے پاتے ہیں۔ <strong>منگل</strong>، اور 28 جولائی 2026 اس مہینے کا آخری منگل ہے، ماہانہ ایکسپائری ہے۔ BSE مشتقات جیسے کہ SENSEX بجائے جمعرات کو طے پاتے ہیں، لیکن اس کورس میں ہر مثال NSE آلہ استعمال کرتی ہے، اس لیے ہماری میعاد ہمیشہ منگل کو ہوتی ہے۔</p>\n<p>وقت یہاں غیر جانبدار پس منظر نہیں ہے۔ یہ ان قوتوں میں سے ایک ہے جو پریمیم کو منتقل کرتی ہے، اور خریدار کے لیے یہ آپ کے خلاف کام کرتی ہے۔ چلانے کے لیے 32 دن کے ساتھ، RELIANCE کے لیے آپ کے راستے پر چلنے کے لیے کافی وقت ہے، اور پریمیم اس امید کی عکاسی کرتا ہے۔ جیسے جیسے دن ڈھلتے جاتے ہیں، یہ امید سکڑتی جاتی ہے، اور پریمیم کا ایک حصہ جسے ٹائم ویلیو کہتے ہیں پگھل جاتا ہے۔ 28 جولائی کے قریب، یہ اتنی ہی تیزی سے پگھلتا ہے۔ اس سست خون کو بعد کا ایک پورا باب دیا جاتا ہے، کیونکہ یہ ہر آپشن خریدنے والے کا خاموش دشمن ہے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>وقت بیچنے والے کی طرف ہے، خریدار کا نہیں۔ ہر وہ دن جو اسٹاک کے کہیں نہ جانے کے ساتھ گزرتا ہے، آپ کے ادا کردہ پریمیم کا ایک حصہ بخارات بن جاتا ہے۔ آپشن ان چند چیزوں میں سے ایک ہے جو آپ خرید سکتے ہیں جس کی قیمت کل صرف اس لیے کم ہے کہ کل آ گیا ہے۔</p>\n</div></div>\n<h2 id=\"reading-a-real-reliance-symbol\">ایک حقیقی RELIANCE علامت پڑھنا</h2>\n<p>ہندوستانی آپشن سمبل ان سب کو ایک صاف ستھرا تار میں پیک کرتے ہیں۔ ہماری کال یہ ہے:</p>\n<p><code>RELIANCE28JUL261320CE</code></p>\n<p>یہ تب تک گڑبڑ کی طرح لگتا ہے جب تک کہ آپ پیٹرن نہیں سیکھتے، جو ہمیشہ ایک جیسا ہوتا ہے: بنیادی نام، پھر میعاد ختم ہونے کی تاریخ، پھر ہڑتال، پھر ٹائپ کریں۔ اسے سیون پر توڑ دو۔</p>\n<ul>\n<li><strong>RELIANCE</strong> بنیاد ہے، بنیادی اسٹاک جس پر آپشن لکھا ہوا ہے۔</li>\n<li><strong>28 جولائی26</strong> میعاد ختم ہونے کی تاریخ ہے، 28 جولائی 2026، دن، مہینہ، سال کے طور پر لکھا گیا ہے۔</li>\n<li><strong>1320</strong> ہڑتال ہے، مقفل قیمت۔</li>\n<li><strong>CE</strong> قسم ہے، جہاں CE کا مطلب ہے کال۔ مماثل پٹ PE میں ختم ہوگا۔</li>\n</ul>\n<p>لہذا پوری علامت اس طرح پڑھتی ہے: RELIANCE کال جو آپ کو 28 جولائی 2026 تک 1320 پر خریدنے دیتی ہے۔ پوٹ ورژن، <code>RELIANCE28JUL261320PE</code>, یکساں طور پر پڑھتا ہے سوائے اس کے کہ یہ آپ کو 1320 پر فروخت کرنے دیتا ہے۔ ایک ہی بنیاد، وہی تاریخ، ایک ہی ہڑتال، صرف آخری دو حروف خرید سے فروخت کے معنی کو پلٹ دیتے ہیں۔</p>\n<p>ایک بار جب آپ چار حصوں کو دیکھتے ہیں، ہر اختیاری علامت پڑھنے کے قابل ہو جاتا ہے. پیٹرن کبھی نہیں بدلتا۔ نام تلاش کریں، تاریخ تلاش کریں، ہڑتال تلاش کریں، CE یا PE تلاش کریں، اور آپ کے پاس پورا معاہدہ ہے۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-basics/images/diagram-premium-strike-expiry.png\" alt=\"تین نمبر جو ہر آپشن کی وضاحت کرتے ہیں وہ ہیں پریمیم، اسٹرائیک اور ایکسپائری، جو یہاں RELIANCE علامت کے ساتھ اس کی بنیاد، تاریخ، ہڑتال اور قسم میں ٹوٹے ہوئے ہیں۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>تین نمبر جو ہر آپشن کی وضاحت کرتے ہیں وہ ہیں پریمیم، اسٹرائیک اور ایکسپائری، جو یہاں RELIANCE علامت کے ساتھ اس کی بنیاد، تاریخ، اسٹرائیک اور قسم میں ٹوٹے ہوئے ہیں۔</figcaption></figure>\n<h2 id=\"how-the-three-numbers-interact\">تین نمبر کس طرح تعامل کرتے ہیں۔</h2>\n<p>پریمیم، ہڑتال اور ایکسپائری تین الگ الگ حقائق نہیں ہیں۔ وہ ایک دوسرے کو کھینچتے ہیں، اور دیکھتے ہیں کہ کس طرح کتابی علم کو حقیقی سمجھ میں بدل دیتا ہے۔</p>\n<ul>\n<li>منتقل کریں <strong>ہڑتال</strong> موجودہ قیمت کے قریب اور پریمیم بڑھتا ہے، کیونکہ آپشن استعمال کرنے کے قابل ہونے کے قریب ہے۔ اسے مزید دور منتقل کریں اور پریمیم گر جائے گا۔</li>\n<li>کھینچنا <strong>میعاد ختم</strong> مزید باہر اور پریمیم بڑھتا ہے، کیونکہ زیادہ وقت کا مطلب ہے کہ اسٹاک کے لیے آپ کے راستے کو منتقل کرنے کا زیادہ موقع۔ اسے مختصر کریں اور پریمیم گر جائے گا۔</li>\n<li>دی <strong>پریمیم</strong> اس ڈیل پر مارکیٹ کی چلتی قیمت کا ٹیگ ہے جسے ہڑتال اور ایکسپائری بیان کرتی ہے۔ یہ ایک نمبر ہے جو ہر وقت حرکت کرتا ہے۔ ہڑتال اور ختم ہونے کا معاہدہ کی زندگی کے لئے مقرر کیا گیا ہے.</li>\n</ul>\n<p>اسے ایک سادہ توازن سمجھیں۔ ہڑتال اور ختم ہونے سے معاہدے کی شرائط طے ہوتی ہیں۔ پریمیم وہی ہے جو اس وقت ان شرائط کے قابل ہے۔ جب آپ ایک آپشن کا انتخاب کرتے ہیں، تو آپ واقعی اسٹرائیک اور ایکسپائری کا انتخاب کر رہے ہوتے ہیں جو آپ کے نقطہ نظر سے مماثل ہو، اور پھر مارکیٹ اس امتزاج کے لیے جو بھی پریمیم کہے اسے ادا کر رہے ہوں۔</p>\n\n<div class=\"callout example\"><span class=\"callout-tag\">حقیقی مثال</span><div><p>RELIANCE 28 جولائی 2026 کو ختم ہونے والی 1320 کال کی قیمت تقریباً 31 روپے فی شیئر ہے جس میں 32 دن باقی ہیں۔ بہت جلد ختم ہونے والی 1320 کال کی لاگت کم ہوگی، کیونکہ صحیح ہونے کے لیے کم وقت ہے۔ 1280 کی ہڑتال، مفید ہونے کی طرف گہری، زیادہ لاگت آئے گی۔ ایک ہی اسٹاک، مختلف شرائط، مختلف قیمت۔</p>\n</div></div>\n<h2 id=\"what-to-carry-forward\">آگے کیا لے جانا ہے</h2>\n<p>اب آپ مارکیٹ میں کسی بھی آپشن کو پڑھ سکتے ہیں، کیونکہ ہر آپشن صرف ان تین نمبروں پر مشتمل ہوتا ہے جو ایک بنیادی کے گرد لپیٹے جاتے ہیں۔</p>\n<ul>\n<li>دی <strong>پریمیم</strong> وہ قیمت ہے جو آپ ادا کرتے ہیں، فی شیئر کوٹڈ، فی لاٹ ادا کی جاتی ہے، تقریباً 31 روپے فی شیئر اور 15,590 روپے یہاں بہت زیادہ ہے، اور یہ خریدار کا زیادہ سے زیادہ نقصان ہے۔</li>\n<li>دی <strong>ہڑتال</strong> ہماری مثال میں مقفل قیمت، 1320 ہے، جو معاہدے کی پوری زندگی کے لیے مقرر ہے۔</li>\n<li>دی <strong>میعاد ختم</strong> آخری تاریخ ہے، 28 جولائی 2026، تقریباً 32 دن بعد، جس کے بعد حق غائب ہو جاتا ہے۔</li>\n<li>جیسی علامت <code>RELIANCE28JUL261320CE</code> بس بیس، تاریخ، ہڑتال اور اس ترتیب میں ایک ساتھ ٹائپ کریں۔</li>\n</ul>\n<p>اس کے بعد ہم ایک خصوصیت کو قریب سے دیکھتے ہیں جو تمام مالیاتی آلات میں اختیارات کو خاص بناتی ہے: حق، ذمہ داری نہیں۔ ہم بالکل یہ دیکھیں گے کہ کیوں ایک خریدار محدود نقصان کے ساتھ آسانی سے سو سکتا ہے، اور کیوں بیچنے والا دوسری طرف لینے اور ایسا کرنے کے لیے پریمیم جمع کرنے کو تیار ہے۔</p>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">کیا آپ جانتے ہیں؟</span><div><p>معاہدے کے بننے کے وقت ہڑتال اور میعاد ختم ہو جاتی ہے۔ صرف پریمیم دن بھر تبدیل ہوتا ہے۔ اس لیے جب تاجر کہتے ہیں کہ کوئی آپشن \"اوپر گیا\" یا \"ونٹ نیچے\"، وہ ہمیشہ اس کے پریمیم کے بارے میں بات کرتے ہیں، اس کی ہڑتال کے بارے میں کبھی نہیں۔</p>\n</div></div>\n","toc":[{"level":2,"text":"پریمیم: حق کی قیمت","id":"premium-the-price-of-the-right"},{"level":2,"text":"ہڑتال: مقفل قیمت","id":"strike-the-locked-price"},{"level":2,"text":"میعاد ختم: آخری تاریخ","id":"expiry-the-deadline"},{"level":2,"text":"ایک حقیقی RELIANCE علامت پڑھنا","id":"reading-a-real-reliance-symbol"},{"level":2,"text":"تین نمبر کس طرح تعامل کرتے ہیں۔","id":"how-the-three-numbers-interact"},{"level":2,"text":"آگے کیا لے جانا ہے","id":"what-to-carry-forward"}],"imgCount":1,"hasContent":true},"6":{"html":"<p>ایک خصوصیت ہے جو آپشنز کو ہر چیز سے مختلف بناتی ہے جو آپ تجارت کر سکتے ہیں، اور یہ اس چھوٹے سے فقرے کے اندر چھپا ہوا ہے جسے ہم دہراتے رہتے ہیں: حق، ذمہ داری نہیں۔ یہ ایک قانونی نیکی کی طرح لگتا ہے۔ یہ اصل میں پوری وجہ کے اختیارات موجود ہیں. وہ واحد ہم آہنگی، جہاں ایک فریق کو انتخاب کرنا پڑتا ہے اور دوسرے فریق کو اس کی تعمیل کرنی چاہیے، یہ شکل دیتا ہے کہ ہر آپشن کس طرح برتاؤ کرتا ہے، خریدار کے نقصان کو کیوں محدود کیا جاتا ہے، بیچنے والا سامنے سے ادائیگی کا مطالبہ کیوں کرتا ہے، اور دونوں فریق ایک ہی معاہدے کو اتنا مختلف کیوں دیکھتے ہیں۔ یہ باب اسی ایک خیال پر سست ہو جاتا ہے، کیونکہ ایک بار جب آپ اسے صحیح معنوں میں محسوس کر لیتے ہیں، تو باقی آپشنز اپنی جگہ پر آ جاتے ہیں۔</p>\n<h2 id=\"two-sides-two-very-different-deals\">دو طرفہ، دو بہت مختلف سودے</h2>\n<p>ہر آپشن کے پیچھے دو لوگ ہوتے ہیں۔ وہاں ہے <strong>خریدار</strong>اسے ہولڈر بھی کہا جاتا ہے، جو پریمیم ادا کرتا ہے اور حق وصول کرتا ہے۔ اور وہاں ہے <strong>بیچنے والا</strong>، اسے مصنف بھی کہا جاتا ہے، جو پریمیم جمع کرتا ہے اور ذمہ داری قبول کرتا ہے۔ ایک ہی معاہدہ ان میں سے ایک کو انتخاب دیتا ہے اور دوسرے کو پابند کرتا ہے۔</p>\n<ul>\n<li>دی <strong>خریدار</strong> حق رکھتا ہے. پریمیم ادا کرنے کے بعد، خریدار کارروائی کر سکتا ہے یا چلا سکتا ہے۔ کوئی چیز خریدار کو کچھ کرنے پر مجبور نہیں کرتی۔</li>\n<li>دی <strong>بیچنے والا</strong> ایک فرض ہے. پریمیم جیب میں ڈالنے کے بعد، بیچنے والے کو وہی کرنا چاہیے جیسا کہ خریدار فیصلہ کرتا ہے۔ اگر خریدار لین دین کا انتخاب کرتا ہے، تو بیچنے والے کو اس کا احترام کرنا ہوگا۔</li>\n</ul>\n<p>یہ کوائن ٹاس کی طرح منصفانہ، ہم آہنگ شرط نہیں ہے جہاں دونوں فریقوں کو ایک جیسے نتائج کا سامنا کرنا پڑتا ہے۔ یہ جان بوجھ کر ایک طرفہ ہے. خریدار نے انتخاب کے استحقاق کے لیے ادائیگی کی ہے، اور بیچنے والے کو اس انتخاب کو ترک کرنے کے لیے ادائیگی کی گئی ہے۔ اختیارات کے بارے میں باقی سب کچھ اس بے رخی سے نکلتا ہے۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-basics/images/diagram-right-not-obligation.png\" alt=\"خریدار کے پاس ایک حق ہے اور وہ کام کرنے یا جانے کے لیے آزاد ہے، جبکہ بیچنے والے کے پاس ایک ذمہ داری ہے اور اسے اس کی تعمیل کرنی چاہیے، اس کے بدلے میں سامنے آنے والے پریمیم کے بدلے میں۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>خریدار کے پاس ایک حق ہے اور وہ کام کرنے یا جانے کے لیے آزاد ہے، جبکہ بیچنے والے کے پاس ایک ذمہ داری ہے اور اسے اس کی تعمیل کرنی چاہیے، اس کے بدلے میں سامنے آنے والے پریمیم کے بدلے میں۔</figcaption></figure>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>ایک آپشن ایک طرفہ سودا ہے۔ خریدار پریمیم ادا کرتا ہے اور اسے منتخب کرنے کا موقع ملتا ہے۔ بیچنے والا پریمیم وصول کرتا ہے اور اس کی تعمیل کرنا ضروری ہے۔ وہ توازن ہر آپشن کی وضاحتی خصوصیت ہے۔</p>\n</div></div>\n<h2 id=\"exercise-or-let-it-expire-worthless\">ورزش کریں، یا اسے بیکار ختم ہونے دیں۔</h2>\n<p>جب میعاد ختم ہوجاتی ہے، خریدار کو صرف دو جوابات کے ساتھ ایک سادہ فیصلے کا سامنا کرنا پڑتا ہے۔ یہ وہ جگہ ہے جہاں حق یا تو استعمال ہوتا ہے یا پھینک دیا جاتا ہے۔</p>\n<p>کو <strong>ورزش</strong> ایک اختیار کا مطلب ہے حق استعمال کرنا۔ ایک کال خریدار ہڑتال پر خرید کر مشق کرتا ہے۔ ایک ڈال خریدار ہڑتال پر فروخت کرکے مشق کرتا ہے۔ آپ صرف اس وقت ورزش کرتے ہیں جب وہ ادائیگی کرتا ہے، یعنی جب بند ہڑتال کھلی مارکیٹ کو شکست دیتی ہے۔</p>\n<p>اسے جانے دینا <strong>بیکار ختم</strong> اس کا مطلب ہے کہ کچھ نہ کریں اور حق کو ضائع ہونے دیں۔ آپ اسے اس وقت منتخب کرتے ہیں جب ورزش کرنا بے معنی ہو گا، کیونکہ اوپن مارکیٹ آپ کی ہڑتال سے بہتر ڈیل پیش کرتی ہے۔ آپشن بس ختم ہوجاتا ہے اور آپ اپنی زندگی میں جو کچھ بچا ہے اسے اپنے پاس رکھتے ہیں، صرف پریمیم کھونے کے بعد۔</p>\n<p>RELIANCE 1320 کال کے ساتھ اس کے ذریعے چلیں، تقریباً 31 روپے فی شیئر کے پریمیم میں خریدا گیا۔</p>\n<ul>\n<li>RELIANCE 1400 پر ختم ہوتا ہے۔ 1320 پر خریدنے کا آپ کا حق قیمتی ہے۔ آپ ورزش کرتے ہیں، مؤثر طریقے سے مارکیٹ سے نیچے 80 روپے فی شیئر خریدتے ہیں۔ حق استعمال کرنے کے قابل تھا۔</li>\n<li>RELIANCE 1290 پر ختم ہوتا ہے۔ 1320 پر خریدنے کا آپ کا حق بیکار ہے، کیونکہ اوپن مارکیٹ اسے سستا فروخت کرتی ہے۔ آپ نے آپشن کو بے کار ہونے دیا اور صرف 31 روپے کا حصہ کھو دیا جو آپ نے ادا کیا، تقریباً 15,590 روپے۔</li>\n</ul>\n<p>انڈیکس آپشن کے لیے یہ تصفیہ نقد میں ہوتا ہے، فرق صرف آپ کو ادا کیا جاتا ہے۔ RELIANCE جیسا سنگل اسٹاک آپشن اس کے بجائے حصص کی ڈیلیوری کے ذریعے طے کیا جاتا ہے اگر اسے پیسے میں ختم ہونے تک لے جایا جاتا ہے، لیکن معاشی منطق ایک ہی ہے: آپ کا فائدہ ہڑتال اور مارکیٹ کے درمیان فرق ہے۔ کسی بھی طرح سے، زیادہ تر تاجر تصفیہ سے گزرنے کے بجائے صرف ایکسپائری سے پہلے مارکیٹ میں آپشن کو بند کر دیتے ہیں۔ نقطہ آزادی ہے: آپ کو کبھی بھی ہارنے کا اختیار استعمال کرنے کی ضرورت نہیں ہے۔ وہ آزادی ہے جو آپ کے نقصان کو پورا کرتی ہے۔</p>\n\n<div class=\"callout example\"><span class=\"callout-tag\">حقیقی مثال</span><div><p>1320 کال کا خریدار کبھی بھی پریمیم سے زیادہ نہیں کھوتا۔ چاہے RELIANCE 1300، 1200 یا 1000 پر ختم ہو، جواب یکساں ہے: اسے ختم ہونے دیں، 15,590 روپے کھو دیں، چلیں۔ منفی پہلو کچھ بھی نہ کرنے کے سادہ حق سے بند ہے۔</p>\n</div></div>\n<h2 id=\"reading-the-buyer-s-capped-loss-on-the-payoff\">ادائیگی پر خریدار کے محدود نقصان کو پڑھنا</h2>\n<p>اے <strong>ادائیگی چارٹ</strong> ایک آپشن کا نفع یا نقصان اس کے مقابلے میں کھینچتا ہے جہاں بنیادی ختم ہونے پر ختم ہوتا ہے۔ افقی محور اسٹاک کی قیمت ہے؛ عمودی محور آپ کا روپیہ نتیجہ ہے۔ ایک پڑھنا سیکھنا ایک بنیادی مہارت ہے، اور لمبی کال شروع کرنے کے لیے سب سے دوستانہ جگہ ہے۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-basics/images/payoff-long-call.png\" alt=\"میعاد ختم ہونے پر طویل کال کی ادائیگی: نقصان فلیٹ ہے اور بائیں طرف تقریباً 15,590 روپے کے پریمیم پر محدود ہے، بریک ایون 1351 پر بیٹھتا ہے، اور منافع اس کے اوپر کسی حد کے بغیر بڑھتا ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">چارٹ</span>میعاد ختم ہونے پر طویل کال کی ادائیگی: نقصان فلیٹ ہے اور بائیں طرف تقریباً 15,590 روپے کے پریمیم پر محدود ہے، بریک ایون 1351 پر بیٹھتا ہے، اور منافع اس کے اوپر کسی حد کے بغیر بڑھتا ہے۔</figcaption></figure>\n<p>اسے بائیں سے دائیں پڑھیں۔</p>\n<ul>\n<li>بائیں طرف، جہاں RELIANCE ہڑتال کے نیچے ختم ہوتا ہے، لائن ہے۔ <strong>فلیٹ</strong>. یہ تقریباً 15,590 روپے کے نقصان پر بیٹھا ہے، جو کہ لاٹ کے لیے مکمل پریمیم ہے، اور یہ مزید خراب نہیں ہوتا چاہے آپ کو چھوڑ دیا جائے۔ وہ فلیٹ فلور تصویر کی شکل میں محدود نقصان ہے۔ اس سے کوئی فرق نہیں پڑتا ہے کہ اسٹاک کتنی ہی بری طرح گرتا ہے، خریدار کا درد پریمیم پر رک جاتا ہے۔</li>\n<li>لائن پھر ڈھلوان ہوتی ہے اور صفر کو عبور کرتی ہے۔ <strong>1351</strong>. یہ ہے <strong>breakeven</strong>1320 کی ہڑتال کے علاوہ تقریباً 31 روپے فی شیئر کا پریمیم۔ خریدار کو پریمیم واپس حاصل کرنے کے لیے اسٹاک کو 1351 کلیئر کرنا چاہیے۔ 1351 کے نیچے تجارت اب بھی خالص نقصان ہے، چاہے آپشن کچھ قدر کے ساتھ ختم ہو۔</li>\n<li>1351 کے اوپر لائن بغیر کسی چھت کے چڑھتی رہتی ہے۔ RELIANCE بڑھنے کے ساتھ ہی خریدار کا منافع روپے کے بدلے بڑھتا ہے، جو کہ لامحدود اضافہ ہے جو کالوں کو پرکشش بناتا ہے۔</li>\n</ul>\n<p>پوری شکل غیر متناسب ہے۔ نیچے کی طرف فلیٹ اور کیپ، کھلی اور اوپر کی طرف بڑھ رہی ہے۔ یہ بالکل وہی ہے جو حق، فرض نہیں، آپ کو خریدتا ہے.</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>فلیٹ کیپڈ نقصان آرام دہ ہے، لیکن دیکھیں کہ بریک ایون کہاں بیٹھتا ہے۔ RELIANCE کو 1318 سے 1351 تک، 30 روپے سے زیادہ، خریدار کے ایک روپیہ سے پہلے چڑھنا چاہیے، اور اسے 28 جولائی سے پہلے ایسا کرنا چاہیے۔ حق آپ کو آفات سے بچاتا ہے، لیکن اس سے نفع آسان نہیں ہوتا۔ زیادہ تر کال خریدار اب بھی ہار جاتے ہیں، کیونکہ اسٹاک بروقت بریک ایون کو صاف کرنے میں ناکام رہتا ہے۔</p>\n</div></div>\n<h2 id=\"why-the-seller-collects-the-premium\">بیچنے والا پریمیم کیوں جمع کرتا ہے۔</h2>\n<p>اب دوسری طرف پلٹیں۔ اگر خریدار کو یہ تمام آزادی، محدود نقصانات اور اوپن اپسائیڈ ہو تو کوئی آپشن کیوں بیچے گا؟ جواب پریمیم ہے، اور یہ واضح وجہ سے سامنے جمع کیا جاتا ہے۔</p>\n<p>بیچنے والے کو ناخوشگوار شکل کے ساتھ ڈیوٹی لینے کے لئے ادائیگی کی جارہی ہے۔ اس 1320 کال کو فروخت کریں اور تجارت کے مکمل ہوتے ہی آپ کو تقریباً 15,590 روپے موصول ہوں گے، اور یہ آپ کے پاس ہے۔ بدلے میں آپ نے 1320 پر ڈیلیور کرنے کا وعدہ کیا ہے اگر آپ کو میعاد ختم ہونے پر تفویض کیا گیا ہے۔ اگر RELIANCE 1320 سے اوپر ختم ہوجاتا ہے، تو آپ کو تفویض کیا جاتا ہے اور آپ اس نقصان کو برداشت کرتے ہیں۔ بیچنے والے کا انعام وصول شدہ پریمیم پر محدود ہوتا ہے، جبکہ خطرہ دوسرے طریقے سے چلتا ہے۔</p>\n<p>لہذا پریمیم تحفہ نہیں ہے۔ یہ ایک ذمہ داری کو قبول کرنے کا معاوضہ ہے جس سے بچنے کے لئے خریدار ادا کرنے میں خوش تھا۔ بیچنے والا، درحقیقت، بیمہ کمپنی ہے۔ وہ مستحکم پریمیم جمع کرتے ہیں اور بدلے میں، اگر مارکیٹ ان کے خلاف سخت حرکت کرتی ہے تو وہ بڑی ادائیگی کا خطرہ مول لیتے ہیں۔</p>\n<ul>\n<li>خریدار ایک چھوٹی، مخصوص رقم ادا کرتا ہے اور ایک بڑی، غیر یقینی رقم حاصل کر سکتا ہے۔</li>\n<li>بیچنے والا ایک چھوٹی، مخصوص رقم لیتا ہے اور ایک بڑی، غیر یقینی رقم کھو سکتا ہے۔</li>\n</ul>\n<p>یہی وجہ ہے کہ وقت بیچنے والے کا دوست ہے۔ ہر پرسکون دن جو گزرتا ہے بیچنے والے کو پورا پریمیم رکھنے کے قریب لاتا ہے، جبکہ یہ خریدار کو ایک بیکار، میعاد ختم ہونے والے حق کے قریب لاتا ہے۔ ہم وقت کی قدر کے باب میں اس پیسنے کا تفصیل سے مطالعہ کریں گے۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>اسے یاد رکھنے کا ایک مفید طریقہ: خریدار اختیاری کرایہ پر لیتا ہے اور استحقاق کی ادائیگی کرتا ہے۔ بیچنے والا اختیاری چیز فروخت کرتا ہے اور بوجھ کے لیے ادائیگی کرتا ہے۔ کوئی بھی فریق بے وقوف نہیں ہے۔ وہ صرف اس بارے میں مخالف خیالات رکھتے ہیں کہ آیا یہ اقدام اتنا بڑا ہوگا کہ میعاد ختم ہونے سے پہلے کوئی فرق نہیں پڑے گا۔</p>\n</div></div>\n<h2 id=\"what-to-carry-forward\">آگے کیا لے جانا ہے</h2>\n<p>ہر آپشن کے مرکز میں عدم توازن اب آپ کی ہے۔</p>\n<ul>\n<li>دی <strong>خریدار</strong> پریمیم ادا کرتا ہے اور حق رکھتا ہے۔ خریدار کا نقصان پریمیم پر محدود ہے، تقریباً 15,590 روپے RELIANCE 1320 لاٹ کے لیے، جبکہ الٹا کھلا رہتا ہے۔ یہ لمبی کال کی ادائیگی پر فلیٹ فلور ہے۔</li>\n<li>دی <strong>بیچنے والا</strong> پریمیم جمع کرتا ہے اور ذمہ داری رکھتا ہے۔ بیچنے والے کا فائدہ اس پریمیم پر محدود ہے، جبکہ خطرہ اس سمت میں بہت زیادہ چلتا ہے جس کی خریدار کی امید ہے۔</li>\n<li>میعاد ختم ہونے پر خریدار صرف انتخاب کرتا ہے: <strong>ورزش</strong> جب ہڑتال مارکیٹ کو مار دیتی ہے، یا اسے جانے دو <strong>بیکار ختم</strong> جب ایسا نہیں ہوتا.</li>\n<li>لمبی کال کے لئے بریک ایون بیٹھتا ہے۔ <strong>1351</strong>، ہڑتال کے علاوہ پریمیم فی شیئر۔ محدود نقصان کا مطلب آسان منافع نہیں ہے، اور زیادہ تر خریدار اب بھی بروقت بریک ایون صاف کرنے میں ناکام ہو کر ہار جاتے ہیں۔</li>\n</ul>\n<p>اس کے بعد ہم پیسے کے تین خاندانوں میں اختیارات کو ترتیب دیتے ہیں، پیسے میں، اندر اور باہر، جو آپ کو ایک نظر میں بتاتا ہے کہ آیا کوئی ہڑتال پہلے سے ہی استعمال کرنے کے قابل ہے، موجودہ قیمت پر ٹھیک بیٹھنا، یا پھر بھی خالص امید۔</p>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">کیا آپ جانتے ہیں؟</span><div><p>چونکہ بیچنے والے کے پاس کھلا خطرہ ہوتا ہے، اس لیے فروخت کے اختیارات کے لیے مارجن پوسٹ کرنے کی ضرورت ہوتی ہے، جو ممکنہ نقصانات کے خلاف مارکیٹ میں جمع ہوتا ہے۔ خریدار خود پریمیم سے آگے کوئی مارجن پوسٹ نہیں کرتے ہیں، کیونکہ پریمیم پہلے ہی سب سے زیادہ ہے جس سے وہ کھو سکتے ہیں۔ میکانکس مختلف ہیں کیونکہ خطرات مختلف ہیں۔</p>\n</div></div>\n","toc":[{"level":2,"text":"دو طرفہ، دو بہت مختلف سودے","id":"two-sides-two-very-different-deals"},{"level":2,"text":"ورزش کریں، یا اسے بیکار ختم ہونے دیں۔","id":"exercise-or-let-it-expire-worthless"},{"level":2,"text":"ادائیگی پر خریدار کے محدود نقصان کو پڑھنا","id":"reading-the-buyer-s-capped-loss-on-the-payoff"},{"level":2,"text":"بیچنے والا پریمیم کیوں جمع کرتا ہے۔","id":"why-the-seller-collects-the-premium"},{"level":2,"text":"آگے کیا لے جانا ہے","id":"what-to-carry-forward"}],"imgCount":2,"hasContent":true},"7":{"html":"<p>آپ کی اسکرین پر، ایک NIFTY آپشن اور RELIANCE آپشن جڑواں بچوں کی طرح نظر آتا ہے۔ دونوں کے پاس کالز اور پوٹس ہیں، دونوں میں ہڑتالیں ہیں، دونوں کی میعاد 28 جولائی 2026 ہے، دونوں کا فی شیئر پریمیم کا حوالہ ہے۔ ایک ابتدائی معقول طور پر فرض کرتا ہے کہ وہ اسی طرح کام کرتے ہیں۔ وہ نہیں کرتے، اور فرق ختم ہونے کے دن تک چھپا رہتا ہے، جب یہ آپ پر حملہ کر سکتا ہے۔ ان معاہدوں میں سے ایک، اگر آپ اسے پیسے کے اندر رہتے ہوئے آخر تک رکھتے ہیں، تو خاموشی سے نقد رقم میں طے ہوجاتا ہے۔ دوسرا آپ کے اکاؤنٹ میں ایک کمپنی کے 500 حقیقی حصص ڈال سکتا ہے، اس کے ساتھ کئی لاکھ روپے کا بل بھی ہوسکتا ہے جو آپ کے پاس نہ ہو۔ یہ باب آپ کو دکھاتا ہے کہ ہندوستان میں انڈیکس کے اختیارات اور سنگل اسٹاک آپشنز میں کس طرح فرق ہے، کیوں یہ فرق ختم ہونے پر سب سے زیادہ اہمیت رکھتا ہے، اور وہ سادہ عادت جو آپ کو پریشانی سے دور رکھتی ہے۔</p>\n<h2 id=\"two-families-of-options\">اختیارات کے دو خاندان</h2>\n<p>ہندوستانی اختیارات دو خاندانوں میں آتے ہیں۔ <strong>انڈیکس کے اختیارات</strong> مارکیٹ انڈیکس پر لکھا جاتا ہے جیسے NIFTY، BANKNIFTY، FINNIFTY یا MIDCPNIFTY۔ ایک انڈیکس ایک حسابی نمبر ہے، ایسی چیز نہیں جسے آپ اپنے پاس رکھ سکتے ہیں، لہذا ڈیلیور کرنے کے لیے اس کے پیچھے کوئی شیئرز نہیں ہیں۔ <strong>سنگل اسٹاک کے اختیارات</strong>جسے اسٹاک آپشنز بھی کہا جاتا ہے، ایک انفرادی کمپنی پر لکھا جاتا ہے جیسے RELIANCE، اور ہر معاہدے کے پیچھے اس کمپنی کے حقیقی، ڈیلیوری ایبل حصص ہوتے ہیں۔</p>\n<p>وہ ایک ساختی حقیقت، معاہدے کے پیچھے حصص یا اس کے پیچھے کوئی حصص نہیں، دونوں کے درمیان تقریباً ہر عملی فرق کو چلاتا ہے۔ ہم جاتے وقت اسے اپنے سامنے رکھیں۔</p>\n<h2 id=\"contract-specs-and-lot-sizes\">معاہدہ چشمی اور لاٹ سائز</h2>\n<p>دونوں خاندان فکسڈ میں تجارت کرتے ہیں۔ <strong>بہت سائز</strong>، اکائیوں کا بنڈل ایک معاہدہ کی نمائندگی کرتا ہے۔ آپ ایک یونٹ نہیں خرید سکتے، آپ بہت کچھ خریدتے ہیں۔ لاٹ کا سائز آلہ کے لحاظ سے مختلف ہوتا ہے، اور یہ ایکسچینج کے ذریعے سیٹ کیا جاتا ہے۔ یہاں اس کورس میں آلات کے لیے حقیقی لاٹ ہیں، اس کے ساتھ کہ ہر ایک کس طرح ختم ہوتا ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>زیرِ نظر</th>\n<th>خاندان</th>\n<th>لاٹ سائز</th>\n<th>کے طور پر ختم ہونے پر طے ہوتا ہے۔</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>NIFTY</td>\n<td>انڈیکس</td>\n<td>65</td>\n<td>کیش</td>\n</tr>\n<tr>\n<td>BANKNIFTY</td>\n<td>انڈیکس</td>\n<td>30</td>\n<td>کیش</td>\n</tr>\n<tr>\n<td>FINNIFTY</td>\n<td>انڈیکس</td>\n<td>60</td>\n<td>کیش</td>\n</tr>\n<tr>\n<td>MIDCPNIFTY</td>\n<td>انڈیکس</td>\n<td>120</td>\n<td>کیش</td>\n</tr>\n<tr>\n<td>RELIANCE</td>\n<td>سنگل اسٹاک</td>\n<td>500</td>\n<td>حصص کی جسمانی ترسیل</td>\n</tr>\n</tbody></table>\n<p>NSE اختیارات a پر طے پاتے ہیں۔ <strong>منگل</strong>، اور 28 جولائی 2026 کو ماہانہ ایکسپائری ہے جو ہماری دونوں مثالیں شیئر کرتی ہیں۔ ہفتہ وار معاہدے صرف اس وقت موجود ہوتے ہیں جہاں ایکسچینج فی الحال انہیں پیش کرتا ہے، فی الحال NIFTY ہفتہ وار، جبکہ RELIANCE اور دیگر اسٹاکس ماہانہ تجارت کرتے ہیں۔ غور کریں کہ لاٹ سائز پہلے ہی ایک کہانی سنا رہے ہیں۔ NIFTY بہت زیادہ 65 میں، RELIANCE بہت زیادہ 500 میں چلتا ہے، اس لیے ایک RELIANCE معاہدہ ختم ہونے پر روپے کی قدر بڑی ہے۔</p>\n<h2 id=\"the-big-difference-cash-versus-delivery\">بڑا فرق: نقد بمقابلہ ترسیل</h2>\n<p>یہاں باب کا دل ہے، اور ایک سب سے اہم چیز جو ایک مبتدی کو اس سے لینا چاہیے۔</p>\n<p><strong>انڈیکس کے اختیارات نقد سے طے شدہ ہیں۔</strong> جب ایک NIFTY آپشن کی میعاد ختم ہونے پر ان دی منی ختم ہوجاتی ہے، تو کوئی بھی چیز جسمانی طور پر تبدیل نہیں ہوتی ہے۔ ایکسچینج صرف یہ بتاتا ہے کہ آپشن کی قیمت کتنی ہے، اس کی اندرونی قیمت، اور اس رقم کو نقد ادائیگی یا چارج کرتا ہے۔ NIFTY 24,056 کی جگہ کے قریب اور 24,050 پر پیسے کی ہڑتال کے ساتھ، 28 جولائی کی کال تقریباً 426 روپے فی شیئر اور پوٹ تقریباً 295 روپے فی شیئر بتائی جاتی ہے۔ جو بھی NIFTY آپشن قریب میں قابل قدر ہے، آپ اس اعداد و شمار کو روپوں میں وصول کرتے ہیں یا ادا کرتے ہیں، 65 کے لاٹ سے ضرب، اور پوزیشن ختم ہوجاتی ہے۔ صاف، سادہ، کوئی شیئرز نہیں۔</p>\n<p><strong>سنگل اسٹاک کے اختیارات جسمانی طور پر طے شدہ ہیں۔</strong> جب ایک RELIANCE آپشن ایکسپائری پر پیسے میں ختم ہوجاتا ہے، تو یہ حصص کی حقیقی تجارت میں تبدیل ہوجاتا ہے۔ ایک ان دی منی 1320 کال 1320 پر 500 RELIANCE حصص خریدنے کی ذمہ داری بن جاتی ہے۔ ایک ان دی منی 1320 پوٹ 1320 پر 500 RELIANCE شیئرز فروخت کرنے کی ذمہ داری بن جاتی ہے۔ اصلی حصص، حقیقی ترسیل، حقیقی رقم۔ یہ وہ جگہ ہے جہاں حیرت رہتی ہے۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>انڈیکس کے اختیارات نقد ادائیگی کرتے ہیں۔ ہندوستان میں سنگل اسٹاک کے اختیارات حقیقی حصص فراہم کرتے ہیں۔ ایک NIFTY آپشن جس کی میعاد ختم ہونے والی رقم ایک روپے کی رقم کے طور پر طے ہوتی ہے۔ ایک RELIANCE آپشن جس کی میعاد ختم ہونے والی رقم میں 500 اصلی حصص ہاتھ بدلتے ہوئے طے پاتے ہیں۔</p>\n</div></div>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>دو چیزوں کو الگ رکھیں: نقد رقم جو آپ کے نفع یا نقصان کا ازالہ کرتی ہے، اور سیکیورٹیز کی ترسیل۔ انڈیکس کا اختیار خالصتاً نقدی میں ختم ہوتا ہے۔ ایک واحد اسٹاک آپشن جس کی میعاد ختم ہونے کے لیے کی جاتی ہے۔ <strong>حصص کی جسمانی ترسیل</strong>، ڈیمیٹ اکاؤنٹس کے درمیان منتقل ہونے والا اصل اسٹاک۔ عام NSE کلیرنگ سیٹلمنٹ میکانزم کا صفحہ نقد فنڈز کی قدر کی تصفیہ کی وضاحت کرتا ہے، جو کہ اس شیئر کی ترسیل سے ایک الگ مرحلہ ہے، اس لیے اس کے کیش الفاظ کو نہ پڑھیں جس کا مطلب ہے کہ اسٹاک آپشن ڈیلیوری سے گریز کرتا ہے۔ اس بات کی مستند تصدیق کہ سنگل اسٹاک ڈیریویٹوز جسمانی طور پر طے شدہ ہیں NSE ایکویٹی ڈیریویٹوز کنٹریکٹ کی تفصیلات اور NSE کلیئرنگ سیٹلمنٹ شیڈول (اس کا STT شیڈول انہیں فزیکل سیٹلڈ اسٹاک ڈیریویٹیوز کے طور پر درج کرتا ہے)۔ یہ قوانین ایکسچینج اور ریگولیٹر کی طرف سے مقرر کیے گئے ہیں اور اس سے پہلے تبدیل ہو چکے ہیں، لہذا کسی بھی میعاد ختم ہونے سے پہلے وہاں موجودہ علاج کی تصدیق کریں۔</p>\n</div></div>\n<h2 id=\"why-a-stock-option-to-expiry-can-surprise-you\">ختم ہونے کا اسٹاک آپشن کیوں آپ کو حیران کر سکتا ہے۔</h2>\n<p>RELIANCE 1320 کال کے ساتھ اس کے ذریعے چلیں۔ آپ نے اسے تقریباً 15,590 روپے میں خریدا، تیزی سے اضافے کی توقع ہے۔ RELIANCE 28 جولائی تک 1,340 تک بڑھ جاتا ہے اور آپ پوزیشن کے بارے میں بھول جاتے ہیں، یا آپ فرض کرتے ہیں کہ یہ آپ کو فرق کی ادائیگی کرتا ہے جیسا کہ NIFTY آپشن ہوگا۔ ایسا نہیں ہوتا۔ چونکہ کال پیسے کے اندر ختم ہوجاتی ہے، اس لیے یہ خود کار طریقے سے استعمال ہوتا ہے، اور اب آپ 1320 پر 500 RELIANCE شیئرز خریدنے کے پابند ہیں۔ اس ڈیلیوری کا بل 500 گنا 1320 ہے، جو کہ تقریباً 6,60,000 روپے ہے۔</p>\n<p>اس نمبر کے ساتھ بیٹھو۔ آپ نے 15,590 روپے ایک ڈائریکشنل ویو پر داؤ پر لگا دیے، اور آپ نے تقریباً 6,60,000 روپے کے حصص کی وجہ سے دن ختم کر دیا جن کا آپ کبھی مالک نہیں ہونا چاہتے تھے۔ ایکسچینج کو اس بات کی پرواہ نہیں ہے کہ آپ کے اکاؤنٹ میں صرف پریمیم رقم تھی۔ ایک جسمانی طور پر طے شدہ آپشن جس کی میعاد رقم کے اندر ختم ہو جاتی ہے ایک حقیقی ڈیلیوری ذمہ داری پیدا کرتی ہے، اور اگر آپ اسے فنڈ نہیں دے سکتے تو تجارت جرمانہ اور مختصر ڈیلیوری کے عمل میں جاتی ہے جس کی قیمت آپ کو بہت زیادہ پڑ سکتی ہے۔ پوٹ سائیڈ بالکل الٹ کے طور پر پریشان کن ہے، ایک ان دی منی 1320 پوٹ ڈیلیور ہونے کا مطلب ہے کہ آپ کو 500 شیئرز کے حوالے کرنے ہوں گے جو آپ کے پاس بھی نہیں ہیں۔</p>\n<p>اوپر ٹیکس کا ڈنک لگا ہوا ہے۔ 1 اپریل 2026 سے، ایک آپشن جس کا استعمال کیا جاتا ہے، اندرونی، یا سیٹلمنٹ، ویلیو پر 0.15 فیصد کا سیکیورٹیز ٹرانزیکشن ٹیکس کو اپنی طرف متوجہ کرتا ہے، جو مارکیٹ میں آپشن کو صرف فروخت کرنے پر ٹیکس سے کہیں زیادہ بھاری ہے۔ لہذا اسٹاک آپشن کو فزیکل سیٹلمنٹ میں چلنے دینا آپ کو ڈیلیوری کی ذمہ داری اور پوزیشن کو بند کرنے کے مقابلے میں زیادہ موٹا ٹیکس بل خرچ کر سکتا ہے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>ایک RELIANCE آپشن کی میعاد ختم ہونے کے لیے رکھی گئی ہے جب کہ اندر موجود رقم صرف آپ کو فرق کی ادائیگی نہیں کرتی ہے۔ یہ 500 شیئرز کی ڈیلیوری میں بدل جاتا ہے، جس کی قیمت ایک لاٹ پر کئی لاکھ روپے ہے، اس کے علاوہ ایک بھاری ورزش ٹیکس۔ کبھی بھی یہ نہ سمجھیں کہ اسٹاک کا آپشن نقد میں طے ہوتا ہے جس طرح انڈیکس آپشن کرتا ہے۔</p>\n</div></div>\n<h2 id=\"square-off-in-time\">وقت میں مربع بند</h2>\n<p>درست کرنا آسان ہے اور یہ وہی ہے جو تقریباً ہر خوردہ تاجر کرتا ہے۔ آپ <strong>مربع بند</strong> میعاد ختم ہونے سے پہلے، یعنی آپ مارکیٹ میں مخالف تجارت لے کر، اپنی خریدی ہوئی کال کو بیچ کر پوزیشن کو بند کرتے ہیں، تاکہ آپ پریمیم فرق کو نقد رقم میں جمع کریں یا ادا کریں اور ڈیلیور کرنے کے لیے بغیر کسی شیئر کے چلے جائیں۔ آپ اپنے نفع یا نقصان کو نقد کے طور پر حاصل کرتے ہیں اور آپ فزیکل سیٹلمنٹ مشینری کو کبھی بھی ہاتھ نہیں لگاتے ہیں۔</p>\n<p>یہی وجہ ہے کہ تجربہ کار تاجر سٹاک آپشن پر ایکسپائری ڈے کو احترام کے ساتھ مانتے ہیں۔ وہ یا تو بند ہونے سے پہلے پوزیشن کو آرام سے بند کر دیتے ہیں، یا وہ مکمل طور پر فنڈنگ ​​کے ساتھ ڈیلیوری لینے یا دینے کے سوچے سمجھے منصوبے کے ساتھ ایکسپائری میں داخل ہوتے ہیں۔ حادثاتی طور پر ایکسپائری میں بہہ جانا غلطی ہے۔ انڈیکس ٹریڈر کے پاس یہاں غلطی کی زیادہ گنجائش ہے، کیونکہ نقد سے طے شدہ NIFTY آپشن آسانی سے ادائیگی کرتا ہے اور غائب ہوجاتا ہے، لیکن وہاں بھی یہ خود کار طریقے سے سیٹلمنٹ پر چھوڑنے کے بجائے خود سے باہر نکلنے کا انتظام کرنا زیادہ صاف ہے۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>سنگل اسٹاک آپشن پر، ایکسپائری ہفتہ سے پہلے اپنے باہر نکلنے کا فیصلہ کریں، میعاد ختم ہونے والے دوپہر کو نہیں۔ مارکیٹ میں اسکوائرنگ آپ کے نتیجہ کو نقد میں بدل دیتا ہے اور کسی بھی ترسیل کی ذمہ داری کو ہٹا دیتا ہے۔ سٹاک آپشن کی میعاد ختم ہونے میں غیر منصوبہ بند بڑھنے کو ایک حقیقی خطرہ سمجھیں، نہ کہ معمولی تفصیل۔</p>\n</div></div>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-basics/images/diagram-index-vs-stock-settlement.png\" alt=\"500 حصص کی فزیکل ڈیلیوری میں تبدیل ہونے والے RELIANCE آپشن کے ساتھ ایکسپائری سیٹ پر کیش میں سیٹل کرنے کا ایک NIFTY آپشن، یہ فرق جو ایکسپائری ڈے پر ابتدائی افراد کو حیران کردیتا ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>500 حصص کی فزیکل ڈیلیوری میں تبدیل ہونے والے ایک RELIANCE آپشن کے ساتھ ایکسپائری سیٹ پر کیش سیٹل کرنے کا ایک NIFTY آپشن، یہ فرق جو ایکسپائری ڈے پر ابتدائی افراد کو حیران کردیتا ہے۔</figcaption></figure>\n<h2 id=\"a-quick-comparison-to-fix-it-in-memory\">اسے میموری میں ٹھیک کرنے کے لیے ایک فوری موازنہ</h2>\n<table>\n<thead>\n<tr>\n<th>سوال</th>\n<th>NIFTY (انڈیکس)</th>\n<th>RELIANCE (سنگل اسٹاک)</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>اس کے پیچھے کیا ہے۔</td>\n<td>ایک حسابی اشاریہ نمبر</td>\n<td>حقیقی کمپنی کے حصص</td>\n</tr>\n<tr>\n<td>لاٹ سائز</td>\n<td>65</td>\n<td>500</td>\n</tr>\n<tr>\n<td>یہ پیسے میں کیسے طے کرتا ہے۔</td>\n<td>نقد، ادا کی جانے والی اندرونی قیمت</td>\n<td>500 شیئرز کی ڈیلیوری</td>\n</tr>\n<tr>\n<td>ایکسپائری ڈے پر حیرت کا خطرہ</td>\n<td>کم، یہ صرف باہر ادا کرتا ہے</td>\n<td>اعلی، ترسیل کی ذمہ داری ظاہر ہوتی ہے۔</td>\n</tr>\n<tr>\n<td>ڈیلیوری کے وقت ایک لاٹ پر سوار ہونا</td>\n<td>نقد رقم کے طور پر طے شدہ</td>\n<td>تقریباً 6,60,000 روپے کے شیئرز</td>\n</tr>\n<tr>\n<td>محفوظ عادت</td>\n<td>باہر نکلنے کا انتظام کریں۔</td>\n<td>میعاد ختم ہونے سے پہلے مربع بند کریں۔</td>\n</tr>\n</tbody></table>\n<h2 id=\"what-to-carry-forward\">آگے کیا لے جانا ہے۔</h2>\n<p>انڈیکس کے اختیارات اور واحد اسٹاک کے اختیارات ایک ہی الفاظ کا اشتراک کرتے ہیں لیکن دو بالکل مختلف طریقوں سے طے کرتے ہیں۔ NIFTY آپشن کیش سیٹلڈ ہے، لہذا اندرونِ رقم مکمل کرنے سے صرف ایک روپیہ کی رقم ادا ہوتی ہے اور پوزیشن خود کو بے ضرر طریقے سے بند کر دیتی ہے۔ ایک RELIANCE آپشن فزیکل طور پر طے شدہ ہے، اس لیے پیسے کے اندر مکمل کرنا 500 اصلی شیئرز کی ڈیلیوری میں بدل جاتا ہے، جس کی مالیت ایک ہی لاٹ پر کئی لاکھ ہوتی ہے، جس میں میچ کرنے کے لیے بھاری ایکسرسائز ٹیکس ہوتا ہے۔</p>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">کیا آپ جانتے ہیں؟</span><div><p>ہندوستان میں، ہر انڈیکس آپشن کیش سیٹل اور ہر ایک اسٹاک آپشن جسمانی طور پر سیٹل ہوتا ہے۔ لاٹ کے سائز پوائنٹ پر مہر لگاتے ہیں، NIFTY پر 65 اور RELIANCE پر 500، لہذا ایکسپائری پر ایک ان دی منی اسٹاک لاٹ پر ڈیلیور کی جانے والی قیمت کئی لاکھ روپے تک جاتی ہے۔</p>\n</div></div>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>تصفیہ وہ واحد جگہ نہیں ہے جہاں سٹاک ڈیریویٹوز کی دنیا کے اصولوں کی وراثت میں سنگل سٹاک کے اختیارات ہیں۔ وہی کنٹرول جو اسٹاک فیوچر کو کنٹرول کرتے ہیں اسٹاک کے اختیارات کو بھی چھوتے ہیں: ایک اسٹاک داخل ہوسکتا ہے۔ <strong>ایف اینڈ او پابندی</strong> جب اس کی مارکیٹ وائڈ پوزیشن کی حد کی خلاف ورزی کی جاتی ہے، تو آپ اس میں کوئی نئی پوزیشن نہیں لے سکتے؛ a <strong>کارپوریٹ کارروائی</strong> جیسے کہ تقسیم یا بونس آپ کے اختیار کے لاٹ سائز اور اسٹرائیک کو ایڈجسٹ کرے گا۔ a <strong>مقدار منجمد</strong> ایک آرڈر کتنا بڑا ہو سکتا ہے اور a <strong>قیمت بینڈ</strong> آپ کے آرڈر کو مسترد کر سکتے ہیں۔ فیوچر ٹریڈنگ کورس ان میں سے ہر ایک کے ذریعے اپنے مارکیٹ کنٹرول ماڈیول میں کام کرتا ہے، اور وہ اسٹاک آپشنز پر اسی طرح لاگو ہوتے ہیں جیسے وہ اسٹاک فیوچرز پر کرتے ہیں۔</p>\n</div></div>\n<p>عملی سبق مختصر ہے۔ جان لیں کہ آپ کا آپشن کس خاندان سے تعلق رکھتا ہے اس سے پہلے کہ آپ اس کی تجارت کریں، اور کسی بھی واحد اسٹاک آپشن پر اپنے ڈیفالٹ کی میعاد ختم ہونے سے پہلے اسکوائرنگ آف کریں۔ سٹاک کے آپشن کو ایکسپائری میں صرف اس وقت رکھیں جب آپ حقیقی طور پر ڈیلیوری لینے یا دینے کا ارادہ رکھتے ہوں اور اس کے لیے مکمل فنڈنگ ​​کر چکے ہوں۔ ایسا کریں، اور ایکسپائری ڈے گھات لگا کر جو بہت سارے نئے لوگوں کو پکڑتا ہے آپ کو کبھی نہیں پکڑے گا۔</p>\n","toc":[{"level":2,"text":"اختیارات کے دو خاندان","id":"two-families-of-options"},{"level":2,"text":"معاہدہ چشمی اور لاٹ سائز","id":"contract-specs-and-lot-sizes"},{"level":2,"text":"بڑا فرق: نقد بمقابلہ ترسیل","id":"the-big-difference-cash-versus-delivery"},{"level":2,"text":"ختم ہونے کا اسٹاک آپشن کیوں آپ کو حیران کر سکتا ہے۔","id":"why-a-stock-option-to-expiry-can-surprise-you"},{"level":2,"text":"وقت میں مربع بند","id":"square-off-in-time"},{"level":2,"text":"اسے میموری میں ٹھیک کرنے کے لیے ایک فوری موازنہ","id":"a-quick-comparison-to-fix-it-in-memory"},{"level":2,"text":"آگے کیا لے جانا ہے۔","id":"what-to-carry-forward"}],"imgCount":1,"hasContent":true},"8":{"html":"<p>آپ جو بھی آپشن خریدتے یا بیچتے ہیں اس پر موت کی تاریخ کی مہر لگی ہوتی ہے۔ ہماری چل رہی مثال میں RELIANCE کے اختیارات کے لیے، وہ تاریخ 28 جولائی 2026 ہے۔ اس وقت تک آپشن ایک زندہ شرط ہے، اسٹاک اور گھڑی کے ساتھ بڑھنا اور گرنا۔ لیکن ایکسپائری ڈے پر شرط کو بلایا جاتا ہے۔ آپشن مستقبل کے بارے میں ہونا بند کر دیتا ہے اور ایک واحد، آسان سوال بن جاتا ہے: کیا یہ کسی حقیقی قیمت کے ساتھ ختم ہوا، یا یہ کچھ بھی نہیں کے طور پر ختم ہوا؟ یہ باب بالکل اس بات پر چلتا ہے کہ اس آخری دن کیا ہوتا ہے، کس کو تنخواہ ملتی ہے، کس کو ادائیگی کرنی پڑتی ہے، اور ایک ایسی عملی عادت جو ابتدائی افراد کو پریشانی سے دور رکھتی ہے۔</p>\n<h2 id=\"expiry-day-the-deadline-arrives\">میعاد ختم ہونے کا دن: آخری تاریخ آ گئی۔</h2>\n<p>ایک آپشن ڈیڈ لائن کے ساتھ ایک حق ہے، اور وہ ڈیڈ لائن ایکسپائری ہے۔ ہندوستان میں، ماہانہ معاہدوں کی میعاد ہفتے کے ایک مقررہ دن پر ختم ہو جاتی ہے، اور تبادلہ انہیں منگل کو طے کرتا ہے۔ ہمارے RELIANCE 1320 آپشنز کی میعاد 28 جولائی 2026 کو ختم ہوتی ہے، اور ہمارے انڈیکس کی مثال میں NIFTY ماہانہ معاہدوں کی میعاد 28 جولائی کو ختم ہوتی ہے۔</p>\n<p>اس دن تک، ایک آپشن کے پریمیم کے دو حصے ہوتے ہیں: اندرونی قدر، اصل یہاں اور اب کی قیمت، اور وقت کی قدر، امید کا پریمیم جو ختم ہونے کے قریب پگھل جاتا ہے۔ ایکسپائری ڈے پر امید ختم ہو جاتی ہے۔ قریب سے، وقت کی قدر مکمل طور پر صفر ہو گئی ہے، اور آپشن کے اندر صرف ایک چیز رہ گئی ہے وہ اس کی اندرونی قدر ہے۔ یہ ایک لائن میں ختم ہونے کی پوری کہانی ہے: وقت کی قدر مر جاتی ہے، اور اندرونی قدر وہی ہے جو طے ہو جاتی ہے۔</p>\n<p>لہٰذا ہر آپشن کی قیمت کیا ہے اس کا انحصار مکمل طور پر اس کی رقم پر ہے، جہاں ہڑتال آخری سیٹلمنٹ قیمت کے خلاف ہے۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>ختم ہونے والے دن، وقت کی قدر ختم ہو جاتی ہے۔ ایک آپشن اس کی داخلی قدر کے لیے طے ہوتا ہے اور اس سے زیادہ کچھ نہیں۔ اگر یہ رقم میں ختم ہو جاتا ہے تو یہ اس اندرونی قیمت کو ادا کرتا ہے۔ اگر یہ رقم پر ختم ہو جائے یا پیسے سے باہر ہو تو اس کی میعاد ختم ہو جاتی ہے۔</p>\n</div></div>\n<h2 id=\"in-the-money-pays-out-of-the-money-expires-worthless\">اندر کا پیسہ ادا کرتا ہے، باہر کا پیسہ بے کار ختم ہو جاتا ہے۔</h2>\n<p>آئیے ہم نتائج کو ساتھ ساتھ رکھتے ہیں RELIANCE 1320 کال کا استعمال کرتے ہوئے، اس بات پر منحصر ہے کہ RELIANCE 28 جولائی کو کہاں طے ہوتا ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>تصفیہ</th>\n<th>1320 کال منینس</th>\n<th>کال کی قیمت کیا ہے۔</th>\n<th>خریدار کے لیے نتیجہ</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1360</td>\n<td>ان دی منی 40 تک</td>\n<td>40 روپے فی شیئر، تقریباً 20,000 روپے</td>\n<td>اس کی اندرونی قیمت ادا کرتا ہے۔</td>\n</tr>\n<tr>\n<td>1320</td>\n<td>پیسے پر</td>\n<td>کچھ بھی نہیں۔</td>\n<td>بیکار ختم ہو جاتی ہے۔</td>\n</tr>\n<tr>\n<td>1290</td>\n<td>باہر کا پیسہ</td>\n<td>کچھ بھی نہیں۔</td>\n<td>بیکار ختم ہو جاتی ہے۔</td>\n</tr>\n</tbody></table>\n<p>صفوں کو ایمانداری سے پڑھیں۔ اگر RELIANCE 1360 پر سیٹل ہوتا ہے، تو 1320 کال چالیس روپے میں ہوتی ہے، اس لیے یہ 40 روپے فی شیئر میں سیٹل ہوتی ہے، جو کہ 500 پر تقریباً 20,000 روپے بنتی ہے۔ اگر RELIANCE 1320 پر، یا اس کے نیچے کہیں بھی طے پاتا ہے، تو کال کی کوئی اندرونی قدر نہیں ہے اور بس بے کار ہو جاتی ہے۔ خریدار ادا کردہ مکمل پریمیم کھو دیتا ہے، تقریباً 15,590 روپے۔ 1320 کا پٹ آئینے کی طرح برتاؤ کرتا ہے: یہ صرف اس صورت میں ادائیگی کرتا ہے جب RELIANCE 1320 سے کم ہو، اور اس کے اوپر یا اس کے اوپر بیکار ختم ہو جائے۔</p>\n<p>یہ خریدار کے لیے ایکسپائری کا ظالمانہ ریاضی ہے۔ قریب ہونے کا کوئی جزوی کریڈٹ نہیں ہے۔ ایک آپشن جو پیسے سے باہر ایک روپیہ ختم کرتا ہے اس کی قیمت بالکل وہی ہے جو ایک سو روپے ختم کرتا ہے، جو کچھ بھی نہیں ہے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>ہڑتال کے قریب ختم ہونے سے خریدار کو کچھ حاصل نہیں ہوتا ہے۔ ایک آپشن جس کی میعاد ختم ہو جاتی ہے یہاں تک کہ پیسے سے باہر بھی اس کی قیمت صفر ہے، اور پورا پریمیم ضائع ہو جاتا ہے۔ زیادہ تر پیسے سے باہر ہونے والے اختیارات کی میعاد ختم ہونے تک پہنچ جاتی ہے، یہی وجہ ہے کہ لاٹری کے بہت سے اختیارات خریداروں کا مسلسل خون بہاتے ہیں۔</p>\n</div></div>\n<h2 id=\"auto-exercise-the-exchange-does-the-work\">خودکار مشق: تبادلہ کام کرتا ہے۔</h2>\n<p>یہاں beginners کے لئے ایک ریلیف ہے. آپ کو ادائیگی کرنے کے لیے اندرون خانہ آپشن کے لیے کچھ کرنے کی ضرورت نہیں ہے۔ تبادلہ چلتا ہے۔ <strong>خودکار ورزش</strong>: میعاد ختم ہونے پر، ہر وہ آپشن جو پیسے کے اندر ختم ہو جاتا ہے خود بخود استعمال ہوتا ہے، اور تصفیہ کی قیمت خریدار کو جمع کر دی جاتی ہے اور بیچنے والے سے ڈیبٹ کی جاتی ہے۔ آپ بٹن نہیں دباتے، آرڈر نہیں دیتے، یا کوئی ہدایات نہیں بھیجتے۔ اگر آپ کا اختیار داخلی قدر کے ساتھ ختم ہو جاتا ہے، تو سسٹم اسے آپ کے لیے جمع کرتا ہے۔</p>\n<p>یکساں طور پر، پیسے سے باہر کے آپشن کو بھی کسی کارروائی کی ضرورت نہیں ہے۔ اس کی میعاد ختم ہو جاتی ہے اور آپ کے اکاؤنٹ سے غائب ہو جاتی ہے، پہلے سے خرچ شدہ پریمیم کے ساتھ۔ ترک کرنے کے لیے کچھ نہیں ہے اور دعویٰ کرنے کے لیے کچھ نہیں ہے، کیونکہ وہاں کچھ بھی نہیں ہے۔</p>\n<p>لہذا خریدار کا ختم ہونے کا تجربہ زیادہ تر خودکار ہوتا ہے۔ کیچ میکینکس نہیں ہے۔ کیچ وہی ہے جو ایک اندرونِ رقم تصفیہ دراصل فراہم کرتا ہے، اور یہ اس بات پر منحصر ہے کہ آیا آپ کے پاس انڈیکس آپشن ہے یا اسٹاک آپشن۔</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>آٹو ایکسرسائز کا مطلب ہے کہ ایکسچینج آپ کی طرف سے کسی کارروائی کے بغیر آپ کے لیے آپ کے لیے پیسے کے ہر آپشن کو ختم کر دیتا ہے۔ آپ کو کبھی بھی دستی طور پر ورزش کرنے کی ضرورت نہیں ہے۔ نظام کرتا ہے. پیسے سے باہر کے اختیارات صرف ختم ہو جاتے ہیں۔</p>\n</div></div>\n<h2 id=\"assignment-the-seller-s-side-of-the-deal\">تفویض: ڈیل کے بیچنے والے کی طرف</h2>\n<p>ہر آپشن کے دو رخ ہوتے ہیں۔ جب خریدار کا اختیار استعمال کیا جاتا ہے، تو دوسری طرف کوئی ہوتا ہے۔ <strong>تفویض</strong>. اسائنمنٹ کا انتخاب صرف اس ذمہ داری کو پورا کرنے کے لیے کیا جا رہا ہے جو آپ نے آپشن بیچنے اور پریمیم جمع کرنے پر اٹھایا تھا۔</p>\n<p>اگر آپ نے RELIANCE 1320 کال فروخت کی ہے اور یہ رقم میں ختم ہوجاتی ہے، تو آپ کو تفویض کیا جاتا ہے۔ آپ نے تقریباً 15,590 روپے کا پریمیم پہلے سے لیا، اور اب آپ کو آپشن کی اندرونی قیمت خریدار کو طے کرنی ہوگی۔ بیچنے والے کو چلنا نہیں آتا۔ یہ وہ سودا ہے جو ایک بیچنے والا مارتا ہے: ایک ڈیوٹی کے بدلے میں آج پریمیم جسے ختم ہونے پر طلب کیا جا سکتا ہے۔</p>\n<p>سیٹلنگ کا اصل مطلب ایک لائن کے ساتھ تیزی سے تقسیم ہوتا ہے، انڈیکس آپشنز بمقابلہ اسٹاک آپشنز۔</p>\n<h2 id=\"cash-for-index-delivery-for-stock\">انڈیکس کے لیے نقد، اسٹاک کے لیے ترسیل</h2>\n<p>یہ وہ حصہ ہے جو شروع کرنے والوں کو حیران کر دیتا ہے، اور یہ آہستہ پڑھنے کا مستحق ہے۔</p>\n<p><strong>انڈیکس کے اختیارات نقد سے طے شدہ ہیں۔</strong> NIFTY کے حوالے کرنے کے لیے کوئی فزیکل شیئرز نہیں ہیں، اس لیے ان دی منی NIFTY کا آپشن صرف نقد میں طے ہوتا ہے۔ اگر آپ نے NIFTY 24050 کال کی تھی اور انڈیکس زیادہ طے پاتا ہے، تو پوائنٹس میں داخلی قدر، 65 کے لاٹ سے گنا، روپے میں آپ کے اکاؤنٹ میں ادا کی جاتی ہے۔ اگر آپ نے اسے فروخت کیا تھا اور تفویض کیا گیا تھا، تو وہی نقد رقم ڈیبٹ ہو جائے گی۔ پیسہ چلتا ہے، اور کچھ نہیں۔</p>\n<p><strong>ہندوستان میں سنگل اسٹاک کے اختیارات جسمانی طور پر طے شدہ ہیں۔</strong> یہ پھندا ہے۔ ان دی منی RELIANCE آپشن نقد میں طے نہیں ہوتا ہے۔ یہ حصص کی اصل ترسیل میں بدل جاتا ہے۔ ایک کال خریدار جس کے پاس ان دی منی RELIANCE کی میعاد ختم ہونے کے لیے کال ہے وہ 500 RELIANCE حصص کی ڈیلیوری لے اور ان کے لیے ادائیگی کرے۔ تقریباً 1,318 روپے فی شیئر پر، جو کہ ایک لاٹ کے لیے تقریباً 6,59,000 روپے کا اسٹاک ہے۔ ایک کال سیلر جس کو تفویض کیا گیا ہے اسے وہ 500 شیئرز ڈیلیور کرنے چاہئیں۔ پوٹ دوسرے طریقے سے کام کرتا ہے: پوٹ خریدار حصص فراہم کرتا ہے اور تفویض کردہ پوٹ بیچنے والے کو انہیں خریدنا ہوگا۔</p>\n<p>لہٰذا ایک ابتدائی جس نے ایک چھوٹے پریمیم کے لیے RELIANCE آپشن بیچا، اس کے بارے میں بھول گیا، اور اسے ایکسپائری میں چلنے دیا، وہ کئی لاکھ روپے کی ڈیلیوری ذمہ داری سے جاگ سکتا ہے، جمع کیے گئے چھوٹے پریمیم سے کہیں زیادہ۔ یہ ایک حقیقی خطرہ ہے، نظریاتی نہیں۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>ایک سٹاک آپشن جس کی میعاد ختم ہونے کے لیے رکھی گئی ہے وہ حقیقی حصص کی ترسیل میں بدل جاتی ہے، نقد نہیں۔ ایک ان دی منی RELIANCE لاٹ کا مطلب ہے 500 حصص ہاتھ بدلتے ہیں، جس کی قیمت تقریباً 6,59,000 روپے ہے۔ اسٹاک آپشن پر تفویض کردہ بیچنے والے کو وہ حصص ڈیلیور کرنا یا لینا چاہیے۔ کسی اسٹاک آپشن کو کبھی بھی حادثاتی طور پر ایکسپائری میں نہ جانے دیں۔</p>\n</div></div>\n<h2 id=\"the-settlement-price-not-the-last-tick\">تصفیہ کی قیمت، آخری ٹک نہیں۔</h2>\n<p>جب ایکسچینج یہ فیصلہ کرتا ہے کہ آیا آپ کا آپشن ان دی منی ہے اور کتنی ہے، وہ آخری ٹک استعمال نہیں کرتا جسے آپ نے دیکھا تھا۔ یہ انڈرلائنگ آفیشل کا استعمال کرتا ہے۔ <strong>حتمی تصفیہ کی قیمت</strong>. انڈیکس آپشن کے لیے یہ انڈیکس کی آفیشل کلوزنگ ویلیو ہے۔ سنگل اسٹاک آپشن کے لیے، سے <strong>3 اگست 2026</strong> بنیادی F&amp;O اسٹاک کا آفیشل کلوز عام طور پر کیش مارکیٹ میں دریافت ہونے والی توازن کی قیمت ہے <strong>اختتامی نیلامی سیشن ( CAS)</strong>، پرانی بند ہونے والی ونڈو VWAP نہیں۔</p>\n<p>VWAP کا اب بھی ایک کردار ہے: اسٹاک کی 15:00-15:15 VWAP CAS حوالہ قیمت ہے اور اگر نیلامی متوازن قیمت دریافت نہیں کرسکتی ہے تو قریب ہوجاتی ہے۔ انڈیکس بذات خود الگ سے نیلام نہیں کیا جاتا ہے، لیکن اس کا آفیشل کلوز CAS اہل حلقوں کی نیلامی بند ہونے اور CAS سے باہر کے اجزاء کے بند ہونے کی عکاسی کرتا ہے۔ ایکویٹی کے اختیارات 15:40 تک تجارت جاری رکھیں گے۔ مشتق معاہدے کی اپنی اختتامی قیمت اب بھی اس کی 15:10-15:40 VWAP استعمال کرتی ہے۔ عملی نکتہ غیر تبدیل شدہ ہے: آپ حتمی سیٹلمنٹ نمبر کا انتخاب نہیں کر سکتے، اس لیے بہت سے تاجر اس پوزیشن کو ختم ہونے پر چھوڑنے کے بجائے خود بند کر دیتے ہیں۔</p>\n<h2 id=\"square-off-in-time-the-practical-rule\">وقت میں مربع بند: عملی اصول</h2>\n<p>یہ سب ایک سادہ عادت کی طرف جاتا ہے جو زیادہ تر ابتدائیوں کی حفاظت کرتا ہے، جو کہ ہے۔ <strong>وقت میں مربع بند</strong>. اسکوائر آف کرنے کا مطلب ہے مخالف تجارت لے کر، جو آپشن آپ نے خریدا ہے اسے بیچ کر، یا جو آپشن آپ نے بیچا ہے اسے واپس خرید کر ختم ہونے سے پہلے پوزیشن کو بند کرنا ہے۔ ایک بار جب آپ اسکوائر آف کر لیتے ہیں، تو آپ کے پاس سیٹل ہونے کے لیے کوئی پوزیشن باقی نہیں رہتی ہے، اور ایکسپائری ڈے آپ کے لیے کوئی سرپرائز نہیں رکھتا۔</p>\n<p>زیادہ تر آپشن ٹریڈرز، ریٹیل اور پروفیشنل یکساں، اپنی پوزیشن ختم ہونے سے پہلے بند کر دیتے ہیں بجائے کہ ان کو تصفیہ میں لے جائیں۔ وہ یہ تین وجوہات کی بنا پر کرتے ہیں۔ سب سے پہلے، یہ اسٹاک آپشنز پر فزیکل ڈیلیوری کی ذمہ داری سے مکمل طور پر گریز کرتا ہے۔ دوسرا، پیسے کے اندر موجود آپشن کو استعمال کرنے یا تفویض کیے جانے پر مکمل داخلی قیمت پر اپنا سیٹلمنٹ ٹیکس ہوتا ہے، یہ ایک اضافی لاگت ہے جو مارکیٹ میں بند ہونے سے بچ جاتی ہے۔ تیسرا، یہ آپ کو اس قیمت پر باہر نکلنے کو کنٹرول کرنے دیتا ہے جسے آپ دیکھ سکتے ہیں، بجائے اس کے کہ کسی ایک سرکاری بند ہونے والی قیمت پر طے کیا جائے جس پر آپ اثر انداز نہیں ہو سکتے۔</p>\n<p>ایک ابتدائی کے لیے اصول سادہ ہے۔ ایکسپائری کے آخری اوقات میں اسٹاک کا آپشن نہ رکھیں جب تک کہ آپ مکمل طور پر ڈیلیوری لینے یا دینے کا ارادہ نہ رکھتے ہوں اور اس کے لیے آپ کے پاس کیش یا شیئرز نہ ہوں۔ اگر آپ کو یقین نہیں ہے تو وقت کے ساتھ پوزیشن کو بند کریں۔ آٹو ایکسرسائز کی سہولت حقیقی ہے، لیکن یہ لاپرواہ ہونے کی کوئی وجہ نہیں ہے، کیونکہ وہی خودکار نظام جو خریدار کو ادائیگی کرتا ہے، ایک بھولے بھالے بیچنے والے کو لاکھوں کی ڈیلیوری کے ساتھ جھکا سکتا ہے۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-basics/images/diagram-expiry-exercise.png\" alt=\"ایکسپائری ڈے پر ایک ان دی منی آپشن خود کار طریقے سے استعمال کیا جاتا ہے اور اس کی اندرونی قیمت ادا کرتا ہے، جب کہ پیسے پر اور باہر کے اختیارات کی میعاد بے کار ہو جاتی ہے۔ ان دی منی آپشن بیچنے والے کو تفویض کیا جاتا ہے اور اسے انڈیکس کے لیے نقد رقم اور اسٹاک کے لیے شیئر ڈیلیوری میں طے کرنا چاہیے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>ایکسپائری ڈے پر ایک ان دی منی آپشن خود کار طریقے سے استعمال کیا جاتا ہے اور اس کی اندرونی قیمت ادا کرتا ہے، جب کہ پیسے پر اور باہر کے اختیارات کی میعاد بے کار ہو جاتی ہے۔ ان دی منی آپشن بیچنے والے کو تفویض کیا جاتا ہے اور اسے انڈیکس کے لیے نقد رقم اور اسٹاک کے لیے شیئر ڈیلیوری میں طے کرنا چاہیے۔</figcaption></figure>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>ایک ابتدائی کے لیے محفوظ ڈیفالٹ یہ ہے کہ میعاد ختم ہونے سے پہلے اسکوائر بند کر دیا جائے۔ پوزیشن کو خود بند کرنے سے کسی بھی اسائنمنٹ یا ڈیلیوری کا خطرہ دور ہو جاتا ہے، ورزش پر سیٹلمنٹ ٹیکس سے بچ جاتا ہے، اور آپ کو اس قیمت پر باہر نکلنے دیتا ہے جسے آپ ایک آفیشل بند کرنے کے بجائے دیکھ سکتے ہیں۔</p>\n</div></div>\n<p>ایکسپائری وہ جگہ ہے جہاں ایک آپشن آخر کار سچ بتاتا ہے۔ آپ نے جس امید کی ادائیگی کی تھی وہ ختم ہو گئی ہے، اور صرف سخت اندرونی قدر باقی ہے۔ خریدار کے لیے اس کا مطلب ہے کہ اگر آپ نے رقم کے اندر اندر ختم کر دی تو ادائیگی اور اگر آپ نے نہیں کی تو کل نقصان۔ بیچنے والے کے لیے اس کا مطلب ہے تفویض، انڈیکس پر نقد رقم اور اسٹاک پر حقیقی حصص۔ کسی معاہدے کو آخری دن تک رکھنے سے پہلے دونوں فریقوں کو سمجھیں، اور وقت پر اسکوائرنگ کو اپنی ڈیفالٹ عادت بنا لیں۔</p>\n","toc":[{"level":2,"text":"میعاد ختم ہونے کا دن: آخری تاریخ آ گئی۔","id":"expiry-day-the-deadline-arrives"},{"level":2,"text":"اندر کا پیسہ ادا کرتا ہے، باہر کا پیسہ بے کار ختم ہو جاتا ہے۔","id":"in-the-money-pays-out-of-the-money-expires-worthless"},{"level":2,"text":"خودکار مشق: تبادلہ کام کرتا ہے۔","id":"auto-exercise-the-exchange-does-the-work"},{"level":2,"text":"تفویض: ڈیل کے بیچنے والے کی طرف","id":"assignment-the-seller-s-side-of-the-deal"},{"level":2,"text":"انڈیکس کے لیے نقد، اسٹاک کے لیے ترسیل","id":"cash-for-index-delivery-for-stock"},{"level":2,"text":"تصفیہ کی قیمت، آخری ٹک نہیں۔","id":"the-settlement-price-not-the-last-tick"},{"level":2,"text":"وقت میں مربع بند: عملی اصول","id":"square-off-in-time-the-practical-rule"}],"imgCount":1,"hasContent":true},"9":{"html":"<p>کوئی بھی آپشن چین کھولیں اور آپ کو تین مختلف موڈ میں بیان کردہ ایک ہی سٹرائیک نظر آئے گی۔ کچھ اختیارات ابھی استعمال کرنے کے قابل ہیں۔ کچھ موجودہ قیمت پر بالکل متوازن بیٹھتے ہیں۔ اور کچھ خالص امید ہیں، جن کی آج قیمت کچھ نہیں ہے لیکن خواب دیکھنے کے لیے کافی سستا ہے۔ ان تینوں مزاجوں کے نام ہیں، پیسے میں، پیسے پر اور پیسے سے باہر، اور مل کر پکارا جاتا ہے۔ <strong>پیسہ</strong>. پیسہ وہ پہلی چیز ہے جسے تجربہ کار تاجر کسی آپشن کے بارے میں پڑھتے ہیں، کیونکہ یہ آپ کو فوری طور پر بتاتا ہے کہ آیا ہڑتال ایک حقیقی، یہاں اور اب کی ڈیل ہے یا مستقبل پر صرف ایک شرط ہے۔ ایک بار جب آپ ان تین بالٹیوں میں کسی بھی آپشن کو ترتیب دے سکتے ہیں، تو آپشن چین نمبروں کی دیوار بننا بند کر دیتا ہے اور ایک کہانی سنانا شروع کر دیتا ہے۔</p>\n<h2 id=\"the-three-buckets\">تین بالٹیاں</h2>\n<p>پیسہ اس ہڑتال کا موازنہ کرتا ہے جہاں اس وقت بنیادی تجارت ہو رہی ہے۔ RELIANCE کے ساتھ 1,318 روپے پر، 1320 کی ہڑتال ہمارا حوالہ نقطہ ہے، اور ہر دوسری ہڑتال کو موجودہ قیمت کے خلاف سمجھا جاتا ہے۔</p>\n<ul>\n<li><strong>پیسے پر</strong>، یا ATM، ایک آپشن ہے جس کی ہڑتال موجودہ قیمت پر، یا اس کے بالکل قریب ہے۔ 1,318 پر RELIANCE کے ساتھ، 1320 کی سٹرائیک پیسے کی سٹرائیک ہے۔ یہ چاقو کے کنارے پر متوازن ہے، ابھی تک استعمال کرنے کے قابل نہیں ہے لیکن کسی بھی طرح سے ٹپ کرنے کے لیے تیار ہے۔</li>\n<li><strong>پیسے میں</strong>، یا ITM، ایک ایسا آپشن ہے جو پہلے سے ہی حقیقی، سیٹل اب قابل ہے۔ اگر یہ اس وقت طے پا جائے تو آپ کو فائدہ ہوگا۔ اس بلٹ ان ویلیو کا ایک نام ہے، <strong>اندرونی قدر</strong>، پریمیم کا وہ حصہ جو پہلے سے ہی قابل قدر معاہدے کی عکاسی کرتا ہے۔</li>\n<li><strong>باہر کا پیسہ</strong>، یا OTM، ایک آپشن ہے جس کی کوئی اندرونی قدر نہیں ہے۔ اسے ابھی طے کرنے سے آپ کو کچھ حاصل نہیں ہوگا، لہذا اس کا پورا پریمیم امید ہے کہ اسٹاک ختم ہونے سے پہلے ہی منتقل ہوجائے گا۔ OTM آپشنز مارکیٹ کے سستے لاٹری ٹکٹ ہیں۔</li>\n</ul>\n<p>پورا خیال اندرونی قدر پر منحصر ہے، اصل یہاں اور اب قابل قدر ہے۔ ان دی منی آپشن میں کچھ ہے۔ پیسے سے باہر کا آپشن کوئی نہیں ہے۔ ایک ایٹ-دی-منی آپشن باؤنڈری پر دائیں طرف بیٹھتا ہے جس میں بنیادی طور پر کوئی نہیں ہوتا ہے۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>پیسہ اس وقت اختیارات کو ان کی حقیقی قدر کے مطابق ترتیب دیتا ہے۔ ان دی منی کی اندرونی قدر ہوتی ہے جسے آپ آج نقد کر سکتے ہیں۔ باہر کے پیسے کے پاس کوئی نہیں ہے اور یہ سب امید ہے۔ پیسہ ان کے درمیان لائن پر بیٹھتا ہے۔</p>\n</div></div>\n<h2 id=\"moneyness-is-mirror-image-for-calls-and-puts\">پیسہ کالز اور پوٹس کے لیے آئینہ دار ہے۔</h2>\n<p>یہ وہ حصہ ہے جو ابتدائیوں کو الجھاتا ہے، لہذا اسے آہستہ سے لیں۔ آیا سٹرائیک پیسے میں ہے یا باہر ہے اس بات پر منحصر ہے کہ آپ کال کر رہے ہیں یا پوٹ۔ دونوں آئینہ دار امیجز ہیں، کیونکہ قیمت بڑھنے پر کال کا منافع ہوتا ہے اور قیمت گرنے پر منافع ہوتا ہے۔</p>\n<p>کے لیے <strong>کال</strong>ہڑتال پر خریدنے کا حق:</p>\n<ul>\n<li>کال ہے۔ <strong>پیسے میں</strong> جب ہڑتال ہے <strong>نیچے</strong> موجودہ قیمت. سستا خریدنے کا آپ کا حق پہلے ہی کسی چیز کے قابل ہے۔ 1,318 پر RELIANCE کے ساتھ 1300 کال آپ کو مارکیٹ سے نیچے 18 روپے خریدنے دیتی ہے۔</li>\n<li>کال ہے۔ <strong>پیسے سے باہر</strong> جب ہڑتال ہے <strong>اوپر</strong> موجودہ قیمت. آپ کا 1340 پر خریدنے کا حق بیکار ہے جبکہ اسٹاک 1,318 پر بیٹھتا ہے، کیونکہ اوپن مارکیٹ سستی ہے۔</li>\n</ul>\n<p>کے لیے <strong>ڈال</strong>، ہڑتال پر فروخت کرنے کا حق، ہر سمت پلٹائیں:</p>\n<ul>\n<li>ڈال ہے <strong>پیسے میں</strong> جب ہڑتال ہے <strong>اوپر</strong> موجودہ قیمت. اونچی فروخت کرنے کا آپ کا حق پہلے ہی کچھ قابل ہے۔ 1,318 پر RELIANCE کے ساتھ ایک 1340 پوٹ آپ کو مارکیٹ میں 22 روپے کے اوپر فروخت کرنے دیتا ہے۔</li>\n<li>ڈال ہے <strong>پیسے سے باہر</strong> جب ہڑتال ہے <strong>نیچے</strong> موجودہ قیمت. آپ کا 1300 پر فروخت کرنے کا حق بیکار ہے جبکہ اسٹاک 1,318 پر بیٹھتا ہے، کیونکہ اوپن مارکیٹ زیادہ ادائیگی کرتی ہے۔</li>\n</ul>\n<p>اسے یاد رکھنے کی ترکیب: ایک کال اسٹرائیک کو کم چاہتی ہے تاکہ یہ سستی خرید سکے، ایک پٹ اسٹرائیک کو زیادہ چاہتا ہے تاکہ یہ عزیز فروخت کر سکے۔ ان دی منی کا ہمیشہ مطلب ہوتا ہے کہ ہڑتال آپ کو اس وقت مارکیٹ سے بہتر ڈیل دیتی ہے۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>جب بھی آپ کھو جائیں، ایک سوال پوچھیں: اگر میں نے اس اختیار کو اس سیکنڈ میں استعمال کیا تو کیا مجھے فائدہ ہوگا؟ اگر ہاں، تو یہ ان دی منی ہے۔ اگر نہیں، تو یہ رقم سے باہر ہے۔ یہ واحد ٹیسٹ ہر بار کالز اور پوٹس دونوں کے لیے کام کرتا ہے۔</p>\n</div></div>\n<h2 id=\"a-moneyness-table-around-1320\">1320 کے آس پاس پیسہ کی میز</h2>\n<p>آئیے اسے ٹھوس انداز میں پیش کریں۔ RELIANCE 1,318 پر ہے، اور یہاں ہر ایک پر کال اور پوٹ کی رقم کے ساتھ ہڑتالوں کی ایک سیڑھی ہے۔ ہر قطار میں پڑھیں اور آئینہ دیکھیں۔</p>\n<table>\n<thead>\n<tr>\n<th>ہڑتال</th>\n<th>پیسے کو کال کریں۔</th>\n<th>پیسہ لگائیں۔</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1260</td>\n<td>پیسے میں</td>\n<td>باہر کا پیسہ</td>\n</tr>\n<tr>\n<td>1300</td>\n<td>پیسے میں</td>\n<td>باہر کا پیسہ</td>\n</tr>\n<tr>\n<td>1320</td>\n<td>پیسے پر</td>\n<td>پیسے پر</td>\n</tr>\n<tr>\n<td>1340</td>\n<td>باہر کا پیسہ</td>\n<td>پیسے میں</td>\n</tr>\n<tr>\n<td>1380</td>\n<td>باہر کا پیسہ</td>\n<td>پیسے میں</td>\n</tr>\n</tbody></table>\n<p>صاف ہم آہنگی کو دیکھیں۔ موجودہ قیمت سے کم، کالیں پیسے کے اندر ہیں اور پوٹس پیسے سے باہر ہیں۔ اس کے اوپر، کردار بدل جاتے ہیں۔ اور 1320 کی سٹرائیک، 1,318 قیمت کے بالکل ساتھ بیٹھی ہے، دونوں کے لیے رقم ہے۔ ایک ہی سیڑھی مخالف سمتوں میں پڑھتی ہے اس پر منحصر ہے کہ آپ کس طرف، کال کریں یا ڈالیں، آپ پکڑتے ہیں۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-basics/images/diagram-moneyness.png\" alt=\"کال کے لیے پیسے کی سیڑھی: موجودہ قیمت سے نیچے کی سٹرائیکس اصل قیمت کے ساتھ پیسے کے اندر ہیں، قیمت پر سٹرائیک پیسے پر ہے، اور اس سے اوپر کی ہڑتالیں پیسے سے باہر ہیں اور تمام امیدیں ہیں۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>کال کے لیے پیسے کی سیڑھی: موجودہ قیمت سے نیچے کی سٹرائیکس اصل قیمت کے ساتھ پیسے کے اندر ہیں، قیمت پر سٹرائیک پیسے پر ہے، اور اس سے اوپر کی ہڑتالیں پیسے سے باہر ہیں اور تمام امیدیں ہیں۔</figcaption></figure>\n\n<div class=\"callout example\"><span class=\"callout-tag\">حقیقی مثال</span><div><p>RELIANCE کے ساتھ 1,318 پر 1300 کال کریں۔ اس کو استعمال کرنے کا مطلب ہے 1300 پر خریدنا جب مارکیٹ 1,318 ہے، جس کی فوری قیمت 18 روپے فی شیئر ہے۔ وہ 18 روپے اس کی اندرونی قیمت ہے، لہذا کال ان دی منی ہے۔ مماثل 1300 پوٹ آپ کو 1300 پر 1,318 مارکیٹ میں فروخت کرنے دے گا، جو کہ بے معنی ہے، اس لیے پوٹ صفر کی اندرونی قیمت کے ساتھ پیسے سے باہر ہے۔</p>\n</div></div>\n<h2 id=\"why-out-of-the-money-options-are-so-cheap\">پیسے سے باہر کے اختیارات اتنے سستے کیوں ہیں۔</h2>\n<p>ابتدائی افراد اکثر ایک وجہ سے پیسے سے باہر کے اختیارات کی طرف راغب ہوتے ہیں: وہ سستے ہیں۔ پیسے سے باہر RELIANCE کال کی قیمت صرف چند روپے فی شیئر ہوسکتی ہے۔ فتنہ ظاہر ہے۔ چھوٹے اخراجات، اور اگر اسٹاک ایک بڑا اقدام کرتا ہے، تو فیصد کا فائدہ بہت بڑا ہوسکتا ہے۔</p>\n<p>لیکن سمجھیں کہ آپ کیا خرید رہے ہیں۔ پیسے سے باہر کا آپشن ہے۔ <strong>کوئی اندرونی قدر نہیں</strong>. اس کا پورا پریمیم امید ہے، مارکیٹ کی قیمت اس موقع پر کہ اسٹاک ختم ہونے سے پہلے کافی حد تک سفر کر لے تاکہ ہڑتال کو مفید بنایا جا سکے۔ اس کے نیچے کچھ بھی ٹھوس نہیں ہے۔</p>\n<p>یہ امید دو طرح سے کمزور ہے۔</p>\n<ul>\n<li>اسٹرائیک تک پہنچنے اور اسے پاس کرنے کے لیے اسٹاک کو کافی آگے بڑھنا چاہیے، اور پھر آپشن ایک روپیہ ادا کرنے سے پہلے، آپ کے ادا کردہ پریمیم کو شکست دینا جاری رکھیں۔</li>\n<li>گھڑی چل رہی ہے۔ امید جو ایک پریمیم پر مشتمل ہے، کہلاتی ہے۔ <strong>وقت کی قدر</strong>ختم ہونے کے قریب آتے ہی پگھل جاتا ہے، اور آخری دنوں میں یہ سب سے تیزی سے پگھلتا ہے۔ پیسہ سے باہر کا اختیار جو کبھی بھی اپنی ہڑتال تک نہیں پہنچتا صرف صفر تک خون بہہ جاتا ہے اور بیکار ختم ہوجاتا ہے۔</li>\n</ul>\n<p>یہی وجہ ہے کہ زیادہ تر پیسے والے خریدار ہار جاتے ہیں۔ وہ امید کے لیے ادائیگی کرتے ہیں، اسٹاک وقت پر کافی سفر کرنے میں ناکام رہتا ہے، اور جو پریمیم انھوں نے خاموشی سے ادا کیا ہے وہ ختم ہوجاتا ہے۔ سستی اچھی قیمت کی طرح نہیں ہے۔ ہم وقت کی قدر دیتے ہیں اور یہ آہستہ آہستہ ان کے اپنے باب کو آگے بڑھاتا ہے، کیونکہ یہ واحد سب سے اہم قوت ہے جو آپشن خریدار کے خلاف کام کرتی ہے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>پیسے سے باہر کے اختیارات کی سستی پھندا ہے، سودا نہیں۔ آپ ایک آخری تاریخ کے ساتھ خالص امید خرید رہے ہیں۔ زیادہ تر پیسے سے باہر کے اختیارات بیکار ختم ہو جاتے ہیں، اور خریدار جو ان کا پیچھا کرتے ہیں وہ مسلسل ہار جاتے ہیں۔ اپنے ساتھ ایماندار رہیں کہ اسٹاک کو واقعی کتنی دور جانا ہے، اور کتنی جلدی۔</p>\n</div></div>\n<h2 id=\"how-moneyness-shifts-as-the-stock-moves\">اسٹاک کی حرکت کے ساتھ ہی پیسہ کیسے بدلتا ہے۔</h2>\n<p>پیسہ کوئی مستقل لیبل نہیں ہے۔ یہ بنیادی حرکت کے لمحے کو تبدیل کرتا ہے، کیونکہ ہڑتال طے شدہ ہے جبکہ موجودہ قیمت نہیں ہے۔ دیکھیں کہ ہماری 1320 سٹرائیک کا کیا ہوتا ہے جب RELIANCE بھٹکتا ہے۔</p>\n<ul>\n<li>RELIANCE 1,318 پر ہے۔ 1320 کال اور پوٹ دونوں رقم پر ہیں، ہڑتال کے وقت متوازن ہیں۔</li>\n<li>RELIANCE بڑھ کر 1,360 ہو گیا۔ اب 1320 کال ان دی منی ہے، کیونکہ 1320 پر خریدنے کا حق 1,360 مارکیٹ کے مقابلے میں 40 روپے ہے۔ 1320 پوٹ پیسے سے باہر نکل گیا ہے۔</li>\n<li>RELIANCE 1,280 پر آتا ہے۔ اب 1320 پوٹ ان دی منی ہے، جس کی قیمت 1,280 مارکیٹ کے مقابلے میں 40 روپے ہے، جبکہ 1320 کال رقم سے باہر ہو چکی ہے۔</li>\n</ul>\n<p>لہذا ایک آپشن جو آپ نے پیسے پر خریدا ہے وہ پیسے میں بڑھ سکتا ہے جیسے ہی اسٹاک آپ کے راستے پر چلتا ہے، حقیقی اندرونی قیمت حاصل کرتا ہے، یا پیسے سے باہر نکل جاتا ہے کیونکہ یہ آپ کے خلاف ہوتا ہے، دوبارہ خالص امید بن جاتا ہے۔ کسی پوزیشن کو باہر کے پیسے سے ان دی منی میں کراس کرتے ہوئے دیکھنا، جیسے جیسے جاتا ہے داخلی قدر اٹھانا، بالکل وہی ہے جو ایک جیتنے والا آپشن خریدار 28 جولائی کی آمد سے پہلے دیکھنے کی امید کر رہا ہے۔</p>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">کیا آپ جانتے ہیں؟</span><div><p>میعاد ختم ہونے کے عین وقت پر، صرف اندرونی قدر ہی باقی رہتی ہے۔ پیسے کے اندر موجود ہر آپشن اس کی اندرونی قیمت کے مطابق طے پاتا ہے، اور پیسے سے باہر ہونے والے ہر آپشن کی میعاد صفر پر ختم ہو جاتی ہے۔ وقت کی قیمت میں قیمت کی تمام امیدیں ختم ہو چکی ہیں، اس لیے ایکسپائری ڈے پر پیسہ پوری کہانی ہے۔</p>\n</div></div>\n<h2 id=\"what-to-carry-forward\">آگے کیا لے جانا ہے</h2>\n<p>اب آپ اس کی بالٹی میں کوئی بھی آپشن رکھ سکتے ہیں اور جان سکتے ہیں کہ اس بالٹی کا کیا مطلب ہے۔</p>\n<ul>\n<li><strong>پیسے میں</strong> اختیارات میں حقیقی اندرونی قدر ہوتی ہے جسے آپ آج نقد کر سکتے ہیں۔ کالز موجودہ قیمت سے کم رقم میں ہیں۔ پوٹس اس کے اوپر ان دی منی ہیں۔</li>\n<li><strong>پیسے پر</strong> اختیارات موجودہ قیمت پر درست ہیں، 1320 سٹرائیک 1,318 پر RELIANCE کے ساتھ، کنارے پر متوازن ہے۔</li>\n<li><strong>باہر کا پیسہ</strong> اختیارات کی کوئی اندرونی قیمت نہیں ہے۔ وہ سب امید ہیں، کسی وجہ سے سستے ہیں، اور ان میں سے اکثر بیکار ختم ہو جاتے ہیں۔</li>\n<li>پیسہ ہے a <strong>آئینے کی تصویر</strong> کالز اور پوٹس کے لیے، اور یہ <strong>شفٹوں</strong> جیسا کہ اسٹاک حرکت کرتا ہے، چونکہ ہڑتال طے شدہ ہے اور قیمت نہیں ہے۔</li>\n</ul>\n<p>قدرتی اگلا سوال یہ ہے کہ پریمیم کیا بناتا ہے۔ ہم نے اب دو بار جواب کی طرف اشارہ کیا ہے: اندرونی قدر، حقیقی قدر، علاوہ وقت کی قدر، امید۔ اگلا باب ہر پریمیم کو ان دو حصوں میں تقسیم کرتا ہے اور آپ کو وقت کی قدر کا سست، مستحکم خون دکھاتا ہے جو آپشن خریدار کا خاموش دشمن ہے۔</p>\n","toc":[{"level":2,"text":"تین بالٹیاں","id":"the-three-buckets"},{"level":2,"text":"پیسہ کالز اور پوٹس کے لیے آئینہ دار ہے۔","id":"moneyness-is-mirror-image-for-calls-and-puts"},{"level":2,"text":"1320 کے آس پاس پیسہ کی میز","id":"a-moneyness-table-around-1320"},{"level":2,"text":"پیسے سے باہر کے اختیارات اتنے سستے کیوں ہیں۔","id":"why-out-of-the-money-options-are-so-cheap"},{"level":2,"text":"اسٹاک کی حرکت کے ساتھ ہی پیسہ کیسے بدلتا ہے۔","id":"how-moneyness-shifts-as-the-stock-moves"},{"level":2,"text":"آگے کیا لے جانا ہے","id":"what-to-carry-forward"}],"imgCount":1,"hasContent":true},"10":{"html":"<p>جب آپ RELIANCE 1320 کال کے لیے تقریباً 31 روپے فی شیئر ادا کرتے ہیں، تو آپ ایک چیز نہیں خرید رہے ہیں۔ آپ ایک ہی قیمت کے ٹیگ میں بنڈل والی دو چیزیں خرید رہے ہیں۔ اس 31 روپے کا ایک حصہ مشکل ہے، یہاں اور اب اس قابل ہے کہ آپ آج جمع کر سکتے ہیں۔ دوسرا حصہ خالص امید ہے، یہ شرط ہے کہ 28 جولائی کو آپشن کے مرنے سے پہلے اسٹاک آپ کے راستے پر چلا جائے گا۔ ان دونوں حصوں کو الگ الگ دیکھنا سیکھنا ایک نیا آپشن ٹریڈر کی سب سے بڑی چھلانگ میں سے ایک ہے، کیونکہ یہ بتاتا ہے کہ اسٹاک کے بمشکل حرکت کرنے پر بھی آپشن کیوں پیسے کھو سکتا ہے۔ یہ باب پریمیم کو اپنے دو ٹکڑوں میں الگ کرتا ہے اور آپ کو دکھاتا ہے کہ کیوں ان میں سے ایک خاموشی سے آپ کے خلاف ہر ایک دن کام کر رہا ہے۔</p>\n<h2 id=\"the-premium-is-made-of-two-parts\">پریمیم دو حصوں سے بنا ہے۔</h2>\n<p>ہر آپشن پریمیم صاف طور پر دو اجزاء میں تقسیم ہوتا ہے جو ہمیشہ آپ کی ادا کردہ قیمت میں اضافہ کرتا ہے۔</p>\n<ul>\n<li><strong>اندرونی قدر</strong> اصلی، سیٹل-اب آپشن کے قابل ہے۔ یہ وہ رقم ہے جو آپ جیب میں ڈالیں گے اگر آپشن اس فوری طور پر طے ہو جائے۔ کے لیے <strong>کال</strong>، اندرونی قدر یہ ہے کہ اسپاٹ کی قیمت اسٹرائیک سے کتنی دور ہے۔ کے لیے <strong>ڈال</strong>، یہ ہے کہ اسپاٹ ہڑتال کے نیچے کتنی دور ہے۔ اندرونی قدر کبھی بھی منفی نہیں ہو سکتی، کیونکہ ایک آپشن جو آپ کے خلاف ختم ہو جاتا ہے اسے نقصان پر طے کرنے کی بجائے ختم ہونے کے لیے چھوڑ دیا جاتا ہے۔ سب سے خراب یہ صفر ہے۔</li>\n<li><strong>وقت کی قدر</strong> باقی سب کچھ ہے. یہ پریمیم کا وہ حصہ ہے جسے آپ خالصتاً اس موقع کے لیے ادا کرتے ہیں کہ اسٹاک ایکسپائری سے پہلے آپ کے حق میں مزید آگے بڑھ جائے۔ کچھ لوگ اسے امید پریمیم کہتے ہیں، اور یہ نام ایماندار ہے۔ وقت کی قیمت وہ مارکیٹ ہے جو آپ سے وقت اور امکان کے لیے چارج کرتی ہے۔</li>\n</ul>\n<p>رشتہ سادہ ہے۔ پریمیم داخلی قدر اور وقت کی قدر کے برابر ہے۔ اگر آپ تین میں سے کسی دو کو جانتے ہیں تو آپ تیسرے کو جانتے ہیں۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>پریمیم داخلی قدر اور وقت کی قدر کے برابر ہے۔ داخلی قدر وہ ہے جو آپشن کے قابل ہے اگر اس کا استعمال کیا جائے۔ وقت کی قیمت وہ ہے جو آپ زیادہ کی امید کے لیے ادا کرتے ہیں۔ وہ ہمیشہ پوری قیمت میں اضافہ کرتے ہیں۔</p>\n</div></div>\n<h2 id=\"a-real-reliance-split\">ایک حقیقی RELIANCE تقسیم</h2>\n<p>آئیے اسے حقیقی نمبروں پر لنگر انداز کرتے ہیں۔ RELIANCE قریب بند <strong>1,318 روپے</strong> 25 جون 2026 کو قریب ترین ہڑتال ہے۔ <strong>1320</strong>، اور ماڈلڈ ایٹ دی منی پریمیم کے بارے میں ہے۔ <strong>31 روپے فی شیئر</strong>، جس کے بارے میں ہے۔ <strong>15,590 روپے</strong> 500 کی ایک لاٹ کے لیے۔</p>\n<p>لے لو <strong>1320 کال کریں۔</strong> پہلے سپاٹ 1318 ہے، ہڑتال 1320 ہے، تو اسپاٹ ہڑتال کے نیچے بیٹھا ہے۔ کال کی اندرونی قدر صرف اس وقت ہوتی ہے جب اسپاٹ اسٹرائیک سے اوپر ہو، لہذا یہاں اندرونی قدر بالکل صفر ہے۔ اس کا مطلب ہے کہ آپ جو 31 روپے ادا کرتے ہیں وہ وقت کی قیمت ہے۔ اس کا ہر روپیہ امید ہے۔ آپ خالصتاً اس موقع کے لیے ادائیگی کر رہے ہیں کہ RELIANCE 1320 سے اوپر چڑھ جائے، اور پھر 28 جولائی سے پہلے جاری رہے۔</p>\n<p>اب میچنگ کو لے لیں۔ <strong>1320 ڈال دیا</strong>. جب اسپاٹ اسٹرائیک سے نیچے ہوتا ہے تو پوٹ کو اندرونی قدر حاصل ہوتی ہے۔ اسپاٹ 1318 ہے اور سٹرائیک 1320 ہے، اس لیے پوٹ 2 روپے کے حساب سے ہے۔ اس کی اندرونی قیمت 2 روپے فی شیئر ہے۔ اگر وہ پوٹ بھی 31 روپے کے قریب ٹریڈ کرتا ہے، تو اس کی ٹائم ویلیو 29 روپے فی شیئر ہے، کیونکہ 31 مائنس 2 سے 29 نکلتا ہے۔ لہذا پوٹ پریمیم امید کی ایک موٹی تہہ کے نیچے بیٹھا ہوا حقیقی مالیت کا ایک چھوٹا ٹکڑا ہے۔</p>\n\n<div class=\"callout example\"><span class=\"callout-tag\">حقیقی مثال</span><div><p>اسپاٹ 1318 پر 1320 کال: اندرونی قیمت 0 روپے، ٹائم ویلیو 31 روپے۔ یہ سب امید ہے۔ 1320 اسپاٹ 1318 پر: اندرونی قیمت 2 روپے، وقت کی قیمت 29 روپے۔ تقریباً تمام امیدیں، نیچے حقیقی مالیت کی پتلی منزل کے ساتھ۔ فی لاٹ 500، وہ 31 روپے کی کال تقریباً 15,590 روپے ہے، اس کا ہر پیسہ وقت کی قیمت۔</p>\n</div></div>\n<p>یہ کسی بھی آپشن کے لیے پیٹرن ہے جو کہ پیسے پر ہے یا پیسے سے باہر ہے۔ ایک <strong>پیسے سے باہر کے آپشن کی کوئی اندرونی قدر نہیں ہے۔</strong>، لہذا اس کا پورا پریمیم وقت کی قیمت ہے۔ یہی وجہ ہے کہ سستے، دور دراز کے اختیارات لاٹری ٹکٹوں کی طرح محسوس ہوتے ہیں۔ آپ امید کے سوا کچھ نہیں خرید رہے ہیں، اور امید پر ایکسپائری ڈیٹ کی مہر لگی ہوئی ہے۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-basics/images/diagram-intrinsic-time-value.png\" alt=\"31 روپے کا پریمیم ایک اسٹیکڈ بار کے طور پر تیار کیا گیا ہے: نچلے حصے میں اندرونی قدر کا ایک پتلا بینڈ اور اوپر ٹائم ویلیو کا ایک موٹا بینڈ، جس میں ٹائم ویلیو بینڈ ختم ہونے کے قریب پگھل جاتا ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>31 روپے کا پریمیم ایک اسٹیکڈ بار کے طور پر تیار کیا گیا ہے: نچلے حصے میں اندرونی قدر کا ایک پتلا بینڈ اور اوپر ٹائم ویلیو کا ایک موٹا بینڈ، جس میں ٹائم ویلیو بینڈ ختم ہونے کے قریب پگھل جاتا ہے۔</figcaption></figure>\n<h2 id=\"time-decay-the-melting-top-band\">وقت کا زوال: پگھلنے والا ٹاپ بینڈ</h2>\n<p>یہ وہ حصہ ہے جو ابتدائی افراد کو حیران کر دیتا ہے۔ اندرونی قیمت اس وقت طے کی جاتی ہے جہاں اسٹاک ابھی ہے۔ وقت کی قدر نہیں ہے۔ ایکسپائری کے قریب آتے ہی وقت کی قدر پگھل جاتی ہے، اور ایکسپائری کے دن یہ صفر تک پہنچ جاتی ہے۔ اس مستحکم لیک کو کہا جاتا ہے۔ <strong>وقت کی خرابی</strong>، اور تاجر اسے یونانی نام سے بھی جانتے ہیں۔ <strong>تھیٹا</strong>.</p>\n<p>وقت کی قدر کو اندرونی قدر کے اوپر بیٹھے برف کے بلاک کے طور پر سوچیں۔ ہر دن جو گزرتا ہے، اس میں سے تھوڑا سا زیادہ پگھل جاتا ہے۔ 28 جولائی کو 32 دن باقی رہ گئے ہیں، RELIANCE 1320 آپشن میں ابھی بھی ٹائم ویلیو کا مکمل بلاک ہے، کیونکہ اسٹاک کو منتقل کرنے کے لیے کافی وقت ہے۔ جیسے جیسے دن گزرتے جاتے ہیں اور کچھ بھی ڈرامائی نہیں ہوتا، وہ بلاک سکڑ جاتا ہے۔ آپشن اب بھی موجود ہے، اسٹاک بمشکل منتقل ہوا ہے، پھر بھی آپ کا پریمیم خاموشی سے کم ہو رہا ہے۔</p>\n<p>اور پگھل بھی نہیں ہے۔ <strong>وقت کا زوال شروع میں سست اور آخر میں ظالمانہ ہے۔</strong> ابتدائی ہفتوں میں آپشن وقت کی قدر کو آہستہ سے کھو دیتا ہے۔ آخری ہفتے میں، اور خاص طور پر آخری یا دو دن، بقیہ وقت کی قدر تیزی سے گر جاتی ہے، کیونکہ اسے بچانے کے لیے کسی اقدام کے لیے تقریباً کوئی وقت نہیں بچا ہے۔ ایک آپشن جو کہ میعاد ختم ہونے کی صبح ختم ہو جائے گا اس کے آخری چند روپوں کی ٹائم ویلیو ختم ہوتے ہی ختم ہو جائے گی۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>وقت کا خاتمہ آپشن خریدار کا خاموش دشمن ہے۔ آپ درست کہہ سکتے ہیں کہ RELIANCE بڑھے گا، 1320 کال خریدے گا، اور پھر بھی اگر اضافہ بہت کم ہے یا بہت آہستہ آتا ہے تو پیسے کھو دیں گے۔ گھڑی آپ سے ہر روز کرایہ پر لیتی ہے، اور یہ ختم ہونے سے پہلے آخری دنوں میں سب سے زیادہ چارج کرتی ہے۔</p>\n</div></div>\n<h2 id=\"why-this-is-the-buyer-s-enemy-and-the-seller-s-friend\">یہ خریدار کا دشمن اور بیچنے والا دوست کیوں ہے؟</h2>\n<p>جب آپ کوئی آپشن خریدتے ہیں، تو آپ پگھلنے والے آئس بلاک کے مالک ہوتے ہیں۔ وقت کا زوال آپ کے خلاف کام کرتا ہے۔ ہر صبح، باقی سب برابر، آپ کے اختیار کی قیمت اس سے پہلے کی رات کے مقابلے میں تھوڑی کم ہے، صرف اس لیے کہ ایک اور دن گزر گیا ہے۔ جیتنے کے لیے، اسٹاک کو کافی منتقل ہونا چاہیے، اور جلد ہی، اس روزمرہ کے رساو کو پیچھے چھوڑنے کے لیے۔ یہ واحد سب سے بڑی وجہ ہے جس میں زیادہ تر آپشن خریدار پیسے کھو دیتے ہیں۔ وہ سمت کے بارے میں درست ہیں لیکن سائز یا رفتار کے بارے میں غلط ہیں، اور وقت کا زوال خاموشی سے باقی کو کھا جاتا ہے۔</p>\n<p>وہ شخص جو آپ کی تجارت کے دوسری طرف ہے۔ <strong>اختیار بیچنے والا</strong>، مخالف پوزیشن رکھتا ہے۔ انہوں نے اس وقت کی قیمت پہلے سے حاصل کی، اور انہیں ہر روز اس میں سے زیادہ سے زیادہ رکھنا پڑتا ہے کہ اسٹاک کوئی بڑا اقدام کرنے میں ناکام ہوجاتا ہے۔ بیچنے والے کے لیے، وقت کا زوال ایک ٹیل ونڈ ہے۔ ہم بعد کے باب میں مناسب طریقے سے فروخت کا احاطہ کرتے ہیں، بشمول اس کے سنگین خطرات، لیکن یہ اب ہم آہنگی کو دیکھنے میں مدد کرتا ہے۔ وقت کی قیمت جو آپ خریدار کے طور پر ادا کرتے ہیں وہ وقت کی قیمت ہے جو فروخت کنندہ جمع کرنے کی کوشش کر رہا ہے۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>کوئی بھی آپشن خریدنے سے پہلے، پوچھیں کہ پریمیم کا کتنا اصل اندرونی قدر ہے اور وقت کی قیمت کتنی ہے آپ کو آگے بڑھنا پڑے گا۔ اگر یہ تمام وقت کی قیمت ہے، تو آپ خالص امید خرید رہے ہیں، اور گھڑی اسے فوراً ختم کرنا شروع کر دیتی ہے۔</p>\n</div></div>\n<h2 id=\"how-the-split-shifts-as-reliance-moves\">RELIANCE کی حرکت کے ساتھ ہی تقسیم کیسے بدلتی ہے۔</h2>\n<p>دونوں اجزاء منجمد نہیں ہیں۔ وہ حقیقی وقت میں منتقل ہوتے ہیں جیسے جیسے اسٹاک چلتا ہے اور جیسے جیسے دن گزرتے ہیں۔</p>\n<ul>\n<li>اگر RELIANCE 1318 سے 1340 تک بڑھتا ہے، تو 1320 کال کو اندرونی قدر حاصل ہوتی ہے۔ اب یہ 20 روپے میں ہے، لہذا کم از کم 20 روپے پریمیم مشکل ہے، جس میں وقت کی قیمت سب سے اوپر ہے۔</li>\n<li>اگر RELIANCE 1300 پر آجاتا ہے، تو 1320 کال مزید رقم سے باہر ہوجاتی ہے۔ اس کی داخلی قدر صفر رہتی ہے، اور صرف وقت کی قدر باقی رہ جاتی ہے، اب چھوٹی ہے کیونکہ اسے جس اقدام کی ضرورت ہے وہ بڑی ہو گئی ہے۔</li>\n<li>اگر RELIANCE صرف دو ہفتوں کے لیے 1318 پر بیٹھتا ہے، نہ تو کال کریں اور نہ ہی داخلی قدر حاصل کریں، پھر بھی دونوں کیلنڈر کے لیے وقت کی قدر کھو دیتے ہیں۔ پریمیم سکڑتا ہے حالانکہ کچھ نہیں ہوا۔</li>\n</ul>\n<p>وہ آخری نقطہ ہے جو یادداشت میں جلتا ہے۔ <strong>جب اسٹاک کہیں نہیں جاتا ہے تو ایک آپشن قدر کھو سکتا ہے۔</strong> ایک حصص جو ایک ماہ کے لیے فلیٹ بند ہو جاتا ہے اس کی قیمت طویل مدتی شیئر ہولڈر کو نہیں ہوتی۔ ایک ہی فلیٹ مہینہ خاموشی سے آپشن خریدار کے زیادہ تر پریمیم کو تباہ کر سکتا ہے۔</p>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">کیا آپ جانتے ہیں؟</span><div><p>ختم ہونے والے دن، وقت کی قدر ختم ہو جاتی ہے اور صرف اندرونی قدر باقی رہ جاتی ہے۔ کسی بھی آپشن کی 28 جولائی کی ادائیگی خالص اندرونی قیمت ہے: اس نے پیسے میں کتنی دور ختم کی، اور اس سے زیادہ کچھ نہیں۔ ہر چیز جو آپ نے اس سے اوپر ادا کی تھی وہ وقت کی قیمت تھی، اور گھڑی نے اب یہ سب جمع کر لیا ہے۔</p>\n</div></div>\n<p>لہذا آپ جو پریمیم ادا کرتے ہیں وہ ایک نمبر میں دو کہانیاں ہیں۔ اندرونی قدر ایک پرسکون، حقیقت پر مبنی حصہ ہے، جس قدر آپشن نے حاصل کیا ہے اس سے اسٹاک اصل میں کہاں ہے۔ وقت کی قدر امید کا حصہ ہے، کرایہ جو آپ زیادہ کے موقع کے لیے ادا کرتے ہیں، اور یہ آپ کے خریدنے کے لمحے سے پگھل رہا ہے۔ ان دونوں کو اپنے سر میں الگ رکھیں اور ہر آپشن کا برتاؤ جو آپ کبھی تجارت کرتے ہیں وہ بہت کم پراسرار ہو جاتا ہے۔ جب ہم اگلے چند ابواب میں حقیقی ادائیگی کے خاکے پڑھتے ہیں، تو آپ دیکھیں گے کہ یہ تقسیم اس وقت زندہ ہوتی نظر آئے گی جب اسٹرائیک کے گرد وکر موڑتا ہے۔</p>\n","toc":[{"level":2,"text":"پریمیم دو حصوں سے بنا ہے۔","id":"the-premium-is-made-of-two-parts"},{"level":2,"text":"ایک حقیقی RELIANCE تقسیم","id":"a-real-reliance-split"},{"level":2,"text":"وقت کا زوال: پگھلنے والا ٹاپ بینڈ","id":"time-decay-the-melting-top-band"},{"level":2,"text":"یہ خریدار کا دشمن اور بیچنے والا دوست کیوں ہے؟","id":"why-this-is-the-buyer-s-enemy-and-the-seller-s-friend"},{"level":2,"text":"RELIANCE کی حرکت کے ساتھ ہی تقسیم کیسے بدلتی ہے۔","id":"how-the-split-shifts-as-reliance-moves"}],"imgCount":1,"hasContent":true},"11":{"html":"<p>آپ RELIANCE 1320 کال خریدتے ہیں، اس بات پر یقین رکھتے ہیں کہ اسٹاک اوپر جا رہا ہے۔ اگلی صبح 1318 سے 1325 تک، بالکل وہی سمت جس پر آپ شرط لگاتے ہیں۔ آپ منافع کی توقع کرتے ہوئے اپنی ٹریڈنگ اسکرین کھولتے ہیں، اور اس کے بجائے پوزیشن ایک چھوٹا سا نقصان ظاہر کرتی ہے۔ کچھ بھی نہیں ٹوٹا۔ آپ نے آپشن ٹریڈنگ میں سب سے اہم اور سب سے زیادہ غلط فہمی والے آئیڈیا کو ابھی پورا کیا ہے: آپ نے تجارت سے پہلے جس تصویر کا مطالعہ کیا، ادائیگی کا خاکہ، ایکسپائری ڈے کو بیان کرتا ہے، آج نہیں۔ نتیجہ جو اس نے 28 جولائی کو زندہ رہنے کا وعدہ کیا تھا۔ آج صبح آپ کی اسکرین پر موجود نمبر بالکل الگ چیز ہے، جس کی وجہ سے پے آف ڈایاگرام نے آپ کو کبھی نہیں دکھایا۔ یہ باب اس فرق کے بارے میں ہے، کیونکہ اس کو سمجھنا ہی ایک تاجر کو الگ کرتا ہے جو جانتا ہے کہ وہ کس چیز کا مالک ہے جو مسلسل، دردناک طور پر حیران رہتا ہے۔</p>\n<h2 id=\"a-payoff-diagram-is-a-picture-of-one-day\">ادائیگی کا خاکہ ایک دن کی تصویر ہے۔</h2>\n<p>ہر ادائیگی کا خاکہ جو آپ نے اس کورس میں دیکھا ہے، لمبی کال، لانگ پوٹ، شارٹ کال، آپ کے نفع یا نقصان کو ظاہر کرتی ہے۔ <strong>ختم ہونے پر</strong>, اس کے خلاف سازش کی گئی جہاں بنیادی تکمیل ہوتی ہے۔ یہ ایک خاص چیز کو فرض کرتا ہے: کہ آپ آخری دن تک آپشن کو برقرار رکھیں اور اسے خالص اندرونی قدر کے لیے طے کرنے دیں۔</p>\n<p>یہ مفروضہ بہت خاموشی سے کام کر رہا ہے۔ ایکسپائری ڈے پر کوئی ٹائم ویلیو باقی نہیں رہتی ہے، اس لیے آپشن اس کی اندرونی قدر کے عین مطابق ہے، اور ادائیگی ایک صاف جھکی ہوئی لکیر ہے، فلیٹ جہاں آپشن بیکار ختم ہو جاتا ہے، پھر ایک بار جب یہ رقم میں ختم ہو جائے تو ڈھلوان۔ مثال کے طور پر، لمبی کال کی ادائیگی، پریمیم کے نقصان پر، تقریباً 15,590 روپے، 1320 پر یا اس سے نیچے کسی بھی تکمیل کے لیے فلیٹ ہے، اور یہ وہاں سے چڑھتا ہے، 1351 پر بھی ٹوٹ جاتا ہے اور اوپر کا فائدہ ہوتا ہے۔</p>\n<p>لیکن بات یہاں ہے۔ وہ خاکہ اس بارے میں کچھ نہیں کہتا ہے کہ آپ کے اختیار کی میعاد ختم ہونے سے تیس دنوں میں سے کسی پر کیا قیمت ہے۔ یہ فائنل لائن کی تصویر ہے، ریس کی فلم نہیں۔ اور آپ کا پیسہ پوری طرح سے دوڑ میں ہے۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>ادائیگی کا خاکہ آپ کے نفع یا نقصان کو ختم ہونے پر ظاہر کرتا ہے، یہ فرض کرتے ہوئے کہ آپ آخری دن تک برقرار ہیں۔ یہ آج آپ کے نفع یا نقصان کی تصویر نہیں ہے۔ جس نتیجہ کا یہ وعدہ کرتا ہے وہ مکمل طور پر صرف اس وقت آتا ہے جب وقت کی قدر ختم ہونے کے دن صفر ہو جاتی ہے۔</p>\n</div></div>\n<h2 id=\"the-two-lines-the-finish-and-today\">دو لائنیں: ختم اور آج</h2>\n<p>یہی وجہ ہے کہ اس کورس میں ادائیگی کے چارٹ ایک نہیں بلکہ دو لائنوں کے ساتھ بنائے گئے ہیں۔ نیچے دی گئی لمبی کال کو قریب سے دیکھیں۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-basics/images/payoff-long-call.png\" alt=\"ٹھوس لکیر ایکسپائری پر نتیجہ ہے، نقطے والی لائن آج کی قدر ہے (T جمع صفر)، اور ان کے درمیان عمودی فرق وقت کی قدر ہے جو آپشن میں ابھی بھی باقی ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">چارٹ</span>ٹھوس لکیر ایکسپائری پر نتیجہ ہے، نقطے والی لائن آج کی قدر ہے (T جمع صفر)، اور ان کے درمیان عمودی فرق وقت کی قدر ہے جو آپشن میں ابھی بھی باقی ہے۔</figcaption></figure>\n<p>دی <strong>ٹھوس لائن</strong> ختم ہونے پر ادائیگی ہے، صاف مڑی ہوئی شکل جو ہم نے ابھی بیان کی ہے، بائیں طرف فلیٹ اور سٹرائیک کے دائیں طرف بڑھتی ہوئی ہے۔ دی <strong>نقطہ دار لائن</strong> ایک ہی آپشن کی قدر ہے۔ <strong>آج</strong>اس کے باقی تمام وقت کے ساتھ ابھی بھی منسلک ہے۔ اس نقطے والی لائن کے بارے میں تین چیزوں پر غور کریں۔</p>\n<p>سب سے پہلے، نقطے والا آج کا وکر بیٹھتا ہے۔ <strong>اوپر</strong> ٹھوس ختم ہونے والی لائن تقریبا ہر جگہ. ان کے درمیان عمودی فرق وقت کی قدر ہے، امید پریمیم کی قیمت اب بھی آپشن میں ہے کیونکہ میعاد ختم نہیں ہوئی ہے۔ تقریباً بتیس دن باقی ہیں، خلا وسیع ہے۔</p>\n<p>دوسرا، نقطے والا وکر ہے۔ <strong>ہموار اور گول</strong>، تیزی سے جھکا نہیں. میعاد ختم ہونے سے پہلے ہڑتال پر ایک آپشن بیکار سے قیمتی تک صاف طور پر نہیں پلٹتا ہے۔ یہ آہستہ سے جھکتا ہے، کیونکہ اسٹاک کے سفر کے لیے ابھی بھی وقت ہے۔</p>\n<p>تیسری، اور سب سے اہم، دو لائنیں ہیں۔ <strong>ایک ہی لائن نہیں</strong>. آج آپ کا نفع یا نقصان نقطہ دار وکر سے پڑھا جاتا ہے۔ ختم ہونے پر آپ کا منافع یا نقصان ٹھوس لائن سے پڑھا جاتا ہے۔ دونوں کو الجھانا اختیارات میں تقریبا کسی بھی چیز سے زیادہ ابتدائی درد کی جڑ ہے۔</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>پے آف چارٹ پر ٹھوس لائن اور نقطے دار وکر دو مختلف چیزیں ہیں۔ نقطہ دار وکر وہی ہے جو آپ کے اختیار کی اب قابل ہے۔ ٹھوس لائن وہی ہے جو ختم ہونے پر اس کی قیمت ہوگی۔ ان کے درمیان خلا وقت کی قدر ہے جو ابھی پگھلنا باقی ہے۔</p>\n</div></div>\n<h2 id=\"what-drives-the-dotted-line-four-forces\">نقطے والی لائن کو کیا چلاتا ہے: چار قوتیں۔</h2>\n<p>اگر آج کے نقطے والا وکر وہی ہے جو آپ کی سکرین دراصل دکھاتا ہے، تو آپ کو یہ جاننے کی ضرورت ہے کہ اسے کیا حرکت دیتا ہے۔ میعاد ختم ہونے سے پہلے، آپشن کی قیمت کو چار قوتوں کے ذریعے دھکیل دیا جاتا ہے، اور صرف پہلی ایک سادہ دشاتمک شرط ہے جسے آپ نے سوچا تھا کہ آپ بنا رہے ہیں۔</p>\n<ul>\n<li><strong>ڈیلٹا</strong> یہ ہے کہ اس وقت اسٹاک میں ہر ایک روپے کی منتقلی کے لیے آپشن کی قیمت کتنی بڑھتی ہے۔ ایک ایٹ-دی-منی کال کا ڈیلٹا نصف کے قریب ہوتا ہے، یعنی یہ ہر ایک روپے کے لیے صرف پچاس پیسے حاصل کرتا ہے RELIANCE بڑھتا ہے، نہ کہ پورا روپیہ۔ لہذا ایک چھوٹی سی حرکت آپ کو ابتدائیوں کی توقع سے کم کماتی ہے۔</li>\n<li><strong>تھیٹا</strong> یومیہ وقت کی کشی خون ہے. ہر دن جو گزرتا ہے، اختیار خاموشی سے تھوڑا سا وقت کی قدر کھو دیتا ہے، یہاں تک کہ اگر اسٹاک کچھ نہیں کرتا ہے۔ تھیٹا آپ کے خلاف خریدار کے طور پر، سارا دن، ہر روز کام کرتا ہے، اور آخری ہفتوں میں یہ سب سے مشکل کاٹتا ہے۔</li>\n<li><strong>ویگا</strong> مضمر اتار چڑھاؤ میں تبدیلی کے لیے آپشن کی حساسیت ہے، مارکیٹ کی توقع ہے کہ اسٹاک کتنا آگے بڑھے گا۔ اگر یہ توقع گر جاتی ہے تو، پریمیم کم ہوجاتا ہے، یہاں تک کہ اگر اسٹاک ساکن رہتا ہے۔ مضمر اتار چڑھاؤ میں کمی خریدار کے اختیار کو خاموشی سے ختم کر سکتی ہے۔</li>\n<li><strong>لیکویڈیٹی اور پھیلاؤ</strong> اندر اور باہر جانے کی قیمت ہے۔ آپ پوچھنے پر خریدتے ہیں اور بولی پر بیچتے ہیں، اور ان کے درمیان فرق، پھیلاؤ، ایک فوری قیمت ہے جو آپ کی پوزیشن میں پہلے سیکنڈ سے بنتی ہے۔ غیر قانونی ہڑتال پر یہ بڑی ہو سکتی ہے۔</li>\n</ul>\n<p>پے آف ڈایاگرام کی ٹھوس لائن ان میں سے کسی کے بارے میں نہیں جانتی ہے۔ یہ ایک خالص ختم ہونے والی تصویر ہے۔ آج کے نقطے والا وکر، اور آپ کی سکرین، مارکیٹ کے کھلنے والے ہر منٹ میں چاروں کو محسوس کرتی ہے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>ادائیگی کے خاکے کو حاصل کرنے والی واحد قوت ختم ہونے پر سمت ہے۔ میعاد ختم ہونے سے پہلے، تھیٹا روزانہ آپ کے پریمیم کا خون بہا رہا ہے، مضمر اتار چڑھاؤ میں کمی اسے سکڑ سکتی ہے، ڈیلٹا کا مطلب ہے کہ ایک چھوٹا سا اقدام تجویز کردہ اقدام سے کم ادائیگی کرتا ہے، اور اسپریڈ سے آپ کو داخلے اور باہر نکلنے پر لاگت آتی ہے۔ یہی وجہ ہے کہ آپ کا آج کا P&amp;L ادائیگی سے پیچھے ہے۔</p>\n</div></div>\n<h2 id=\"i-was-right-on-direction-but-still-lost-money\">\"میں صحیح سمت پر تھا لیکن پھر بھی پیسہ کھو گیا\"</h2>\n<p>اب افتتاحی پہیلی سمجھ میں آتی ہے۔ آئیے کام کی گئی مثال کو احتیاط سے دیکھیں۔</p>\n<p>آپ RELIANCE 1320 کال تقریباً 31 روپے فی شیئر میں خریدتے ہیں، 15,590 روپے بہت زیادہ، RELIANCE کے ساتھ 1318 پر اور ختم ہونے میں تقریباً بتیس دن ہیں۔ راتوں رات اسٹاک بڑھ کر 1325 ہو جاتا ہے۔ آپ ٹھیک کہتے تھے۔ تو نقصان کیوں؟</p>\n<ul>\n<li>ڈیلٹا نے صرف آپ کو اس اقدام کا حصہ دیا۔ ڈیلٹا کے قریب ڈیلٹا کے ساتھ، RELIANCE میں سات روپے کا اضافہ کال کی قیمت میں سات نہیں بلکہ صرف ساڑھے تین روپے کا اضافہ کرتا ہے۔</li>\n<li>تھیٹا نے ایک دن کا کرایہ لیا۔ ایک دن گزر گیا، لہذا آپشن نے وقت کی قدر کا ایک ٹکڑا بہایا۔ یہ کشی آپ کے چھوٹے فائدے کے مخالف سمت میں کھینچتی ہے۔</li>\n<li>پھیلاؤ پہلے ہی آپ کو خرچ کر چکا ہے۔ آپ نے پوچھنے پر خریدا، اور پوزیشن کی قدر کرنے کے لیے اب آپ بولی کو دیکھتے ہیں، جو تھوڑی کم ہے۔ یہ فرق ایک قیمت تھی جسے آپ نے فوری طور پر ادا کیا تھا۔</li>\n</ul>\n<p>اسے شامل کریں۔ ایک چھوٹا سا دشاتمک فائدہ، جو صرف جزوی طور پر ڈیلٹا کے ذریعے حاصل کیا جاتا ہے، آسانی سے تھیٹا کے ایک دن کے علاوہ اس پھیلاؤ سے بھی چھوٹا ہو سکتا ہے جسے آپ نے عبور کیا ہے۔ نیٹ ایک ایسی پوزیشن ہے جو تھوڑا سا سرخ ہے حالانکہ اسٹاک آپ کے راستے میں چلا گیا ہے۔ آپ صحیح سمت پر تھے اور پھر بھی پیسے کم ہیں۔ بازار نے تمہیں دھوکہ نہیں دیا۔ ادائیگی کے خاکے نے کبھی بھی آپ سے منافع کا وعدہ نہیں کیا۔ <strong>آج</strong>. اس نے میعاد ختم ہونے پر منافع کا وعدہ کیا تھا، اور صرف اس صورت میں جب RELIANCE 1351 کو صاف کرتا ہے۔</p>\n<p>یہ وہ تجربہ ہے جو نئے خریداروں کو توڑ دیتا ہے۔ وہ منافع میں ہونے کے ساتھ سمت کے بارے میں صحیح ہونے کو الجھن میں ڈالتے ہیں، اور دونوں ختم ہونے تک ایک جیسے نہیں ہوتے، اور تب بھی نہیں جب تک کہ یہ اقدام اتنا بڑا نہ ہو کہ ہڑتال اور پریمیم کو صاف کر سکے۔</p>\n\n<div class=\"callout example\"><span class=\"callout-tag\">حقیقی مثال</span><div><p>RELIANCE آپ کے 1320 کال خریدنے کے اگلے دن 1318 سے بڑھ کر 1325 ہو جاتا ہے۔ ڈیلٹا آپ کو اس سات روپے کی چال کا صرف نصف دے دیتا ہے، تھیٹا خاموشی سے وقت کی قدر کے ایک دن کو ہٹا دیتا ہے، اور جس بولی پر آپ بیچیں گے اس سے نیچے بیٹھتا ہے جس پر آپ نے خریدا تھا۔ آپ کی اسکرین پر نتیجہ ایک چھوٹا سا نقصان ہے، جس دن اسٹاک بالکل آپ کے راستے پر چلا گیا۔</p>\n</div></div>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-basics/images/diagram-payoff-vs-live-pnl.png\" alt=\"ایک ہی لمبی کال کو دو طریقوں سے دیکھا گیا: ایٹ-ایکسپائری پے آف ایک صاف مڑی ہوئی لائن ہے، جب کہ آج کا وکر ایک ہموار، نچلی لائن ہے جس کی شکل ڈیلٹا، تھیٹا اور مضمر اتار چڑھاؤ سے ہے، اور ان کے درمیان وقفہ وقت کی قدر ہے جو ختم ہونے کے قریب پہنچتی ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>ایک ہی لمبی کال کو دو طریقوں سے دیکھا گیا: ایٹ-ایکسپائری پے آف ایک صاف مڑی ہوئی لائن ہے، جب کہ آج کا وکر ایک ہموار، نچلی لائن ہے جس کی شکل ڈیلٹا، تھیٹا اور مضمر اتار چڑھاؤ سے ہے، اور ان کے درمیان وقفہ وقت کی قدر ہے جو ختم ہونے کے قریب پہنچتی ہے۔</figcaption></figure>\n<h2 id=\"the-gap-closes-as-expiry-nears\">میعاد ختم ہونے کے ساتھ ہی خلا بند ہوجاتا ہے۔</h2>\n<p>اس سب میں ایک سکون بخش سمیٹری چھپی ہوئی ہے۔ نقطے دار آج کا وکر ہمیشہ کے لیے ٹھوس لکیر سے اوپر نہیں رہتا ہے۔ جیسے جیسے دن گزرتے ہیں اور وقت کی قدر پگھلتی ہے، نقطے والا وکر ٹھوس ایکسپائری لائن کی طرف مستقل طور پر ڈوب جاتا ہے۔ 28 جولائی کی صبح، کوئی وقت نہیں بچا، دونوں لائنیں ایک ہو گئیں۔ امید کا پریمیم مکمل طور پر ختم ہو گیا ہے، اور آپ کا اختیار بالکل اس کی داخلی قدر کے قابل ہے، ٹھوس لائن، مزید نہیں۔</p>\n<p>یہی وجہ ہے کہ ایک ہی اقدام مختلف اوقات میں مختلف مقداروں کے قابل ہے۔ تیس دن باقی رہ کر 1360 تک چھلانگ لگانے سے آج کے گول گول کو اچھی طرح سے اٹھا لیا جاتا ہے، کیونکہ ابھی بھی وقت کی قدر سب سے اوپر ہے۔ وہی 1360 جس میں ایک گھنٹہ باقی ہے تقریباً بالکل ٹھوس لائن پر بیٹھا ہے، جس کی قیمت چالیس روپے ہے اور اس سے زیادہ کچھ نہیں۔ وقت آپشن ٹریڈ کا پس منظر نہیں ہے۔ یہ قیمتوں میں سے ایک ہے۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>جب آپ تجارت سے پہلے ادائیگی کا خاکہ پڑھتے ہیں تو دونوں لائنیں تلاش کریں۔ ٹھوس لائن آپ کو نتیجہ بتاتی ہے اگر آپ کی میعاد ختم ہوتی ہے۔ نقطے والا وکر آپ کو بتاتا ہے کہ آپ کی سکرین پچھلے دنوں میں کیا دکھائے گی۔ دونوں کے لیے منصوبہ بنائیں، کیونکہ آپ کا پیسہ ٹھوس لکیر تک پہنچنے سے بہت پہلے نقطے دار وکر پر بیٹھ جاتا ہے۔</p>\n</div></div>\n<h2 id=\"reading-your-own-screen-honestly\">ایمانداری سے اپنی اسکرین کو پڑھنا</h2>\n<p>تو ایک مبتدی کو یہ سب کیسے استعمال کرنا چاہئے؟ تین عادتیں مدد کرتی ہیں۔</p>\n<p>سب سے پہلے، ادائیگی کے خاکے کو اپنے ایکسپائری پلان کے طور پر سمجھیں، نہ کہ آپ کے یومیہ سکور بورڈ۔ یہ اس سوال کا جواب دیتا ہے کہ اگر میں 28 جولائی کو ہر ممکنہ قیمت پر رکھتا ہوں تو میں کہاں کھڑا ہوں۔ یہ جواب نہیں دیتا، کل میری سکرین کیا کہے گی۔</p>\n<p>دوسرا، داخل ہونے سے پہلے چار قوتوں کا احترام کریں۔ پوچھیں کہ اسٹاک کو کتنی حرکت کرنی چاہیے، اور کتنی جلدی، روزانہ تھیٹا کے خون کو شکست دینے اور 1351 کے بریک ایون کو صاف کرنے کے لیے۔ اگر ایماندارانہ جواب ایک بڑا، تیز رفتار اقدام ہے، تو جان لیں کہ آپ ہر دن انتظار کرتے ہوئے وقت کے زوال سے لڑ رہے ہیں۔</p>\n<p>تیسرا، دو سوالوں کو الگ کریں جو کہ ابتدائی طور پر ایک میں مل جاتے ہیں: کیا میں سمت کے بارے میں صحیح تھا، اور کیا میں منافع میں ہوں؟ میعاد ختم ہونے سے پہلے وہ مکمل طور پر متفق نہیں ہوسکتے ہیں، کیونکہ ڈیلٹا، تھیٹا، ویگا اور اسپریڈ صحیح کال اور گرین اسکرین کے درمیان بیٹھتے ہیں۔ ایک تاجر جو دو سوالوں کو الگ رکھتا ہے وہ حیران ہونا بند کر دیتا ہے، اور اس تجارت کا انتظام کرنا شروع کر دیتا ہے جو اصل میں موجود ہے بجائے اس کے کہ جس کا وعدہ کیا گیا تھا۔</p>\n<p>ادائیگی کا خاکہ اب بھی ایک شاندار ٹول ہے۔ یہ سب سے واضح واحد تصویر ہے کہ آپشن کیا کر سکتا ہے۔ بس یاد رکھیں کہ یہ آخری دن کی تصویر ہے جس کی تمام امیدیں جل گئی ہیں۔ اس دن سے پہلے کی ہر چیز، وہ حصہ جہاں آپ کا پیسہ اصل میں رہتا ہے، آج کا گول کریو ہے، جس کی شکل ڈیلٹا، تھیٹا، مضمر اتار چڑھاؤ اور پھیلاؤ ہے۔ دونوں تصویروں کو ایک ساتھ اپنے سر پر رکھنا سیکھیں، اور جس دن اسٹاک بڑھے گا جبکہ آپ کا آپشن گر جائے گا آپ کو مزید الجھائے نہیں جائیں گے۔ یہ صرف احساس کرے گا.</p>\n","toc":[{"level":2,"text":"ادائیگی کا خاکہ ایک دن کی تصویر ہے۔","id":"a-payoff-diagram-is-a-picture-of-one-day"},{"level":2,"text":"دو لائنیں: ختم اور آج","id":"the-two-lines-the-finish-and-today"},{"level":2,"text":"نقطے والی لائن کو کیا چلاتا ہے: چار قوتیں۔","id":"what-drives-the-dotted-line-four-forces"},{"level":2,"text":"\"میں صحیح سمت پر تھا لیکن پھر بھی پیسہ کھو گیا\"","id":"i-was-right-on-direction-but-still-lost-money"},{"level":2,"text":"میعاد ختم ہونے کے ساتھ ہی خلا بند ہوجاتا ہے۔","id":"the-gap-closes-as-expiry-nears"},{"level":2,"text":"ایمانداری سے اپنی اسکرین کو پڑھنا","id":"reading-your-own-screen-honestly"}],"imgCount":2,"hasContent":true},"12":{"html":"<p>کسی بھی آپشن اسکرین کو کھولیں اور پہلی چیز جو آپ کو مارتی ہے وہ نمبروں کی دیوار ہے۔ قطاریں اور ہڑتالوں کی قطاریں، دونوں طرف قیمتوں کے دو کالم، اعداد و شمار کا ایسا بکھرا جو آپ نے پہلے کبھی نہیں دیکھا ہوگا۔ یہ ایک کاک پٹ ڈیش بورڈ کی طرح لگتا ہے، اور ابتدائی لوگ اکثر گھبراہٹ میں اسے بند کر دیتے ہیں۔ لیکن <strong>آپشن چین</strong> واقعی صرف ایک مینو ہے۔ یہ ایک دی گئی میعاد ختم ہونے کے لیے RELIANCE پر دستیاب ہر آپشن کی فہرست دیتا ہے، جس میں ایک طرف سے کالز، دوسری طرف نیچے کی جاتی ہیں، اور اسٹرائیک کی قیمتیں ریڑھ کی ہڈی کی طرح درمیان سے نیچے چلتی ہیں۔ ایک بار جب آپ جان لیں کہ اسے کس طریقے سے پڑھنا ہے، نمبروں کی دیوار ایک سادہ، منظم فہرست میں بدل جاتی ہے۔ یہ باب آپ کو اس مینو کو اعتماد کے ساتھ پڑھنا سکھاتا ہے۔</p>\n<h2 id=\"the-shape-of-the-chain\">زنجیر کی شکل</h2>\n<p>تین زونوں میں تقسیم ہونے والی میز کی تصویر بنائیں۔ دی <strong>ہڑتال کی قیمتوں</strong> مرکز کے کالم میں بیٹھیں، اوپر سے نیچے سے اونچے تک چڑھتے ہوئے۔ پر <strong>بائیں طرف تمام کالیں ہیں۔</strong>، ایک قطار فی ہڑتال۔ پر <strong>دائیں طرف تمام پوٹس ہیں۔</strong>ایک بار پھر ایک قطار فی ہڑتال۔ لہذا ایک ہی قطار آپ کو کال اور پوٹ دیتی ہے جو ایک ہی ہڑتال اور ایک ہی ختم ہونے کا اشتراک کرتی ہے۔ کال اور ایک سٹرائیک کا موازنہ کرنے کے لیے پوری قطار میں پڑھیں۔ مختلف سٹرائیکس میں ایک ہی قسم کا موازنہ کرنے کے لیے کالم پڑھیں۔</p>\n<p>سلسلہ ہمیشہ ایک وقت میں ایک میعاد ختم ہونے سے منسلک ہوتا ہے۔ ہماری مثالوں کے لیے یہ ہے۔ <strong>28 جولائی 2026</strong>25 جون کو بند ہونے سے تقریباً 32 دن باقی ہیں۔ اگر آپ ایکسپائری کو سوئچ کرتے ہیں، تو پوری چین قیمتوں کے مختلف سیٹ کے ساتھ ریفریش ہو جاتی ہے، کیونکہ زیادہ وقت کے ساتھ آپشنز کی قیمت زیادہ ہوتی ہے۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-basics/images/diagram-option-chain.png\" alt=\"آپشن چین تین زونوں میں ترتیب دیا گیا ہے: بائیں طرف کالیں، قیمتیں مرکز کی ریڑھ کی ہڈی سے نیچے، اور دائیں طرف رکھتا ہے، اسپاٹ 1320 کے قریب رقم کی قطار کو نمایاں کیا گیا ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>آپشن چین تین زونوں میں ترتیب دیا گیا ہے: بائیں طرف کالیں، قیمتیں مرکز کی ریڑھ کی ہڈی سے نیچے، اور دائیں طرف رکھتا ہے، اسپاٹ 1320 کے قریب رقم کی قطار کو نمایاں کیا گیا ہے۔</figcaption></figure>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>آپشن چین ایک مینو ہے، بھولبلییا نہیں۔ بائیں طرف کال کرتا ہے، دائیں طرف رکھتا ہے، درمیان سے نیچے مارتا ہے۔ ایک قطار ایک ہی ہڑتال ہے، جو اپنی کال کو دکھا رہی ہے اور اسی ایکسپائری کے لیے ساتھ ساتھ رکھ رہی ہے۔</p>\n</div></div>\n<h2 id=\"the-numbers-in-each-cell\">ہر سیل میں نمبر</h2>\n<p>ہر کال سیل اور ہر پوٹ سیل میں چند اعداد ہوتے ہیں۔ یہ وہی ہیں جو ایک ابتدائی ضرورت ہے، سادہ الفاظ میں.</p>\n<ul>\n<li><strong>LTP</strong> آخری تجارت کی قیمت کے لئے کھڑا ہے. یہ وہ پریمیم ہے جس پر اس اختیار نے حال ہی میں ہاتھ بدلے ہیں، وہ اعداد و شمار جو آپ تقریباً ادا کریں گے یا وصول کریں گے۔ RELIANCE 1320 اسٹرائیک کے لیے، کال اور پوٹ دونوں 31 روپے فی شیئر کے قریب بیٹھتے ہیں، جو کہ 500 کی ایک لاٹ کے لیے تقریباً 15,590 روپے ہے۔</li>\n<li><strong>بولی۔</strong> وہ سب سے زیادہ قیمت ہے جو فی الحال ایک خریدار اس اختیار کے لیے ادا کرنے کو تیار ہے۔ <strong>پوچھو</strong> سب سے کم قیمت ہے جو فی الحال ایک بیچنے والا قبول کرنے کو تیار ہے۔ اگر آپ بازار میں خریدتے ہیں، تو آپ پوچھنے کے قریب ادائیگی کرتے ہیں۔ اگر آپ بازار میں فروخت کرتے ہیں، تو آپ بولی کے قریب وصول کرتے ہیں۔ ان کے درمیان فاصلہ ہے۔ <strong>پھیلاؤ</strong>، اور ایک وسیع پھیلاؤ ایک قیمت ہے جسے آپ خاموشی سے اندر آنے اور باہر جانے کے راستے پر ادا کرتے ہیں۔</li>\n<li><strong>حجم</strong> آج تک اس آپشن کے کتنے معاہدوں کی تجارت ہوئی ہے۔ زیادہ والیوم کا مطلب ہے کہ آپشن فعال ہے اور اندر اور باہر جانا آسان ہے۔</li>\n<li><strong>کھلی دلچسپی</strong>، اکثر کے طور پر دکھایا جاتا ہے۔ <strong>OI</strong>، فی الحال کھلے اور ابھی تک بند نہ ہونے والے معاہدوں کی تعداد ہے۔ حجم کو آج کے فٹ فال اور کھلی دلچسپی کے طور پر سوچیں کہ عمارت میں اب بھی کتنے لوگ ہیں۔ بھاری کھلی دلچسپی کے ساتھ ہڑتال وہ ہے جس پر مارکیٹ توجہ دے رہی ہے۔</li>\n</ul>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>ایک ابتدائی کے لیے، دو اعداد و شمار جو سب سے زیادہ اہمیت رکھتے ہیں LTP ہیں، لہذا آپ کو قیمت معلوم ہے، اور حجم کے ساتھ کھلی دلچسپی، تاکہ آپ کو معلوم ہو کہ آیا یہ آپشن کافی مائع ہے کہ بغیر کسی تکلیف دہ پھیلاؤ کے تجارت کر سکے۔ ایک پتلی تجارت کی ہڑتال جس میں تقریباً کوئی حجم نہیں ہے، مناسب قیمت پر باہر نکلنا مشکل ہو سکتا ہے۔</p>\n</div></div>\n<h2 id=\"finding-the-at-the-money-strike-at-a-glance\">ایک نظر میں پیسے کی ہڑتال کو تلاش کرنا</h2>\n<p>سب سے پہلے جس ہڑتال کی تلاش ہے وہ ہے۔ <strong>پیسے پر</strong> ہڑتال، موجودہ اسپاٹ قیمت کے قریب ترین بیٹھنے والا۔ RELIANCE کے ساتھ <strong>1,318 روپے</strong>، قریب ترین درج ہڑتال ہے۔ <strong>1320</strong>، تو 1320 پیسے کی قطار ہے۔ یہ سلسلہ کا قدرتی مرکز ہے، اور زیادہ تر اسکرینیں اسے نمایاں کرتی ہیں یا خود بخود اس تک سکرول کرتی ہیں۔</p>\n<p>اس سے فرق کیوں پڑتا ہے؟ کیونکہ پیسے کی ہڑتال پیسے کی تقسیم کی لکیر ہے۔</p>\n<ul>\n<li>کے لیے <strong>کالز</strong>، اسپاٹ کے نیچے ہر اسٹرائیک ان دی منی ہے، اور اسپاٹ کے اوپر ہر اسٹرائیک پیسے سے باہر ہے۔ لہذا کال سائیڈ پر، 1320 لائن کے اوپر کی قطاریں پیسے میں ہیں، اور اس کے نیچے کی قطاریں پیسے سے باہر ہیں۔</li>\n<li>کے لیے <strong>رکھتا ہے</strong>، یہ آئینے کی تصویر ہے۔ اسپاٹ کے اوپر ہونے والی ہڑتالیں پیسے کے اندر ہیں، اور نیچے کی ہڑتالیں پیسے سے باہر ہیں۔ تو پوٹ سائیڈ پر، 1320 لائن کے نیچے کی قطاریں پیسے میں ہیں۔</li>\n</ul>\n<p>ایک بار جب آپ پیسے کی قطار تلاش کر لیتے ہیں، تو پوری زنجیر خود کو اس کے ارد گرد موڑ دیتی ہے۔ آپ کو فوری طور پر معلوم ہو جاتا ہے کہ کون سی کالیں حقیقی اندرونی قدر رکھتی ہیں اور کون سی خالص امید ہے، جہاں سے وہ اس لائن کے نسبت سے بیٹھتے ہیں۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>پیسے پر ہونے والی ہڑتال تلاش کرنے کے لیے، موجودہ جگہ کے قریب درج فہرست کو تلاش کریں۔ RELIANCE کے لیے 1318 پر، یعنی 1320۔ وہاں سے، کالیں سستی ہو جاتی ہیں جب آپ اعلیٰ سٹرائیکس تک پڑھتے ہیں، اور جب آپ لوئر سٹرائیکس تک پڑھتے ہیں تو پوٹس سستے ہو جاتے ہیں۔</p>\n</div></div>\n<h2 id=\"a-small-reliance-chain-to-read\">پڑھنے کے لیے ایک چھوٹی RELIANCE سلسلہ</h2>\n<p>یہاں پیسے کی ہڑتال کے ارد گرد RELIANCE 28 جولائی کی زنجیر کا ایک مثالی ٹکڑا ہے۔ پریمیم کے اعداد و شمار گول اور صرف پڑھانے کے لیے ہیں، لیکن وہ حقیقی شکل کی پیروی کرتے ہیں: گہری ہڑتالیں زیادہ اندرونی قدر رکھتی ہیں، اور پیسے کی 1320 قطار دونوں طرف 31 روپے کے قریب بیٹھتی ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>LTP پر کال کریں۔</th>\n<th>OI پر کال کریں۔</th>\n<th>ہڑتال</th>\n<th>LTP ڈالیں۔</th>\n<th>OI ڈالیں۔</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>42</td>\n<td>1,80,000</td>\n<td>1300</td>\n<td>24</td>\n<td>2,40,000</td>\n</tr>\n<tr>\n<td>36</td>\n<td>1,30,000</td>\n<td>1310</td>\n<td>28</td>\n<td>1,60,000</td>\n</tr>\n<tr>\n<td>31</td>\n<td>3,10,000</td>\n<td>1320</td>\n<td>31</td>\n<td>3,40,000</td>\n</tr>\n<tr>\n<td>26</td>\n<td>1,50,000</td>\n<td>1330</td>\n<td>37</td>\n<td>1,20,000</td>\n</tr>\n<tr>\n<td>21</td>\n<td>2,00,000</td>\n<td>1340</td>\n<td>44</td>\n<td>90,000</td>\n</tr>\n</tbody></table>\n<p>اسے آہستہ آہستہ پڑھیں اور پیٹرن باہر کودیں۔ دی <strong>1320 قطار پیسے کی قطار ہے۔</strong>، کشش ثقل کا مرکز، اور نوٹس یہ دونوں اطراف میں سب سے زیادہ کھلی دلچسپی رکھتا ہے۔ جیسے ہی آپ کال کالم کو اونچی سٹرائیکس پر لے جاتے ہیں، کال پریمیم گر جاتے ہیں، کیونکہ ان کالوں کو ادائیگی کے لیے بڑے اقدام کی ضرورت ہوتی ہے۔ جیسے ہی آپ پوٹ کالم کو لوئر سٹرائیکس پر لے جاتے ہیں، اسی وجہ سے پوٹ پریمیم گر جاتے ہیں۔ 1300 کال کی قیمت 1320 کال سے زیادہ ہے کیونکہ یہ پہلے سے ہی 18 روپے میں ہے، اصل اندرونی قیمت لے کر۔ 1340 پوٹ کی قیمت 1320 پوٹ سے زیادہ ہے کیونکہ یہ پہلے سے ہی 22 روپے میں ہے۔</p>\n\n<div class=\"callout example\"><span class=\"callout-tag\">حقیقی مثال</span><div><p>ایک قطار پڑھنا۔ 1320 قطار میں 31 کی کال LTP اور 31 کا ایک پوٹ LTP دکھاتا ہے۔ دونوں کی قیمت تقریباً 15,590 روپے ہے۔ کال 1320 پر RELIANCE خریدنے کا حق ہے، پوٹ 1320 پر فروخت کرنے کا حق ہے، اور اس جگہ کے قریب اس ہڑتال پر، دونوں اطراف کی مارکیٹ کی قیمتیں تقریباً ایک جیسی ہیں۔</p>\n</div></div>\n<h2 id=\"what-the-chain-is-telling-you\">زنجیر آپ کو کیا بتا رہی ہے۔</h2>\n<p>سلسلہ صرف قیمت کی فہرست نہیں ہے۔ مجموعی طور پر پڑھیں، یہ معلومات رکھتا ہے۔</p>\n<ul>\n<li><strong>کہاں پریمیم سستے ہیں اور کہاں عزیز ہیں۔</strong> پیسے سے باہر کے اختیارات کی قیمت بہت کم ہے کیونکہ وہ تمام وقت کی قیمت ہیں اور انہیں ایک بڑے اقدام کی ضرورت ہے۔ پیسے میں گہرے اختیارات کی قیمت بہت زیادہ ہے کیونکہ ان کی زیادہ تر قیمت حقیقی اندرونی قیمت ہے۔</li>\n<li><strong>جہاں ہجوم کھڑا ہے۔</strong> غیر معمولی طور پر بھاری کھلی دلچسپی کے ساتھ ہڑتالیں ظاہر کرتی ہیں جہاں بڑی تعداد میں تاجروں نے شرطیں لگائی ہیں۔ بہت سے تاجر بڑے کھلے سود کی ہڑتالوں کو کسی حد تک مارکر کے طور پر دیکھتے ہیں جہاں مارکیٹ کو سپورٹ یا مزاحمت کی توقع ہوتی ہے، حالانکہ یہ ایک اشارہ ہے اور کبھی ضمانت نہیں دیتا۔</li>\n<li><strong>ہر ہڑتال کتنی مائع ہوتی ہے۔</strong> حجم اور کھلی دلچسپی ایک ساتھ آپ کو بتاتی ہے کہ آیا آپ صاف طور پر اندر اور باہر جا سکتے ہیں۔ جب آپ شروعات کر رہے ہوں تو فعال، اٹ-دی-منی سٹرائیکس کے قریب رہیں، کیونکہ دور، پتلی سٹرائیکس آپ کو وسیع پیمانے پر پھنس سکتی ہیں۔</li>\n</ul>\n<p>ایمانداری کا ایک لفظ۔ مارکیٹ کے تازہ ترین اعداد و شمار کے ساتھ سلسلہ مسلسل تازہ دم ہوتا ہے، لیکن اس پر کوئی قطار مستقبل کی پیشین گوئی نہیں کرتی ہے۔ یہ آپ کو بتاتا ہے کہ ہر حق کی کیا قیمت ہے اور ہر ہڑتال کتنی مصروف ہے۔ یہ آپ کو یہ نہیں بتاتا ہے کہ RELIANCE کس طرف جائے گا۔ مبتدی بعض اوقات بھاری کھلی دلچسپی کو یقینی سگنل کے طور پر پڑھتے ہیں اور جل جاتے ہیں۔ چین کو قیمتوں اور سرگرمی کے ایک منظم مینو کے طور پر سمجھیں، نہ کہ کرسٹل بال۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>ایک مصروف ہڑتال تجارت کرنا آسان ہے، لیکن لیکویڈیٹی سمت نہیں ہے۔ 1320 پر بھاری کھلی دلچسپی آپ کو بتاتی ہے کہ بہت سے تاجر وہاں تعینات ہیں۔ یہ آپ کو یہ نہیں بتاتا ہے کہ آیا 28 جولائی تک RELIANCE اٹھے گا، گرے گا یا ساکن ہوگا۔ زنجیر اختیارات کی قیمت لگاتی ہے۔ یہ اقدام کو نہیں کہتے ہیں۔</p>\n</div></div>\n<p>اپنے سر میں اس نقشے کے ساتھ ایک حقیقی RELIANCE چین کو پڑھنے میں چند منٹ گزاریں۔ 1320 کے قریب ایٹ-دی-منی قطار تلاش کریں۔ سٹرائیکس بڑھنے کے ساتھ ہی قیمت میں گرنے والی کالز، سٹرائیکس کے گرنے کے ساتھ ہی پوٹس گرنے، اور گہری سٹرائیکس کے اندر چھپی اندرونی قدر کو دیکھیں۔ ایک بار جب مینو نمبروں کی دیوار کی طرح نظر آنا بند ہو جاتا ہے اور ایک منظم فہرست کی طرح نظر آنے لگتا ہے، تو آپ حقیقت میں کچھ خریدنے کے لیے تیار ہو جاتے ہیں۔ اگلے باب میں ہم بالکل وہی کرتے ہیں، سب سے زیادہ بدیہی تجارت کے ساتھ: کال خریدنا۔</p>\n","toc":[{"level":2,"text":"زنجیر کی شکل","id":"the-shape-of-the-chain"},{"level":2,"text":"ہر سیل میں نمبر","id":"the-numbers-in-each-cell"},{"level":2,"text":"ایک نظر میں پیسے کی ہڑتال کو تلاش کرنا","id":"finding-the-at-the-money-strike-at-a-glance"},{"level":2,"text":"پڑھنے کے لیے ایک چھوٹی RELIANCE سلسلہ","id":"a-small-reliance-chain-to-read"},{"level":2,"text":"زنجیر آپ کو کیا بتا رہی ہے۔","id":"what-the-chain-is-telling-you"}],"imgCount":1,"hasContent":true},"13":{"html":"<p>زیادہ تر آپشن اسکرینوں پر سب سے بڑی اور روشن ترین پرنٹ شدہ نمبر آخری تجارت شدہ قیمت ہے، LTP۔ یہ قیمت کی طرح لگتا ہے، ایک صاف فگر جو آپ کو بتاتا ہے کہ آپشن کی قیمت کیا ہے۔ یہ سب سے زیادہ گمراہ کن نمبروں میں سے ایک ہے جن پر ایک ابتدائی بھروسہ کرتا ہے۔ LTP صرف وہ قیمت ہے جس پر آپشن نے آخری بار ہاتھ بدلا ہے، اور یہ تجارت سیکنڈ یا بیس منٹ پہلے ہو سکتی ہے۔ یہ تاریخ ہے۔ جب آپ واقعی خریدنے یا بیچنے جاتے ہیں، تو آپ دو بالکل مختلف قیمتوں پر تجارت کرتے ہیں، اور ان کے درمیان فرق ایک حقیقی قیمت ہے جو آپ کے داخل ہوتے ہی آپ کی جیب سے نکل جاتی ہے۔ یہ باب ان قیمتوں کے بارے میں ہے جو واقعی اہم ہیں، بولی اور پوچھنا، ان کے درمیان پھیلاؤ، اور لیکویڈیٹی جو یہ فیصلہ کرتی ہے کہ آیا ہڑتال تجارت کے لیے محفوظ ہے یا ایک خاموش جال۔</p>\n<h2 id=\"the-last-traded-price-is-a-record-not-an-offer\">آخری تجارت کی قیمت ایک ریکارڈ ہے، پیشکش نہیں ہے۔</h2>\n<p>اس بارے میں سوچیں کہ LTP واقعی آپ کو کیا بتاتا ہے۔ یہ ایک معاہدے کی قیمت ہے جو ماضی میں، دو دوسرے لوگوں کے درمیان پہلے ہی ہو چکی ہے۔ RELIANCE اسٹرائیک پر، سودے مسلسل ہوتے رہتے ہیں، اس لیے LTP تازہ اور حقیقت کے قریب ہے۔ لیکن ایک نیند کی دور کی ہڑتال پر، آخری تجارت بیس منٹ پہلے کی ہو سکتی ہے، اس سے پہلے کہ اسٹاک پندرہ روپے بڑھے۔ وہ LTP ہے۔ <strong>باسی</strong>, ایک قیمت کوئی بھی آپ کو اصل میں اب نہیں دے گا.</p>\n<p>تو LTP اس سوال کا جواب دیتا ہے، یہ آپشن آخری بار کس چیز کے لیے فروخت ہوا۔ یہ اس سوال کا جواب نہیں دیتا جو آپ کے لیے اہم ہے، میں اسے ابھی کس چیز کے لیے خرید سکتا ہوں یا بیچ سکتا ہوں۔ اس کے لیے، آپ کو LTP کے دونوں طرف بیٹھے ہوئے دو قیمتوں کو دیکھنا ہوگا۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>آخری تجارت شدہ قیمت ماضی کے معاہدے کا ریکارڈ ہے، نہ کہ وہ قیمت جو آپ حاصل کر سکتے ہیں۔ غیر قانونی ہڑتال پر یہ بری طرح باسی ہو سکتا ہے۔ اکیلے LTP سے تجارت کو کبھی بھی سائز نہ دیں؛ بولی اور پوچھیں، جو قیمتیں اصل میں اس وقت پیشکش پر ہیں۔</p>\n</div></div>\n<h2 id=\"bid-and-ask-the-two-real-prices\">بولی اور پوچھیں: دو حقیقی قیمتیں۔</h2>\n<p>کسی بھی وقت، ایک آپشن کی دو قیمتیں ہیں جو حقیقی طور پر دستیاب ہیں۔</p>\n<ul>\n<li>دی <strong>پوچھنا</strong>جسے پیشکش بھی کہا جاتا ہے، وہ سب سے کم قیمت ہے جس پر کوئی آپ کو آپشن بیچنے کے لیے تیار ہے۔ جب آپ خریدتے ہیں، تو آپ مانگ ادا کرتے ہیں۔</li>\n<li>دی <strong>بولی</strong> وہ سب سے زیادہ قیمت ہے جس پر کوئی آپ سے آپشن خریدنے کو تیار ہے۔ جب آپ فروخت کرتے ہیں تو آپ کو بولی ملتی ہے۔</li>\n</ul>\n<p>مانگ ہمیشہ بولی سے زیادہ ہوتی ہے۔ یہ کوئی خرابی نہیں ہے۔ یہ ہے کہ ایک مارکیٹ کیسے کام کرتا ہے. بیچنے والے تھوڑا زیادہ چاہتے ہیں، خریدار تھوڑا کم ادا کرنا چاہتے ہیں، اور دونوں قیمتیں درمیان میں کہیں LTP کے ساتھ تھوڑا سا فاصلہ رکھتی ہیں۔ ایک ابتدائی کے لیے اہم اصول سادہ اور قدرے تکلیف دہ ہے: <strong>آپ پوچھنے پر خریدتے ہیں اور بولی پر بیچتے ہیں۔</strong> آپ ہمیشہ اپنے لیے دو قیمتوں میں سے بدتر پر ٹریڈ کر رہے ہیں۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>آپ آخری تجارت شدہ قیمت پر تجارت نہیں کرتے ہیں۔ آپ پوچھنے پر خریدتے ہیں، قیمت بیچنے والے پوچھ رہے ہیں، اور آپ بولی پر بیچتے ہیں، قیمت خریدار بولی لگا رہے ہیں۔ پوچھنا ہمیشہ زیادہ نمبر پر ہوتا ہے، لہذا آپ بدتر قیمت پر داخل ہوتے ہیں اور بدتر قیمت پر باہر نکلتے ہیں۔</p>\n</div></div>\n<h2 id=\"the-spread-is-an-instant-cost\">پھیلاؤ ایک فوری قیمت ہے۔</h2>\n<p>بولی اور پوچھنے کے درمیان فاصلہ ہے۔ <strong>پھیلاؤ</strong>. یہ آپشن ٹریڈنگ میں واحد سب سے کم قیمت ہے، کیونکہ یہ اس وقت تک پوشیدہ ہے جب تک آپ اسے سمجھ نہیں سکتے، اور پھر آپ اسے ہر تجارت پر دیکھتے ہیں۔</p>\n<p>یہاں یہ ہے کہ پھیلاؤ ایک حقیقی قیمت ہے۔ فرض کریں کہ آپ پوچھنے پر ایک آپشن خریدتے ہیں اور پھر، ایک سیکنڈ بعد، اپنا خیال بدل کر اسے بیچ دیتے ہیں۔ اسٹاک بالکل منتقل نہیں ہوا ہے۔ آپ اب بھی پیسے کھوتے ہیں، کیونکہ آپ نے زیادہ مانگ پر خریدا اور کم بولی پر بیچا۔ پھیلاؤ وہ ٹول ہے جسے آپ پوزیشن میں آنے اور پیچھے ہٹنے کے لیے ادا کرتے ہیں۔ اسٹاک کے کچھ کرنے سے پہلے، آپ کے داخل ہونے کا وقت ختم ہو گیا ہے۔</p>\n<p>آئیے ہم اسے RELIANCE کال سٹرائیکس کی ایک مثالی جوڑی کے ساتھ ٹھوس بنائیں۔ نیچے دیے گئے نمبر پڑھانے کے لیے ہیں، لیکن شکل بالکل وہی ہے جو آپ دیکھیں گے۔</p>\n<table>\n<thead>\n<tr>\n<th>ہڑتال (کال)</th>\n<th>بولی۔</th>\n<th>پوچھو</th>\n<th>پھیلاؤ</th>\n<th>500 کی ایک لاٹ پر پھیلائیں۔</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1320، رقم پر</td>\n<td>30.80</td>\n<td>31.20</td>\n<td>0.40 روپے</td>\n<td>200 روپے</td>\n</tr>\n<tr>\n<td>1500، بہت زیادہ رقم</td>\n<td>0.50</td>\n<td>1.50</td>\n<td>1.00 روپے</td>\n<td>500 روپے</td>\n</tr>\n</tbody></table>\n<p>پہلے ایٹ دی منی 1320 قطار پڑھیں۔ بولی 30.80 ہے اور پوچھنا 31.20 ہے، تو اسپریڈ صرف چالیس پیسے فی شیئر ہے، 500 کی لاٹ پر تقریباً 200 روپے۔ یہ سخت ہے۔ آپشن کا بہت زیادہ کاروبار کیا جاتا ہے، بہت سارے خریدار اور بیچنے والے ایک ساتھ جمع ہوتے ہیں، اور داخل ہونے اور باہر نکلنے کی لاگت تقریباً 15,590 روپے کے پریمیم کے برابر ہے۔</p>\n<p>اب باہر کی 1500 قطار پڑھیں۔ بولی پچاس پیسے ہے اور پوچھنا ایک روپیہ پچاس، تو اسپریڈ مکمل ایک روپیہ ہے، تقریباً 500 روپے پر۔ روپے کے لحاظ سے یہ چھوٹا لگتا ہے۔ لیکن اسے قیمت کے ایک حصے کے طور پر دیکھیں۔ آپ خریدنے کے لیے 1.50 ادا کریں گے اور بیچنے کے لیے صرف 0.50 وصول کریں گے۔ آپ نے اپنی دو تہائی رقم اکیلے اسپریڈ میں کھو دی ہے، اس سے پہلے کہ اسٹاک ایک پیسہ منتقل کرے۔ یہ ایک سستی، غیر قانونی ہڑتال کے اندر چھپا ہوا خطرہ ہے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>ایک وسیع پھیلاؤ آپ کے پورے کنارے سے زیادہ خرچ کر سکتا ہے۔ 0.50 بولی اور 1.50 پوچھنے کے حوالے سے بہت دور کی ہڑتال پر، آپ تین گنا ادا کرتے ہیں جو آپ کو فوری طور پر فروخت کرنے کے لیے ملے گا۔ سستی ایک وہم ہے؛ پھیلاؤ خاموشی سے تجارت کو کھا جاتا ہے۔</p>\n</div></div>\n<h2 id=\"volume-and-open-interest-reading-the-crowd\">حجم اور کھلی دلچسپی: بھیڑ پڑھنا</h2>\n<p>آپ تجارت سے پہلے ایک وسیع، خطرناک سے سخت، محفوظ ہڑتال کو کیسے بتائیں گے؟ آپشن چین پر دو نمبر آپ کو بتاتے ہیں کہ کتنا ہجوم موجود ہے۔</p>\n<ul>\n<li><strong>حجم</strong> آج تجارت شدہ معاہدوں کی تعداد ہے۔ یہ ہر صبح دوبارہ ترتیب دیتا ہے۔ زیادہ حجم کا مطلب ہے کہ ہڑتال ابھی فعال ہے، بہت سارے خریدار اور بیچنے والے ہاتھ بدلتے ہیں، جس کا مطلب عام طور پر سخت پھیلاؤ اور آسانی سے باہر نکلنا ہے۔</li>\n<li><strong>کھلی دلچسپی</strong>، یا OI، ابھی بھی کھلے ہوئے معاہدوں کی تعداد ہے، یعنی وہ پوزیشنیں جو کھولی گئی ہیں لیکن ابھی تک بند نہیں ہوئی ہیں۔ یہ دنوں میں بنتا ہے۔ زیادہ کھلی دلچسپی کا مطلب ہے کہ بہت سے شرکاء پہلے ہی اس ہڑتال کو منعقد کر رہے ہیں، لہذا اس میں دلچسپی کا ایک گہرا تالاب ہے۔</li>\n</ul>\n<p>سادہ الفاظ میں، حجم آپ کو بتاتا ہے کہ آج ہڑتال کتنی مصروف ہے، اور کھلی دلچسپی آپ کو بتاتی ہے کہ مجموعی طور پر کتنا ہجوم ہے۔ صحت مند حجم اور صحت مند کھلی دلچسپی دونوں کے ساتھ ایک ہڑتال مائع ہے: داخل ہونے میں آسان، باہر نکلنا آسان، ایک تنگ پھیلاؤ کے ساتھ۔ تقریبا کوئی حجم اور پتلی کھلی دلچسپی کے ساتھ ہڑتال غیر قانونی ہے، اور بالکل وہی ہے جہاں ابتدائیوں کو تکلیف ہوتی ہے۔ ہم دیکھتے ہیں کہ کھلی دلچسپی میں ہونے والی تبدیلیاں بعد کے باب میں پوزیشننگ کی طرف اشارہ کرتی ہیں۔ ابھی کے لیے، حجم اور کھلی دلچسپی کو محض اپنے لیکویڈیٹی چیک کے طور پر سمجھیں۔</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>حجم یہ ہے کہ آج کتنے معاہدوں کی تجارت ہوئی، اس وقت سرگرمی کا ایک پیمانہ۔ کھلی دلچسپی یہ ہے کہ مجموعی طور پر کتنے معاہدے کھلے رہتے ہیں، اس بات کا ایک پیمانہ کہ ہڑتال میں کتنا ہجوم ہے۔ دونوں میں صحت مند نمبروں کا مطلب عام طور پر ایک تنگ پھیلاؤ اور آسانی سے باہر نکلنا ہے۔</p>\n</div></div>\n<h2 id=\"why-a-far-out-illiquid-strike-is-dangerous\">غیر قانونی ہڑتال کیوں خطرناک ہے؟</h2>\n<p>ٹکڑوں کو ایک ساتھ رکھیں اور آپ دیکھ سکتے ہیں کہ کیوں سستی، پیسے سے باہر کی ہڑتال ایک ابتدائی کے لیے گھومنے کے لیے سب سے خطرناک جگہوں میں سے ایک ہے۔</p>\n<ul>\n<li>پھیلاؤ ہے <strong>چوڑا</strong>، جیسے کہ 1500 کی ہڑتال سے ظاہر ہوتا ہے کہ داخل ہونے اور باہر نکلنے کے لیے اکثر پریمیم کا ایک بڑا ٹکڑا خرچ کرنا پڑتا ہے۔</li>\n<li>یہ ہے <strong>باہر نکلنا مشکل ہے</strong>. آس پاس کے چند خریداروں کے ساتھ، جب آپ فروخت کرنا چاہتے ہیں تو ہو سکتا ہے کہ مناسب قیمت کے قریب کوئی بھی بولی نہ لگا سکے، اس لیے آپ یا تو ایک خوفناک بولی قبول کرتے ہیں یا پوزیشن میں پھنس کر بیٹھ جاتے ہیں۔</li>\n<li>قیمت کر سکتے ہیں <strong>خلا</strong>. کچھ اور اس کے درمیان تجارت کے ساتھ، قیمت آسانی سے آگے بڑھنے کے بجائے تیزی سے بڑھ جاتی ہے، اس لیے آپشن ایک سطح سے دوسری سطح تک چھلانگ لگا سکتا ہے جس کے درمیان کچھ نہیں ہوتا ہے، جو باہر نکلنے کو ناقابل اعتبار بنا دیتا ہے۔</li>\n</ul>\n<p>تکلیف دہ ستم ظریفی یہ ہے کہ یہ غیر قانونی دور دراز کی ہڑتالیں بالکل وہی ہیں جن کی طرف ابتدائی طور پر کھینچا گیا ہے، کیونکہ یہ سستے ہیں اور بہت زیادہ فیصد حاصل کرنے کا وعدہ کرتے ہیں۔ کم قیمت کوئی سودا نہیں ہے۔ یہ مارکیٹ آپ کو بتاتی ہے کہ تقریباً کوئی بھی یہ معاہدہ نہیں چاہتا ہے، اور یہ بالکل پتلا پن ہے جس کی وجہ سے تجارت کرنا مہنگا اور فرار ہونا مشکل ہے۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>کسی بھی ہڑتال کی تجارت کرنے سے پہلے، اس کے پھیلاؤ، اس کے حجم اور اس کی کھلی دلچسپی کو ایک ساتھ دیکھیں۔ اگر پھیلاؤ وسیع ہے اور حجم اور کھلی دلچسپی پتلی ہے، تو دور ہٹ جائیں، اگرچہ سستا پریمیم نظر آ رہا ہو۔ جس ہڑتال سے آپ صاف طور پر باہر نہیں نکل سکتے وہ ایک جال ہے، موقع نہیں۔</p>\n</div></div>\n<h2 id=\"how-to-stay-on-liquid-ground\">مائع زمین پر کیسے رہنا ہے۔</h2>\n<p>پھندے سے بچنا زیادہ تر چند سادہ عادات کا معاملہ ہے۔</p>\n<p>سب سے پہلے، تجارت پیسے کے قریب حملہ کرتا ہے، جہاں بھیڑ ہے. پیسے پر اور قریبی سٹرائیکس جیسے کہ RELIANCE یا NIFTY سب سے زیادہ حجم اور سخت ترین اسپریڈز پر مشتمل ہے، اس لیے آپ کے داخلے اور باہر نکلنے کے اخراجات کم رہتے ہیں۔</p>\n<p>دوسرا، بولی کے ذریعے قیمت کا فیصلہ کریں اور پوچھیں، کبھی بھی اکیلے LTP کو نہیں۔ اگر بولی اور پوچھنا ایک دوسرے سے دور بیٹھتے ہیں، تو ہڑتال غیر قانونی، فل اسٹاپ ہے، اس سے کوئی فرق نہیں پڑتا ہے کہ LTP نے اسے کتنا ہی فعال بنایا ہے۔</p>\n<p>تیسرا، قریب ترین میعاد ختم ہونے کو ترجیح دیں جو زیادہ تر تاجر استعمال کرتے ہیں، کیونکہ ان کے پاس زیادہ تر حجم اور کھلی دلچسپی ہے۔ آپ کی ہڑتال کے ارد گرد ہجوم جتنا گہرا ہوگا، اتنا ہی چھوٹا پھیلاؤ آپ ادا کریں گے اور جب آپ چاہیں چھوڑنا اتنا ہی آسان ہوگا۔</p>\n<p>اسپریڈ وہ لاگت ہے جو آپ کبھی بھی ادائیگی کے خاکے پر نہیں دیکھتے اور نہ ہی نصابی کتاب کی مثال میں پڑھتے ہیں، پھر بھی یہ ہر حقیقی تجارت پر موجود ہے، جو اسٹاک کے منتقل ہونے سے پہلے ہی نکال لی جاتی ہے۔ لیکویڈیٹی کو ایک فلٹر کے طور پر سمجھیں جسے آپ کسی بھی چیز سے پہلے لاگو کرتے ہیں: غیر قانونی ہڑتال پر ایک شاندار تجارتی آئیڈیا اکثر عملی طور پر کھونے والی تجارت ہے، کیونکہ پھیلاؤ اور باہر نکلنے کی دشواری خاموشی سے آپ کے کنارے کو پیچھے چھوڑ دیتی ہے۔ جہاں بھیڑ ہے وہاں رہیں، بولی اور سوال پڑھیں، اور پتلی، سستی، دور دراز کی ہڑتالیں کسی اور کو جانے دیں۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-basics/images/diagram-bid-ask-spread.png\" alt=\"بولی سب سے زیادہ قیمت ہے جو خریدار ادا کرے گا اور پوچھنا سب سے کم قیمت ہے جو بیچنے والے قبول کریں گے۔ ان کے درمیان فرق پھیلاؤ ہے، ایک فوری لاگت جو آپ داخلے پر ادا کرتے ہیں، اور یہ غیر قانونی دور کی ہڑتالوں پر تیزی سے وسیع ہوتا ہے جہاں حجم اور کھلی دلچسپی پتلی ہوتی ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>بولی سب سے زیادہ قیمت ہے جو خریدار ادا کرے گا اور پوچھنا سب سے کم قیمت ہے جو بیچنے والے قبول کریں گے۔ ان کے درمیان فرق پھیلاؤ ہے، ایک فوری لاگت جو آپ داخلے پر ادا کرتے ہیں، اور یہ غیر قانونی دور کی ہڑتالوں پر تیزی سے وسیع ہوتا ہے جہاں حجم اور کھلی دلچسپی پتلی ہوتی ہے۔</figcaption></figure>\n","toc":[{"level":2,"text":"آخری تجارت کی قیمت ایک ریکارڈ ہے، پیشکش نہیں ہے۔","id":"the-last-traded-price-is-a-record-not-an-offer"},{"level":2,"text":"بولی اور پوچھیں: دو حقیقی قیمتیں۔","id":"bid-and-ask-the-two-real-prices"},{"level":2,"text":"پھیلاؤ ایک فوری قیمت ہے۔","id":"the-spread-is-an-instant-cost"},{"level":2,"text":"حجم اور کھلی دلچسپی: بھیڑ پڑھنا","id":"volume-and-open-interest-reading-the-crowd"},{"level":2,"text":"غیر قانونی ہڑتال کیوں خطرناک ہے؟","id":"why-a-far-out-illiquid-strike-is-dangerous"},{"level":2,"text":"مائع زمین پر کیسے رہنا ہے۔","id":"how-to-stay-on-liquid-ground"}],"imgCount":1,"hasContent":true},"14":{"html":"<p>آپشنز کی دنیا میں ہر تجارت میں سے، کال خریدنا وہ ہے جو ابتدائی طور پر پہلے پہنچتا ہے، اور اچھی وجہ سے۔ یہ اس سے میل کھاتا ہے جس طرح ہم پہلے ہی سوچتے ہیں۔ آپ کو یقین ہے کہ RELIANCE بڑھ رہا ہے، لہذا آپ حصص کی پوری قیمت کو کم کیے بغیر اضافے سے منافع حاصل کرنے کا طریقہ چاہتے ہیں۔ اے <strong>لمبی کال</strong>، جس کا سیدھا مطلب ہے کہ آپ نے خریدا ہوا کال آپشن، بالکل وہی کرتا ہے۔ آپ ایک مقررہ قیمت پر RELIANCE خریدنے کے حق کے لیے آج ہی ایک چھوٹا پریمیم ادا کرتے ہیں، اور اگر اسٹاک بڑھتا ہے، تو آپ کا اختیار اس کے ساتھ چڑھ جاتا ہے۔ آپ کا نقصان آپ کے ادا کردہ پریمیم سے زیادہ نہیں ہو سکتا، جبکہ آپ کے فائدے کی کوئی حد نہیں ہے۔ وہ توازن حقیقی طور پر خوبصورت ہے۔ اگر آپ کیچ کو نہیں سمجھتے تو یہ بھی ایک جال ہے، اور یہ باب آپ کو حقیقی RELIANCE ادائیگی کا استعمال کرتے ہوئے خوبصورتی اور کیچ دونوں دکھاتا ہے۔</p>\n<h2 id=\"what-you-actually-own\">جو آپ اصل میں مالک ہیں۔</h2>\n<p>جب آپ خریدتے ہیں۔ <strong>RELIANCE 1320 کال</strong> 28 جولائی کی میعاد ختم ہو رہی ہے، آپ تقریباً ادائیگی کرتے ہیں۔ <strong>31 روپے فی شیئر</strong>. کیونکہ ایک لاٹ RELIANCE ہے۔ <strong>500 شیئرز</strong>, کہ ایک لاٹ آپ کے بارے میں لاگت آئے گی <strong>15,590 روپے</strong>. آپ کی سکرین پر علامت پڑھتی ہے۔ <code>RELIANCE28JUL261320CE</code>، جہاں CE اسے کال کے طور پر نشان زد کرتا ہے۔</p>\n<p>وہ 15,590 روپے آپ کو 1320 پر ختم ہونے پر 1320 پر RELIANCE کے 500 شیئرز خریدنے کا حق خریدتا ہے، لیکن کبھی بھی اس کی ذمہ داری نہیں۔ اگر RELIANCE میعاد ختم ہونے پر 1320 سے اوپر ہے، تو یہ حق آپ کے حق میں طے ہو جاتا ہے اور فرق کو حاصل کر لیتا ہے، اور ایکسپائری سے پہلے آپ کسی بھی وقت آپشن کو مارکیٹ میں بیچ کر باہر نکل سکتے ہیں۔ اگر RELIANCE ڈوب جاتا ہے، تو آپ آسانی سے آپشن کو ختم ہونے دیتے ہیں اور چلے جاتے ہیں۔ آپ سب سے زیادہ کھو سکتے ہیں وہ 15,590 روپے جو آپ نے ادا کیے ہیں۔ کوئی آپ سے ایک روپیہ بھی نہیں مانگ سکتا۔ یہ محدود منفی پہلو حصص خریدنے کے بجائے اختیارات خریدنے کی پوری اپیل ہے۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>ایک لمبی کال ہڑتال پر خریدا ہوا حق ہے۔ آپ پریمیم پہلے سے ادا کرتے ہیں، آپ کا زیادہ سے زیادہ نقصان وہ پریمیم ہے، اور آپ کا سٹاک جتنا اونچا بڑھتا ہے آپ کا الٹا بڑھتا ہے۔ محدود خطرہ، بڑا انعام، لیکن آپ کو استحقاق کی ادائیگی کرنی ہوگی۔</p>\n</div></div>\n<h2 id=\"reading-the-real-payoff\">حقیقی ادائیگی پڑھنا</h2>\n<p>نیچے دیا گیا خاکہ اس تجارت کے لیے حقیقی ادائیگی ہے، جو کہ 1,318 روپے، اسٹرائیک 1320، لاٹ 500 پر OpenAlgo کی حکمت عملی ریاضی سے بنایا گیا ہے، جس کی میعاد ختم ہونے میں تقریباً 32 دن ہیں، جس میں ماڈل شدہ پریمیم روپے 31 روپے کے قریب ہے۔ ٹھوس لکیر وہ ہے جس کی پوزیشن 28 جولائی کو ختم ہونے پر ہے۔ نقطہ دار سیان لائن وہی ہے جو آج اس کی قیمت ہے، اس سے پہلے کہ وقت کی زوال نے اپنا کام کیا ہو۔ آئیے ہم ٹھوس لکیر کو بائیں سے دائیں چلتے ہیں۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-basics/images/payoff-long-call.png\" alt=\"ایکسپائری پر طویل کال کی ادائیگی: سٹرائیک کے نیچے ہر قیمت پر تقریباً 15,590 روپے کا فلیٹ نقصان، 1320 پر قبضہ، 1351 پر بریک ایون، اور اوپر کی طرف لائن جو اوپر بغیر کسی حد کے چڑھتی رہتی ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">چارٹ</span>ایکسپائری پر طویل کال کی ادائیگی: سٹرائیک کے نیچے ہر قیمت پر تقریباً 15,590 روپے کا فلیٹ نقصان، 1320 پر قبضہ، 1351 پر بریک ایون، اور اوپر کی طرف لائن جو اوپر بغیر کسی حد کے چڑھتی رہتی ہے۔</figcaption></figure>\n<p><strong>بائیں طرف، لائن فلیٹ ہے۔</strong> 1320 کی سٹرائیک سے کم کسی بھی ایکسپائری قیمت کے لیے، کال ختم ہو جاتی ہے پیسے سے باہر اور بیکار۔ آپ پورا پریمیم کھو دیتے ہیں، تقریباً <strong>15,590 روپے</strong>، اور نقصان اس سے بھی زیادہ خراب نہیں ہوتا ہے چاہے RELIANCE کتنی ہی دور ہو جائے۔ چاہے اسٹاک 1300 پر ختم ہو یا 1100 پر کریش ہو، آپ کا نقصان وہی ہے جو 15,590 روپے ہے۔ یہ فلیٹ فلور ایکشن میں محدود خطرہ ہے۔</p>\n<p><strong>درمیان میں، لکیر ٹکرا جاتی ہے اور اوپر اٹھنا شروع ہو جاتی ہے۔</strong> ایک بار جب RELIANCE 1320 سے اوپر دھکیلتا ہے، تو کال کی اندرونی قدر روپے کے بدلے روپیہ بڑھ جاتی ہے۔ لیکن آپ ابھی تک منافع میں نہیں ہیں، کیونکہ آپ کو ابھی بھی اپنے ادا کردہ پریمیم کو واپس کرنا ہے۔ لائن صفر کو کراس کرتی ہے۔ <strong>1351 کی بریک ایون قیمت</strong>جو کہ 1320 کی سٹرائیک کے علاوہ 31 روپے فی شیئر پریمیم ہے۔ بالکل 1351 پر آپ کے خریدنے کے حق پر ہونے والے فوائد آپ نے خرچ کیا ہوا پریمیم منسوخ کر دیا، اور آپ فلیٹ ختم کر دیں۔</p>\n<p><strong>دائیں طرف، لائن بغیر چھت کے چڑھتی رہتی ہے۔</strong> 1351 سے اوپر آپ حقیقی منافع میں ہیں، اور ہر مزید روپیہ RELIANCE آپ کی پوزیشن میں 500 روپے کا اضافہ کرتا ہے، کیونکہ آپ 500 شیئرز کو کنٹرول کرتے ہیں۔ اگر RELIANCE 1400 پر ختم ہو جاتا ہے، تو آپ بریک ایون کے اوپر تقریباً 49 روپے فی شیئر اوپر ہیں، تقریباً 24,500 روپے۔ اگر یہ 1450 تک چلتا ہے تو منافع بڑھتا رہتا ہے۔ یہ مشہور ہے۔ <strong>لامحدود الٹا</strong>. کوئی نقطہ نہیں ہے جس پر لائن بڑھنا بند ہو جائے۔</p>\n\n<div class=\"callout example\"><span class=\"callout-tag\">حقیقی مثال</span><div><p>1320 کال کے تین اختتام۔ RELIANCE ختم ہونے پر 1310 پر: کال بیکار ہے، تقریباً 15,590 روپے کا نقصان، آپ سب سے زیادہ کھو سکتے ہیں۔ RELIANCE 1351 پر: آپ صفر نفع یا نقصان کے قریب بھی ٹوٹ جاتے ہیں۔ RELIANCE 1400 پر: تقریباً 24,500 روپے کا منافع، اور اگر اسٹاک زیادہ چلتا ہے تو یہ بڑھتا رہے گا۔</p>\n</div></div>\n<h2 id=\"the-catch-nobody-puts-on-the-poster\">کیچ کوئی بھی پوسٹر پر نہیں لگاتا ہے۔</h2>\n<p>صرف سرخی پڑھیں، محدود خطرہ اور لامحدود انعام، اور کالز خریدنا ایک طرفہ شرط کی طرح لگتا ہے۔ ایسا نہیں ہے، اور اس بارے میں ایماندار ہونا کیوں سب سے مفید چیز ہے جو یہ باب آپ کو دے سکتا ہے۔ <strong>زیادہ تر کال خریدار پیسے کھو دیتے ہیں۔</strong> یہاں وجوہات کا سلسلہ ہے۔</p>\n<p>سب سے پہلے، <strong>اسٹاک کو بریک ایون کو صاف کرنا چاہیے، نہ صرف ہڑتال۔</strong> RELIANCE کے لیے 1320 سے اوپر جانے کے لیے کافی نہیں ہے۔ اسے صرف آپ کے پیسے واپس حاصل کرنے کے لیے ایکسپائری سے پہلے 1351 پر چڑھنا ہوگا۔ آپ کے ادا کردہ پریمیم کا ہر روپیہ ایک رکاوٹ ہے اس سے پہلے کہ آپ ایک روپیہ منافع دیکھیں۔</p>\n<p>دوسرا، <strong>وقت کا زوال ہر وقت آپ کے خلاف پیس رہا ہے۔</strong> یاد رکھیں کہ اس ایٹ دی منی کال کا پورا 31 روپے ٹائم ویلیو ہے، خالص امید جس کی کوئی اندرونی قیمت نہیں ہے، کیونکہ 1318 کا اسپاٹ 1320 کے اسٹرائیک سے نیچے ہے۔ وہ ٹائم ویلیو ہر روز تھوڑی سی پگھلتی ہے اور آخری ہفتے میں سب سے تیزی سے پگھلتی ہے۔ لہذا آپ صرف اسٹاک کے بڑھنے کا انتظار نہیں کر رہے ہیں۔ آپ اسے سکڑتی ہوئی گھڑی کے خلاف دوڑ رہے ہیں۔ ڈایاگرام میں آج کی نقطے والی لائن ٹھوس ایکسپائری لائن کے بالکل اوپر بیٹھی ہے کیونکہ آپشن میں ابھی بھی وقت کی قدر ہے جو کہ 28 جولائی تک ختم ہو جائے گی۔</p>\n<p>تیسرا، <strong>اسٹاک کافی اور جلد ہی منتقل ہونا چاہئے.</strong> ایک چھوٹا، آہستہ بڑھے اونچا کافی نہیں ہے۔ RELIANCE 1318 سے بڑھ کر 1345 ہو سکتا ہے، جو شیئر ہولڈر کے لیے ایک حقیقی اور قابل احترام فائدہ ہے، اور کال خریدار پھر بھی پیسے کھو دے گا، کیونکہ 1345 1351 کے بریک ایون سے نیچے ہے اور اس دوران وقت کی قدر ختم ہو چکی ہے۔ آپ سمت پر صحیح ہوسکتے ہیں اور پھر بھی ہار سکتے ہیں۔ یہ وہ کڑا سچ ہے جو صاف ستھری ادائیگی کا خاکہ الفاظ میں نہیں دکھاتا۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>آپ درست کہہ سکتے ہیں کہ RELIANCE بڑھے گا اور پھر بھی ایک لمبی کال پر پیسے کھو دے گا۔ سٹاک کو 1351 کو ایکسپائری کے ذریعے کلیئر کرنا چاہیے، اور اسے ایسا کرنا چاہیے اس سے پہلے کہ وقت کی کمی آپ کے پریمیم کو کھا جائے۔ پیسے سے باہر کالز خریدنا اور کسی بڑے اقدام کی امید کرنا یہ ہے کہ کس طرح زیادہ تر آپشن خریدار اپنا سرمایہ آہستہ آہستہ حوالے کرتے ہیں۔</p>\n</div></div>\n<h2 id=\"when-a-long-call-makes-sense\">جب ایک لمبی کال سمجھ میں آتی ہے۔</h2>\n<p>اس میں سے کوئی بھی مطلب کبھی بھی کال نہ خریدیں۔ اس کا مطلب ہے صاف آنکھوں کے ساتھ ایک خریدیں۔ ایک لمبی کال ایک سمجھدار ٹول ہے جب کچھ چیزیں قطار میں لگ جاتی ہیں۔</p>\n<ul>\n<li><strong>آپ کے پاس جلد ہی ایک بڑے اقدام کی توقع کرنے کی ایک حقیقی وجہ ہے۔</strong> لمبی کال ایک ایسی حرکت کا بدلہ دیتی ہے جو بڑی اور معقول حد تک تیز ہو، نہ کہ آہستہ۔ مبہم رجائیت بریک ایون اور گھڑی کو شکست دینے کے لیے کافی نہیں ہے۔</li>\n<li><strong>آپ وضاحت کرنا چاہتے ہیں، محدود خطرہ۔</strong> 15,590 روپے وہ سب سے زیادہ ہے جسے آپ کھو سکتے ہیں، پہلے سے معلوم ہے۔ ایک تاجر کے لیے جو دوسری پوزیشنوں کے کھلے عام خطرے کو برداشت نہیں کر سکتا، وہ ہارڈ کیپ حقیقی طور پر قیمتی ہے۔</li>\n<li><strong>آپ سرمایہ کا ایک چھوٹا، سستی ٹکڑا استعمال کر رہے ہیں۔</strong> چونکہ پورا پریمیم صفر تک جا سکتا ہے، اس لیے کبھی بھی ایک کال پر پیسے نہ لگائیں جسے آپ مکمل طور پر کھونے کے متحمل نہیں ہو سکتے۔ ہر لمبی کال کو پوری طرح خطرے میں رقم سمجھیں۔</li>\n</ul>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>اپنے آپ کو دو محاذوں پر جگہ دیں۔ کافی وقت خریدیں تاکہ اس اقدام کو زوال کے کاٹنے سے پہلے ہونے کا موقع ملے، اور بریک ایون کا احترام کریں، نہ کہ صرف ہڑتال کا۔ ایک کال جس کو جمعہ تک معجزے کی ضرورت ہوتی ہے عام طور پر عطیہ ہوتا ہے، تجارت نہیں۔</p>\n</div></div>\n<h2 id=\"practising-without-real-money\">حقیقی رقم کے بغیر مشق کرنا</h2>\n<p>حقیقی سرمایہ کا ارتکاب کرنے سے پہلے، آپ پوری تجارت کی مشق کر سکتے ہیں۔ <strong>سینڈ باکس ٹریڈنگ (Analyzer mode in OpenAlgo)</strong>. آپ وہی RELIANCE 1320 کال کرتے ہیں، دیکھتے ہیں کہ اسٹاک کے بڑھنے کے ساتھ ہی پریمیم کس طرح کا رد عمل ظاہر کرتا ہے، اور ایک روپیہ کو خطرے میں ڈالے بغیر وقت کی کمی کو دن بہ دن محسوس کرتے ہیں۔ اس باب میں ادائیگی کے خاکے کو تصویر سے جبلت میں تبدیل کرنے کا کوئی تیز طریقہ نہیں ہے۔</p>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">کیا آپ جانتے ہیں؟</span><div><p>طویل کال کی ادائیگی اختیارات میں سب سے صاف شکل ہے۔ بائیں طرف فلیٹ کیپڈ نقصان، اسٹرائیک پر ایک قبضہ، اسٹرائیک پلس پریمیم پر ایک بریک ایون، اور دائیں طرف ایک کھلی ہوئی چڑھائی۔ اس ایک منحنی خطوط کو پڑھنے والے ماسٹر اور ہر دوسرے سنگل ٹانگ کی ادائیگی، جس میں ہم اگلی ملاقات کرتے ہیں، اس تھیم پر ایک تغیر کی طرح پڑھے گا جسے آپ پہلے سے جانتے ہیں۔</p>\n</div></div>\n<p>لہذا لمبی کال آپ کو تقریباً 15,590 روپے کا ایک محدود، معلوم نقصان، 1351 پر ایک بریک ایون، اور اس کے اوپر حقیقی طور پر لامحدود اوپر کی طرف اشارہ کرتی ہے۔ یہ ایک اچھا سودا ہے جب واقعی ایک بڑا اقدام ممکن ہو اور آپ نے اپنے آپ کو کافی وقت خرید لیا ہو۔ جب آپ مبہم امید پر خریدتے ہیں اور گھڑی کو چلنے دیتے ہیں تو یہ ایک پرسکون پیسہ کھونے والا ہے۔ ان دونوں سچائیوں کو ایک ساتھ رکھیں اور آپ پہلے سے ہی ایک جواری کی بجائے تاجر کی طرح سوچ رہے ہیں۔ اس کے بعد ہم پوری تصویر کو الٹا کر دیتے ہیں اور ایک پوٹ، آئینے کی تصویر خریدتے ہیں، جب آپ RELIANCE کے گرنے کی توقع کرتے ہیں۔</p>\n","toc":[{"level":2,"text":"جو آپ اصل میں مالک ہیں۔","id":"what-you-actually-own"},{"level":2,"text":"حقیقی ادائیگی پڑھنا","id":"reading-the-real-payoff"},{"level":2,"text":"کیچ کوئی بھی پوسٹر پر نہیں لگاتا ہے۔","id":"the-catch-nobody-puts-on-the-poster"},{"level":2,"text":"جب ایک لمبی کال سمجھ میں آتی ہے۔","id":"when-a-long-call-makes-sense"},{"level":2,"text":"حقیقی رقم کے بغیر مشق کرنا","id":"practising-without-real-money"}],"imgCount":1,"hasContent":true},"15":{"html":"<p>کال اس وقت تجارت ہوتی ہے جب آپ اسٹاک کے بڑھنے کی توقع کرتے ہیں۔ لیکن مارکیٹیں بھی گرتی ہیں، بعض اوقات سخت اور تیز، اور آپ کو منافع کا ایک طریقہ چاہیے جب وہ کرتے ہیں، یا کم از کم اپنی ملکیت کی حفاظت کا ایک طریقہ۔ یہی کام ہے۔ <strong>طویل ڈال</strong>، ایک پوٹ آپشن جو آپ نے خریدا ہے۔ یہ لمبی کال کا عین آئینہ ہے۔ جہاں کال آپ کو ہڑتال پر خریدنے کا حق دیتی ہے، وہیں پٹ آپ کو ہڑتال پر فروخت کرنے کا حق دیتا ہے۔ آپ پوٹ خریدتے ہیں جب آپ کو لگتا ہے کہ RELIANCE نیچے کی طرف جا رہا ہے، اور یہ جتنا نیچے جاتا ہے، آپ کے پوٹ کی قیمت اتنی ہی زیادہ ہوگی۔ کال کی طرح، آپ کا نقصان آپ کے ادا کیے گئے پریمیم پر ہوتا ہے، جب کہ اسٹاک گرنے کے ساتھ ہی آپ کا انعام بڑھتا ہے۔ یہ باب حقیقی RELIANCE پوٹ پے آف کو پڑھتا ہے اور پھر آپ کو پوٹ کا دوسرا، پرسکون کام دکھاتا ہے: انشورنس۔</p>\n<h2 id=\"what-you-actually-own\">جو آپ اصل میں مالک ہیں۔</h2>\n<p>جب آپ خریدتے ہیں۔ <strong>RELIANCE 1320 ڈالیں۔</strong> 28 جولائی کی میعاد ختم ہو رہی ہے، آپ تقریباً ادائیگی کرتے ہیں۔ <strong>31 روپے فی شیئر</strong>، کال کی طرح ماڈل والا پریمیم۔ ایک لاٹ ہے۔ <strong>500 شیئرز</strong>, تو بہت کے بارے میں لاگت آئے گی <strong>15,590 روپے</strong>. علامت پڑھتی ہے۔ <code>RELIANCE28JUL261320PE</code>، جہاں PE اسے بطور پوٹ نشان زد کرتا ہے۔</p>\n<p>یہ پریمیم آپ کو 500 حصص 1320 میں ختم ہونے پر فروخت کرنے کا حق، لیکن کبھی بھی ذمہ داری نہیں خریدتا ہے۔ اگر RELIANCE کریش ہو جاتا ہے، تو یہ حق قیمتی ہو جاتا ہے، کیونکہ آپ 1320 پر فروخت کر سکتے ہیں جب کہ مارکیٹ بہت نیچے ٹریڈ کر رہی ہے، اور ایکسپائری سے پہلے آپ کسی بھی وقت مارکیٹ میں پوٹ بیک بیچ کر باہر نکل سکتے ہیں۔ اگر RELIANCE اس کے بجائے چڑھتا ہے، تو آپ پوٹ کی میعاد ختم ہونے دیتے ہیں اور صرف پریمیم کھو دیتے ہیں۔ آپ سب سے زیادہ کھو سکتے ہیں وہ 15,590 روپے جو آپ نے ادا کیے، اور ایک روپیہ زیادہ نہیں۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>ہڑتال پر بیچنے کا خریدا ہوا حق ایک لمبی پوٹ ہے۔ اسٹاک گرنے کے ساتھ ہی آپ کو فائدہ ہوتا ہے، آپ کا زیادہ سے زیادہ نقصان وہ پریمیم ہے جو آپ نے ادا کیا ہے، اور اس سے زیادہ آپ پر کبھی واجب الادا نہیں۔ یہ لمبی کال کی آئینہ دار تصویر ہے جو اوپر کی بجائے نیچے کی طرف اشارہ کرتی ہے۔</p>\n</div></div>\n<h2 id=\"reading-the-real-payoff\">حقیقی ادائیگی پڑھنا</h2>\n<p>نیچے دیا گیا خاکہ اس تجارت کے لیے حقیقی معاوضہ ہے، OpenAlgo کی حکمت عملی ریاضی سے اسپاٹ 1,318 روپے، اسٹرائیک 1320، لاٹ 500، ختم ہونے میں تقریباً 32 دن، پریمیم تقریباً 31 روپے فی شیئر۔ ٹھوس لائن 28 جولائی کو ختم ہونے والی قیمت ہے۔ نقطے والی سیان لائن آج کی قدر ہے، اس سے پہلے کہ وقت کا زوال اپنا راستہ چلا جائے۔ ہم ٹھوس لائن پر چلتے ہیں، اس بار دائیں سے بائیں، کیونکہ ایک ڈالنے سے قیمتیں گرتی ہیں۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-basics/images/payoff-long-put.png\" alt=\"ایکسپائری پر لانگ پوٹ پے آف: سٹرائیک کے اوپر ہر قیمت پر تقریباً 15,590 روپے کا فلیٹ نقصان، 1320 پر قبضہ، 1289 پر بریک ایون، اور ایک لائن جو اوپر سے اوپر چڑھتی ہے جیسا کہ RELIANCE صفر کی طرف آتی ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">چارٹ</span>ایکسپائری پر لانگ پوٹ ادائیگی: سٹرائیک کے اوپر ہر قیمت پر تقریباً 15,590 روپے کا فلیٹ نقصان، 1320 پر قبضہ، 1289 پر بریک ایون، اور ایک لائن جو اوپر سے اوپر چڑھتی ہے جیسا کہ RELIANCE صفر کی طرف آتی ہے۔</figcaption></figure>\n<p><strong>دائیں طرف، لائن فلیٹ ہے۔</strong> 1320 کی سٹرائیک سے اوپر کی کسی بھی ایکسپائری قیمت کے لیے، پوٹ پیسے سے باہر اور بیکار ہو جاتا ہے۔ آپ پورا پریمیم کھو دیتے ہیں، تقریباً <strong>15,590 روپے</strong>، اور یہ نقصان اس بات سے نہیں بڑھتا ہے کہ RELIANCE کتنی ہی اونچائی پر چڑھ جائے۔ چاہے سٹاک 1330 پر ختم ہو یا راکٹ 1500 پر، آپ کا نقصان وہی ہے جس کی حد 15,590 روپے ہے۔ دائیں طرف کی یہ فلیٹ چھت خریدار کا محدود خطرہ ہے۔</p>\n<p><strong>بیچ میں، لائن قلابے لگتی ہے اور قیمت گرنے پر بڑھنا شروع ہو جاتی ہے۔</strong> ایک بار جب RELIANCE 1320 سے نیچے آجاتا ہے، تو پوٹ کو روپے کی اندرونی قدر میں اضافہ ہوتا ہے۔ لیکن آپ کو پہلے پریمیم واپس کرنا ہوگا، تاکہ آپ ابھی تک منافع میں نہیں ہیں۔ لائن صفر کو کراس کرتی ہے۔ <strong>بریک ایون قیمت 1289</strong>جو کہ 1320 مائنس 31 روپے فی شیئر پریمیم کی ہڑتال ہے۔ بالکل 1289 پر آپ کو بیچنے کے حق پر حاصل ہونے والے فوائد آپ کے خرچ کردہ پریمیم کو منسوخ کر دیتے ہیں۔</p>\n<p><strong>بائیں طرف، لائن چڑھتی رہتی ہے جیسا کہ RELIANCE گرتا ہے۔</strong> 1289 سے نیچے آپ حقیقی منافع میں ہیں، اور ہر مزید روپے کے نقصان سے آپ کی پوزیشن میں 500 روپے کا اضافہ ہوتا ہے، کیونکہ آپ 500 شیئرز کو کنٹرول کرتے ہیں۔ اگر RELIANCE 1250 پر ختم ہو جاتا ہے، تو آپ تقریباً 39 روپے فی شیئر بریک ایون کے نیچے، تقریباً 19,500 روپے تک بڑھ جاتے ہیں۔ اگر یہ 1200 تک گر جائے تو منافع مزید بڑھتا ہے۔ فائدہ نیچے کی طرف بڑھتا رہتا ہے۔ صرف فطری حد یہ ہے کہ حصص کی قیمت صفر سے نیچے نہیں آسکتی ہے، اس لیے پوٹ کا منافع واقعی لامحدود ہونے کی بجائے بہت زیادہ ہے، لیکن کسی بھی حقیقت پسندانہ اقدام کے لیے یہ اس طرح برتاؤ کرتا ہے جیسے کال کا الٹا ہو جائے۔</p>\n\n<div class=\"callout example\"><span class=\"callout-tag\">حقیقی مثال</span><div><p>1320 کے تین اختتام۔ RELIANCE ختم ہونے پر 1330 پر: پوٹ بیکار ہے، تقریباً 15,590 روپے کا نقصان، آپ سب سے زیادہ کھو سکتے ہیں۔ RELIANCE 1289 پر: آپ بھی ٹوٹ جاتے ہیں۔ RELIANCE 1250 پر: تقریباً 19,500 روپے کا منافع، اور جتنا اسٹاک گرتا ہے اس میں اضافہ ہوتا رہتا ہے۔</p>\n</div></div>\n<h2 id=\"the-same-honest-catch\">وہی ایماندار کیچ</h2>\n<p>ہر وہ چیز جس نے لانگ کال کو مشکل بنا دیا ہے بالکل اسی طرح مضبوطی سے لانگ پوٹ پر لاگو ہوتا ہے، صرف نیچے کی طرف اشارہ کیا جاتا ہے۔ <strong>زیادہ تر پوٹ خریدار بھی پیسے کھو دیتے ہیں۔</strong>، اور اسی وجہ سے۔</p>\n<p>دی <strong>اسٹاک کو بریک ایون کو صاف کرنا چاہیے، نہ صرف ہڑتال۔</strong> RELIANCE 1320 سے نیچے ڈبونا کافی نہیں ہے۔ صرف آپ کے پریمیم کی وصولی کے لیے اسے ختم ہونے سے پہلے 1289 سے گزر جانا چاہیے۔ اور <strong>وقت کا زوال پورے وقت آپ کے خلاف پیستا ہے۔</strong> یہ پیسے کی قیمت تقریباً تمام وقتی قیمت ہے، اس لیے اس کا پریمیم ہر روز تھوڑا سا پگھلتا ہے اور آخری ہفتے میں سب سے تیز ہوتا ہے۔ آپ گرنے پر شرط لگا رہے ہیں، سکڑتی ہوئی گھڑی کی دوڑ لگا رہے ہیں۔ RELIANCE 1318 سے 1295 تک سلائیڈ کر سکتا ہے، ایک حقیقی کمی، اور پوٹ خریدار پھر بھی نقصان پر ختم ہو جائے گا، کیونکہ 1295 1289 بریک ایون سے اوپر بیٹھا ہے اور اس دوران وقت کی قدر ختم ہو گئی۔ کال کی طرح، آپ صحیح سمت میں ہو سکتے ہیں اور پھر بھی ہار سکتے ہیں۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>RELIANCE گرنے پر بھی لمبا پوٹ پیسہ کھو سکتا ہے۔ سٹاک کو 1289 کو ایکسپائری کے ذریعے کلیئر کرنا چاہیے، اور اسے ایسا کرنا چاہیے اس سے پہلے کہ وقت کی کمی پریمیم کھا جائے۔ بہت زیادہ پیسہ خریدنا اور حادثے کی امید رکھنا، اس کے کال کزن کی طرح، سرمایہ کھونے کا ایک سست طریقہ ہے۔</p>\n</div></div>\n<h2 id=\"the-put-s-second-job-insurance\">پوٹ کا دوسرا کام: انشورنس</h2>\n<p>یہ وہ جگہ ہے جہاں پوٹ صرف قیاس آرائیاں کرنے والوں کے لیے نہیں بلکہ عام سرمایہ کاروں کے لیے بھی کماتا ہے۔ ایک ڈال ہے <strong>آپ کے پاس پہلے سے موجود حصص پر انشورنس۔</strong> اس استعمال کو اکثر کہا جاتا ہے۔ <strong>حفاظتی ڈال</strong>، اور یہ سب سے زیادہ سمجھدار چیزوں میں سے ایک ہے جسے ایک ابتدائی سمجھ سکتا ہے۔</p>\n<p>فرض کریں کہ آپ خود ہیں۔ <strong>RELIANCE کے 500 شیئرز</strong>فی الحال 1318 پر تقریباً 6,59,000 روپے کی قیمت ہے۔ آپ اگلے مہینے میں گراوٹ سے گھبرا رہے ہیں، شاید کسی آنے والے ایونٹ کی وجہ سے، لیکن آپ اپنے حصص کو فروخت کرنا اور ٹیکس کو متحرک کرنا یا ریباؤنڈ سے محروم ہونا نہیں چاہتے۔ تو آپ خرید لیں۔ <strong>ایک 1320 ڈال دیا</strong> تقریباً 15,590 روپے میں۔ اب سوچو کہ تم کیا رکھتے ہو۔</p>\n<ul>\n<li>اگر RELIANCE کریش ہو کر 1200 ہو جاتا ہے، تو آپ کے حصص کی قدر ختم ہو جاتی ہے، لیکن آپ کا فائدہ ہوتا ہے۔ 1320 پر فروخت کرنے کا حق ہے جبکہ مارکیٹ 1200 پر تجارت کرتا ہے زیادہ تر زوال کو آفسیٹ کرتا ہے۔ آپ کے پوٹ نے بالکل انشورنس کی ادائیگی کی طرح کام کیا ہے۔</li>\n<li>اگر RELIANCE 1400 پر چڑھ جاتا ہے، تو آپ کے حصص کو بہت زیادہ فائدہ ہوتا ہے، اور آپ صرف پوٹ کی میعاد ختم ہونے دیتے ہیں۔ آپ نے جو 15,590 روپے خرچ کیے وہ انشورنس کی قیمت تھی، وہ پریمیم جو آپ نے ایک ماہ کے تحفظ کے لیے ادا کیا جس کی آپ کو خوشی سے ضرورت نہیں تھی۔</li>\n</ul>\n<p>یہی دیانت دار فریمنگ ہے۔ ایک حفاظتی پوٹ آپ کے ہولڈنگ پر انشورنس پالیسی کی طرح برتاؤ کرتا ہے۔ اس پر ایک پریمیم لاگت آتی ہے، اس کی میعاد ختم ہو جاتی ہے، اور آپ امید کرتے ہیں کہ آپ اس پر کبھی جمع نہیں ہوں گے، بالکل اسی طرح جیسے آپ امید کرتے ہیں کہ موٹر پالیسی پر کبھی دعویٰ نہیں کریں گے۔ لاگت حقیقی ہے اور جب بھی آپ تجدید کرتے ہیں تو یہ دہرائی جاتی ہے، لیکن ذہنی سکون اور محدود کمی ایک پریشان کن پیچ کے ذریعے اس کے قابل ہو سکتی ہے۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>اپنے RELIANCE پر ایک ماہ کی انشورنس پالیسی کے طور پر حفاظتی پوٹ کے بارے میں سوچیں۔ پریمیم کور کی قیمت ہے، اسٹرائیک قیمت کی منزل ہے جس کی ضمانت دیتا ہے، اور پالیسی ختم ہونے پر ختم ہو جاتی ہے۔ آپ اسے اس امید پر خریدتے ہیں کہ اسٹاک بڑھے گا اور پالیسی غیر استعمال شدہ ہو جائے گی۔</p>\n</div></div>\n<h2 id=\"when-a-long-put-makes-sense\">جب لمبا لگانا معنی رکھتا ہے۔</h2>\n<p>بیمہ کے علاوہ، ایک قیاس آرائی پر مبنی لمبی پوٹ ان ہی نظم و ضبط والے حالات میں ایک معقول ٹول ہے جیسے کال، صرف الٹی۔</p>\n<ul>\n<li><strong>آپ کو جلد ہی ایک بڑے زوال کی توقع ہے۔</strong> A put ایک ایسی حرکت کا بدلہ دیتا ہے جو بڑی اور معقول حد تک تیز ہوتی ہے، جو کہ کشی کے کاٹنے سے پہلے بریک ایون کو صاف کرنے کے لیے کافی ہے۔</li>\n<li><strong>آپ بیئرش ویو پر متعین، محدود خطرہ چاہتے ہیں۔</strong> شارٹ سیلنگ حصص کے برعکس، طویل پوٹ پر آپ کا نقصان کبھی بھی پریمیم سے زیادہ نہیں ہو سکتا۔ 15,590 روپے کی وہ ہارڈ کیپ آپ کے خریدتے وقت معلوم ہو جاتی ہے۔</li>\n<li><strong>آپ صرف پیسہ ہی خطرے میں ڈال رہے ہیں جو آپ مکمل طور پر کھونے کے متحمل ہوسکتے ہیں۔</strong>، کیونکہ پورا پریمیم کچھ بھی نہیں سڑ سکتا ہے۔</li>\n</ul>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">کیا آپ جانتے ہیں؟</span><div><p>معیاد ختم ہونے پر لمبا پوٹ خالص اندرونی قدر ہے: یہ اسٹرائیک سے کتنا نیچے ختم ہوا، 500 سے ضرب، مائنس آپ نے ادا کیا پریمیم۔ 1320 کے اوپر یہ بیکار ہے۔ ڈاٹڈ ٹوڈے لائن ٹھوس ایکسپائری لائن کے اوپر اس وقت کی قدر کے مطابق بیٹھتی ہے جو آپشن اب بھی رکھتی ہے اور 28 جولائی تک ہتھیار ڈال دے گی۔</p>\n</div></div>\n<p>آپ ان سب کی مشق کر سکتے ہیں، قیاس آرائی اور حفاظتی پوٹ، اندر <strong>سینڈ باکس ٹریڈنگ ( OpenAlgo میں تجزیہ کار موڈ)</strong> حقیقی رقم کا ارتکاب کرنے سے پہلے، پریمیم کے رد عمل کو RELIANCE کی حرکت کے طور پر دیکھتے ہوئے اور جیسے جیسے دن نیچے آتے ہیں۔</p>\n<p>لہذا لانگ پوٹ آپ کو تقریباً 15,590 روپے کا محدود نقصان، 1289 پر بریک ایون، اور RELIANCE گرنے کے ساتھ ایک بڑا اور بڑھتا ہوا منافع دیتا ہے۔ قیاس آرائی کے طور پر اس میں کال کی طرح ہی ایماندارانہ کیچ ہے، لہذا اسے حقیقی، قابل قدر، بروقت اقدام کے لیے خریدیں نہ کہ مبہم اداسی پر۔ جیسا کہ آپ کے حصص پر انشورنس ہے، یہ وہاں موجود آپشن کے سب سے زیادہ سمجھدار استعمال میں سے ایک ہے۔ ہم نے اب خریداری کے دونوں اطراف سے ملاقات کی ہے۔ اس کے بعد ہم میز کے دوسری طرف جاتے ہیں اور بیچنے والے بن جاتے ہیں، جہاں پریمیم ہمارے پاس آتا ہے، لیکن اس سے کہیں زیادہ بھاری قسم کا خطرہ ہوتا ہے۔</p>\n","toc":[{"level":2,"text":"جو آپ اصل میں مالک ہیں۔","id":"what-you-actually-own"},{"level":2,"text":"حقیقی ادائیگی پڑھنا","id":"reading-the-real-payoff"},{"level":2,"text":"وہی ایماندار کیچ","id":"the-same-honest-catch"},{"level":2,"text":"پوٹ کا دوسرا کام: انشورنس","id":"the-put-s-second-job-insurance"},{"level":2,"text":"جب لمبا لگانا معنی رکھتا ہے۔","id":"when-a-long-put-makes-sense"}],"imgCount":1,"hasContent":true},"16":{"html":"<p>اب تک آپ ہمیشہ خریدار رہے ہیں، حق کے لیے پریمیم ادا کر رہے ہیں۔ لیکن ہر آپشن جو خریدا جاتا ہے کسی اور کے ذریعہ فروخت ہوتا ہے، اور یہ کہ کوئی آپ کے حوالے کردہ پریمیم جمع کرتا ہے۔ یہ باب آپ کو میز کے دوسری طرف لے جاتا ہے، جہاں آپ بن جاتے ہیں۔ <strong>اختیار بیچنے والا</strong>, بھی کہا جاتا ہے <strong>مصنف</strong>. پریمیم ادا کرنے کے بجائے، آپ اسے پیشگی وصول کرتے ہیں۔ حق رکھنے کے بجائے آپ فرض ادا کرتے ہیں۔ یہ آسان رقم کی طرح محسوس کر سکتا ہے، اور یہ بالکل خطرہ ہے، کیونکہ بیچنے والے کا انعام محدود ہے جبکہ بیچنے والے کا خطرہ بہت زیادہ ہو سکتا ہے۔ ہم حقیقی RELIANCE نمبروں پر دونوں مختصر ادائیگیوں کو پڑھیں گے، اور ہم خطرے کے بارے میں دو ٹوک ہوں گے، کیونکہ آپشنز کو اس کا احترام کیے بغیر فروخت کرنا ان تیز ترین طریقوں میں سے ایک ہے جو ایک ابتدائی اکاؤنٹ کو اڑا سکتا ہے۔</p>\n<h2 id=\"flipping-the-trade-around\">تجارت کے ارد گرد پلٹنا</h2>\n<p>جب آپ <strong>فروخت</strong> ایک آپشن، آپ آج ہی پریمیم جمع کرتے ہیں اور بدلے میں ایک ذمہ داری قبول کرتے ہیں۔</p>\n<ul>\n<li><strong>کال بیچنا</strong> اس کا مطلب ہے کہ آپ پریمیم وصول کرتے ہیں اور ڈیلیور کرنے یا سیٹل کرنے کی ڈیوٹی سنبھالتے ہیں، جیسا کہ اگر خریدار مشق کرتا ہے تو آپ کو ہڑتال پر RELIANCE فروخت کرنا پڑتا ہے۔ آپ چاہتے ہیں کہ اسٹاک اسٹرائیک کے نیچے رہے تاکہ کال بے کار ہو جائے اور آپ پریمیم برقرار رکھیں۔</li>\n<li><strong>ایک پٹ بیچنا</strong> اس کا مطلب ہے کہ آپ پریمیم وصول کرتے ہیں اور خریدنے، یا سیٹل کرنے کی ڈیوٹی سنبھالتے ہیں، جیسے کہ اگر خریدار مشق کرتا ہے تو آپ کو ہڑتال پر RELIANCE خریدنا پڑتا ہے۔ آپ چاہتے ہیں کہ اسٹاک اسٹرائیک سے اوپر رہے تاکہ پوٹ بیکار ختم ہو جائے اور آپ پریمیم برقرار رکھیں۔</li>\n</ul>\n<p>دونوں صورتوں میں آپ کا بہترین نتیجہ ایک ہی ہے: آپشن کی میعاد ختم ہو جاتی ہے، خریدار چلا جاتا ہے، اور آپ اپنے جمع کردہ پریمیم کا ہر پیسہ اپنے پاس رکھتے ہیں۔ RELIANCE 1320 سٹرائیک کے لیے، وہ پریمیم تقریباً ہے۔ <strong>31 روپے فی شیئر</strong>، یا کے بارے میں <strong>15,590 روپے</strong> 500 کی ایک لاٹ کے لیے۔ وہ اعداد و شمار، موصول ہونے والا پریمیم، ہے۔ <strong>زیادہ تر آپ کبھی بھی بنا سکتے ہیں۔</strong> تجارت پر. آپ کا منافع پہلے دن پر محدود ہے۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>آپشن بیچنا سودا پلٹ جاتا ہے۔ آپ پریمیم پہلے سے جمع کرتے ہیں، اور یہ پریمیم زیادہ سے زیادہ ہے جو آپ کما سکتے ہیں۔ بدلے میں آپ ایک ذمہ داری کو قبول کرتے ہیں، اور وہ ذمہ داری وہ ہے جہاں بڑا خطرہ رہتا ہے۔ محدود انعام، غیر محدود یا بہت بڑا خطرہ۔</p>\n</div></div>\n<h2 id=\"reading-the-short-call-payoff\">مختصر کال کی ادائیگی پڑھنا</h2>\n<p>یہ ہے RELIANCE 1320 کال فروخت کرنے کے لیے حقیقی ادائیگی، OpenAlgo کی حکمت عملی ریاضی سے اسپاٹ 1,318 روپے، اسٹرائیک 1320، لاٹ 500، تقریباً 32 دن باہر، پریمیم 31 روپے کے قریب۔ ٹھوس لائن ایکسپائری پر قیمت ہے۔ نقطے والی سائین لائن آج کی قدر ہے۔ غور کریں کہ یہ پہلے کے باب سے الٹا ہوا طویل کال کی ادائیگی ہے، جو سمجھ میں آتی ہے، کیونکہ بیچنے والا وہی جیتتا ہے جو خریدار ہارتا ہے۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-basics/images/payoff-short-call.png\" alt=\"میعاد ختم ہونے پر مختصر کال کی ادائیگی: سٹرائیک کے نیچے ہر قیمت کے لیے تقریباً 15,590 روپے کا فلیٹ منافع، 1351 پر بریک ایون، اور ایک لائن جو گہرائی سے گہرائی میں گرتی ہے کیونکہ RELIANCE اسٹرائیک کے اوپر چڑھتا ہے، بغیر کسی منزل کے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">چارٹ</span>میعاد ختم ہونے پر مختصر کال کی ادائیگی: سٹرائیک کے نیچے ہر قیمت پر تقریباً 15,590 روپے کا فلیٹ منافع، 1351 پر بریک ایون، اور ایک لائن جو گہرائی اور گہرائی میں گرتی ہے کیونکہ RELIANCE اسٹرائیک کے اوپر چڑھتا ہے، بغیر کسی منزل کے۔</figcaption></figure>\n<p><strong>بائیں طرف، لائن منافع پر فلیٹ ہے۔</strong> 1320 کی سٹرائیک سے کم کسی بھی ختم ہونے والی قیمت کے لیے، آپ کی فروخت کردہ کال کی میعاد ختم ہو جاتی ہے۔ آپ مکمل پریمیم رکھیں، تقریباً <strong>15,590 روپے</strong>، اور یہ آپ کا زیادہ سے زیادہ فائدہ ہے۔ چاہے RELIANCE 1300 یا 1100 پر ختم ہوتا ہے، آپ وہی 15,590 روپے بناتے ہیں، مزید نہیں۔</p>\n<p><strong>درمیان میں، آپ کا منافع کم ہو جاتا ہے۔</strong> 1320 سے اوپر آپ نے جو کال بیچی ہے اس کی قدر ہونا شروع ہو جاتی ہے، خریدار آپ سے اس قدر کا دعویٰ کر سکتا ہے۔ آپ اب بھی پریمیم کا حصہ اس وقت تک رکھتے ہیں۔ <strong>1351 پر بریک ایون</strong>جو کہ 1320 کی سٹرائیک کے علاوہ 31 روپے فی شیئر پریمیم ہے۔ 1351 پر جو نقصان آپ کا خریدار پر واجب الادا ہے وہ بالکل آپ کے جمع کردہ پریمیم کو منسوخ کر دیتا ہے۔</p>\n<p><strong>دائیں طرف، لائن بغیر فرش کے گرتی ہے۔</strong> 1351 سے اوپر آپ حقیقی نقصان میں ہیں، اور ہر مزید روپیہ RELIANCE بڑھنے پر آپ کی قیمت 500 روپے ہوگی، کیونکہ پوزیشن 500 شیئرز پر ہے۔ اگر RELIANCE 1400 پر ختم ہوجاتا ہے تو آپ کو تقریباً 24,500 روپے کا نقصان ہوگا۔ 1450 میں، کہیں زیادہ۔ کوئی ایسی سطح نہیں ہے جس پر نقصان بڑھنا بند ہو جائے، کیونکہ اس بات کی کوئی حد نہیں ہے کہ اسٹاک کتنی بلندی پر جا سکتا ہے۔ یہ ہے <strong>لامحدود نقصان</strong> ایک ننگی مختصر کال کی، اور یہ واحد سب سے خطرناک ادائیگی ہے جس میں ایک ابتدائی ٹھوکر کھا سکتا ہے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>ایک مختصر کال میں لامحدود نقصان ہوتا ہے۔ اگر RELIANCE خبروں پر فرق پڑتا ہے، تو آپ کی فروخت کردہ کال آپ کے جمع کیے گئے 15,590 روپے سے کہیں زیادہ خرچ کر سکتی ہے، جس کی کوئی اوپری حد نہیں ہے۔ ایک تیز ریلی کئی جیتنے والے مہینوں کے پریمیم کو ختم کر سکتی ہے۔ کبھی بھی یہ سوچ کر اتفاق سے کال نہ بیچیں کہ پریمیم آپ کے پاس ہے۔</p>\n</div></div>\n<h2 id=\"reading-the-short-put-payoff\">شارٹ پٹ ادائیگی پڑھنا</h2>\n<p>اب شارٹ پوٹ، دوبارہ اصلی RELIANCE نمبرز، لانگ پوٹ پے آف الٹا ہوگیا۔ آپ نے 1320 کا پوٹ بیچ کر تقریباً 31 روپے فی شیئر اکٹھا کیا، امید ہے کہ RELIANCE ہڑتال سے اوپر رہے گا۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-basics/images/payoff-short-put.png\" alt=\"ایکسپائری پر شارٹ پوٹ ادائیگی: سٹرائیک سے اوپر کی ہر قیمت کے لیے تقریباً 15,590 روپے کا فلیٹ منافع، 1289 پر بریک ایون، اور ایک لائن جو بہت بڑے نقصان میں پڑتی ہے کیونکہ RELIANCE صفر کی طرف گرتا ہے، تقریباً 6,44,000 روپے تک پہنچ جاتا ہے اگر اسٹاک پوری طرح نیچے گر جائے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">چارٹ</span>ایکسپائری پر شارٹ پوٹ ادائیگی: سٹرائیک سے اوپر کی ہر قیمت کے لیے تقریباً 15,590 روپے کا فلیٹ منافع، 1289 پر بریک ایون، اور ایک لائن جو بہت بڑے نقصان میں پڑتی ہے کیونکہ RELIANCE صفر کی طرف گرتا ہے، تقریباً 6,44,000 روپے تک پہنچ جاتا ہے اگر اسٹاک پوری طرح نیچے گر جاتا ہے۔</figcaption></figure>\n<p><strong>دائیں طرف، لائن منافع پر فلیٹ ہے۔</strong> 1320 کی اسٹرائیک سے اوپر کسی بھی ایکسپائری قیمت کے لیے، آپ نے جو پوٹ بیچا ہے وہ بے کار ہو جاتا ہے اور آپ پورا پریمیم رکھتے ہیں، تقریباً <strong>15,590 روپے</strong>. یہ آپ کا زیادہ سے زیادہ فائدہ ہے، وہی ٹوپی جو پہلے تھی۔</p>\n<p><strong>درمیان میں، آپ کا منافع کم ہو جاتا ہے۔</strong> تک <strong>1289 پر بریک ایون</strong>1320 کی ہڑتال مائنس 31 روپے فی شیئر پریمیم۔ 1289 سے نیچے آپ حقیقی نقصان میں ہیں۔</p>\n<p><strong>بائیں طرف، RELIANCE گرنے سے لائن بہت بڑے نقصان میں پڑتی ہے۔</strong> ہڑتال کے نیچے ہر روپیہ آپ کو 500 روپے میں خرچ کرتا ہے۔ نقصان لفظی طور پر لامحدود نہیں ہے، کیونکہ ایک حصہ صفر سے نیچے نہیں گر سکتا، لیکن بدترین صورت بہت زیادہ ہے۔ اگر RELIANCE صفر کی طرف گر جاتا ہے، تو اس واحد شارٹ پٹ کا نقصان تقریباً پہنچ جائے گا۔ <strong>6,44,000 روپے</strong>آپ کے جمع کردہ 15,590 روپے کے خلاف۔ آپ نے 1320 پر 500 شیئرز خریدنے کی ڈیوٹی سنبھالی چاہے وہ تقریباً بیکار ہو جائیں، اور یہ ڈیوٹی وہ ہے جسے قبول کرنے کے لیے آپ کو چھوٹا پریمیم ادا کیا جاتا ہے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>ایک شارٹ پٹ بہت بڑا خطرہ رکھتا ہے۔ 15,590 روپے جمع کرنے کے لیے آپ 500 RELIANCE حصص 1320 پر خریدنے کی ذمہ داری قبول کرتے ہیں چاہے اسٹاک کریش ہوجائے۔ بدترین صورت میں یہ نقصان تقریباً 6,44,000 روپے تک پہنچتا ہے۔ پریمیم چھوٹا ہے؛ اس کے پیچھے خطرہ نہیں ہے.</p>\n</div></div>\n<h2 id=\"why-sellers-must-post-margin\">بیچنے والوں کو مارجن کیوں پوسٹ کرنا چاہیے۔</h2>\n<p>چونکہ بیچنے والے کا خطرہ بہت زیادہ ہے، اس لیے آپ کسی آپشن کو مفت میں نہیں بیچ سکتے جس طرح خریدار صرف پریمیم ادا کرتا ہے۔ ایکسچینج ایک ڈپازٹ کا مطالبہ کرتا ہے جسے کہا جاتا ہے۔ <strong>مارجن</strong>، آپ کے اکاؤنٹ میں رقم کو بلاک کر دیا گیا ہے اس نقصان کے خلاف سیکیورٹی کے طور پر جو آپ پر واجب الادا ہو سکتے ہیں۔ ایک RELIANCE آپشن لاٹ فروخت کرنے سے آپ کو ملنے والے 15,590 روپے سے کہیں زیادہ رقم ملتی ہے، اور اگر پوزیشن آپ کے خلاف جاتی ہے تو یہ مارجن بڑھ سکتا ہے، جو آپ کو مزید اضافہ کرنے یا بند کرنے پر مجبور کرتا ہے۔</p>\n<p>مارجن کی یہ ضرورت سرخ فیتہ نہیں ہے۔ یہ سسٹم کا دیانتدارانہ اعتراف ہے کہ بیچنے والا اپنے جمع کردہ سے کہیں زیادہ کھو سکتا ہے۔ ایک خریدار ایک پریمیم ادا کرتا ہے اور یہ ان کے عزم کا خاتمہ ہے۔ ایک بیچنے والے کو ایک پریمیم ملتا ہے لیکن اسے مارجن پوسٹ کرنا چاہیے اور اسے فنڈز رکھنا چاہیے، کیونکہ ذمہ داری بڑھ سکتی ہے، اور اس مارجن کا سائز اس خطرے کا ایک کھردرا آئینہ ہے جو آپ لے رہے ہیں۔ اگر پیشکش پر چھوٹے پریمیم کے لیے مارجن غیر آرام دہ حد تک بڑا محسوس ہوتا ہے، تو یہ تکلیف آپ کو تجارت کے بارے میں کچھ سچ بتا رہی ہے۔</p>\n<p>ارتکاب کرنے سے پہلے آپ صحیح نمبر دیکھ سکتے ہیں۔ ایکسچینج بیچنے والے کے مارجن کو a کے طور پر سیٹ کرتا ہے۔ <strong>SPAN</strong> جزو، جو ایک دن کے بدترین اقدام کا احاطہ کرتا ہے، نیز ایک <strong>ایکسپوژر</strong> سب سے اوپر بفر، اور OpenAlgo میں ایک مارجن کیلکولیٹر شامل ہے جو کسی بھی معاہدے اور مقدار کے لیے دونوں حصوں اور ان کا کل واپس کرتا ہے۔ آپشن لکھنے سے پہلے اسے چلائیں تاکہ مسدود رقم اور اس سے ظاہر ہونے والا خطرہ کبھی بھی حیران کن نہ ہو۔</p>\n<h2 id=\"this-is-not-free-income\">یہ مفت آمدنی نہیں ہے۔</h2>\n<p>فروخت کے اختیارات کو اکثر مستقل آمدنی حاصل کرنے کے طریقے کے طور پر تیار کیا جاتا ہے، اور یہ سچ ہے کہ زیادہ تر اختیارات بیکار ختم ہو جاتے ہیں، اس لیے ایک بیچنے والا ہارنے سے زیادہ جیتتا ہے۔ یہ بالکل وہی ہے جو اسے موہک بناتا ہے اور بالکل اسی وجہ سے ابتدائی افراد کو تکلیف ہوتی ہے۔ آپ ماہانہ 15,590 روپے جمع کر سکتے ہیں اور ایک باصلاحیت کی طرح محسوس کر سکتے ہیں، اور پھر ایک پرتشدد اقدام ایک ہی سہ پہر میں کئی مہینوں کا پریمیم واپس دے سکتا ہے۔ جیت چھوٹی اور بار بار ہوتی ہے۔ نقصانات نایاب اور بڑے ہیں. اس شکل کا احترام کرنا بیچنے کا پورا ہنر ہے۔</p>\n\n<div class=\"callout example\"><span class=\"callout-tag\">حقیقی مثال</span><div><p>تعداد میں جال۔ 1320 کال بیچیں اور 15,590 روپے جیب میں رکھیں۔ اسے چھ پرسکون مہینوں تک کریں اور تقریباً 93,540 روپے جمع کریں۔ پھر خبروں پر RELIANCE کا فرق 1450 تک پہنچ جاتا ہے اور مختصر کال پر آپ کو ایک ہی بار میں تقریباً 49,500 روپے کا خرچہ آتا ہے، جس سے تین ماہ سے زیادہ کا پریمیم ختم ہوجاتا ہے۔ بار بار چھوٹی جیت، کبھی کبھار بڑے نقصانات۔ یہی وجہ ہے کہ بیچنے سے عزت کی ضرورت ہوتی ہے نہ کہ غیرت۔</p>\n</div></div>\n<p>اگر آپ فروخت کی تلاش کرتے ہیں، تو اسے کھلی آنکھوں سے کریں. بچ جانے والے بیچنے والے اپنے خطرے کی پہلے سے وضاحت کرتے ہیں، اکثر کال کے پیچھے بنیادی حصص کو پکڑ کر یا خریدے گئے آپشن کے ساتھ مختصر آپشن جوڑ کر جو نقصان کو پورا کرتا ہے، وہ ڈھانچہ جو آپ اگلے کورس میں ملیں گے۔ وہ پوزیشنوں کا سائز چھوٹا کرتے ہیں، وہ مارجن کے لیے نقد رقم رکھتے ہیں، اور وہ کبھی بھی پریمیم کو پہلے سے کمائی ہوئی رقم نہیں مانتے۔ اور وہ پہلے مشق کرتے ہیں۔ <strong>سینڈ باکس ٹریڈنگ (Analyzer mode in OpenAlgo)</strong>حقیقی سرمائے کو خطرے میں ڈالنے سے پہلے، یہ دیکھنا کہ جب سٹاک غلط طریقے سے آگے بڑھتا ہے تو مختصر پوزیشن کیسے برتاؤ کرتی ہے۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>اگر آپ کبھی کوئی آپشن بیچتے ہیں تو داخل ہونے سے پہلے اپنے باہر نکلنے کا فیصلہ کریں۔ اس قیمت کو جانیں جس پر نقصان ناقابل قبول ہو جائے اور مارکیٹ سے بحث کیے بغیر اس پر عمل کریں۔ بیچنے والے کا دشمن چھوٹا، بار بار نقصان نہیں ہے؛ یہ ایک بڑا اقدام ہے جس کا انہوں نے احترام کرنے سے انکار کر دیا۔</p>\n</div></div>\n<p>تو بیچنا ہر لحاظ سے خرید کا آئینہ ہے۔ بیچنے والے کا انعام پریمیم ہے، جس کی حد تقریباً 15,590 روپے ہے، جبکہ خریدار کا انعام کھلا تھا۔ بیچنے والے کا خطرہ شارٹ کال پر لامحدود اور شارٹ پٹ پر بہت بڑا ہوتا ہے، جبکہ خریدار کا خطرہ محدود تھا۔ کوئی بھی فریق مفت پیسہ نہیں ہے۔ خریدار ایک بڑی ادائیگی کے لئے مشکلات ادا کرتا ہے؛ بیچنے والا ایک چھوٹے کے لیے مشکلات لیتا ہے اور بھاری دم اٹھاتا ہے۔ اگلے باب میں ہم دونوں فریقوں کو آمنے سامنے رکھتے ہیں اور ایماندارانہ سوال پوچھتے ہیں کہ ہر آپشن کے تاجر کو اپنے لیے جواب دینا چاہیے: خریدار یا بیچنے والا، کس کے پاس واقعی برتری ہے؟</p>\n","toc":[{"level":2,"text":"تجارت کے ارد گرد پلٹنا","id":"flipping-the-trade-around"},{"level":2,"text":"مختصر کال کی ادائیگی پڑھنا","id":"reading-the-short-call-payoff"},{"level":2,"text":"شارٹ پٹ ادائیگی پڑھنا","id":"reading-the-short-put-payoff"},{"level":2,"text":"بیچنے والوں کو مارجن کیوں پوسٹ کرنا چاہیے۔","id":"why-sellers-must-post-margin"},{"level":2,"text":"یہ مفت آمدنی نہیں ہے۔","id":"this-is-not-free-income"}],"imgCount":2,"hasContent":true},"17":{"html":"<p>ہر آپشن جو موجود ہے اس کے ساتھ دو لوگ منسلک ہیں۔ ایک نے حق رکھنے کے لیے پریمیم ادا کیا، دوسرے نے پریمیم وصول کیا اور ڈیوٹی لی۔ اب ہم دونوں جوتوں کے جوڑے میں کھڑے ہیں۔ ہم نے RELIANCE 1320 کال خریدی ہے اور نقصان کو تقریباً 15,590 روپے تک محدود رہنے کو دیکھا ہے۔ ہم نے اسے بیچ دیا ہے اور چارٹ کے نیچے سے نقصان کو دیکھا ہے۔ لہذا اب ہم یہ سوال پوچھ سکتے ہیں کہ ہر آپشن ٹریڈر کو آخرکار اپنے لیے ایمانداری سے جواب دینا ہوگا۔ اگر خریدنا آپ کے خطرے کو کم کرتا ہے لیکن بیچنے سے پریمیم اور وقت کی مدد جمع ہوتی ہے، تو درحقیقت کس طرف برتری حاصل ہے؟ جواب نعرہ نہیں ہے۔ یہ ایک حقیقی تجارت ہے، اور اسے سمجھنا ہی ایک سوچنے سمجھنے والے تاجر کو ایک امید مند جواری سے الگ کرتا ہے۔</p>\n<h2 id=\"the-honest-trade-off\">ایماندارانہ تجارت</h2>\n<p>ایک آپشن میں کہیں بھی مفت لنچ چھپا نہیں ہے۔ دونوں اطراف آئینے کی تصویریں ہیں، اور ایک طرف سے حاصل ہونے والے ہر فائدے کی ادائیگی مماثل نقصان سے کی جاتی ہے۔</p>\n<ul>\n<li>دی <strong>خریدار</strong> محدود خطرہ ہے. ایک کال یا پوٹ خریدار سب سے زیادہ جو کھو سکتا ہے وہ ہے ادا کردہ پریمیم ہے، تقریباً <strong>15,590 روپے</strong> ایک RELIANCE لاٹ کے لیے۔ لیکن خریدار مشکلات کا مقابلہ کرتا ہے۔ تجارت جیتنے کے لیے، RELIANCE کو 28 جولائی سے پہلے اسٹرائیک کے علاوہ پریمیم کو صاف کرنے کے لیے کافی حد تک، اور کافی تیزی سے آگے بڑھنا چاہیے، جب کہ وقت کی زوال خاموشی سے ہر روز پریمیم کو ختم کرتی ہے۔</li>\n<li>دی <strong>بیچنے والا</strong> مشکلات اور کیلنڈر ان کی طرف ہے۔ زیادہ تر اختیارات کی میعاد ختم ہو جاتی ہے، اس لیے بیچنے والا زیادہ بار جیتتا ہے، اور ہر گزرتا دن ان کے پاس جمع کردہ وقت کی قدر کا تھوڑا سا زیادہ حصہ دیتا ہے۔ لیکن بیچنے والے کا انعام موصول ہونے والے پریمیم پر محدود ہوتا ہے، جبکہ اس کے پیچھے خطرہ شارٹ پٹ پر بڑا ہوتا ہے اور ایک مختصر کال پر لامحدود ہوتا ہے۔</li>\n</ul>\n<p>تو کسی بھی فریق کو کچھ نہیں مل رہا ہے۔ خریدار ایک آرام دہ، محدود خطرہ خریدتا ہے اور امکان سے لڑ کر اس کی ادائیگی کرتا ہے۔ بیچنے والا سازگار امکان خریدتا ہے اور خطرے کی بھاری دم اٹھا کر اس کی ادائیگی کرتا ہے۔ پریمیم صرف وہ قیمت ہے جس پر یہ دونوں تجارتیں ملتی ہیں۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>خرید و فروخت آئینہ دار ہیں۔ خریدار کے پاس محدود خطرہ اور ناموافق مشکلات ہیں۔ بیچنے والے کے پاس سازگار مشکلات اور بڑے یا لامحدود خطرہ ہیں۔ جو کچھ بھی ایک طرف آرام سے حاصل کرتا ہے، وہ امکان میں چھوڑ دیتا ہے، اور دوسری طرف۔</p>\n</div></div>\n<h2 id=\"probability-versus-payoff\">امکان بمقابلہ ادائیگی</h2>\n<p>تجارت کو دیکھنے کا سب سے صاف طریقہ یہ ہے کہ دو چیزوں کو الگ کر دیا جائے جو کہ ابتدائی افراد مسلسل الجھن میں رہتے ہیں: آپ کتنی بار جیتتے ہیں، اور جب آپ کرتے ہیں تو آپ کتنی جیتتے یا ہارتے ہیں۔</p>\n<p>پیسے سے باہر ہونے والے آپشن کا خریدار عام طور پر کسی ایک تجارت پر ہار جاتا ہے۔ اسٹاک کافی منتقل ہونے میں ناکام رہتا ہے، وقت ختم ہوجاتا ہے، اور پریمیم صفر پر چلا جاتا ہے۔ لیکن کام کرنے والی نایاب تجارت پر، ادائیگی پریمیم سے کئی گنا زیادہ ہو سکتی ہے، کیونکہ لانگ کال پر اپسائیڈ مؤثر طریقے سے اوپن اینڈڈ ہوتا ہے اور لانگ پوٹ پر الٹا بہت بڑا ہوتا ہے۔ لہذا خریدار بہت سے چھوٹے نقصانات اور کبھی کبھار ایک بڑی جیت جمع کرتا ہے۔ یہ ایک کم امکان، اعلی ادائیگی کی شکل ہے۔</p>\n<p>بیچنے والا مخالف شکل میں رہتا ہے۔ وہ زیادہ تر تجارتوں پر پریمیم جمع کرتے ہیں کیونکہ زیادہ تر اختیارات بیکار ختم ہو جاتے ہیں۔ جیتو، جیتو، جیتو، صاف ستھرا 15,590 روپے کا مجموعہ جو تنخواہ کی طرح محسوس ہوتا ہے۔ پھر، کبھی کبھار، ایک پرتشدد اقدام آتا ہے اور ایک نقصان ان مجموعوں کے کئی مہینوں کو مٹا دیتا ہے۔ یہ ایک خطرناک دم کے ساتھ ایک اعلی امکان، کم ادائیگی کی شکل ہے.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-basics/images/diagram-buyer-vs-seller.png\" alt=\"دونوں اطراف ایک ساتھ رکھے ہوئے ہیں: خریدار جس کے بائیں طرف محدود خطرہ اور ناموافق مشکلات ہیں، بیچنے والا موافق مشکلات کے ساتھ اور دائیں طرف بڑا یا لامحدود خطرہ، یہ ظاہر کرتا ہے کہ کوئی بھی کالم مفت رقم نہیں ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>دونوں اطراف ایک ساتھ رکھے ہوئے ہیں: خریدار جس کے بائیں طرف محدود خطرہ اور ناموافق مشکلات ہیں، بیچنے والا موافق مشکلات کے ساتھ اور دائیں طرف بڑا یا لامحدود خطرہ، یہ ظاہر کرتا ہے کہ کوئی بھی کالم مفت رقم نہیں ہے۔</figcaption></figure>\n<p>دونوں کو ساتھ ساتھ رکھیں اور ہم آہنگی بالکل درست ہے۔</p>\n<table>\n<thead>\n<tr>\n<th></th>\n<th>آپشن خریدار</th>\n<th>آپشن بیچنے والا</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>ادا کرتا ہے یا وصول کرتا ہے۔</td>\n<td>پریمیم ادا کرتا ہے۔</td>\n<td>پریمیم وصول کرتا ہے۔</td>\n</tr>\n<tr>\n<td>زیادہ سے زیادہ نقصان</td>\n<td>پریمیم کی حد، تقریباً 15,590 روپے</td>\n<td>بڑا (شارٹ پٹ) یا لامحدود (مختصر کال)</td>\n</tr>\n<tr>\n<td>زیادہ سے زیادہ فائدہ</td>\n<td>بڑا یا لامحدود</td>\n<td>پریمیم کی حد، تقریباً 15,590 روپے</td>\n</tr>\n<tr>\n<td>وقت کی طرف سے مدد یا تکلیف</td>\n<td>ہر روز کشی سے چوٹ لگتی ہے۔</td>\n<td>ہر روز کشی کی طرف سے مدد کی</td>\n</tr>\n<tr>\n<td>سب سے زیادہ تجارت جیتتا ہے؟</td>\n<td>نہیں، عام طور پر چھوٹا پریمیم کھو دیتا ہے۔</td>\n<td>ہاں، زیادہ تر اختیارات بیکار ختم ہو جاتے ہیں۔</td>\n</tr>\n<tr>\n<td>کیچ</td>\n<td>سمت، سائز اور وقت پر درست ہونا ضروری ہے۔</td>\n<td>ایک بری حرکت بہت سی جیتوں کو ختم کر سکتی ہے۔</td>\n</tr>\n</tbody></table>\n<p>اس ٹیبل کو آہستہ سے پڑھیں۔ غور کریں کہ خریدار کا کالم اور بیچنے والے کا کالم دونوں کبھی بھی ایک ساتھ پرکشش نظر نہیں آتے۔ ہر قطار ایک تبادلہ ہے۔ یہی سارا سبق ہے۔</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>ایک اعلی جیت کی شرح ایک منافع بخش حکمت عملی کے طور پر ایک ہی نہیں ہے. ایک بیچنے والا دس میں سے نو تجارت جیت سکتا ہے اور پھر بھی سال کا اختتام ختم ہو سکتا ہے اگر دسویں نقصان مشترکہ نو جیتوں سے زیادہ ہو۔ ہمیشہ وزن کریں کہ آپ کتنی بار جیتتے ہیں اس کے مقابلے میں کہ آپ کتنی جیتتے ہیں یا ہارتے ہیں، ایک دوسرے کے بغیر کبھی نہیں۔</p>\n</div></div>\n<h2 id=\"why-most-buyers-lose\">زیادہ تر خریدار کیوں ہار جاتے ہیں۔</h2>\n<p>یہ دو ٹوک ہونے کے قابل ہے، کیونکہ آپشنز کے ارد گرد مارکیٹنگ کبھی نہیں ہوتی۔ زیادہ تر آپشن خریدار وقت کے ساتھ پیسے کھو دیتے ہیں، اور اس کی وجہ ساخت میں بنتی ہے، بدقسمتی میں نہیں۔</p>\n<p>RELIANCE 1320 کال کے خریدار کے طور پر جیتنے کے لیے، تین چیزوں کو ایک ہی وقت میں درست کرنا ہوگا۔ آپ کو سمت کی ضرورت ہے، اسٹاک بڑھنا ضروری ہے. آپ کو سائز کی ضرورت ہے، اسے بریک ایون سے آگے بڑھنا چاہیے۔ <strong>1351</strong>، 1320 کی ہڑتال کے علاوہ 31 روپے فی شیئر پریمیم۔ اور آپ کو وقت کی ضرورت ہے، یہ سب کچھ 28 جولائی سے پہلے ہونا چاہیے، کیونکہ اس کے بعد آپشن ختم ہو جاتا ہے۔ تین میں سے ایک یا دو پر درست ہونا کافی نہیں ہے۔ ایک تاجر جو صحیح اندازہ لگاتا ہے کہ RELIANCE بڑھے گا، لیکن صرف 1335 تک، پھر بھی ہارتا ہے، کیونکہ 1335 برییکون سے نیچے ہے۔ سمت درست تھی اور تجارت پھر بھی ناکام رہی۔</p>\n<p>دریں اثنا، گھڑی چارج پورے وقت کرایہ. یہاں تک کہ ایک دن جب RELIANCE تھوڑا سا بڑھتا ہے، وقت کا زوال خاموشی سے فائدہ کو منسوخ کر سکتا ہے، اس لیے پریمیم بمشکل حرکت کرتا ہے۔ خریدار نیچے ایسکلیٹر چلا رہا ہے۔ یہی وجہ ہے کہ بہت سارے ابتدائی افراد مارکیٹ کے بارے میں صحیح ہونے اور پھر بھی آپشن پر پیسہ کھونے کے عجیب تجربے کی اطلاع دیتے ہیں۔ ڈھانچے نے انہیں تین طریقوں سے درست ہونے کو کہا، اور کیلنڈر نے ہر دن ان کا انتظار کیا۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>پیسے سے باہر کے اختیارات خریدنا سب سے عام طریقہ ہے کہ ابتدائی افراد مارکیٹ میں پیسے کھو دیتے ہیں۔ آپشن سستا ہے کیونکہ یہ تمام امید ہے اور کوئی اندرونی قیمت نہیں ہے، منافع میں تکمیل کے امکانات کم ہیں، اور وقت کا زوال ہر ایک دن اسے ختم کر دیتا ہے۔ سستے کا مطلب اچھی قیمت نہیں ہے۔</p>\n</div></div>\n<p>اس میں سے کوئی بھی مطلب فروخت کرنا محفوظ جواب نہیں ہے۔ بیچنے والا خریدار کی ناقص مشکلات کو خطرے کی خراب شکل کے لیے بدل دیتا ہے۔ 15,590 روپے بار بار اکٹھا کرنا اس وقت تک آسان محسوس ہوتا ہے جب تک کہ خبروں پر ماہ RELIANCE کا فرق نہیں ہوتا ہے اور ایک مختصر کال پر پریمیم کے نصف سال سے زیادہ لاگت آتی ہے۔ خریدار ہزار چھوٹے کٹوں سے مر جاتا ہے۔ بیچنے والا ایک بڑے زخم سے مر جاتا ہے۔ دونوں موتیں حقیقی ہیں۔</p>\n<h2 id=\"choosing-a-side-honestly\">ایمانداری سے ایک طرف کا انتخاب کرنا</h2>\n<p>تو آپ کو کس طرف ہونا چاہئے؟ ایماندارانہ جواب یہ ہے کہ یہ اس بات پر منحصر ہے کہ آپ اصل میں کیا کرنے کی کوشش کر رہے ہیں، اور اپنے آپ کے ساتھ سچے ہونے اور خطرے کے لیے اپنی رواداری پر منحصر ہے۔</p>\n<ul>\n<li><strong>خریدنے کی طرف جھکاؤ</strong> جب آپ کے پاس ایک مخصوص، وقت کا پابند نظریہ ہے اور آپ چاہتے ہیں کہ آپ کے داخلے سے پہلے روپے کو آپ کا منفی پہلو معلوم ہو۔ خریدنا ایک ایسے مبتدی کے لیے موزوں ہے جو مارکیٹ کو نقصان کے ساتھ سیکھنا چاہتا ہے جس کا وہ پہلے سے نام لے سکتے ہیں۔ صرف اس رقم کا سائز بنائیں جس سے آپ مکمل طور پر کھونے کے متحمل ہوسکتے ہیں، کیونکہ پریمیم کا مکمل نقصان عام نتیجہ ہے، نایاب نہیں۔</li>\n<li><strong>فروخت کی طرف جھکاؤ</strong> صرف اس صورت میں جب آپ خطرے کو حقیقی طور پر سمجھتے ہیں اور فنڈ کر سکتے ہیں، جب آپ کے پاس ٹیل کیپ کرنے کا منصوبہ ہے، اور جب آپ پریمیم کو خطرے کے طور پر لیتے ہیں تو آپ کرائے پر دے رہے ہیں، نہ کہ وہ آمدنی جو آپ نے پہلے سے کمائی ہے۔ انعامات فروخت کرنا نظم و ضبط اور سزا دیتا ہے، اور یہ مارجن کا مطالبہ کرتا ہے، جس پر ہم آخری باب میں واپس جائیں گے۔</li>\n</ul>\n<p>شروع کرنے والے تقریباً ہر ایک کے لیے، صحیح پہلا قدم چھوٹا خریدنا، نقصان کی وضاحت کرنا، اور یہ جاننا کہ پریمیم اصل میں RELIANCE کے طور پر کیسے برتاؤ کرتا ہے اور جیسے جیسے دن گزرتے ہیں۔ پہلے اس کی مشق کریں۔ <strong>سینڈ باکس ٹریڈنگ (Analyzer mode in OpenAlgo)</strong>، جہاں آپ ایک روپیہ خطرے میں ڈالے بغیر آپ کے خلاف ایک لمبی کال کی کمی اور ایک مختصر کال دیکھ سکتے ہیں۔ نمبروں کی حرکت کو دیکھنا کسی بھی وضاحت سے کہیں زیادہ سکھاتا ہے۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>کسی بھی آپشن کی تجارت کرنے سے پہلے، یہ لکھیں کہ آپ ٹریڈ آف کا کون سا رخ قبول کر رہے ہیں۔ اگر آپ خرید رہے ہیں تو قبول کریں کہ آپ غالباً پریمیم کھو دیں گے اور یہ کہ آپ کو جیتنے کے لیے تین طریقے درست ہونے چاہئیں۔ اگر آپ فروخت کر رہے ہیں تو بڑی دم کو قبول کریں اور داخل ہونے سے پہلے اپنے باہر نکلنے کا فیصلہ کریں۔ اگر آپ اپنی طرف کے کیچ کو اونچی آواز میں نہیں بتا سکتے، تو آپ تجارت کرنے کے لیے تیار نہیں ہیں۔</p>\n</div></div>\n<p>کوئی مستقل کنارہ نہیں جو ایک طرف سے تعلق رکھتا ہو۔ خریدار اور بیچنے والا ایک ہی خطرہ مول لینے کے صرف دو طریقے ہیں، جس کی قیمت اتنی ہے کہ اوسطاً، کوئی بھی تحفہ نہیں ہے۔ کنارے، جب یہ موجود ہے، فیصلے، سائز اور نظم و ضبط سے آتا ہے، خود طرف کے انتخاب سے نہیں. اگلے دو ابواب آپ کو ایسے ٹولز دیتے ہیں جو اس فیصلے کو تیز کرتے ہیں: یونانی، جو اس بات کی پیمائش کرتے ہیں کہ آپشن کی قیمت دنیا میں کیسے رد عمل ظاہر کرتی ہے، اور مضمر اتار چڑھاؤ، جو آپ کو بتاتا ہے کہ آپ جو پریمیم ادا کرنے والے ہیں وہ پہلے سستا ہے یا مہنگا۔</p>\n","toc":[{"level":2,"text":"ایماندارانہ تجارت","id":"the-honest-trade-off"},{"level":2,"text":"امکان بمقابلہ ادائیگی","id":"probability-versus-payoff"},{"level":2,"text":"زیادہ تر خریدار کیوں ہار جاتے ہیں۔","id":"why-most-buyers-lose"},{"level":2,"text":"ایمانداری سے ایک طرف کا انتخاب کرنا","id":"choosing-a-side-honestly"}],"imgCount":1,"hasContent":true},"18":{"html":"<p>آپ نے شاید تاجروں کو ڈیلٹا اور تھیٹا جیسے الفاظ کو اس طرح پھینکتے ہوئے سنا ہوگا جیسے وہ خفیہ کوڈ ہوں۔ وہ نہیں ہیں۔ یونانی صرف اس بارے میں چار سادہ سوالات ہیں کہ آپشن کا پریمیم اس کے آس پاس کی دنیا پر کیا رد عمل ظاہر کرتا ہے۔ جب RELIANCE ایک روپیہ منتقل کرتا ہے، تو میرا آپشن کتنا منتقل ہوتا ہے؟ جب ایک دن گزرتا ہے تو میں صرف کیلنڈر میں کتنا کھو دیتا ہوں؟ جب مارکیٹ گھبرا جاتی ہے تو میرے پریمیم کا کیا ہوتا ہے؟ ہر یونانی ان سوالوں میں سے ایک کا جواب ایک عدد کے ساتھ دیتا ہے۔ آپ کو ان کو استعمال کرنے کے لیے کسی ریاضی کی ضرورت نہیں ہے، اور اس باب میں کوئی بھی نہیں ہوگا۔ ہم ہر یونانی کو سادہ انگریزی میں رکھیں گے، حقیقی RELIANCE 1320 آپشن پر لنگر انداز ہوں گے، تاکہ آخر تک آپ موسم کی پیشن گوئی کو پڑھنے کے طریقے سے آپشن پڑھ سکیں۔</p>\n<h2 id=\"delta-how-much-the-premium-moves\">ڈیلٹا: پریمیم کتنا چلتا ہے۔</h2>\n<p><strong>ڈیلٹا</strong> سب کے سب سے بنیادی سوال کا جواب دیتا ہے۔ اگر RELIANCE ایک روپیہ بڑھتا ہے، تو میرا آپشن پریمیم کتنا بڑھتا ہے؟ ڈیلٹا جواب ہے، کالز کے لیے صفر اور ایک کے درمیان، اور پوٹس کے لیے صفر اور مائنس ون کے درمیان رقم کے طور پر حوالہ دیا جاتا ہے۔</p>\n<p>RELIANCE 1320 کال کریں، 1318 کے قریب اسپاٹ کے ساتھ ایٹ-دی-منی بیٹھیں۔ اس کا مطلب ہے کہ اگر RELIANCE ایک روپیہ بڑھتا ہے، تو کال پریمیم تقریباً پچاس پیسے فی شیئر بڑھ جاتا ہے۔ اگر RELIANCE میں ایک روپے کی کمی آتی ہے، تو پریمیم تقریباً اتنا ہی گرتا ہے۔ پٹ آئینے کی طرح برتاؤ کرتا ہے۔ ایک 1320 پوٹ کا ڈیلٹا تقریبا مائنس 0.5 ہوتا ہے، اس لیے جب RELIANCE ایک روپیہ گرتا ہے اور جب RELIANCE بڑھتا ہے تو اس میں تقریباً پچاس پیسے کا فائدہ ہوتا ہے۔</p>\n<p>ڈیلٹا بھی بدل جاتا ہے جب آپشن پیسے کے اندر اور باہر منتقل ہوتا ہے۔</p>\n<ul>\n<li>ایک گہرا <strong>پیسے میں</strong> آپشن میں ایک کے قریب ڈیلٹا ہے۔ یہ اسٹاک کے ساتھ روپے کے بدلے تقریباً روپیہ منتقل کرتا ہے، کیونکہ یہ تقریباً حصص کو اپنے پاس رکھنے کی طرح برتاؤ کرتا ہے۔</li>\n<li>ایک <strong>پیسے پر</strong> آپشن میں 0.5 کے قریب ڈیلٹا ہے۔ یہ ہر حرکت کے نصف حصے پر قبضہ کرتا ہے۔</li>\n<li>ایک دور <strong>پیسے سے باہر</strong> آپشن میں صفر کے قریب ڈیلٹا ہے۔ اسٹاک بھٹک سکتا ہے اور پریمیم بمشکل چمکتا ہے، کیونکہ ہڑتال بہت دور ہے۔</li>\n</ul>\n<p>ڈیلٹا کو پڑھنے کا ایک دوسرا، بہت مفید طریقہ ہے۔ یہ آپ کو اس موقع کے بارے میں کسی نہ کسی طرح کا احساس دلاتا ہے کہ آپشن پیسے میں ختم ہو جاتا ہے۔ ایٹ-دی-منی کال پر تقریباً 0.5 کا ڈیلٹا، ڈھیلے انداز میں کہتا ہے کہ مارکیٹ میں اندرونی قدر کے ساتھ کال کی میعاد ختم ہونے کے تقریباً یکساں امکانات نظر آتے ہیں۔ پیسے سے باہر کال پر 0.15 کا ڈیلٹا سرگوشی کرتا ہے کہ اس کی ادائیگی کے امکانات بہت کم ہیں۔ یہ قطعی امکان نہیں ہے، لیکن ایک گٹ احساس کے طور پر یہ حقیقی طور پر مفید ہے۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>ڈیلٹا یہ ہے کہ RELIANCE میں ہر ایک روپے کی منتقلی کے لیے پریمیم کتنا بڑھتا ہے۔ تقریباً 0.5 اٹ-دی-منی، ایک ڈیپ ان دی منی کے قریب، پیسے سے باہر صفر کے قریب۔ یہ آپشن کے اندرونی قدر کے ساتھ ختم ہونے کے موقع کے لیے بھی ایک کھردرا احساس دیتا ہے۔</p>\n</div></div>\n<h2 id=\"gamma-how-fast-delta-itself-changes\">گاما: ڈیلٹا خود کتنی تیزی سے تبدیل ہوتا ہے۔</h2>\n<p>ڈیلٹا طے نہیں ہے۔ جیسے جیسے RELIANCE حرکت کرتا ہے، آپ کے اختیار کا ڈیلٹا بھی بدل جاتا ہے، اور <strong>گاما</strong> یونانی ہے جو پیمائش کرتا ہے کہ یہ کتنی تیزی سے ہوتا ہے۔ اگر ڈیلٹا آپ کو آپ کی موجودہ رفتار بتاتا ہے، تو گاما آپ کو بتاتا ہے کہ وہ رفتار کتنی تیزی سے بدل رہی ہے۔</p>\n<p>یہ اس لیے اہمیت رکھتا ہے کیونکہ ایک ایٹ-دی-منی آپشن میں سب سے زیادہ گاما ہوتا ہے۔ 1320 کی ہڑتال کے آس پاس، RELIANCE میں ایک چھوٹی سی حرکت ڈیلٹا کو نمایاں طور پر جھول سکتی ہے۔ ایک کال جس کا ڈیلٹا 0.5 تھا وہ معمولی ریلی کے بعد 0.6 کی طرف چھلانگ لگا سکتا ہے اور معمولی گرنے کے بعد 0.4 کی طرف پھسل سکتا ہے۔ اس لیے آپشن کی اسٹاک کے لیے حساسیت خود ہی جاندار ہے اور وہیں منتقل ہو رہی ہے جہاں اسپاٹ اب بیٹھا ہے۔</p>\n<p>ڈیپ ان دی منی اور پیسے سے باہر کے اختیارات میں کم گاما ہوتا ہے۔ ان کے ڈیلٹا پہلے سے ہی ایک کے قریب یا صفر کے قریب پن کیے ہوئے ہیں، لہذا ان کے پاس تبدیل کرنے کی بہت کم گنجائش ہے۔ گاما ہڑتال کے قریب سب سے مضبوط اور ایکسپائری کے قریب آنے کے ساتھ ہی سب سے مضبوط ہے، یہی وجہ ہے کہ آپشنز ہفتوں تک پرسکون محسوس کر سکتے ہیں اور پھر پیسے کے قریب آخری دنوں میں اچانک کوڑے مار سکتے ہیں۔</p>\n<p>ایک ابتدائی کے لیے، عملی راستہ آسان ہے۔ ہائی گاما کا مطلب ہے کہ آپ کے اختیار کا رویہ تیزی سے تبدیل ہو سکتا ہے، اس لیے ایسی پوزیشن جس میں نیند آتی ہے وہ اسٹرائیک ختم ہونے کے قریب تیزی سے زندہ ہو سکتی ہے۔ آپ کو گاما کا حساب لگانے کی ضرورت نہیں ہے۔ آپ کو صرف اس بات کا احترام کرنے کی ضرورت ہے کہ ڈیلٹا ایک متحرک ہدف ہے، اور گاما اس کی وجہ ہے۔</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>گاما ڈیلٹا کی تبدیلی کی شرح ہے۔ یہ ایکسپائری کے قریب ایٹ دی منی آپشنز کے لیے سب سے زیادہ ہے۔ یہی وجہ ہے کہ 28 جولائی سے ایک یا دو دن پہلے ہڑتال پر بیٹھے ہوئے آپشن کی قدر ایک ماہ پہلے کے اسی آپشن کے مقابلے میں کہیں زیادہ تیزی سے بدل سکتی ہے۔</p>\n</div></div>\n<h2 id=\"theta-the-daily-rupee-bleed\">تھیٹا: روزانہ روپیہ خون بہتا ہے۔</h2>\n<p><strong>تھیٹا</strong> یونانی ہر آپشن خریدار ڈرنا سیکھتا ہے۔ یہ اس وقت کے زوال کی پیمائش کرتا ہے جس سے ہم نے پہلے باب میں ملاقات کی تھی، جس کا اظہار اس پریمیم کی مقدار کے طور پر کیا گیا ہے جو آپ کا اختیار ہر روز کھوتا ہے خالصتاً اس وجہ سے کہ ایک اور دن گزر چکا ہے، باقی سب کچھ باقی ہے۔</p>\n<p>فرض کریں کہ RELIANCE 1320 کال کا تھیٹا اس کی زندگی کے اس موڑ پر روزانہ تقریباً ایک روپیہ ہے۔ اس کا مطلب ہے، اگر RELIANCE صرف 1318 پر بیٹھتا ہے اور کوئی اور چیز تبدیل نہیں ہوتی ہے، تو کال خاموشی سے راتوں رات تقریباً ایک روپیہ فی شیئر پریمیم کھو دیتی ہے، جو کہ 500 کے لاٹ پر تقریباً 500 روپے ہے۔ اگلی رات، تھوڑا اور۔ اسٹاک نے کچھ نہیں کیا، خبر خاموش تھی، اور پھر بھی ہر صبح آپشن کی قیمت کم ہے۔ وہ مستقل لیک کام پر تھیٹا ہے۔</p>\n<p>تھیٹا کی دو خصوصیات یادداشت میں جلنے کے قابل ہیں۔</p>\n<ul>\n<li>پیسے کے اختیارات کے لیے تھیٹا سب سے بڑا ہے، کیونکہ وہ سب سے زیادہ وقت کی قیمت رکھتے ہیں، اور وقت کی قدر بالکل وہی ہے جو زوال پذیر ہوتی ہے۔</li>\n<li>ختم ہونے کے قریب آتے ہی تھیٹا میں تیزی آتی ہے۔ یومیہ خون 32 دن باقی رہ جانے کے ساتھ ہلکا ہوتا ہے اور آخری ہفتے میں اس وقت ظالمانہ ہو جاتا ہے، جب آخری وقت کی قدر صفر پر گر جاتی ہے۔</li>\n</ul>\n<p>یہی وجہ ہے کہ تھیٹا خریدار کا دشمن اور بیچنے والے کا دوست ہے۔ خریدار پگھلنے کے وقت کی قیمت کا مالک ہے اور ہر روز تھیٹا ادا کرتا ہے۔ بیچنے والے نے اس وقت کی قیمت کو پہلے سے جمع کیا اور اسے خاموشی سے گزرنے والے ہر دن کے ساتھ تھوڑا سا مزید رکھنا پڑتا ہے۔ تھیٹا امید کا کرایہ ہے، اور یہ ہمیشہ خریدار سے بیچنے والے تک جاتا ہے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>تھیٹا ہر ایک دن آپ کے خلاف کام کرتا ہے جب آپ خریدا ہوا آپشن رکھتے ہیں۔ آپ سمت کے بارے میں درست ہو سکتے ہیں اور پھر بھی ہار سکتے ہیں، کیونکہ روزانہ خون بہنے کی رفتار آہستہ یا چھوٹی ہوتی ہے۔ جوں جوں ایکسپائری قریب آتی جاتی ہے، اتنی ہی تیزی سے خون بہہ جاتا ہے، اس لیے آخری ہفتے میں ایک طویل آپشن ایک بڑھتی ہوئی سردی سے لڑ رہا ہے۔</p>\n</div></div>\n<h2 id=\"vega-sensitivity-to-fear\">ویگا: خوف کی حساسیت</h2>\n<p>آخری یونانی قیمت یا وقت سے کم واضح چیز کی پیمائش کرتی ہے۔ <strong>ویگا</strong> آپ کو بتاتا ہے کہ آپ کا آپشن پریمیم کتنا بدلتا ہے جب مارکیٹ کی نقل و حرکت کی توقع، اس کے <strong>مضمر اتار چڑھاؤ</strong>، اٹھتا ہے یا گرتا ہے۔ ہم مضمر اتار چڑھاؤ کو اگلا ایک مکمل باب دیتے ہیں، اس لیے ابھی کے لیے اسے قیمت میں خوف اور توقع کی سطح کے طور پر سوچیں۔</p>\n<p>جب مضمر اتار چڑھاؤ بڑھتا ہے، اختیارات پورے بورڈ میں زیادہ مہنگے ہو جاتے ہیں، اور ویگا یونانی ہے جو اس بات کو پکڑتی ہے کہ آپ کے مخصوص آپشن کو اس سے کتنا فائدہ ہوتا ہے۔ جب مضمر اتار چڑھاؤ گر جاتا ہے، اختیارات سستے ہو جاتے ہیں، اور ویگا پیمائش کرتا ہے کہ آپ کتنا کھوتے ہیں۔ اہم طور پر، یہ ہو سکتا ہے یہاں تک کہ اگر RELIANCE خود بالکل بھی منتقل نہ ہوا ہو۔ اسٹاک بالکل ساکن بیٹھ سکتا ہے جب کہ آپ کا پریمیم پھول جاتا ہے یا سکڑتا ہے صرف اس وجہ سے کہ مارکیٹ مستقبل کے بارے میں کم و بیش گھبراتی ہے۔</p>\n<p>بہت سارے وقت کے ساتھ پیسے کے اختیارات میں سب سے زیادہ ویگا ہوتا ہے، لہذا وہ خوف میں شفٹ ہونے پر سب سے زیادہ ردعمل ظاہر کرتے ہیں۔ پرسکون مارکیٹ کے ذریعے منعقد ہونے والا ایک طویل آپشن گرتی ہوئی اتار چڑھاؤ کی وجہ سے قیمت کھو سکتا ہے یہاں تک کہ خریدار صبر سے حرکت کا انتظار کرتا ہے۔ یہ IV کے پیچھے کا جال ہے جس کا ہم آگے مطالعہ کریں گے، اور ویگا وہ ڈائل ہے جو اس کی پیمائش کرتا ہے۔</p>\n\n<div class=\"callout example\"><span class=\"callout-tag\">حقیقی مثال</span><div><p>RELIANCE ایک ہفتے کے لیے 1318 پر فلیٹ بیٹھتا ہے۔ دو الگ الگ وجوہات کی بنا پر 1320 کال اب بھی قدر کھو دیتی ہے۔ جیسے جیسے دن گزرتے گئے تھیٹا میں کچھ وقت کی قدر ختم ہو گئی، اور ویگا کے ذریعے ماپا جانے والے مضمر اتار چڑھاؤ میں کمی، مزید منڈوا گئی۔ ایک ہی اسٹاک کی قیمت، کم پریمیم، دو گنا زیادہ۔ اس طرح ایک خریدار صبر کر سکتا ہے، درست ہو سکتا ہے کہ اسٹاک نہیں گرا ہے، اور پھر بھی آپشن کو ختم ہوتے دیکھ سکتا ہے۔</p>\n</div></div>\n<h2 id=\"reading-the-four-together\">چاروں کو ایک ساتھ پڑھنا</h2>\n<p>آپ تنہائی میں کبھی ایک یونانی تجارت نہیں کرتے۔ وہ ایک ہی وقت میں چار زاویوں سے ایک ہی اختیار کو بیان کرتے ہیں، اور ایک حقیقی پوزیشن چاروں کا مجموعہ ہے۔ یہاں ایک کارڈ پر پوری تصویر ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>یونانی</th>\n<th>وہ سوال جس کا جواب دیتا ہے۔</th>\n<th>خریدار اسے محسوس کرتا ہے۔</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>ڈیلٹا</td>\n<td>RELIANCE میں پریمیم فی ایک روپیہ کتنا ہوتا ہے؟</td>\n<td>صحیح سمت پر ہونے پر منافع کا انجن</td>\n</tr>\n<tr>\n<td>گاما</td>\n<td>ڈیلٹا خود کتنی تیزی سے تبدیل ہوتا ہے؟</td>\n<td>آپشن اچانک ہڑتال کے قریب کیوں تیز ہو سکتا ہے۔</td>\n</tr>\n<tr>\n<td>تھیٹا</td>\n<td>ہر روز کتنا پریمیم لیک ہوتا ہے؟</td>\n<td>روز دشمن، امید پر کرایہ</td>\n</tr>\n<tr>\n<td>ویگا</td>\n<td>مضمر اتار چڑھاؤ میں تبدیلی پریمیم کو کتنی منتقل کرتی ہے؟</td>\n<td>پوشیدہ فائدہ یا نقصان یہاں تک کہ جب اسٹاک ساکن ہو۔</td>\n</tr>\n</tbody></table>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-basics/images/diagram-the-greeks.png\" alt=\"چار یونانیوں کو بطور لیبل باکس: ڈیلٹا فی روپیہ کی حرکت کے لیے، گاما اس کے لیے کہ ڈیلٹا کتنی تیزی سے شفٹ ہوتا ہے، روزانہ وقت کے خون کے لیے تھیٹا، اور مضمر اتار چڑھاؤ کو تبدیل کرنے کی حساسیت کے لیے ویگا۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>چار یونانیوں کو بطور لیبل باکس: ڈیلٹا فی روپیہ کی حرکت کے لیے، گاما اس کے لیے کہ ڈیلٹا کتنی تیزی سے شفٹ ہوتا ہے، روزانہ وقت کے خون کے لیے تھیٹا، اور مضمر اتار چڑھاؤ کو تبدیل کرنے کی حساسیت کے لیے ویگا۔</figcaption></figure>\n<p>ایک ساتھ رکھو، یونانی تقریبا ہر چیز کی وضاحت کرتے ہیں جو ایک اختیار کرتا ہے. RELIANCE بڑھنے پر کال بمشکل کیوں منتقل ہوئی، کیوں کہ اس کا ڈیلٹا چھوٹا تھا اور پیسے سے باہر تھا۔ ایک پرسکون ہفتے میں اس کی قدر کیوں کھو گئی، کیوں کہ تھیٹا اور ویگا دونوں نے اس کے خلاف کام کیا۔ یہ اچانک ختم ہونے کے قریب ہڑتال کے قریب کیوں زندہ ہو گیا، کیونکہ گاما میں اضافہ ہوا۔ آپ کو ان میں سے کسی کو ہاتھ سے شمار کرنے کی ضرورت نہیں ہے۔ OpenAlgo یونانیوں کو کسی بھی RELIANCE اسٹرائیک کی اطلاع دے سکتا ہے، اور انھیں پڑھنا ایک پراسرار پلک جھپکنے والے نمبر سے پریمیم کو ایسی چیز میں بدل دیتا ہے جسے آپ حقیقت میں سمجھ سکتے ہیں۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>آپشن خریدنے سے پہلے، اس کے ڈیلٹا اور تھیٹا کو ایک ساتھ دیکھیں۔ ڈیلٹا آپ کو بتاتا ہے کہ اگر آپ صحیح سمت پر ہیں تو آپ کتنا فائدہ اٹھانا چاہتے ہیں، اور تھیٹا آپ کو بتاتا ہے کہ آپ انتظار کرتے ہوئے ہر روز کتنا خون بہاتے ہیں۔ اگر آپ کی توقع کے خلاف روزانہ خون بہت زیادہ نظر آتا ہے، تو تجارت اس سے کہیں زیادہ مشکل گھڑی سے لڑ رہی ہے۔</p>\n</div></div>\n<p>یونانی پیمائش کرتے ہیں کہ آپشن کیسے رد عمل ظاہر کرتا ہے۔ ایک چیز جس پر وہ سب خاموشی سے انحصار کرتے ہیں وہ ہے مضمر اتار چڑھاؤ، مارکیٹ کی یہ توقع کہ RELIANCE کتنا آگے بڑھے گا۔ وہ واحد نمبر فیصلہ کرتا ہے کہ آپ جو پریمیم ادا کرنے والے ہیں وہ پہلے سستا ہے یا مہنگا، اور یہ اگلے باب کا موضوع ہے۔</p>\n","toc":[{"level":2,"text":"ڈیلٹا: پریمیم کتنا چلتا ہے۔","id":"delta-how-much-the-premium-moves"},{"level":2,"text":"گاما: ڈیلٹا خود کتنی تیزی سے تبدیل ہوتا ہے۔","id":"gamma-how-fast-delta-itself-changes"},{"level":2,"text":"تھیٹا: روزانہ روپیہ خون بہتا ہے۔","id":"theta-the-daily-rupee-bleed"},{"level":2,"text":"ویگا: خوف کی حساسیت","id":"vega-sensitivity-to-fear"},{"level":2,"text":"چاروں کو ایک ساتھ پڑھنا","id":"reading-the-four-together"}],"imgCount":1,"hasContent":true},"19":{"html":"<p>یہاں ایک پہیلی ہے جو تقریباً ہر نئے تاجر کو الجھا دیتی ہے۔ دو RELIANCE کال آپشنز، 1320 کی ایک ہی ہڑتال، 28 جولائی کی ایک ہی ایکسپائری، دو مختلف دنوں پر بہت مختلف پریمیم کے قابل ہو سکتے ہیں یہاں تک کہ جب اسٹاک بالکل ایک ہی قیمت پر بیٹھا ہو۔ ہڑتال کے بارے میں کچھ نہیں بدلا۔ باقی وقت کے بارے میں کچھ زیادہ نہیں بدلا۔ پھر بھی ایک دن کال کی قیمت 31 روپے فی شیئر ہوتی ہے اور دوسرے دن اسی طرح کے آپشن کی قیمت کہیں زیادہ یا کہیں کم ہوتی ہے۔ لاپتہ جزو ہے <strong>مضمر اتار چڑھاؤ</strong>تمام آپشنز ٹریڈنگ میں واحد سب سے زیادہ غلط فہمی نمبر۔ یہ مارکیٹ کا خوف کا اندازہ ہے، اور ایک بار جب آپ اسے پڑھ سکتے ہیں، تو آپ امید کے لیے زیادہ ادائیگی کرنا چھوڑ دیتے ہیں اور آپ سمجھتے ہیں کہ کیوں صحیح سمت پر رہنے سے بھی بعض اوقات پیسے ضائع ہوتے ہیں۔</p>\n<h2 id=\"what-implied-volatility-actually-is\">اصل میں اتار چڑھاؤ کا تقاضا کیا ہے۔</h2>\n<p><strong>مضمر اتار چڑھاؤ</strong>، عام طور پر مختصر کیا جاتا ہے۔ <strong>IV</strong>، مارکیٹ کی یہ توقع ہے کہ RELIANCE اب اور ایکسپائری کے درمیان کتنا آگے بڑھے گا، فیصد کے طور پر ظاہر کیا جاتا ہے اور سیدھے آپشن کے پریمیم میں پکایا جاتا ہے۔</p>\n<p>یہ سارا خیال ہے۔ جب تاجروں کو آنے والے ہفتوں میں RELIANCE کے وحشیانہ انداز میں گھومنے کی توقع ہوتی ہے، تو وہ اختیارات کے لیے مزید ادائیگی کرنے کے لیے تیار ہوتے ہیں، کیونکہ زیادہ متوقع جھول کا مطلب یہ ہے کہ آپشن کے پیسے کے اندر اندر مکمل ہونے کا ایک بہتر موقع ہے۔ جب تاجر توقع کرتے ہیں کہ RELIANCE خاموشی سے آگے بڑھے گا، تو وہ کم ادائیگی کرتے ہیں، کیونکہ ایک چھوٹی متوقع حرکت کا مطلب ہے کہ آپشنز کی ادائیگی کے امکانات کم ہوتے ہیں۔ پریمیم، دوسرے لفظوں میں، ہنگامہ خیزی کی پیشن گوئی پر مشتمل ہے، اور IV وہ پیشن گوئی ہے جو قیمت سے پیچھے ہٹ گئی ہے۔</p>\n<p>کچھ چیزیںIVکو غلط پڑھنا آسان بناتی ہیں، تو آئیے بالکل درست رہیں۔</p>\n<ul>\n<li>IV ہے۔ <strong>آگے دیکھ رہے ہیں</strong>. یہ اس بات کا پیمانہ نہیں ہے کہ ماضی میں کتنا RELIANCE منتقل ہوا ہے۔ یہ مستقبل کے بارے میں مارکیٹ کا اندازہ ہے، جو غلط ہو سکتا ہے۔</li>\n<li>IV ہے۔ <strong>مضمر</strong>، یعنی یہ اس قیمت سے ریورس انجنیئرڈ ہے جو لوگ اصل میں ادا کر رہے ہیں، اسٹاک کو براہ راست نہیں پڑھتے ہیں۔ اگر وقت اور ہڑتال کی نسبت پریمیم زیادہ ہے، تو تعریف کے لحاظ سے، IV زیادہ ہے۔</li>\n<li>IV کو سالانہ فیصد کے طور پر نقل کیا گیا ہے۔ ہمارے RELIANCE اینکر میں تقریباً IV ہوتا ہے۔ <strong>20 فیصد</strong>، کافی پرسکون پڑھنا۔ ایک ہی اسٹاک پر خوفزدہ مارکیٹ IV کو کہیں زیادہ دھکیل سکتی ہے۔</li>\n</ul>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>مضمر اتار چڑھاؤ مارکیٹ کی اس بات کی توقع ہے کہ پریمیم میں پکا ہوا کتنا RELIANCE منتقل ہوگا۔ اعلی IV کا مطلب ہے کہ مارکیٹ کو ایک بڑے اقدام کی توقع ہے اور اختیارات مہنگے ہیں۔ کم IV کا مطلب ہے کہ مارکیٹ کو پرسکون ہونے کی توقع ہے اور اختیارات سستے ہیں۔ یہ ہنگامہ خیزی کی پیشین گوئی ہے، ماضی کا اندازہ نہیں۔</p>\n</div></div>\n<h2 id=\"high-iv-makes-options-expensive-low-iv-makes-them-cheap\">اعلی IV اختیارات کو مہنگا بناتا ہے، کم IV انہیں سستا بناتا ہے۔</h2>\n<p>IV کا عملی نتیجہ اس باب میں سب سے اہم چیز ہے، لہذا آئیے اسے RELIANCE 1320 آپشن پر ٹھوس بنائیں۔ اسٹاک کو 1318 پر برقرار رکھیں، 28 جولائی کو ایکسپائری ہولڈ کریں، اور مارکیٹ میں صرف خوف کی سطح کو تبدیل کریں۔</p>\n<table>\n<thead>\n<tr>\n<th>بازار کا مزاج</th>\n<th>مضمر اتار چڑھاؤ</th>\n<th>1320 کال کی قیمت تقریباً ہے۔</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>پرسکون اور پرسکون</td>\n<td>تقریباً 15 فیصد</td>\n<td>ہمارے اینکر پریمیم سے کم</td>\n</tr>\n<tr>\n<td>ہمارا اینکر کیس</td>\n<td>تقریباً 20 فیصد</td>\n<td>تقریباً 31 روپے فی شیئر، 15,590 روپے بہت زیادہ</td>\n</tr>\n<tr>\n<td>خبروں سے پہلے گھبراہٹ</td>\n<td>تقریباً 35 فیصد</td>\n<td>لنگر پریمیم کے اوپر</td>\n</tr>\n<tr>\n<td>خوفناک، واقعہ پیش آرہا ہے۔</td>\n<td>50 فیصد یا اس سے زیادہ</td>\n<td>اینکر پریمیم سے بہت اوپر</td>\n</tr>\n</tbody></table>\n<p>اس ٹیبل کو پڑھیں اور دیکھیں کہ کیا ہو رہا ہے۔ اسٹاک منتقل نہیں ہوا ہے۔ ہڑتال میں کوئی تبدیلی نہیں آئی۔ ایکسپائری ایک ہی ہے۔ صرف ایک چیز جو بدلی ہے وہ ہے مارکیٹ کی نقل و حرکت کی توقع، اور اس کے ساتھ پریمیم پھولا یا سکڑ گیا۔ وہی آپشن جس کی قیمت ایک پر سکون مارکیٹ میں تقریباً 31 روپے فی حصص ہوتی ہے، اس کی قیمت دو یا تین گنا ہو سکتی ہے جو کہ کسی اعصابی واقعے سے پہلے، خالصتاً خوف کی وجہ سے۔</p>\n<p>یہی وجہ ہے کہ دو تاجر ایک ہی RELIANCE کال خرید سکتے ہیں اور ان کے نتائج بالکل مختلف ہیں۔ جس نے IV کم ہونے پر خریدا اس کی امید سستے میں مل گئی۔ وہ جس نے خریدا جب IV اسی امید کے لیے زیادہ ادائیگی کی گئی تھی، اور اب اسے توڑنے کے لیے اس سے بھی بڑے اقدام کی ضرورت ہے، کیونکہ بہت زیادہ پریمیم خوف تھا جو بخارات بن سکتا ہے۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>کوئی بھی آپشن خریدنے سے پہلے پوچھیں کہ آیا اس وقت مضمر اتار چڑھاؤ زیادہ ہے یا کم۔ IV زیادہ ہونے پر خریدنے کا مطلب ہے کہ آپ خوف کا پریمیم ادا کر رہے ہیں جو خود ہی ختم ہو سکتا ہے۔ سب سے سستی امید اس وقت خریدی جاتی ہے جب بازار پرسکون ہو، اس وقت نہیں جب سب پہلے ہی خوفزدہ ہوں۔</p>\n</div></div>\n<h2 id=\"iv-crush-the-trap-that-catches-beginners\">IV کچلنے والا: وہ جال جو ابتدائی لوگوں کو پکڑتا ہے۔</h2>\n<p>سب سے تکلیف دہ سبق IV سکھاتا ہے ایک نام ہے: <strong>IV کو کچلنا</strong>. یہ کسی معروف ایونٹ سے عین قبل ایک مہنگا آپشن خریدنے کا تجربہ ہے، سمت کے بارے میں درست ہونا، اور پھر بھی پیسہ کھونا کیونکہ ایونٹ گزرنے کے بعد پریمیم ختم ہو جاتا ہے۔</p>\n<p>یہاں یہ ہے کہ یہ کیسے کھلتا ہے۔ RELIANCE میں ایک اہم اعلان آنے والا ہے، شاید سہ ماہی نتائج۔ تاریخ سب کو معلوم ہے۔ اس سے پہلے کے دنوں میں، تاجر کسی بڑے اقدام کی توقع کرتے ہوئے آپشنز کا ڈھیر لگاتے ہیں، اور یہ مطالبہ تیزی سے اتار چڑھاؤ کو تیز کرتا ہے۔ 1320 کال جس کی قیمت پرسکون حالات میں تقریباً 31 روپے فی شیئر ہوگی اب اس سے کہیں زیادہ لاگت آسکتی ہے، کیونکہ یہ خوف کے پریمیم سے بھری ہوئی ہے۔ ایک ابتدائی جوش و خروش دیکھتا ہے، اسٹاک کے بڑھنے کی توقع رکھتا ہے، اور فلائی کال خریدتا ہے۔</p>\n<p>پھر اعلان سامنے آتا ہے۔ غیر یقینی صورتحال ختم ہو گئی ہے، واقعہ اب معلوم ہو چکا ہے، اور مضمر اتار چڑھاؤ تقریباً فوری طور پر معمول پر آ جاتا ہے۔ یہ تباہی کچلنا ہے۔ چونکہ بہت زیادہ پریمیم خوف تھا، اس وقت جب خوف ختم ہو جاتا ہے تو پریمیم سخت گر جاتا ہے۔ اور یہاں ظالمانہ حصہ ہے. RELIANCE اصل میں اچھے نتائج پر بڑھ سکتا ہے، بالکل اسی طرح جیسے کہ ابتدائی نے امید کی تھی، اور کال اب بھی پیسے کھو سکتی ہے، کیونکہ اسٹاک کے اقدام سے حاصل ہونے والا فائدہ غائب ہونے والے IV سے ہونے والے نقصان سے کم تھا۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-basics/images/diagram-implied-volatility.png\" alt=\"پرسکون مارکیٹ میں سستے آپشنز بمقابلہ خوف زدہ میں مہنگے آپشنز، جس میں IV کو کچلنے والے پریمیم کے طور پر دکھایا گیا ہے جیسے ہی کوئی معروف واقعہ گزر جاتا ہے اور خوف ختم ہوجاتا ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>پرسکون مارکیٹ میں سستے آپشنز بمقابلہ خوف زدہ میں مہنگے آپشنز، جس میں IV کو کچلنے کے ساتھ دکھایا گیا ہے جس لمحے کوئی معروف واقعہ گزرتا ہے اور خوف ختم ہوجاتا ہے۔</figcaption></figure>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>کسی معروف واقعہ سے عین قبل ایک آپشن خریدنا سب سے عام ابتدائی ٹریپس میں سے ایک ہے۔ آپ فلایا ہوا، اونچا IV پریمیم ادا کرتے ہیں، ایونٹ گزر جاتا ہے، مضمر اتار چڑھاؤ ختم ہوجاتا ہے، اور پریمیم گر جاتا ہے چاہے آپ صحیح سمت میں ہوں۔ مارکیٹ نے پہلے سے ہی متوقع اقدام کی قیمت مقرر کر دی ہے جو آپ نے ادا کی ہے۔ جیتنے کے لیے، اصل اقدام کو ہرا دینا چاہیے جس کی قیمت متوقع ہے، نہ کہ صرف صحیح راستہ بتانا۔</p>\n</div></div>\n<p>سبق یہ نہیں ہے کہ واقعات ناقابلِ تجارت ہیں۔ یہ ہے کہ مارکیٹ بولی نہیں ہے. جب ہر کوئی کسی بڑے اقدام کی توقع کرتا ہے، تو وہ توقع پہلے سے ہی قیمت میں ہوتی ہے، اور آپ اس کی قیمت ادا کر رہے ہوتے ہیں۔ آپشن صرف آپ کو انعام دیتا ہے اگر حقیقی اقدام اس سے بڑا ہو جس کے لیے بھیڑ نے پہلے سے ادائیگی کی تھی۔ زیادہ تر وقت ایسا نہیں ہوتا۔</p>\n<h2 id=\"reading-iv-practically\">IV کو عملی طور پر پڑھنا</h2>\n<p>آپ کو اسے استعمال کرنے کے لیے اتار چڑھاؤ کو ماڈل کرنے کی ضرورت نہیں ہے۔ آپ کو دماغ کی چند عادات کی ضرورت ہے جو آپ کو زیادہ ادائیگی سے روکتی ہیں۔</p>\n<ul>\n<li><strong>چیک کریں کہ آیا اس اسٹاک کے لیے IV زیادہ ہے یا کم۔</strong> OpenAlgo ہر RELIANCE ہڑتال کے لیے مضمر اتار چڑھاؤ کی اطلاع دیتا ہے۔ اسٹاک کی معمول کی حد سے اوپر پڑھنا ایک انتباہ ہے کہ اختیارات مہنگے ہیں اور خوف کا پریمیم موجود ہے۔</li>\n<li><strong>معلوم واقعات سے پہلے خریداری میں محتاط رہیں۔</strong> نتائج، پالیسی فیصلے اور بڑے اعلانات IV کو پہلے سے پمپ کرتے ہیں اور بعد میں اسے کچل دیتے ہیں۔ اگر آپ کو کسی ایونٹ کے ذریعے ایک نظریہ لینا چاہیے تو جان لیں کہ آپ مہنگائی کی قیمت ادا کر رہے ہیں اور آپ کو کچلنے والا ہے۔</li>\n<li><strong>یاد رکھیں کہ کم IV دونوں طریقوں کو کاٹتا ہے۔</strong> سستے آپشنز دلکش ہیں، لیکن کم IV کا مطلب یہ بھی ہے کہ مارکیٹ کو ہلکی حرکت کی توقع ہے، اس لیے جس اقدام پر آپ شرط لگا رہے ہیں وہ شاید نہ پہنچے۔ سستا امکان کے طور پر ایک ہی نہیں ہے.</li>\n<li><strong>بیچنے والے اس کے برعکس سوچتے ہیں۔</strong> ایک بیچنے والا پریمیم جمع کرنا چاہتا ہے جب IV زیادہ اور امیر ہو، پھر اس کے واپس آنے پر منافع حاصل کریں۔ یہ خریدار کے جال کا آئینہ ہے، اور یہ اس بات کا حصہ ہے کہ کیوں تجربہ کار تاجروں کو اپیلیں بیچی جاتی ہیں، حالانکہ اس میں وہ بڑا خطرہ ہوتا ہے جس کا ہم پہلے ہی سامنا کر چکے ہیں۔</li>\n</ul>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>اعلی IV خود بخود فروخت کرنے کی وجہ نہیں ہے، اور کم IV خود بخود خریدنے کی وجہ نہیں ہے۔ IV آپ کو بتاتا ہے کہ امید کتنی مہنگی ہے، یہ نہیں کہ اسٹاک کس طرف جائے گا۔ ایک تاجر کو اب بھی سمت کے بارے میں درست ہونا ضروری ہے۔ IV صرف یہ فیصلہ کرتا ہے کہ آیا اس شرط کا ٹکٹ سستا ہے یا عزیز۔</p>\n</div></div>\n<p>اس سے ان سب کے برتاؤ کو دیکھنے میں مدد ملتی ہے۔ <strong>سینڈ باکس ٹریڈنگ (Analyzer mode in OpenAlgo)</strong>. RELIANCE 1320 کال کو کھینچیں، پرسکون دن پر اس کی مضمر اتار چڑھاؤ اور پریمیم کو نوٹ کریں، پھر دیکھیں کہ ایک مصروف واقعہ کے قریب آنے اور گزرنے پر دونوں کیسا رد عمل ظاہر ہوتا ہے۔ اس کے بعد سٹاک بمشکل آگے بڑھنے کے ساتھ، خوف اور کچلنے پر پریمیم کو پھولتا دیکھنا، کسی بھی وارننگ سے کہیں زیادہ گہرائی سے سبق سکھاتا ہے۔</p>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">کیا آپ جانتے ہیں؟</span><div><p>آپ جو پریمیم پہلے ہی ادا کرتے ہیں اس میں مستقبل کی نقل و حرکت کے بارے میں مارکیٹ کا بہترین اندازہ ہوتا ہے۔ آپ کبھی بھی یہ شرط نہیں لگا رہے ہیں کہ RELIANCE اٹھے گا یا گرے گا۔ آپ شرط لگا رہے ہیں کہ یہ اس رقم سے زیادہ بڑھے گا یا گرے گا جس کی قیمت مارکیٹ نے پہلے ہی مضمر اتار چڑھاؤ میں رکھی ہے۔ یہ اصلی بار ہے جو ہر آپشن خریدار کو صاف کرنا پڑتا ہے۔</p>\n</div></div>\n<p>مضمر اتار چڑھاؤ آخری بڑا تصور ہے کہ اختیارات کی قیمت کیسے لگائی جاتی ہے، اور یہ پوری تصویر کو ایک دوسرے سے جوڑ دیتی ہے۔ ہڑتال اور ایکسپائری فریم کو سیٹ کرتی ہے، اندرونی قدر اور وقت کی قدر پریمیم کو تقسیم کرتی ہے، یونانی پیمائش کرتے ہیں کہ یہ کیسے رد عمل ظاہر کرتا ہے، اور IV فیصلہ کرتا ہے کہ اس ردعمل کی قیمت کتنی بھرپور ہے۔ ان تمام چیزوں کو ہاتھ میں رکھتے ہوئے، آخری باب تھیوری سے مشکل پریکٹیکل میکینکس کی طرف موڑتا ہے: لاٹ سائز اور تجارت کی حقیقی قیمت، ہندوستانی آپشنز کی میعاد ختم ہونے پر کیسے طے ہوتی ہے، اور حقیقی رقم کا خطرہ مول لینے سے پہلے آپ کو ایماندارانہ خطرات کا احترام کرنا چاہیے۔</p>\n","toc":[{"level":2,"text":"اصل میں اتار چڑھاؤ کا تقاضا کیا ہے۔","id":"what-implied-volatility-actually-is"},{"level":2,"text":"اعلی IV اختیارات کو مہنگا بناتا ہے، کم IV انہیں سستا بناتا ہے۔","id":"high-iv-makes-options-expensive-low-iv-makes-them-cheap"},{"level":2,"text":"IV کچلنے والا: وہ جال جو ابتدائی لوگوں کو پکڑتا ہے۔","id":"iv-crush-the-trap-that-catches-beginners"},{"level":2,"text":"IV کو عملی طور پر پڑھنا","id":"reading-iv-practically"}],"imgCount":1,"hasContent":true},"20":{"html":"<p>ایک واحد نمبر تقریبا ہر آپشن کے ساتھ بیٹھتا ہے جسے آپ دیکھتے ہیں، عام طور پر فیصد کے طور پر حوالہ دیا جاتا ہے۔ یہ مضمر اتار چڑھاؤ ہے، جسے اکثر مختصر کر کے IV کر دیا جاتا ہے، اور ابتدائی افراد اس پر نظر ڈالتے ہیں، فیصلہ کرتے ہیں کہ بڑی تعداد کا مطلب ایک بڑی حرکت کا بہتر موقع ہے، اور آگے بڑھیں۔ یہ جبلت غلط ہے، اور اس پر لوگوں کو پیسے خرچ ہوتے ہیں۔ اپنے طور پر، ایک IV نمبر آپ کو تقریباً کچھ نہیں بتاتا ہے۔ یہ صرف اس وقت کارآمد ہوتا ہے جب آپ اس کا موازنہ دو چیزوں سے کریں: اسٹاک اصل میں کیا کر رہا ہے، اور اسی آپشن کی عام طور پر قیمت کیا ہوتی ہے۔ یہ باب آپ کو دونوں موازنہ کرنا سکھاتا ہے، اور پھر IV کو حقیقی طور پر عملی چیز میں بدل دیتا ہے، متوقع اقدام، جو کہ مارکیٹ کا اپنا اندازہ ہے کہ قیمت ختم ہونے سے پہلے کتنی دور ہوگی۔</p>\n<h2 id=\"two-kinds-of-volatility\">اتار چڑھاؤ کی دو قسمیں۔</h2>\n<p>جاننے کے قابل دو اتار چڑھاؤ کے نمبر ہیں، اور وہ دو مختلف سوالات کے جوابات دیتے ہیں۔</p>\n<ul>\n<li><strong>تاریخی اتار چڑھاؤ</strong>، جسے کبھی کبھی محسوس شدہ اتار چڑھاؤ کہا جاتا ہے، اس بات کا اندازہ لگاتا ہے کہ پچھلے بیس یا تیس تجارتی دنوں کا کہنا ہے کہ کچھ پچھلی کھڑکی پر اصل میں کتنا آگے بڑھا ہے۔ یہ ماضی کے بارے میں ایک حقیقت ہے۔ یہ پیچھے کی طرف دیکھتا ہے اور کہتا ہے، اسٹاک واقعی اس قدر اچھل رہا ہے۔</li>\n<li><strong>مضمر اتار چڑھاؤ</strong> ابھی آپشن پریمیم میں پکا ہوا ہے۔ یہ مارکیٹ کی توقع ہے کہ آج اور ایکسپائری کے درمیان انڈرلائننگ کتنا آگے بڑھے گا۔ یہ آگے لگ رہا ہے. جب آپشن کے خریدار گھبراتے ہیں اور بولی کے پریمیم بڑھ جاتے ہیں، IV بڑھ جاتا ہے۔ جب مارکیٹ پرسکون ہوتی ہے اور پریمیم سستے ہوتے ہیں، IV گر جاتا ہے۔</li>\n</ul>\n<p>دونوں کا تعلق ہے لیکن وہ ایک جیسے نہیں ہیں، اور ان کے درمیان فاصلہ وہ جگہ ہے جہاں بہت ساری کہانی رہتی ہے۔ اگر RELIANCE خاموشی سے بہہ رہا ہے اور اس کا تاریخی اتار چڑھاؤ کم ہے، لیکن اس کی مضمر اتار چڑھاؤ زیادہ ہے، تو مارکیٹ اس اقدام کے لیے ادائیگی کر رہی ہے جس کی اسے توقع ہے لیکن ابھی تک نہیں دیکھا گیا ہے۔ شاید نتائج آنے والے ہیں۔ اگر مضمر اتار چڑھاؤ نیچے بیٹھا ہے جو اسٹاک اصل میں فراہم کر رہا ہے، اختیارات حالیہ حقیقت کے نسبت سستے نظر آتے ہیں۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>تاریخی اتار چڑھاؤ وہی ہے جو اسٹاک نے کیا۔ مضمر اتار چڑھاؤ وہ ہے جس کی مارکیٹ اس سے توقع کرتی ہے، جس کی قیمت آج پریمیم میں ہے۔ کوئی پیچھے دیکھتا ہے، کوئی آگے دیکھتا ہے، اور ان میں فرق معلومات کا ہے۔</p>\n</div></div>\n<p>ہماری چل رہی مثال میں IV تقریباً 20 فیصد ہے۔ اکیلے اس نمبر کا کوئی مطلب نہیں جب تک کہ آپ دو سوال نہ پوچھیں۔ کیا خاص طور پر RELIANCE کے لیے 20 فیصد زیادہ یا کم ہے؟ اور یہ اس سے کس طرح موازنہ کرتا ہے کہ حال ہی میں RELIANCE اصل میں کتنا آگے بڑھ رہا ہے؟ 20 فیصد IV ایک اسٹاک کے لیے پرسکون اور دوسرے کے لیے طوفانی ہے۔ اتار چڑھاؤ ہمیشہ اس بنیادی چیز سے متعلق ہوتا ہے جس سے یہ تعلق رکھتا ہے۔</p>\n<h2 id=\"is-today-s-iv-high-or-low-iv-rank-and-iv-percentile\">کیا آج کا IV زیادہ ہے یا کم؟ IV درجہ اور IV پرسنٹائل</h2>\n<p>چونکہ ایک خام IV نمبر سیاق و سباق کے بغیر بے معنی ہے، تاجر اسے اس کے اپنے ماضی کے خلاف درجہ دیتے ہیں۔ دو آسان اقدامات ایسا کرتے ہیں۔</p>\n<ul>\n<li><strong>IV درجہ</strong> پوچھتا ہے کہ آج کا IV پچھلے سال کے دوران اپنی سب سے کم اور سب سے زیادہ پڑھنے کے درمیان کہاں بیٹھا ہے۔ اگر RELIANCE IV پچھلے بارہ مہینوں میں 14 فیصد کی کم سے کم سے لے کر 34 فیصد کی بلندی تک ہے، اور آج یہ 20 فیصد ہے، تو آج 20 پوائنٹ کی حد میں سے کم سے 6 پوائنٹ اوپر بیٹھا ہے، جو کہ تقریباً 30 فیصد کا درجہ ہے۔ آج کا IV اپنی سالانہ رینج کے نچلے نصف حصے پر ہے۔</li>\n<li><strong>IV پرسنٹائل</strong> پوچھتا ہے، پچھلے سال کتنے دنوں میں IV آج کے مقابلے میں کم تھا؟ اگر IV 40 فیصد دنوں میں آج کی سطح سے نیچے رہا ہے، تو IV پرسنٹائل 40 ہے۔ یہ قدرے زیادہ ایماندارانہ پیمانہ ہے کیونکہ یہ اس بات کا حساب کرتا ہے کہ IV کو کس طرح تقسیم کیا گیا تھا، نہ کہ صرف انتہا۔</li>\n</ul>\n<p>آپ کو ہاتھ سے ان کی گنتی کرنے کی ضرورت نہیں ہے۔ بات عادت کی ہے۔ اس سے پہلے کہ آپ فیصلہ کریں کہ کوئی آپشن مہنگا ہے یا سستا، آپ چیک کریں کہ آیا اس کا موجودہ IV اس مخصوص بنیادی کے لیے زیادہ ہے یا کم۔ 20 فیصد IV جو RELIANCE کی اپنی رینج کے اوپری حصے کے قریب ہے نیچے کے قریب 20 فیصد IV سے بہت مختلف سیٹ اپ ہے، حالانکہ اسکرین پر نمبر ایک جیسا ہے۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>تنہائی میں کبھی بھی کسی آپشن کے IV کا فیصلہ نہ کریں۔ پوچھیں کہ یہ اپنی سالانہ رینج میں کہاں بیٹھتا ہے۔ اعلی IV رینک کا مطلب ہے کہ اس بنیادی کے لیے پریمیم معمول سے زیادہ امیر ہیں۔ کم IV رینک کا مطلب ہے کہ وہ معمول سے سستے ہیں۔ ایک ہی فیصد ایک اسٹاک پر مہنگا اور دوسرے پر سستا ہوسکتا ہے۔</p>\n</div></div>\n<h2 id=\"expensive-does-not-mean-bad-cheap-does-not-mean-good\">مہنگے کا مطلب برا نہیں ہوتا، سستے کا مطلب اچھا نہیں ہوتا</h2>\n<p>یہاں جال ہے. ابتدائی لوگ سیکھتے ہیں کہ اعلی IV اختیارات کو مہنگا بنا دیتا ہے، اور وہ یہ نتیجہ اخذ کرتے ہیں کہ انھیں کبھی بھی اعلی IV آپشن نہیں خریدنا چاہیے اور ہمیشہ سستے کو ترجیح دینی چاہیے۔ اس کے دونوں حصے غلط ہیں۔</p>\n<p>اعلی IV آپشن مہنگا ہے کیونکہ مارکیٹ کو ایک بڑے اقدام کی توقع ہے۔ اگر یہ اقدام قیمت سے بھی بڑا نکلا، تو مہنگا آپشن خوبصورتی سے ادا کرتا ہے۔ آپ سے بہت زیادہ معاوضہ لیا گیا، اور آپ کو بہت کچھ ملا۔ اعلی IV خریدنا خود بخود غلطی نہیں ہے۔ یہ صرف ایک غلطی ہے اگر اس اقدام سے آپ کی ادائیگی کی نسبت مایوسی ہوتی ہے۔</p>\n<p>کم IV آپشن سستا ہے کیونکہ مارکیٹ کو پرسکون ہونے کی توقع ہے۔ لیکن سستا جیتنے کا امکان نہیں ہے۔ اگر اسٹاک خاموش بیٹھا رہتا ہے، تو وہ سستا آپشن پھر بھی اس کی ٹائم ویلیو کو صفر کر دیتا ہے اور بیکار ختم ہو جاتا ہے۔ آپ نے بہت کم ادائیگی کی، اور آپ کو کچھ نہیں ملا۔ سستے اختیارات بھی ہر روز پیسے کھو دیتے ہیں۔</p>\n<p>صحیح سوال کبھی بھی سادہ نہیں ہوتا، کیا یہ مہنگا ہے یا سستا؟ یہ ہے، کیا اصل اقدام اس پریمیم میں پہلے سے طے شدہ اقدام سے بڑا یا چھوٹا ہوگا؟ یہ موازنہ وہی ہے جو اچھے اندراج کو برے سے الگ کرتا ہے، اور یہ براہ راست اس باب میں واحد سب سے مفید خیال کی طرف لے جاتا ہے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>سستے اختیارات زیادہ محفوظ نہیں ہیں اور مہنگے اختیارات بدتر نہیں ہیں۔ ایک سستا آپشن جو حرکت نہیں کرتا ہے وہ مکمل نقصان ہے۔ ایک مہنگا آپشن جو قیمت سے زیادہ حرکت کرتا ہے وہ فاتح ہے۔ قیمت آپ کو بتاتی ہے کہ مارکیٹ کیا توقع رکھتی ہے، یہ نہیں کہ کیا ہوگا۔</p>\n</div></div>\n<h2 id=\"the-expected-move-the-range-the-market-is-pricing\">متوقع اقدام: مارکیٹ کی قیمتوں کی حد</h2>\n<p>ہر آپشن پریمیم میں پوشیدہ پیشن گوئی ہوتی ہے۔ ایک ہی سٹرائیک اور ایکسپائری پر ایک ایٹ دی منی کال اور ایٹ دی منی کے لیے جو مارکیٹ چارج کرتی ہے اس میں اضافہ کریں، اور آپ کو اس بات کا فوری، حیرت انگیز طور پر اچھا تخمینہ مل جائے گا کہ مارکیٹ کے خیال میں اس ایکسپائری سے کس حد تک سفر کرے گا۔ وہ مشترکہ پریمیم ہے۔ <strong>پیسے کی طرف بڑھنا</strong>، اور یہ سب سے آسان پڑھا جاتا ہے۔ <strong>متوقع اقدام</strong>.</p>\n<p>آئیے حقیقی NIFTY نمبر استعمال کریں۔ NIFTY اسپاٹ تقریباً 24,056 ہے، اور 28 جولائی کی ماہانہ میعاد ختم ہونے کے لیے قریب ترین ہڑتال 24,050 ہے۔ ایٹ دی منی کال تقریباً 426 روپے فی حصص کی تجارت کرتی ہے اور ایٹ دی منی کی قیمت تقریباً 295 روپے فی شیئر ہے۔ ان کو ایک ساتھ شامل کریں، 426 روپے اور 295 روپے، اور آپ کو تقریباً 720 روپے ملتے ہیں۔ یہ 720 روپے پیسے کی کمائی کا پریمیم ہے، اور یہ متوقع اقدام کا مارکیٹ کا اپنا تخمینہ ہے۔ واضح الفاظ میں، مارکیٹ 28 جولائی تک دونوں سمتوں میں تقریباً 720 پوائنٹس کا سفر کرنے کے لیے NIFTY کی قیمت لگا رہی ہے۔ متوقع رینج تقریباً 24,056 پلس یا مائنس 720 ہے، جو نیچے کی طرف تقریباً 23,336 سے اوپر کی طرف تقریباً 24,776 تک چلتی ہے۔</p>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">کیا آپ جانتے ہیں؟</span><div><p>28 جولائی کے لیے NIFTY ایٹ-دی-منی اسٹیڈل تقریباً 720 روپے ہے، کال 426 روپے کے قریب پلس پوٹ 295 روپے کے قریب ہے۔ یہ 720 روپے مارکیٹ کی متوقع حرکت ہے: ختم ہونے پر تقریباً پلس یا مائنس 720 پوائنٹس، جس کی حد تقریباً 23,76636 سے ہے۔</p>\n</div></div>\n<p>یہ کوئی ضمانت نہیں ہے اور یہ سمت کی پیشن گوئی نہیں ہے۔ یہ ایک معیاری انحراف طرز کا تخمینہ ہے، یعنی مارکیٹ تقریباً تین میں سے دو بار اس بینڈ کے اندر اترنے کی توقع رکھتی ہے، اور دوسرے تیسرے وقت سے باہر۔ متوقع اقدام دونوں سمتوں میں غلط ہو سکتا ہے: اصل اقدام بہت بڑا یا بہت چھوٹا ہو سکتا ہے۔ لیکن یہ آپ کو اپنی تجارت کے خلاف پیمائش کرنے کے لیے ایک منصفانہ، مارکیٹ سے منسلک یارڈ اسٹک فراہم کرتا ہے، اور اسے سیدھے سٹرڈل سے پڑھنے کے لیے آپ کو کچھ خرچ نہیں کرنا پڑتا۔</p>\n<p>نیچے دی گئی جدول تعلقات کو ٹھوس بناتی ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>پڑھنا</th>\n<th>NIFTY مثال (28 جولائی)</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>سپاٹ</td>\n<td>تقریباً 24,056</td>\n</tr>\n<tr>\n<td>پر پیسے کی ہڑتال</td>\n<td>24,050</td>\n</tr>\n<tr>\n<td>ایٹ دی منی کال پریمیم</td>\n<td>تقریباً 426 روپے فی شیئر</td>\n</tr>\n<tr>\n<td>ایٹ دی منی پریمیم ڈالیں۔</td>\n<td>تقریباً 295 روپے فی شیئر</td>\n</tr>\n<tr>\n<td>پیسے کی کمائی (متوقع حرکت)</td>\n<td>تقریباً 720 روپے فی شیئر</td>\n</tr>\n<tr>\n<td>میعاد ختم ہونے کے لحاظ سے متوقع حد</td>\n<td>تقریباً 23,336 سے 24,776 تک</td>\n</tr>\n</tbody></table>\n<h2 id=\"why-a-correct-call-can-still-lose\">کیوں ایک صحیح کال اب بھی کھو سکتی ہے۔</h2>\n<p>اب متوقع اقدام ایک سبق کے طور پر ادا کرتا ہے۔ فرض کریں کہ آپ کو یقین ہے کہ NIFTY بڑھے گا، تو آپ کال خریدتے ہیں۔ NIFTY ختم ہونے پر، 300 پوائنٹس کا اضافہ ہوتا ہے۔ آپ صحیح سمت میں تھے۔ پھر بھی آپ پیسے کھو سکتے ہیں، اور متوقع اقدام واضح طور پر اس کی وجہ بتاتا ہے۔</p>\n<p>مارکیٹ نے پہلے ہی تقریباً 720 پوائنٹس کی ایک حرکت میں قیمت لگا دی تھی۔ آپ نے جو پریمیم ادا کیا ہے تقریباً اتنا سفر فرض کیا ہے۔ 300 پوائنٹ کا اضافہ حقیقی ہے، لیکن یہ اس سے بھی کم ہے جو آپ کے پریمیم میں پہلے سے پکا ہوا تھا۔ بڑے متوقع اقدام کے لیے آپ نے جو وقت کی قیمت ادا کی تھی وہ ختم ہو جاتی ہے، اور معمولی حقیقی اقدام اسے واپس نہیں کرتا ہے۔ آپ نے صحیح کہا، اور آپ پھر بھی ہار گئے، کیونکہ یہ اقدام اس اقدام سے چھوٹا تھا جس کی آپ نے ادائیگی کی تھی۔</p>\n<p>یہ انتباہ کا گہرا مطلب ہے جو اس پورے کورس میں چلتا ہے: سمت پر درست ہونا کافی نہیں ہے۔ آپ کو پہلے سے طے شدہ قیمت کے مطابق درست ہونا پڑے گا۔ متوقع اقدام بار ہے۔ اگر آپ پریمیم خریدتے ہیں، تو بنیادی کو اس بار کو صاف کرنا ہوگا، نہ کہ صرف آپ کے حق میں جانا ہے۔ اگر آپ پریمیم فروخت کرتے ہیں، تو آپ شرط لگا رہے ہیں کہ متوقع اقدام کے اندر اندر اندر قیام کیا جائے، اور وہی 720 روپے وہ کشن بن جائے گا جسے آپ رکھنے کی کوشش کر رہے ہیں۔</p>\n\n<div class=\"callout example\"><span class=\"callout-tag\">حقیقی مثال</span><div><p>آپ ریلی کی توقع کرتے ہوئے NIFTY کال خریدتے ہیں۔ NIFTY 28 جولائی تک 300 پوائنٹس پر چڑھ گیا۔ آپ کی سمت درست تھی، لیکن مارکیٹ نے آپ کے پریمیم میں تقریباً 720 پوائنٹ کی قیمت رکھی تھی۔ اصل 300 پوائنٹ کی حرکت اس سے کم ہے جس کی آپ نے ادائیگی کی ہے، لہذا آپشن اب بھی نقصان کے طور پر ختم ہو سکتا ہے۔ صحیح سمت، غلط سائز، پیسہ چلا گیا.</p>\n</div></div>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-basics/images/diagram-expected-move.png\" alt=\"NIFTY تقریباً 720 روپے کا اسپاٹ 24,056 کے آس پاس ایک متوقع موو بینڈ کے طور پر تیار کیا گیا، جس میں بینڈ کے اندر ایک چھوٹی اصل حرکت اتری اور پھر بھی کال خریدار کو نقصان میں چھوڑ دیا۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>NIFTY تقریباً 720 روپے کا اسپاٹ 24,056 کے آس پاس ایک متوقع موو بینڈ کے طور پر تیار کیا گیا ہے، جس میں بینڈ کے اندر ایک چھوٹی اصل حرکت اترتی ہے اور پھر بھی کال خریدار کو نقصان میں چھوڑتی ہے۔</figcaption></figure>\n<p>لہذا اتار چڑھاؤ ایک واحد نمبر نہیں ہے جس پر نظر ڈالی جائے۔ یہ ایک موازنہ ہے۔ تاریخی اتار چڑھاؤ کے خلاف مضمر اتار چڑھاؤ کو برقرار رکھیں یہ دیکھنے کے لیے کہ آیا مارکیٹ اسٹاک سے زیادہ یا کم کی ادائیگی کر رہی ہے۔ آج کے IV کو اس کی اپنی سالانہ رینج کے مقابلے میں، IV رینک یا پرسنٹائل کے ذریعے، یہ دیکھنے کے لیے کہ آیا اس مخصوص بنیادی کے لیے پریمیم امیر ہیں یا سستے ہیں۔ اور پیسے کی کمائی کو متوقع اقدام میں تبدیل کریں تاکہ آپ کے پاس ٹھوس یارڈ اسٹک ہو۔ ایک بار جب آپ اپنی تجارت کو اس اقدام کے خلاف ناپ لیتے ہیں جس کی قیمت پہلے سے طے شدہ ہے، تو سمت پر صحیح ہونے اور پھر بھی پیسہ کھونے کی پہیلی آخر کار سمجھ میں آتی ہے۔</p>\n","toc":[{"level":2,"text":"اتار چڑھاؤ کی دو قسمیں۔","id":"two-kinds-of-volatility"},{"level":2,"text":"کیا آج کا IV زیادہ ہے یا کم؟ IV درجہ اور IV پرسنٹائل","id":"is-today-s-iv-high-or-low-iv-rank-and-iv-percentile"},{"level":2,"text":"مہنگے کا مطلب برا نہیں ہوتا، سستے کا مطلب اچھا نہیں ہوتا","id":"expensive-does-not-mean-bad-cheap-does-not-mean-good"},{"level":2,"text":"متوقع اقدام: مارکیٹ کی قیمتوں کی حد","id":"the-expected-move-the-range-the-market-is-pricing"},{"level":2,"text":"کیوں ایک صحیح کال اب بھی کھو سکتی ہے۔","id":"why-a-correct-call-can-still-lose"}],"imgCount":1,"hasContent":true},"21":{"html":"<p>آپشن چین کو کسی بھی فعال انڈرلائننگ پر کھولیں اور آپ کو نمبروں کے دو کالم نظر آئیں گے جو کہ ابتدائی افراد مسلسل الجھتے رہتے ہیں: حجم اور کھلی دلچسپی۔ لوگ ان کے ساتھ ایک ہی چیز کے طور پر سلوک کرتے ہیں، یا اس سے بھی بدتر، وہ ایک بڑی کھلی دلچسپی والی شخصیت کو ایک ہجوم کے طور پر پڑھتے ہیں جو انہیں بتاتے ہیں کہ قیمت کہاں جا رہی ہے۔ کوئی بھی عادت درست نہیں۔ اوپن انٹرسٹ اور پوٹ کال ریشو تمام آپشنز ٹریڈنگ میں سب سے زیادہ پڑھے جانے والے نمبروں میں سے ہیں۔ وہ حقیقی طور پر کارآمد ہیں، لیکن صرف اس صورت میں جب آپ یہ سمجھتے ہیں کہ وہ کس چیز کی پیمائش کرتے ہیں، جو پوزیشننگ ہے، پیشن گوئی نہیں۔ یہ باب اس بات کی وضاحت کرتا ہے کہ کھلی دلچسپی دراصل کیا ہے، اس کی تبدیلیوں کو ایمانداری سے کیسے پڑھا جائے، پوٹ کال کا تناسب آپ کو کیا بتا سکتا ہے اور کیا نہیں بتا سکتا، اور کیوں ایک ابتدائی شخص جو پیشین گوئی کی مشین کے طور پر ان نمبروں پر ٹیک لگاتا ہے اسے تکلیف پہنچتی ہے۔</p>\n<h2 id=\"open-interest-is-not-volume\">کھلی دلچسپی حجم نہیں ہے۔</h2>\n<p>اس فرق کے ساتھ شروع کریں جو سب کو اوپر لے جاتا ہے۔</p>\n<ul>\n<li><strong>حجم</strong> سیشن کے دوران اب تک ہونے والے معاہدوں کی تعداد ہے۔ یہ ہر صبح صفر پر دوبارہ سیٹ ہوتا ہے۔ ہڑتال پر 50,000 کے حجم کا مطلب ہے کہ آج 50,000 معاہدے بدل گئے ہیں۔ حجم سرگرمی کی پیمائش کرتا ہے، دن کا منڈلانا۔</li>\n<li><strong>کھلی دلچسپی</strong>، اکثر مختصر کرکے OI، معاہدوں کی تعداد ہے جو اب بھی کھلے ہیں، یعنی وہ پوزیشنیں جو کھولی گئی ہیں اور ابھی تک بند نہیں ہوئی ہیں۔ یہ روزانہ ری سیٹ نہیں ہوتا ہے۔ یہ سیشن سے سیشن تک چلتا ہے۔ کھلی دلچسپی کا اندازہ ہوتا ہے کہ ابھی اس ہڑتال پر کتنے کھلے دائو بیٹھے ہیں۔</li>\n</ul>\n<p>فرق محسوس کرنے کا آسان ترین طریقہ: اگر آپ اور دوسرا تاجر آپ کے درمیان بالکل نیا معاہدہ کھولتے ہیں، تو کھلی دلچسپی ایک ایک کرکے بڑھ جاتی ہے۔ اگر دو موجودہ ہولڈرز ایک دوسرے کے ساتھ تجارت کرتے ہیں اور ایک بند ہو رہا ہے جب کہ دوسرا کھل رہا ہے، کھلی دلچسپی تبدیل نہیں ہوتی ہے، اگرچہ حجم میں اضافہ ہو۔ اگر دونوں فریق بند ہو رہے ہیں تو کھلی دلچسپی ایک سے گر جاتی ہے جبکہ حجم اب بھی تجارت کو ریکارڈ کرتا ہے۔ حجم تجارت کو شمار کرتا ہے۔ کھلی دلچسپی کھلی پوزیشنوں کو شمار کرتی ہے۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>حجم یہ ہے کہ آج کتنے معاہدوں کی تجارت ہوئی اور ہر صبح ری سیٹ ہوتے ہیں۔ کھلی دلچسپی یہ ہے کہ کتنے معاہدے اب بھی کھلے ہیں اور روز بروز جاری ہیں۔ اگر تاجر زیادہ تر نئی پوزیشنز بنانے کے بجائے موجودہ پوزیشنز کو پاس کر رہے ہوں تو ہڑتال کا حجم بہت زیادہ ہو سکتا ہے لیکن اس میں کھلی دلچسپی ہو سکتی ہے۔</p>\n</div></div>\n<p>یہ فرق اہمیت رکھتا ہے کیونکہ بڑھتی ہوئی کھلی دلچسپی آپ کو بتاتی ہے کہ تازہ رقم اس ہڑتال کا ارتکاب کر رہی ہے، جبکہ کھلی یا گرتی ہوئی کھلی دلچسپی آپ کو بتاتی ہے کہ پوزیشنیں بند ہو رہی ہیں۔ صرف حجم ہی آپ کو یہ نہیں بتا سکتا کہ آیا دن کی سرگرمی نے نئی نمائش بنائی یا پرانی نمائش کو ختم کیا۔ کھلی دلچسپی کر سکتے ہیں.</p>\n<h2 id=\"reading-oi-changes-honestly-the-2x2-matrix\">OI کو پڑھنا ایمانداری سے تبدیل ہوتا ہے: 2x2 میٹرکس</h2>\n<p>جب آپ اس کی تبدیلی کو قیمت میں تبدیلی کے ساتھ جوڑتے ہیں تو کھلی دلچسپی معلوماتی بن جاتی ہے۔ چار مجموعے ہیں، اور وہ ایک چھوٹا سا گرڈ بناتے ہیں جو یاد رکھنے کے قابل ہے۔ منطق ہمیشہ یکساں ہوتی ہے: کھلی دلچسپی میں اضافے کا مطلب ہے کہ نئی پوزیشنیں بن رہی ہیں، اور قیمت کی سمت آپ کو بتاتی ہے کہ کون سا فریق تخلیق کر رہا ہے۔</p>\n<table>\n<thead>\n<tr>\n<th></th>\n<th>کھلی دلچسپی بڑھ رہی ہے۔</th>\n<th>کھلی دلچسپی گر رہی ہے۔</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><strong>قیمت بڑھ رہی ہے۔</strong></td>\n<td>طویل تعمیر (تازہ خریداروں کا اضافہ)</td>\n<td>شارٹ کورنگ (بیچنے والے واپس خرید رہے ہیں)</td>\n</tr>\n<tr>\n<td><strong>قیمت گر رہی ہے۔</strong></td>\n<td>مختصر تعمیر (تازہ فروخت کنندگان کا اضافہ)</td>\n<td>لمبا کھولنا (خریدار بند ہو رہے ہیں)</td>\n</tr>\n</tbody></table>\n<p>ہر سیل کو سادہ الفاظ میں پڑھیں۔</p>\n<ul>\n<li><strong>کھلے سود میں اضافے کے ساتھ قیمت میں اضافہ ایک طویل تعمیر ہے۔</strong> نئے خریدار قدم رکھ رہے ہیں اور قیمت ان کے ساتھ بڑھ رہی ہے۔ تازہ تیزی سے پیسہ کمٹ کر رہا ہے۔ یہ اکثر اس کے پیچھے حقیقی شرکت کے ساتھ اوپر کی حرکت کے طور پر پڑھا جاتا ہے۔</li>\n<li><strong>کھلے سود میں اضافے کے ساتھ قیمت گرنا ایک مختصر تعمیر ہے۔</strong> نئے بیچنے والے قدم رکھ رہے ہیں اور قیمت ان کے ساتھ سلائیڈ ہو رہی ہے۔ تازہ مندی کا پیسہ کمٹ کر رہا ہے۔ نیچے کی حرکت کے پیچھے حقیقی فروخت ہے۔</li>\n<li><strong>کھلی دلچسپی میں کمی کے ساتھ قیمت میں اضافہ شارٹ کورنگ ہے۔</strong> قیمت نئے خریداروں کی وجہ سے نہیں بلکہ اس وجہ سے بڑھ رہی ہے کہ موجودہ بیچنے والے اپنی کھوئی ہوئی شارٹس کو بند کرنے کے لیے واپس خرید رہے ہیں۔ حرکت تیز ہو سکتی ہے لیکن یہ باہر نکلنے سے چلتی ہے، اور ڈھانپنے کے بعد یہ ختم ہو سکتی ہے۔</li>\n<li><strong>کھلی دلچسپی کے گرنے کے ساتھ قیمتوں میں کمی طویل عرصے سے غیر منقطع ہے۔</strong> قیمت نیچے جا رہی ہے کیونکہ موجودہ خریدار فروخت کر رہے ہیں، جارحانہ نئے شارٹس کی وجہ سے نہیں۔ پرانی خواہشیں ترک کر رہی ہیں۔</li>\n</ul>\n<p>ایماندارانہ نکتہ نظر: پہلے دو، تعمیرات، مارکیٹ میں داخل ہونے والے نئے یقین کی وضاحت کرتے ہیں۔ دوسرے دو، ڈھکنا اور کھولنا، پرانی پوزیشنوں کو چھوڑنے کی وضاحت کرتے ہیں۔ عام طور پر یہ خیال کیا جاتا ہے کہ تازہ تعمیرات کے ذریعے چلنے والی حرکت کو اس کے پیچھے لوگوں کی طرف سے چلنے والے اقدام سے کہیں زیادہ ہے۔ لیکن عام طور پر سمجھا جاتا ہے کہ اس جملے میں بہت زیادہ کام کرنا ہے، اور ہم واپس آئیں گے کہ یہ کتنا متزلزل ہوسکتا ہے۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>ہمیشہ کھلی دلچسپی کو قیمت کے ساتھ پڑھیں، کبھی اکیلے نہیں۔ بیٹھا ہوا ایک بڑا کھلا دلچسپی نمبر آپ کو بہت کم بتاتا ہے۔ یہ کھلی دلچسپی میں تبدیلی ہے، جو قیمت کی سمت کے ساتھ جوڑا جاتا ہے، جو اس بات کا اشارہ کرتا ہے کہ آیا نیا پیسہ پوزیشن بنا رہا ہے یا پرانا پیسہ چھوڑ رہا ہے۔</p>\n</div></div>\n\n<div class=\"callout example\"><span class=\"callout-tag\">حقیقی مثال</span><div><p>فرض کریں کہ NIFTY تقریباً 24,056 سے بڑھتا ہے جب کہ سیشن کے دوران قریبی کال اسٹرائیک پر کھلی دلچسپی بڑھ جاتی ہے۔ یہ جوڑا، قیمت میں اضافہ اور کھلی دلچسپی، ایک طویل تعمیر کے طور پر پڑھتا ہے: تازہ خریدار اس ہڑتال کا ارتکاب کر رہے ہیں۔ اگر اس کی بجائے NIFTY میں اضافہ ہوتا جبکہ بھاری شارٹ پوزیشنز پر کھلی دلچسپی کم ہوتی، تو وہی اوپر کی حرکت شارٹ کورنگ کے طور پر پڑھے گی، بیچنے والے نئے بیلوں کی آمد کے بجائے واپس خرید رہے ہیں۔ ایک ہی قیمت کی حرکت، نیچے بہت مختلف کہانی۔</p>\n</div></div>\n<h2 id=\"support-resistance-and-the-oi-walls\">سپورٹ، مزاحمت اور OI دیواریں۔</h2>\n<p>کھلی دلچسپی کا ایک عام استعمال محتاط، ایماندارانہ ذکر کا مستحق ہے۔ تاجر ہڑتالوں کو دیکھتے ہیں جہاں کھلا سود ڈالا جاتا ہے اور کھلے سود کا ڈھیر لگ جاتا ہے۔ موجودہ قیمت سے نیچے بہت بڑے کھلے مفاد کے ساتھ ہڑتال کو بعض اوقات سپورٹ لیول کے طور پر سمجھا جاتا ہے، اس استدلال پر کہ ان پوٹس کے بیچنے والوں کی قیمت اس ہڑتال سے اوپر رہنے میں دلچسپی ہے۔ موجودہ قیمت کے اوپر بہت بڑی کال کھلی دلچسپی کے ساتھ ہڑتال کو بعض اوقات آئینہ کی منطق کے مطابق مزاحمت سمجھا جاتا ہے۔ لوگ ان کو OI دیواریں کہتے ہیں۔</p>\n<p>اس میں کچھ ہے، کیونکہ کھلی پوزیشنوں کی بڑی تعداد ہیجنگ کی سرگرمی کو اپنی طرف متوجہ کرتی ہے جو قیمت کو کلسٹر کر سکتی ہے۔ لیکن یہ ایک نرم رجحان ہے، کوئی اصول نہیں۔ کھلی دلچسپی کی دیواریں حقیقی دیواریں نہیں ہیں۔ یہ سطحیں دن بھر بدلتی رہتی ہیں جیسے جیسے پوزیشنیں شامل اور ہٹا دی جاتی ہیں، وہ باقاعدگی سے ٹوٹتی ہیں، اور ٹرینڈنگ والے دن یا کسی ایونٹ کے آس پاس کی قیمتوں میں براہ راست ان کے ذریعے تبدیلی آتی ہے۔ ان کے ساتھ بہت سے لوگوں کے درمیان ایک کھردرے ان پٹ کے طور پر سلوک کریں، کبھی بھی اس طرح کہ باڑ کی قیمت کو عبور نہیں کیا جا سکتا، اور کبھی بھی اس یقین پر تجارت کا سائز نہ بنائیں کہ کھلی دلچسپی کی سطح برقرار رہے گی۔</p>\n<h2 id=\"the-put-call-ratio-as-a-rough-mood-gauge\">موڈ گیج کے طور پر پوٹ کال کا تناسب</h2>\n<p>دی <strong>پوٹ کال کا تناسب</strong>، یا PCR، تمام کھلی دلچسپی لیتا ہے اور اسے ایک نمبر میں نچوڑ دیتا ہے۔ اس کی عام شکل میں یہ کل پوٹ اوپن انٹرسٹ کو پوری چین میں کل کال اوپن انٹرسٹ سے تقسیم کیا جاتا ہے۔ اگر پوٹس اور کالز یکساں کھلی دلچسپی رکھتے ہیں، تو PCR 1.0 ہے۔ کالز کے مقابلے میں زیادہ پوٹس اسے 1.0 سے اوپر دھکیلتے ہیں۔ پوٹس سے زیادہ کالز اسے نیچے کھینچتی ہیں۔</p>\n<p>نصابی کتاب کا مطالعہ اس طرح ہوتا ہے۔ ایک اعلی PCR، 1 سے اوپر، کا مطلب ہے کہ بہت سارے پوٹس کھلے ہوئے ہیں، جسے بیئرش پوزیشننگ، کراؤڈ ہیجنگ یا زوال پر شرط لگانے کے طور پر لیا جاتا ہے۔ ایک کم PCR، 1 سے بالکل نیچے، کا مطلب ہے کالز ڈومینیٹ، جسے تیزی کی پوزیشننگ کے طور پر لیا جاتا ہے۔ اب تک یہ صرف وہی بیان کر رہا ہے جو کتاب میں ہے۔</p>\n<p>اس کے بعد وہ موڑ آتا ہے جو ابتدائیوں کو الجھا دیتا ہے: بہت سے تاجر PCR کو متضاد سگنل کے طور پر پڑھتے ہیں۔ استدلال یہ ہے کہ جب تقریباً سبھی نے پہلے ہی پوٹس خرید لیے ہیں اور PCR بہت زیادہ ہے، بیئرش بیٹ پر ہجوم ہے اور زیادہ تر فروخت پہلے ہی ہو سکتی ہے، اس لیے اگلا اقدام اوپر ہو سکتا ہے۔ جب PCR بہت کم ہے اور ہر کوئی لمبی کال کر رہا ہے، تو تیزی کی طرف ہجوم ہے اور پل بیک قریب ہو سکتا ہے۔ لہذا ایک ہی نمبر کو دو مخالف طریقوں سے پڑھا جاتا ہے اس پر منحصر ہے کہ آیا آپ اسے رفتار کے طور پر مانتے ہیں یا پرہجوم تجارتی وارننگ کے طور پر۔ یہ اکیلے آپ کو بتانا چاہئے کہ یہ کتنا ڈھیلا ٹول ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>PCR پڑھنا</th>\n<th>لفظی پوزیشننگ</th>\n<th>یہ اکثر کیسے پڑھا جاتا ہے۔</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1 سے اوپر</td>\n<td>کالوں سے زیادہ کھلے ہوئے پوٹس</td>\n<td>بیئرش پوزیشننگ، یا ہجوم ہونے پر متضاد تیزی</td>\n</tr>\n<tr>\n<td>1 کے ارد گرد</td>\n<td>پوٹس اور کالز تقریبا متوازن ہیں۔</td>\n<td>کوئی مضبوط جھکاؤ نہیں۔</td>\n</tr>\n<tr>\n<td>1 سے نیچے</td>\n<td>پوٹس سے زیادہ کالیں کھلتی ہیں۔</td>\n<td>تیزی کی پوزیشننگ، یا ہجوم ہونے کی صورت میں متضاد مندی</td>\n</tr>\n</tbody></table>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>پوٹ کال کا تناسب پوری چین کو ایک نمبر میں کمپریس کرتا ہے: کل پوٹ اوپن انٹرسٹ کو کل کال اوپن انٹرسٹ سے تقسیم کیا جاتا ہے۔ اوپر 1 کا مطلب ہے کہ مزید پوٹس کھلے ہیں، نیچے 1 کا مطلب ہے مزید کالز۔ لیکن ایک ہی پڑھنے کو رفتار اور متضاد سگنل دونوں کے طور پر استدلال کیا جاتا ہے، جو آپ کا پہلا اشارہ ہے کہ یہ موڈ گیج ہے، پیشن گوئی نہیں۔</p>\n</div></div>\n<h2 id=\"the-honest-limits-positioning-is-not-prediction\">ایماندارانہ حدود: پوزیشننگ پیشن گوئی نہیں ہے۔</h2>\n<p>یہ وہ حصہ ہے جس کی ابتدائی کو سب سے زیادہ ضرورت ہوتی ہے، کیونکہ یہ وہ حصہ ہے جو اونچی آوازیں آن لائن چھوڑتا ہے۔ کھلی دلچسپی اور پوٹ کال کا تناسب پوزیشننگ کو بیان کرتا ہے۔ وہ آپ کو معقول درستگی کے ساتھ بتاتے ہیں کہ فی الحال کتاب پر کیا شرطیں لگائی گئی ہیں۔ وہ آپ کو یہ نہیں بتاتے کہ اگلی قیمت کیا ہوگی۔ پوزیشننگ حال کی تصویر ہے، مستقبل کی پیشن گوئی نہیں۔</p>\n<p>تین ایماندارانہ احتیاطیں۔ سب سے پہلے، کھلی دلچسپی ارادے کو ظاہر نہیں کرتی ہے۔ کھلے پوٹس کا ایک بڑا بلاک سراسر مندی کی شرط ہو سکتا ہے، یا یہ کسی بڑے اسٹاک ہولڈنگ کی حفاظت کرنے والا ہیج ہو سکتا ہے، یا یہ اسپریڈ کی ایک ٹانگ ہو سکتی ہے جس کی دوسری ٹانگ آپ نہیں دیکھ سکتے۔ ایک ہی نمبر کا مطلب بہت مختلف چیزوں پر منحصر ہے کہ پوزیشن کیوں موجود ہے، اور سلسلہ آپ کو کبھی نہیں بتاتا کہ کیوں۔ دوسرا، یہ نمبر پیچھے اور شفٹ ہوتے ہیں۔ اس وقت تک جب کوئی تعمیر واضح ہو، اس کو بنانے والا اقدام بڑی حد تک ہو سکتا ہے، اور پوزیشنیں اتنی ہی تیزی سے کھل سکتی ہیں جتنی وہ ظاہر ہوتی ہیں۔ تیسرا، PCR کی کوئی مقررہ حد نہیں ہے جو کام کرے۔ گزشتہ سال انتہائی حد تک شمار ہونے والی سطح اس سال عام ہو سکتی ہے، کیونکہ عام حد مارکیٹ کے ساتھ بڑھ جاتی ہے۔</p>\n<p>مبتدی اس سب کو زیادہ پڑھتے ہیں۔ وہ ایک اعلی PCR دیکھتے ہیں اور ایک اچھال، یا ایک موٹی کال کھلی دلچسپی اور زیادہ سے زیادہ حد کا یقین محسوس کرتے ہیں، اور وہ ایک ہی نمبر پر حقیقی رقم کی شرط لگاتے ہیں جیسے کہ یہ ایک سگنل ہو۔ یہ نہیں ہے. بہترین طور پر، کھلی دلچسپی اور PCR سیاق و سباق ہیں، ایک اور ان پٹ جو قیمت کی کارروائی اور آپ کے اپنے منصوبے کے ساتھ مل کر، ایک منظر کو رنگ دے سکتا ہے۔ بدترین طور پر، ایک پیشن گوئی مشین کے طور پر علاج کیا جاتا ہے، یہ اعتماد محسوس کرنے اور غلط ہونے کا ایک تیز طریقہ ہے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>کھلی دلچسپی اور پوٹ کال کا تناسب پوزیشننگ کو بیان کرتا ہے، مستقبل کی نہیں۔ وہ سیاق و سباق ہیں، سگنل نہیں۔ کوئی بھی جو آپ کو ایک کھلی دلچسپی کی سطح بتاتا ہے یا PCR پڑھنا قابل اعتماد طریقے سے اگلے اقدام کی پیش گوئی کرتا ہے اس بات کا یقین فروخت کر رہا ہے کہ نمبر فراہم نہیں کر سکتے۔ ان کا استعمال یہ سمجھنے کے لیے کہ کون کہاں پوزیشن میں ہے، کبھی بھی تجارت میں داخل ہونے کی وجہ کے طور پر۔</p>\n</div></div>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-basics/images/diagram-oi-pcr.png\" alt=\"کھلی دلچسپی کی تبدیلی کے خلاف قیمت کی سمت کے 2x2 گرڈ کے طور پر چار کھلی دلچسپی کے منظرنامے رکھے گئے ہیں، جس میں پوٹ کال ریشو کو ایک واحد موڈ گیج کے طور پر دکھایا گیا ہے جس میں واضح نوٹ ہے کہ پوزیشننگ پیشن گوئی نہیں ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>کھلی دلچسپی کی تبدیلی کے خلاف قیمت کی سمت کے 2x2 گرڈ کے طور پر چار کھلی دلچسپی کے منظرنامے رکھے گئے ہیں، جس میں پوٹ کال ریشو کو ایک واحد موڈ گیج کے طور پر دکھایا گیا ہے جس میں واضح نوٹ ہے کہ پوزیشننگ پیشن گوئی نہیں ہے۔</figcaption></figure>\n<p>اس لیے دونوں خیالات کو اپنے سر میں الگ رکھیں۔ حجم آج کا منتھن ہے؛ کھلی دلچسپی شرط کا ڈھیر ہے جو اب بھی کھلا ہے۔ کھلی دلچسپی میں تبدیلی کو قیمت میں تبدیلی کے ساتھ جوڑیں اور آپ پڑھ سکتے ہیں کہ کیا اقدام تازہ تعمیر ہے یا پرانی پوزیشنیں چھوڑنا ہے۔ زنجیر کو ایک پوٹ کال کے تناسب میں نچوڑیں اور آپ کو ہجوم کے موڈ کا اندازہ ہو جائے گا۔ یہ سب پس منظر کے طور پر حقیقی طور پر مفید ہے۔ اس میں سے کوئی بھی کرسٹل گیند نہیں ہے۔ جو تاجر اس لائن کا احترام کرتا ہے وہ ان نمبروں کو اچھی طرح سے استعمال کرتا ہے، اور جو اسے بھول جاتا ہے وہ ان کو اس سے کہیں زیادہ اختیار دیتا ہے جتنا اس نے کمایا ہے۔</p>\n","toc":[{"level":2,"text":"کھلی دلچسپی حجم نہیں ہے۔","id":"open-interest-is-not-volume"},{"level":2,"text":"OI کو پڑھنا ایمانداری سے تبدیل ہوتا ہے: 2x2 میٹرکس","id":"reading-oi-changes-honestly-the-2x2-matrix"},{"level":2,"text":"سپورٹ، مزاحمت اور OI دیواریں۔","id":"support-resistance-and-the-oi-walls"},{"level":2,"text":"موڈ گیج کے طور پر پوٹ کال کا تناسب","id":"the-put-call-ratio-as-a-rough-mood-gauge"},{"level":2,"text":"ایماندارانہ حدود: پوزیشننگ پیشن گوئی نہیں ہے۔","id":"the-honest-limits-positioning-is-not-prediction"}],"imgCount":1,"hasContent":true},"22":{"html":"<p>آپشن ٹریڈ میں جو کچھ ہوتا ہے اس میں سے زیادہ تر دو فیصلے تشکیل دیتے ہیں، اور آپ ان دونوں کو اس سے پہلے بناتے ہیں کہ اسٹاک ایک روپیہ بڑھ جائے۔ پہلا یہ ہے کہ آپ کون سی ہڑتال خریدتے ہیں۔ دوسرا یہ کہ آپ کون سی ایکسپائری خریدتے ہیں۔ آپ سمت کو صحیح پڑھ سکتے ہیں اور پھر بھی کھو سکتے ہیں، کیونکہ آپ نے کبھی پکڑنے کے لیے بہت دور کی ہڑتال کا انتخاب کیا ہے، یا آپ کے خیال کو سانس لینے کے لیے جگہ دینے کے لیے ایک میعاد بہت کم ہے۔ ہڑتال اور معیاد کو سمجھدار بنائیں اور ایک معمولی، درست اقدام آپ کو اچھی قیمت ادا کر سکتا ہے۔ یہ باب حادثاتی طور پر ان دو انتخابوں کو جان بوجھ کر کرنے کے بارے میں ہے۔</p>\n<h2 id=\"the-strike-decides-your-trade-off\">ہڑتال آپ کی تجارت کا فیصلہ کرتی ہے۔</h2>\n<p>جب آپ RELIANCE پر کال خریدتے ہیں، 1,318 روپے کے قریب اسٹاک اور 1320 پر قریب ترین اسٹرائیک کے ساتھ، آپ اس ایک اسٹرائیک کے ساتھ نہیں پھنستے ہیں۔ آپشن چین اوپر اور نیچے ہڑتالوں کی ایک پوری سیڑھی پیش کرتا ہے۔ جہاں آپ اس سیڑھی پر کھڑے ہوتے ہیں وہ ایک ساتھ تین چیزوں کا فیصلہ کرتی ہے: آپ کتنی ادائیگی کرتے ہیں، آپشن اسٹاک کو کتنی مضبوطی سے ٹریک کرتا ہے، اور اس کے ختم ہونے پر کسی بھی چیز کے قابل ہونے کا کتنا امکان ہے۔</p>\n<p>جاننے کے لیے تین وسیع زون ہیں۔</p>\n<ul>\n<li>ایک <strong>ان دی منی ( ITM)</strong> کال میں اسپاٹ کے نیچے سٹرائیک ہے، لہذا یہ پہلے سے ہی حقیقی، سیٹل اب قابل ہے۔ یہ خریدنا سب سے مہنگا ہے، کیونکہ آپ اس بلٹ ان ویلیو کے علاوہ تھوڑی سی ٹائم ویلیو کی ادائیگی کر رہے ہیں۔ بدلے میں یہ تقریباً اسٹاک کی طرح برتاؤ کرتا ہے: جب RELIANCE ایک روپیہ بڑھتا ہے، تو ایک گہری ITM کال بھی ایک روپے کے قریب بڑھ جاتی ہے۔ پگھلنے کی امید بہت کم ہے، لہذا وقت کا زوال اسے کم کاٹتا ہے۔</li>\n<li>ایک <strong>پیسے پر ( ATM)</strong> اسپاٹ کے قریب کال کی ہڑتال ہے، یہاں 1320 کال تقریباً 31 روپے فی شیئر پر ہے، جو کہ 500 کی ایک لاٹ کے لیے تقریباً 15,590 روپے ہے۔ یہ متوازن انتخاب ہے۔ کسی بھی اقدام کا تقریباً آدھا حصہ پریمیم میں جاتا ہے، وقت کی قدر اس کی سب سے موٹی ہوتی ہے، اور مشکلات برابر کے قریب ہوتی ہیں۔</li>\n<li>ایک <strong>پیسے سے باہر ( OTM)</strong> کال کی جگہ کے اوپر ہڑتال ہے۔ یہ سستا ہے، کیونکہ اس کی کوئی اندرونی قدر نہیں ہے، صرف امید ہے۔ جب اسٹاک تھوڑا سا حرکت کرتا ہے تو یہ سست حرکت کرتا ہے، اور اسے ادائیگی کے لیے ایک واضح، پرعزم اقدام کی ضرورت ہوتی ہے۔ آپ جتنا آگے جائیں گے، اتنا ہی سستا ہو جائے گا اور مشکلات اتنی ہی لمبی ہو جائیں گی۔</li>\n</ul>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>ایک سستا آپشن بہتر آپشن نہیں ہے۔ قیمت گرتی ہے جیسے ہی آپ پیسے سے باہر منتقل ہوتے ہیں کیونکہ اس کے کبھی بھی کسی چیز کے قابل ہونے کا امکان بھی گر جاتا ہے۔ آپ کو کوئی سودا نہیں مل رہا ہے، آپ ایک لمبی شاٹ خرید رہے ہیں۔</p>\n</div></div>\n<h2 id=\"delta-is-your-rough-chance-of-finishing-in-the-money\">ڈیلٹا آپ کے لیے رقم کو مکمل کرنے کا ایک مشکل موقع ہے۔</h2>\n<p>یہاں ایک عملی شارٹ کٹ ہے جو سلسلہ آپ کو مفت میں دیتا ہے۔ ہر آپشن میں ایک ہے۔ <strong>ڈیلٹا</strong>ایک کال کے لیے 0 اور 1 کے درمیان ایک نمبر، جو آپ کو بتاتا ہے کہ اسٹاک میں ہر ایک روپے کی منتقلی کے لیے پریمیم کتنا بڑھتا ہے۔ 0.50 کے ڈیلٹا کا مطلب ہے کہ جب اسٹاک ایک روپیہ بڑھتا ہے تو آپشن کو تقریباً 50 پیسے کا فائدہ ہوتا ہے۔ لیکن ڈیلٹا ایک سیکنڈ، بہت مفید پڑھتا ہے: یہ اس موقع کے لیے ایک موٹا گائیڈ ہے کہ آپشن کی میعاد ختم ہونے پر رقم ختم ہو جاتی ہے۔</p>\n<p>ایک ATM آپشن 0.50 کے ڈیلٹا کے قریب بیٹھتا ہے، جو سکے کے پلٹنے کے قریب ہے۔ 0.80 کے قریب ڈیلٹا کے ساتھ ایک گہرا ITM آپشن سرگوشی کر رہا ہے کہ اس میں تقریباً 80 فیصد کا احساس ہوتا ہے کہ اس میں پیسہ ختم ہو جاتا ہے۔ 0.10 کے ڈیلٹا کے ساتھ دور OTM آپشن آپ کو بتا رہا ہے کہ اس کے پاس کسی بھی قدر کے ساتھ مکمل ہونے کا صرف دس میں سے ایک موقع ہے۔ نمبر ایک وعدہ نہیں ہے، اور یہ اسٹاک اور کیلنڈر کے منتقل ہونے کے ساتھ ہی بدل جاتا ہے، لیکن یہ آپ کی مشکلات پر ایماندارانہ گٹ چیک ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>ہڑتال ( RELIANCE کال)</th>\n<th>جہاں یہ اسپاٹ 1318 کے مقابلے میں بیٹھا ہے۔</th>\n<th>پریمیم</th>\n<th>ڈیلٹا (کھڑا)</th>\n<th>ان دی منی کو ختم کرنے کا کم امکان</th>\n<th>یہ کیسا برتاؤ کرتا ہے۔</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>پیسے میں</td>\n<td>جگہ کے نیچے ہڑتال</td>\n<td>سب سے مہنگا</td>\n<td>تقریباً 0.70 سے 0.90</td>\n<td>اعلی</td>\n<td>روپے کے بدلے اسٹاک کو تقریباً ٹریک کرتا ہے۔</td>\n</tr>\n<tr>\n<td>پیسے پر (1320)</td>\n<td>موقع کے قریب حملہ</td>\n<td>تقریباً 31 روپے فی شیئر</td>\n<td>تقریبا 0.50</td>\n<td>تقریباً ایک سکے کا پلٹنا</td>\n<td>متوازن، موٹی وقت کی قدر</td>\n</tr>\n<tr>\n<td>باہر کا پیسہ</td>\n<td>جگہ کے اوپر حملہ</td>\n<td>سستا</td>\n<td>تقریباً 0.30</td>\n<td>نیچے بھی</td>\n<td>ادائیگی کے لیے ایک واضح اقدام کی ضرورت ہے۔</td>\n</tr>\n<tr>\n<td>پیسے سے دور</td>\n<td>جگہ سے بہت اوپر حملہ</td>\n<td>بہت سستا</td>\n<td>تقریباً 0.10 یا اس سے کم</td>\n<td>کم</td>\n<td>ایک طویل شاٹ، عام طور پر بیکار ختم ہو جاتا ہے</td>\n</tr>\n</tbody></table>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>خریدنے سے پہلے ڈیلٹا پڑھیں۔ اگر کوئی سٹرائیک 0.15 کا ڈیلٹا دکھاتا ہے، تو آپ کسی ایسی چیز کو دیکھ رہے ہیں جس کی ادائیگی کا تقریباً سات میں سے ایک موقع ہے۔ یہ اب بھی جان بوجھ کر لگائی گئی شرط ہو سکتی ہے، لیکن اسے مشکلات کو جانتے ہوئے بنائیں، اس لیے نہیں کہ پریمیم چھوٹا نظر آیا۔</p>\n</div></div>\n<h2 id=\"the-far-otm-lottery-trap\">دور OTM لاٹری ٹریپ</h2>\n<p>اسکرین پر سب سے سستے آپشنز بہت زیادہ پیسے والے ہیں، اور یہ وہ ہیں جن پر ابتدائی طور پر پہنچتے ہیں، کیونکہ چند روپے فی شیئر سستی محسوس کرتے ہیں اور خواب دس پیسے والا ہے۔ یہ واحد سب سے عام طریقہ ہے جو نئے خریدار اپنے سرمائے کا خون بہا دیتے ہیں۔</p>\n<p>ایک دور OTM آپشن ایک چھوٹے ڈیلٹا پر بیٹھا ہوا تقریباً تمام وقتی قدر ہے۔ اس کی ادائیگی کے لیے، اسٹاک کو آپ کی سمت میں ایک بڑا اقدام کرنا ہوگا، اور جلد ہی، وقت کے زوال سے پہلے اس کے پاس موجود تھوڑا سا پریمیم ختم ہوجاتا ہے۔ زیادہ تر وقت اس لائن میں سے کوئی بھی نہیں ہوتا ہے، اور آپشن خاموشی سے بیکار ختم ہوجاتا ہے۔ آپ سرمایہ کاری نہیں کر رہے تھے، آپ لاٹری ٹکٹ خرید رہے تھے، اور زیادہ تر لاٹری ٹکٹوں کی طرح اس نے کچھ بھی ادا نہیں کیا۔ ان میں سے دس خریدنے سے مشکلات میں بہتری نہیں آتی، یہ آپ کو صرف دس ہارے ہوئے ٹکٹ خریدتا ہے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>لاٹری کے ٹکٹس بہت زیادہ پیسے کے اختیارات ہیں۔ وہ سستے ہیں کیونکہ وہ عام طور پر بیکار ختم ہوجاتے ہیں۔ لانگ شاٹ سٹرائیکس پر بہت سے چھوٹے نقصانات کو ایک ساتھ جوڑنا یہ ہے کہ کس طرح بہت سے نئے لوگ سب کچھ کھو دیتے ہیں، بغیر کسی بڑی، واضح ہٹ کے۔</p>\n</div></div>\n<h2 id=\"expiry-weekly-versus-monthly\">میعاد ختم: ہفتہ وار بمقابلہ ماہانہ</h2>\n<p>دوسرا فیصلہ یہ ہے کہ آپ کتنا وقت خریدتے ہیں۔ کچھ بنیادی پیشکش a <strong>ہفتہ وار</strong> میعاد ختم ہونے کے ساتھ ساتھ <strong>ماہانہ</strong> ایک NIFTY، مثال کے طور پر، 28 جولائی کے ماہانہ کے ساتھ ہفتہ وار معاہدے کی تجارت کرتا ہے، جبکہ RELIANCE ماہانہ تجارت کرتا ہے۔ ان کے درمیان انتخاب واقعی وقت کے خاتمے کے بارے میں ایک انتخاب ہے۔</p>\n<p>ہفتہ وار آپشن سستا ہے، کیونکہ اس کے اندر بہت کم وقت بچا ہے۔ لیکن اسی کمی کا مطلب ہے کہ اس کی وقت کی قدر تیزی سے پگھل جاتی ہے۔ <strong>تھیٹا</strong>, وقت کی قیمت کا روزانہ خون، ہفتہ وار معاہدے میں شدید ہوتا ہے۔ ایک ہفتہ وار خریدار کو ایک یا دو دن کے اندر تیزی سے اقدام کرنے کی ضرورت ہے، یا حتمی سمت درست نکلنے پر بھی پریمیم ختم ہو جائے گا۔ ہفتہ وار ایک عین مطابق، تیز کال کا بدلہ دیتے ہیں اور صبر کو سزا دیتے ہیں۔</p>\n<p>ماہانہ آپشن کی قیمت زیادہ ہوتی ہے، کیونکہ آپ زیادہ وقت خرید رہے ہیں، لیکن یہ وقت ابتدائی ہفتوں میں زیادہ نرمی سے ختم ہو جاتا ہے۔ 28 جولائی RELIANCE آپشن اب بھی وقت کی قدر کا ایک مکمل بلاک رکھتا ہے جس میں ہفتوں کا وقت ہے، لہذا ایک سست، درست اقدام آپ کے حق میں کام کرنے کی گنجائش رکھتا ہے۔ آپ استحقاق کے لیے زیادہ ادائیگی کرتے ہیں، لیکن آپ پہلے گھنٹے سے اسٹاپ واچ نہیں چلا رہے ہیں۔</p>\n<table>\n<thead>\n<tr>\n<th>فیچر</th>\n<th>ہفتہ وار آپشن</th>\n<th>ماہانہ آپشن</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>پریمیم</td>\n<td>سستا</td>\n<td>زیادہ مہنگا</td>\n</tr>\n<tr>\n<td>وقت رہ گیا۔</td>\n<td>دن</td>\n<td>ہفتے</td>\n</tr>\n<tr>\n<td>تھیٹا (روزانہ زوال)</td>\n<td>تیز اور سخت</td>\n<td>سب سے پہلے سست</td>\n</tr>\n<tr>\n<td>سوٹ</td>\n<td>ایک تیز، عین مطابق اقدام</td>\n<td>ترقی کے لیے کمرے کے ساتھ ایک اقدام</td>\n</tr>\n<tr>\n<td>اہم خطرہ</td>\n<td>اس اقدام کے آنے سے پہلے کچھ بھی نہیں ہوتا</td>\n<td>زیادہ لاگت آتی ہے، زیادہ پریمیم باندھتا ہے۔</td>\n</tr>\n</tbody></table>\n<h2 id=\"theta-accelerates-as-expiry-nears\">ختم ہونے کے قریب آتے ہی تھیٹا میں تیزی آتی ہے۔</h2>\n<p>آپ جس بھی میعاد کا انتخاب کرتے ہیں، یاد رکھیں کہ وقت کا خاتمہ آپشن کی زندگی بھر بھی نہیں ہے۔ <strong>وقت کی قدر پہلے آہستہ آہستہ پگھلتی ہے اور پھر آخری دنوں میں گر جاتی ہے۔</strong> چلانے کے لیے ایک ماہ والا آپشن ہر سیشن میں صرف تھوڑا سا کھوتا ہے۔ اس کے آخری دو یا تین دنوں میں ایک ہی آپشن اس کے باقی وقت کی قدر کو تقریباً راتوں رات کم کر سکتا ہے۔</p>\n<p>یہ ایک صاف عملی سبق دیتا ہے۔ اگر آپ کے نقطہ نظر کو مکمل ہونے میں دو یا تین ہفتوں کی ضرورت ہے، تو صرف ایک ہفتہ باقی رہ کر معاہدہ خریدنے کا مطلب ہے کہ کشی کے منحنی خطوط کے سب سے بڑے حصے سے لڑنا۔ ایک سست خیال کو آپ کے خیال سے زیادہ وقت دیں جس کی ضرورت ہے۔ اور اگر آپ کے پاس اس کے آخری دنوں میں ایک لمبا آپشن ہے جب کہ اسٹاک کہیں نہیں جاتا ہے، تو سمجھیں کہ ہر گزرتے ہوئے سیشن کے ساتھ آپ کے پریمیم کے نیچے فرش تیزی سے گر رہا ہے۔</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>تھیٹا مستقل نہیں ہے۔ آپشن کی زندگی کا آخری ہفتہ وہ ہوتا ہے جہاں وقت کی قدر تیزی سے غائب ہو جاتی ہے۔ بہت کم وقت خریدنا، یا بہت لمبا پکڑنا، دونوں آپ کو اس وکر کے کھڑے حصے پر ڈال دیتے ہیں۔</p>\n</div></div>\n<h2 id=\"do-not-let-an-event-ambush-your-expiry\">کسی واقعہ کو اپنی میعاد ختم نہ ہونے دیں۔</h2>\n<p>اسے خریدنے سے پہلے دیکھیں کہ آپ کے اختیار کی کھڑکی کے اندر کیا آتا ہے۔ کمپنی کے نتائج، ایک RBI پالیسی میٹنگ، یونین بجٹ، ایک اہم عالمی مرکزی بینک کا فیصلہ، ان میں سے کوئی بھی آج اور آپ کی میعاد ختم ہونے کے درمیان آ سکتا ہے۔ ایسے واقعہ سے پہلے، مضمر اتار چڑھاؤ بڑھ جاتا ہے اور پریمیم مہنگے ہو جاتے ہیں۔ اس کے فوراً بعد، وہ اضافی اتار چڑھاؤ ختم ہو جاتا ہے اور پریمیم گر سکتا ہے، یہاں تک کہ جب سٹاک آپ کے راستے میں چلا جائے۔ یہ IV ہے، جس کا اپنا ایک باب ہے۔</p>\n<p>ایکسپائری کو منتخب کرنے کا سبق آسان ہے۔ اگر آپ کسی ایونٹ پر شرط لگانا نہیں چاہتے ہیں، تو ایسی ایکسپائری کا انتخاب نہ کریں جس کی ونڈو فلایا ہوا، پری-ایونٹ پریمیم ادا کرتے وقت اسے گھیرے ہوئے ہو۔ اگر ایونٹ پر شرط لگانا ہی پوری بات ہے، تو آنکھیں کھلی رکھ کر اندر جائیں، یہ جانتے ہوئے کہ آپ مہنگی اتار چڑھاؤ خرید رہے ہیں جو کہ خبر کے آنے کے لمحے کو خراب کر دے گا۔</p>\n<h2 id=\"liquidity-is-the-filter-over-both-choices\">لیکویڈیٹی دونوں انتخابوں پر فلٹر ہے۔</h2>\n<p>آخر میں، ایک فلٹر جو دونوں فیصلوں پر بیٹھتا ہے۔ ہڑتال یا ایکسپائری صرف اتنی ہی اچھی ہے جتنی کہ مناسب قیمت پر اس میں داخل ہونے اور باہر جانے کی آپ کی صلاحیت۔ <strong>لیکویڈیٹی</strong> یہ ہے کہ قیمت آپ کے خلاف بڑھے بغیر آپ کتنی آسانی سے تجارت کر سکتے ہیں۔ آپ نے اسے بولی اور پوچھنے کے درمیان کے وقفے میں، اور اس ہڑتال میں حجم اور کھلی دلچسپی میں پڑھا ہے۔</p>\n<p>قریب کے مہینے میں پیسے کے قریب ہونے والی ہڑتالیں، مقبول معاہدہ عام طور پر مائع ہوتا ہے: سخت بولی مانگنے کا پھیلاؤ، بہت ساری تجارتیں، آسان اخراج۔ پیسے سے باہر، یا ایک پتلی دور مہینے میں گھومنا، اور پھیلاؤ وسیع ہو جاتا ہے، بعض اوقات بے دردی سے۔ غیر قانونی ہڑتال پر آپ صرف داخل ہونے کے لیے ایک وسیع اسپریڈ کی ادائیگی کر سکتے ہیں، پھر چھوڑنے کے لیے ایک اور وسیع اسپریڈ ادا کر سکتے ہیں، اور وہ راؤنڈ ٹرپ لاگت خاموشی سے آپ کے نقطہ نظر کے کسی بھی کنارے کو نگل سکتی ہے۔ ایک ہڑتال جو ادائیگی کے خاکے پر کامل نظر آتی ہے اگر آپ اسے معقول قیمت پر تجارت نہیں کر سکتے تو بیکار ہے۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>اس سے پہلے کہ آپ ہڑتال اور ایکسپائری کا ارتکاب کریں، چیک کریں کہ یہ اصل میں تجارت کرتا ہے: ایک سخت بولی طلب پھیلاؤ اور صحت مند حجم اور کھلی دلچسپی۔ دنیا کا سب سے صاف نظارہ اب بھی اس ہڑتال پر پیسے کھو دیتا ہے جس سے آپ باہر نہیں نکل سکتے۔</p>\n</div></div>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-basics/images/diagram-strike-expiry-selection.png\" alt=\"ہر آپشن کی تجارت کے دو ڈائل: ایک اسٹرائیک ڈائل جو کہ ڈیپ ان دی منی سے لے کر پیسے سے باہر تک چل رہا ہے، اور ایک ایکسپائری ڈائل تیزی سے زوال پذیر ہفتہ وار سے سست ماہانہ تک چل رہا ہے، دونوں پر فلٹر کی طرح مائعیت کے ساتھ۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>ہر آپشن کی تجارت کے دو ڈائل: ایک اسٹرائیک ڈائل جو کہ ڈیپ ان دی منی سے لے کر پیسے سے باہر تک چل رہا ہے، اور ایک ایکسپائری ڈائل تیزی سے زوال پذیر ہفتہ وار سے سست ماہانہ تک چل رہا ہے، دونوں پر فلٹر کی طرح مائعیت کے ساتھ۔</figcaption></figure>\n<p>دونوں فیصلوں کو ایک ساتھ رکھیں اور ایک واضح عادت ابھرتی ہے۔ ایک اسٹرائیک کا انتخاب کریں جس کا ڈیلٹا دونوں سے میل کھاتا ہو کہ آپ کتنے پراعتماد ہیں اور آپ کو اسٹاک کے سفر کی حقیقی توقع ہے۔ ایسی میعاد کا انتخاب کریں جو آپ کے خیال کو اس وقت کی ادائیگی کے بغیر کافی وقت دے جو آپ کبھی استعمال نہیں کریں گے، اور یہ اتفاقی طور پر کسی ایسے ایونٹ کو نہیں گھیرے گا جس پر آپ شرط لگانا نہیں چاہتے تھے۔ پھر چیک کریں کہ دونوں صاف طور پر تجارت کرنے کے لیے کافی مائع ہیں۔ اس کو مستقل طور پر کریں اور آپ نے دو سب سے بڑی، سب سے زیادہ قابل گریز وجوہات کو ہٹا دیا ہے جو ابتدائی آپشنز سے محروم ہو جاتے ہیں، اس سے بہت پہلے کہ اس معاملے میں مارکیٹ کی کوئی رائے ہو۔</p>\n","toc":[{"level":2,"text":"ہڑتال آپ کی تجارت کا فیصلہ کرتی ہے۔","id":"the-strike-decides-your-trade-off"},{"level":2,"text":"ڈیلٹا آپ کے لیے رقم کو مکمل کرنے کا ایک مشکل موقع ہے۔","id":"delta-is-your-rough-chance-of-finishing-in-the-money"},{"level":2,"text":"دور OTM لاٹری ٹریپ","id":"the-far-otm-lottery-trap"},{"level":2,"text":"میعاد ختم: ہفتہ وار بمقابلہ ماہانہ","id":"expiry-weekly-versus-monthly"},{"level":2,"text":"ختم ہونے کے قریب آتے ہی تھیٹا میں تیزی آتی ہے۔","id":"theta-accelerates-as-expiry-nears"},{"level":2,"text":"کسی واقعہ کو اپنی میعاد ختم نہ ہونے دیں۔","id":"do-not-let-an-event-ambush-your-expiry"},{"level":2,"text":"لیکویڈیٹی دونوں انتخابوں پر فلٹر ہے۔","id":"liquidity-is-the-filter-over-both-choices"}],"imgCount":1,"hasContent":true},"23":{"html":"<p>ایک آپشن بیچیں اور پریمیم اس وقت آپ کے اکاؤنٹ میں آجائے جس وقت تجارت بھر جائے گی۔ یہ مفت پیسے کی طرح محسوس کر سکتا ہے: آپ نے کچھ نہیں کیا، اسٹاک منتقل نہیں ہوا ہے، اور وہاں نقد رقم موجود ہے. یہ احساس اختیارات میں سب سے مہنگا وہم ہے۔ فروخت مفت پیسہ نہیں ہے، دو مشکل وجوہات کی بناء پر۔ سب سے پہلے، ایکسچینج آپ کو اس خطرے کے مقابلے میں ایک بڑا مارجن پوسٹ کرتا ہے جو آپ نے ابھی لیا ہے، کیونکہ یہ خطرہ آپ کے جمع کردہ پریمیم سے کہیں زیادہ ہو سکتا ہے۔ دوسرا، ہر تجارت، چاہے آپ خریدیں یا بیچیں، اپنے پیچھے چارجز کا ایک ڈھیر گھسیٹتا ہے جو خاموشی سے آپ کے حقیقی بریک ایون کو نئی شکل دیتا ہے۔ یہ باب دونوں کے ذریعے چلتا ہے، لہذا آپ کی سکرین پر نمبر وہ نمبر نہیں ہے جو آپ کو بیوقوف بناتا ہے۔</p>\n<h2 id=\"selling-is-not-free-money-the-margin\">فروخت مفت پیسہ نہیں ہے: مارجن</h2>\n<p>جب آپ کوئی آپشن بیچتے یا لکھتے ہیں، تو آپ ایک ذمہ داری قبول کرتے ہیں۔ ایک ننگی مختصر کال ہڑتال کے اوپر لامحدود خطرہ رکھتی ہے۔ سٹاک گرنے کے ساتھ ہی ننگے شارٹ پٹ میں بہت بڑا خطرہ ہوتا ہے۔ ایکسچینج یہ جانتا ہے، لہذا اس سے پہلے کہ وہ آپ کو فروخت کرنے دے، یہ آپ کے سرمائے کا ایک حصہ بلاک کر دیتا ہے۔ <strong>مارجن</strong>, ایک سیکورٹی ڈپازٹ اس کے پاس اس موقع کے خلاف ہے کہ تجارت آپ کے خلاف جاتی ہے۔</p>\n<p>ایک ننگے شارٹ انڈیکس آپشن کے لیے، وہ مارجن تقریباً چلتا ہے۔ <strong>1.5 لاکھ سے 1.8 لاکھ روپے فی لاٹ</strong>. یہ دو ٹکڑوں سے بنایا گیا ہے۔ <strong>SPAN مارجن</strong> ایکسچینج کی رسک پر مبنی بنیادی ضرورت ہے، جس کا حساب اس بات سے لگایا جاتا ہے کہ مختلف حرکات کے تحت پوزیشن کتنی کھو سکتی ہے۔ اس کے اوپر ایک بیٹھتا ہے۔ <strong>نمائش مارجن</strong>، ایک اضافی بفر۔ ایک ساتھ وہ جان بوجھ کر بڑے ہوتے ہیں، کیونکہ اس کا احاطہ کرنے کا خطرہ بڑا ہوتا ہے۔ وہ پریمیم جو آپ نے اکٹھا کیا، اکثر ایک لاٹ پر چند ہزار روپے، اس کے سائز سے کئی گنا مارجن بلاک کے خلاف بیٹھا ہے۔ مناسب طریقے سے دیکھا جائے تو، فروخت مفت پیسہ نہیں ہے، یہ ایک حقیقی اور بعض اوقات لامحدود خطرہ اٹھانے کے لیے بڑی مقدار میں سرمایہ کرایہ پر لینا ہے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>ایک بیچنے والا جو پریمیم جمع کرتا ہے وہ بلاک شدہ مارجن کے آگے چھوٹا ہوتا ہے اور جو خطرہ ہوتا ہے۔ ایک ننگی شارٹ کال کا سٹرائیک کے اوپر لامحدود نقصان ہوتا ہے، قیمت گرنے پر ایک ننگے شارٹ کا بہت بڑا نقصان ہوتا ہے۔ مارجن بڑا ہے کیونکہ خطرہ حقیقی ہے۔ اس کا احترام کریں، ورنہ یہ آپ کو مل جائے گا۔</p>\n</div></div>\n<h2 id=\"a-hedge-cuts-the-margin-sharply\">ایک ہیج مارجن کو تیزی سے کاٹتا ہے۔</h2>\n<p>اس مارجن کو نیچے لانے کا ایک نظم و ضبط والا طریقہ ہے، اور یہ وہی اقدام ہے جو آپ کے خطرے کو کم کرتا ہے۔ اگر آپ اپنے بیچنے والے کے خلاف کوئی اور آپشن خریدتے ہیں، تو آپ اپنے بدترین کیس کو محدود کر لیتے ہیں۔ ایکسچینج دیکھ سکتا ہے کہ آپ کا نقصان اب محدود ہے، اس لیے یہ چھوٹے خطرے کو تسلیم کرتا ہے اور مارجن تیزی سے گرتا ہے، اکثر ننگی شخصیت کے ایک چھوٹے سے حصے تک۔</p>\n<p>یہ ایک کے پیچھے خیال ہے <strong>طے شدہ خطرہ</strong> پوزیشن: خریدا ہوا آپشن بیچے جانے والے پر بیک سٹاپ کا کام کرتا ہے، اس لیے بھاگنے والا اقدام آپ کو صرف اتنا ہی نقصان پہنچا سکتا ہے۔ ہم یہاں نام کی حکمت عملی نہیں بناتے ہیں، یہ حکمت عملی کورس کا کام ہے، لیکن اب اصول اہمیت رکھتا ہے۔ ایک ہیج نہ صرف زیادہ محفوظ ہے، بلکہ اسے رکھنا بہت سستا ہے، کیونکہ مارجن سکڑ جاتا ہے جب آپ کا زیادہ سے زیادہ نقصان طے ہوجاتا ہے اور معلوم ہوجاتا ہے۔</p>\n<h2 id=\"collateral-can-be-pledged-with-a-caveat\">ضمانت کے ساتھ گروی رکھا جا سکتا ہے۔</h2>\n<p>آپ کو ہمیشہ اس مارجن کو نقد میں پوسٹ کرنے کی ضرورت نہیں ہے۔ آپ کر سکتے ہیں۔ <strong>عہد</strong> آپ کے پاس پہلے سے موجود ہولڈنگز، حصص یا کچھ فنڈز، بطور ضمانت، اور ایکسچینج ان کی قیمت کو آپ کے مارجن میں شمار کرتا ہے۔ پورٹ فولیو رکھنے والے کسی کے لیے، یہ ایک ہی سرمایہ کو ایک ساتھ دو کام کرنے دیتا ہے۔</p>\n<p>لیکن انتباہ کو غور سے پڑھیں۔ گروی رکھا ہوا ضمانت a کے ساتھ آتا ہے۔ <strong>بال کٹوانے</strong>: آپ قابل استعمال مارجن کے طور پر پوری مارکیٹ ویلیو سے کم وصول کرتے ہیں، کیونکہ ضمانت خود قیمت میں گر سکتی ہے۔ ایکسچینج یہ بھی اصرار کرتا ہے کہ آپ کے کل مارجن کا ایک حصہ، عام طور پر نصف کے قریب، اصل کے طور پر رکھا جائے۔ <strong>نقد</strong>، نہ صرف گروی رکھے ہوئے حصص۔ اور اہم بات یہ ہے کہ گروی رکھی گئی ضمانت آپ کے روز مرہ کے نقصانات کی ادائیگی نہیں کرتی ہے۔ اگر پوزیشن آپ کے خلاف چلتی ہے، نتیجے میں مارک ٹو مارکیٹ نقصان کا ازالہ حقیقی نقد میں ہونا چاہیے۔ ایک بیچنے والا جس نے حصص گروی رکھے اور کوئی کیش بفر نہ رکھا اسے بدترین ممکنہ لمحے پر بیچنے پر مجبور کیا جا سکتا ہے، یا جرمانے کا سامنا کرنا پڑ سکتا ہے، صرف اس وجہ سے کہ ہارنے والی پوزیشن نے نقد رقم کا مطالبہ کیا تھا کہ کولیٹرل فراہم نہیں کر سکتا تھا۔</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>ضمانت دینے سے سرمایہ آزاد ہوجاتا ہے، لیکن یہ مفت پاس نہیں ہے۔ قیمت پر بال کٹوانے ہیں، مارجن کا ایک حصہ اب بھی نقد ہونا چاہیے، اور چلتے ہوئے نقصانات کا ازالہ نقد میں کیا جاتا ہے۔ کیش بفر رکھیں، نہ صرف گروی رکھے ہوئے حصص۔</p>\n</div></div>\n<h2 id=\"the-full-charges-stack\">مکمل چارجز اسٹیک</h2>\n<p>اب دوسری حقیقت، وہ جو ہر اس تجارت کو چھوتی ہے جو آپ کبھی کرتے ہیں، خریدار یا بیچنے والا۔ پریمیم کبھی بھی پوری کہانی نہیں ہوتا ہے۔ چارجز کا ایک ڈھیر ہر تجارت کے اوپر یا اس سے باہر ہوتا ہے، اور وہ آپ کے حقیقی منافع کا فیصلہ کرتے ہیں۔ 1 اپریل 2026 سے لاگو ہونے والے نرخوں کے ساتھ، ہندوستان میں آپشنز کی تجارت کا اسٹیک یہ ہے کہ وہ کہاں مقرر ہیں۔</p>\n<table>\n<thead>\n<tr>\n<th>چارج</th>\n<th>جب یہ لاگو ہوتا ہے۔</th>\n<th>کھردری بنیاد</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>دلالی</td>\n<td>ہر آرڈر پر خرید و فروخت</td>\n<td>ایک فلیٹ فیس فی عملدرآمد آرڈر، عام طور پر تقریباً 20 روپے، اور کچھ بروکرز کے لیے کوئی نہیں۔</td>\n</tr>\n<tr>\n<td>STT ایک آپشن فروخت کرنے پر</td>\n<td>جب آپ آپشن بیچتے یا لکھتے ہیں۔</td>\n<td>پریمیم قیمت کا 0.15%</td>\n</tr>\n<tr>\n<td>STT ایک استعمال شدہ آپشن پر</td>\n<td>جب میعاد ختم ہونے پر ان دی منی آپشن کا استعمال کیا جاتا ہے۔</td>\n<td>داخلی (تصفیہ) قدر کا 0.15%</td>\n</tr>\n<tr>\n<td>ایکسچینج ٹرانزیکشن چارجز</td>\n<td>ہر حکم پر، دونوں طرف</td>\n<td>پریمیم ٹرن اوور کا ایک چھوٹا فیصد</td>\n</tr>\n<tr>\n<td>SEBI چارجز</td>\n<td>ہر حکم پر، دونوں طرف</td>\n<td>کاروبار کا ایک چھوٹا فیصد</td>\n</tr>\n<tr>\n<td>GST</td>\n<td>ہر حکم پر، دونوں طرف</td>\n<td>18% پر (بروکریج کے علاوہ ٹرانزیکشن چارجز)</td>\n</tr>\n<tr>\n<td>سٹیمپ ڈیوٹی</td>\n<td>صرف خریداری کی طرف</td>\n<td>خرید قیمت کا ایک چھوٹا فیصد</td>\n</tr>\n</tbody></table>\n<p>ان میں سے کوئی بھی اپنے طور پر بڑا نہیں ہے۔ ایک چھوٹی سی تجارت پر، وہ ایک حقیقی نمبر میں اضافہ کرتے ہیں، اور وہ نمبر آپ کے نتائج سے سیدھا آتا ہے۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>آپ جو پریمیم ادا کرتے یا جمع کرتے ہیں وہ آپ کی لاگت یا آپ کی آمدنی نہیں ہے۔ بروکریج، STT، ایکسچینج اور SEBI چارجز، 18% GST اور اسٹامپ ڈیوٹی سب اوپر بیٹھے ہیں۔ آپ کا حقیقی منافع پورے اسٹیک کو کم کر کے پریمیم اقدام ہے۔</p>\n</div></div>\n<h2 id=\"how-charges-move-your-true-breakeven\">چارجز آپ کے حقیقی بریک ایون کو کیسے منتقل کرتے ہیں۔</h2>\n<p>RELIANCE 1320 کال پر تقریباً 31 روپے فی شیئر پر غور کریں۔ ایکسپائری پر اس کا بریک ایون اسٹرائیک پلس پریمیم، 1320 پلس 31 ہے، جو کہ 1351 ہے: اسٹاک کو صرف پریمیم کی ادائیگی کے لیے 1351 کو کلیئر کرنا ہوگا۔ چارجز شامل کریں اور آپ کا حقیقی بریک ایون 1351 سے تھوڑا اوپر بیٹھ جائے گا، کیونکہ اسٹاک میں آپ کو لاگت کے حوالے سے بھی پورا کرنا چاہیے۔ ایک لمبے، بڑے اقدام پر کہ اضافی ٹکڑا معمولی ہے۔ ایک فوری کھوپڑی پر یہ سارا کھیل ہوسکتا ہے۔</p>\n<p>ایک چھوٹے سے راؤنڈ ٹرپ کی تصویر بنائیں۔ آپ 1320 کال کا ایک لاٹ تقریباً 31 روپے فی شیئر پر خریدتے ہیں، جس کی قیمت تقریباً 15,590 روپے ہے، اور یہ ٹک جاتا ہے تو آپ 31.50 روپے میں فروخت ہوتے ہیں۔ صرف پریمیم پر 50 پیسے کا فائدہ 0.50 گنا 500 ہے، جو مجموعی منافع کا 250 روپے ہے۔ اب چارجز جمع کریں: خرید آرڈر پر ایک فلیٹ بروکریج اور دوبارہ سیل آرڈر پر۔ STT فروخت کی قیمت کے 0.15% پر، 31.50 گنا 500 ہے 15,750 روپے، تو تقریباً 24 روپے؛ ایکسچینج اور SEBI دو طرفہ ٹرن اوور کے تقریباً 31,000 روپے پر چارجز، چند روپے؛ بروکریج پر 18% GST کے علاوہ ان ٹرانزیکشن چارجز؛ اور خرید پر سٹیمپ ڈیوٹی. یہ مل کر تقریباً 80 روپے سے 100 روپے تک آ سکتے ہیں۔ آپ کا 250 روپے کا مجموعی اچانک 150 روپے کے قریب ہے۔</p>\n<p>اب اس حرکت کو پتلا کریں۔ کہتے ہیں کہ آپ 31.10 روپے پر فروخت کرتے ہیں، 10 پیسے کا فائدہ۔ پریمیم پر جو کہ 0.10 گنا 500 ہے، جو کہ مجموعی منافع کے 50 روپے ہے، اور اسکرین سبز چمکتی ہے۔ لیکن تقریباً 80 سے 100 روپے کا وہی چارج اسٹیک اب بھی موجود ہے۔ وہ تجارت جو پریمیم پر منافع بخش نظر آتی ہے ایک بار اخراجات کی ادائیگی کے بعد خالص نقصان ہوتا ہے۔ یہ چھوٹی کھوپڑی کا جال ہے: پریمیم کہتا ہے کہ آپ جیت گئے، چارجز کہتے ہیں کہ آپ ہار گئے، اور صرف دوسرا اصلی ہے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>ایک چھوٹی آپشن ٹریڈ پریمیم پر منافع دکھا سکتی ہے اور چارجز کے بعد بھی کھو سکتی ہے۔ آپ جتنی پتلی حرکت کو کھوپڑی لگانے کی کوشش کر رہے ہیں، لاگت کا مقررہ اسٹیک اتنا ہی زیادہ اہمیت رکھتا ہے۔ ہمیشہ نیٹ کے ذریعے تجارت کا فیصلہ کریں، کبھی بھی اکیلے پریمیم سے نہیں۔</p>\n</div></div>\n<h2 id=\"the-stt-on-exercise-trap\">STT پر ورزش کا جال</h2>\n<p>اس ٹیبل میں ایک چارج اس کی اپنی وارننگ کا مستحق ہے، کیونکہ یہ میعاد ختم ہونے والے دن ابتدائی افراد پر حملہ کرتا ہے۔ دو مختلف STT لائنوں کو دیکھیں۔ جب آپ <strong>فروخت</strong> مارکیٹ میں ایک آپشن، STT کا 0.15% ہے۔ <strong>پریمیم</strong>. لیکن جب آپ ان دی منی آپشن کو ختم ہونے کے لیے چلنے دیتے ہیں اور یہ ہوتا ہے۔ <strong>خودکار مشق</strong>، STT کا 0.15% ہے۔ <strong>داخلی (تصفیہ) قدر</strong>, مکمل اندرونِ رقم رقم، نہ کہ چھوٹا پریمیم جو آپ نے اصل میں ادا کیا تھا۔</p>\n<p>پیسے میں گہرے آپشن کے لیے، وہ سیٹلمنٹ ویلیو بڑی ہو سکتی ہے، اس لیے STT کو بڑی تعداد سے چھوٹا کیا جاتا ہے۔ کہیے کہ ایک NIFTY کال 300 روپے فی شیئر ان دی منی، بہت سارے 65 پر ختم ہوتی ہے۔ اندرونی تصفیہ کی قیمت 300 گنا 65 ہے، جو کہ 19,500 روپے ہے، اور مشق STT 0.15% پر تقریباً 29 روپے ہے، اس رقم پر چارج کیا جاتا ہے۔ ایک ابتدائی جس نے سوچا تھا کہ ان کی واحد قیمت وہ سستا پریمیم ہے جو اس نے ہفتے پہلے ادا کیا تھا اب اس کا مکمل تصفیہ ختم کردیا گیا ہے۔ پیسے میں جتنا گہرا آپشن، اتنا ہی بڑا بیس، اور اتنا ہی بڑا سرپرائز۔</p>\n<p>دفاع وہی اصول ہے جو ایکسپائری میکینکس کو پہلے ہی سکھایا گیا ہے۔ ایکسپائری ڈے پر بند ہونے سے پہلے مارکیٹ میں پیسے کے اندر موجود آپشن کو اسکوائر آف کر دیں، بجائے اس کے کہ اسے خودکار طریقے سے استعمال کیا جائے، الا یہ کہ آپ خاص طور پر تصفیہ لینا چاہتے ہوں۔ اسے فروخت کرنے سے پریمیم پر STT ادا ہوتا ہے اور ورزش کے چارج کو مکمل طور پر چھوڑ دیتا ہے، اور سنگل اسٹاک آپشن کے لیے یہ ایک لاٹ پر کئی لاکھ مالیت کی فزیکل ڈیلیوری میں جانے سے بھی گریز کرتا ہے۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>ان دی منی آپشن کو حادثاتی طور پر آٹو ایکسرسائز میں نہ جانے دیں۔ ورزش STT کو مکمل اندرونی قیمت پر چارج کیا جاتا ہے، جو پریمیم سے کہیں زیادہ بڑی بنیاد ہے۔ میعاد ختم ہونے سے پہلے اسکوائر آف کرنا پریمیم پر ٹیکس برقرار رکھتا ہے اور آپ کو ڈیلیوری سے دور رکھتا ہے۔</p>\n</div></div>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-basics/images/diagram-charges-stack.png\" alt=\"چارجز ایک ہی آپشن ٹریڈ پر اسٹیک ہوتے ہیں: بیس پر پریمیم، پھر بروکریج، STT، ایکسچینج اور SEBI چارجز، 18% GST اور اسٹامپ ڈیوٹی سب سے اوپر، سادہ پریمیم بریک ایون کے اوپر بیٹھے ہوئے حقیقی بریک ایون کے ساتھ۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>چارجز ایک ہی آپشن ٹریڈ پر اسٹیک ہوتے ہیں: بنیاد پر پریمیم، پھر بروکریج، STT، ایکسچینج اور SEBI چارجز، 18% GST اور اسٹامپ ڈیوٹی سب سے اوپر، سادہ پریمیم بریک ایون کے اوپر بیٹھے ہوئے حقیقی بریک ایون کے ساتھ۔</figcaption></figure>\n<p>دونوں حصوں کو ایک ساتھ رکھیں اور ایماندارانہ تصویر واضح ہے۔ پریمیم فروخت کرنا مفت آمدنی نہیں ہے، یہ ایک مارجن بھاری پوزیشن ہے جس میں حقیقی اور بعض اوقات لامحدود خطرہ ہوتا ہے، صرف اس وقت آسان ہوتا ہے جب آپ اسے ایک متعین خطرے کی شکل میں ہیج کرتے ہیں۔ اور ہر تجارت، دونوں طرف سے، چارجز کا ایک ڈھیر ادا کرتا ہے جو آپ کے بریک ایون کو بدل دیتا ہے اور ایک پتلے پریمیم نفع کو حقیقی نقصان میں بدل سکتا ہے۔ فروخت کرنے سے پہلے اپنے مارجن کو جاننا، اور منافع کا فیصلہ کرنے سے پہلے آپ کی پوری قیمت جاننا، کاغذی کارروائی نہیں ہے۔ یہ اس تجارت میں فرق ہے جو اچھی لگ رہی تھی اور ایک تجارت جو اچھی تھی۔</p>\n","toc":[{"level":2,"text":"فروخت مفت پیسہ نہیں ہے: مارجن","id":"selling-is-not-free-money-the-margin"},{"level":2,"text":"ایک ہیج مارجن کو تیزی سے کاٹتا ہے۔","id":"a-hedge-cuts-the-margin-sharply"},{"level":2,"text":"ضمانت کے ساتھ گروی رکھا جا سکتا ہے۔","id":"collateral-can-be-pledged-with-a-caveat"},{"level":2,"text":"مکمل چارجز اسٹیک","id":"the-full-charges-stack"},{"level":2,"text":"چارجز آپ کے حقیقی بریک ایون کو کیسے منتقل کرتے ہیں۔","id":"how-charges-move-your-true-breakeven"},{"level":2,"text":"STT پر ورزش کا جال","id":"the-stt-on-exercise-trap"}],"imgCount":1,"hasContent":true},"24":{"html":"<p>آپ نے اب تک جو کچھ سیکھا ہے اس میں سے زیادہ تر آپشن کی قیمت کو ایک ہموار چیز کے طور پر مانتے ہیں۔ یہ اسٹاک کے ساتھ بہہ جاتا ہے، اس سے ہر روز تھوڑا وقت کی قیمت نکلتی ہے، اور تصویر منظم محسوس ہوتی ہے۔ لمبے لمبے لمبے لمبے چوڑائیوں کے لیے بالکل ایسا ہی ہوتا ہے جیسے کوئی آپشن برتاؤ کرتا ہے۔ لیکن کیلنڈر ہموار نہیں ہے۔ اس میں بکھری ہوئی تاریخیں ہیں جو ہر کوئی آنے والی دیکھ سکتا ہے: کسی کمپنی کے نتائج کا دن، ایک RBI پالیسی میٹنگ، یونین بجٹ، قومی انتخابات کا نتیجہ، US فیڈ کا فیصلہ۔ ان تاریخوں کے آس پاس آپشن کا پریمیم کچھ پرتشدد کرتا ہے جس کا اس بات سے بہت کم تعلق ہے کہ آیا آپ نے سمت کا صحیح اندازہ لگایا ہے۔ یہ پہلے سے پھول جاتا ہے اور بعد میں گر جاتا ہے۔ اس تال کو سیکھنا واقعات کو استعمال کرنے اور خاموشی سے ان کے ذریعہ تباہ ہونے میں فرق ہے۔</p>\n<h2 id=\"options-live-on-a-calendar-of-events\">اختیارات واقعات کے کیلنڈر پر رہتے ہیں۔</h2>\n<p>ایک <strong>واقعہ</strong>آپشن ٹریڈر کے لیے، ایک طے شدہ لمحہ ہوتا ہے جب نئی معلومات کا ایک بڑا ڈھیر ایک ساتھ مارکیٹ میں آتا ہے۔ کلیدی لفظ طے شدہ ہے۔ ہر کوئی پہلے سے تاریخ دیکھ سکتا ہے، لہذا مارکیٹ حیران ہونے کا انتظار نہیں کرتا. یہ تیار کرتا ہے۔</p>\n<p>یہ وہ واقعات ہیں جو ہندوستانی اختیارات کو سب سے زیادہ متحرک کرتے ہیں۔</p>\n<ul>\n<li><strong>کمپنی کے نتائج۔</strong> RELIANCE اپنے سہ ماہی نمبروں کو معلوم تاریخ پر رپورٹ کرتا ہے۔ اسٹاک میں تیزی سے فرق ہو سکتا ہے جب وہ نمبرز اور مینجمنٹ کمنٹری زمین پر آجائے۔</li>\n<li><strong>RBI مانیٹری پالیسی۔</strong> شرح سود کا فیصلہ اور مرکزی بینک کا لہجہ بینکوں، شرح کے لحاظ سے حساس اسٹاکس اور انڈیکس کو ایک ساتھ منتقل کرتا ہے۔</li>\n<li><strong>مرکزی بجٹ۔</strong> ایک ہی سہ پہر جو پورے شعبوں کو ایک ساتھ دوبارہ قیمت دے سکتی ہے۔</li>\n<li><strong>انتخابات۔</strong> قومی یا ریاستی نتائج خبروں کا ایک بائنری گانٹھ ہیں، اور انڈیکس نتائج پر سخت جھول سکتا ہے۔</li>\n<li><strong>عالمی واقعات جیسے کہ US Fed میٹنگ۔</strong> غیر ملکی مرکزی بینک کا فیصلہ اب بھی عالمی خطرے کے جذبات کے ذریعے NIFTY میں پھنستا ہے۔</li>\n</ul>\n<p>عام دھاگہ یہ ہے کہ تاریخ عوامی ہے اور نتیجہ نامعلوم ہے۔ وہ مجموعہ، نامعلوم نتیجہ کے ساتھ ایک معلوم تاریخ، بالکل وہی ہے جس پر ردعمل ظاہر کرنے کے لیے آپشن کی قیمت بنائی گئی ہے۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>ایک واقعہ اس تاریخ پر بڑی خبروں کا ایک طے شدہ ڈراپ ہوتا ہے جو پوری مارکیٹ کو پہلے سے معلوم ہوتا ہے۔ چونکہ تاریخ عوامی ہے، آپشن مارکیٹ اس کے لیے پیشگی تیاری کرتی ہے، اور خریدار کو زیادہ تر نقصان پریمیم کے ذریعے ہوتا ہے، اسٹاک کی سمت سے نہیں۔</p>\n</div></div>\n<h2 id=\"before-the-event-implied-volatility-expands\">واقعہ سے پہلے: مضمر اتار چڑھاؤ پھیلتا ہے۔</h2>\n<p>مارکیٹ کے خوف کی پیمائش کے طور پر، آپ نے پہلے سے مضمر اتار چڑھاؤ کا سامنا کیا، اس اقدام کا متوقع سائز پریمیم میں بیک کیا گیا۔ ایک واقعہ اس گیج چڑھنے کی خالص ترین مثال ہے۔ ایک معروف واقعہ سے پہلے کے دنوں میں، تاجر ممکنہ چھلانگ لگانے کے لیے آپشنز کی طرف ہجوم کرتے ہیں، اور یہ مطالبہ، حقیقی غیر یقینی صورتحال کے ساتھ، آگے بڑھتا ہے۔ <strong>مضمر اتار چڑھاؤ</strong> اعلی پریمیم موٹا ہوتا ہے۔</p>\n<p>اسے RELIANCE اینکر پر دیکھیں۔ ایک پرسکون مارکیٹ میں 1320 کال کی قیمت تقریباً 31 روپے فی شیئر ہے، جو کہ 500 کی ایک لاٹ کے لیے تقریباً 15,590 روپے ہے۔ نتائج سے پہلے ہفتے میں چلیں اور وہی کال، ایک ہی ہڑتال، ایک ہی ایکسپائری، اس سے کہیں زیادہ لاگت آسکتی ہے، شاید 50 روپے فی شیئر یا اس سے زیادہ، اس لیے نہیں کہ اسٹاک منتقل ہو گیا ہے بلکہ اس لیے کہ مارکیٹ اب ایک بڑے دن کے نتیجے میں قیمتوں کا تعین کر رہی ہے۔ آپ سے امید کی اسی پٹی کے لیے موٹا ڈر پریمیم ادا کرنے کو کہا جا رہا ہے۔</p>\n<p>اشاریہ اپنے سٹرڈل کے ذریعے وہی کہانی بیان کرتا ہے۔ NIFTY کے قریب 24,056 اور 24,050 اسٹرائیک کے ساتھ، ایٹ دی منی کال تقریباً 426 روپے فی شیئر اور پوٹ تقریباً 295 روپے ہے، اس لیے ایٹ دی منی اسٹریڈل تقریباً 720 روپے فی شیئر ہے۔ یہ سٹریڈل 28 جولائی تک تقریباً پلس یا مائنس 720 پوائنٹس کے متوقع اقدام کا مارکیٹ کا فوری تخمینہ ہے۔ کسی بڑے ایونٹ سے پہلے، وہ سٹرڈل وسیع ہو جاتا ہے، جو کہ مہنگے ہونے والے اختیارات کا انڈیکس ورژن ہے۔ مارکیٹ کھلے عام آپ کو بتا رہی ہے کہ اسے بڑے جھول کی توقع ہے۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>اسٹریڈل قیمت مارکیٹ کا ایونٹ کا اپنا تخمینہ ہے۔ اگر اٹ-دی-منی کال پلس پوٹ موٹا ہے تو، مارکیٹ نے پہلے ہی ایک بڑے اقدام سے قیمتیں طے کر لی ہیں۔ ایک خریدار کے طور پر منافع حاصل کرنے کے لیے، حقیقی اقدام کو اس قیمت کی توقع کو شکست دینا ہوگی، نہ کہ صرف صحیح راستہ بتانا۔</p>\n</div></div>\n<h2 id=\"after-the-event-the-iv-crush\">ایونٹ کے بعد: IV کو کچلنا</h2>\n<p>پھر واقعہ ہوتا ہے۔ نمبر ختم ہو گئے، پالیسی کا اعلان ہو گیا، نتیجہ معلوم ہو گیا۔ بے یقینی کا واحد سب سے بڑا ذریعہ، نہ جاننے والا، ایک لمحے میں غائب ہو جاتا ہے۔ مضمر اتار چڑھاؤ تقریباً فوراً ہی اپنی معمول کی سطح کی طرف گر جاتا ہے، اور چونکہ واقعہ سے پہلے کا زیادہ تر پریمیم خالص خوف تھا، اس لیے پریمیم اس لمحے سخت گر جاتا ہے جب خوف ختم ہو جاتا ہے۔ یہ اچانک گرنا ہے۔ <strong>IV کو کچلنا</strong>.</p>\n<p>کچلنا کوئی خرابی نہیں ہے اور یہ غیر منصفانہ نہیں ہے۔ یہ بازار صحیح طریقے سے خطرے کے پریمیم کو ہٹاتا ہے جس کی مزید ضرورت نہیں ہے۔ مصیبت یہ ہے کہ ابتدائی مہنگے، اعلی IV لمحے خریدتے ہیں، جوش و خروش سے تیار ہوتے ہیں، اور پھر سیدھے کچلتے رہتے ہیں۔</p>\n<table>\n<thead>\n<tr>\n<th>اسٹیج</th>\n<th>مارکیٹ کیا کر رہی ہے۔</th>\n<th>مضمر اتار چڑھاؤ</th>\n<th>پریمیم</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>تقریب سے کچھ دن پہلے</td>\n<td>ایک بڑے نامعلوم اقدام میں قیمتوں کا تعین</td>\n<td>پھیلتا ہے، اوپر چڑھتا ہے۔</td>\n<td>پھول جاتا ہے، امید مہنگی ہو جاتی ہے۔</td>\n</tr>\n<tr>\n<td>جس لمحے خبر آتی ہے۔</td>\n<td>غیر یقینی صورتحال دور ہو گئی ہے۔</td>\n<td>کچلتا ہے، تیزی سے گرتا ہے۔</td>\n<td>اندرونی قدر کی طرف سمٹ جاتا ہے۔</td>\n</tr>\n<tr>\n<td>غبار اُڑنے کے بعد</td>\n<td>ایک عام توقع پر واپس جائیں۔</td>\n<td>اس کی معمول کی حد کے قریب</td>\n<td>صرف حقیقی اقدام اور باقی وقت کی عکاسی کرتا ہے۔</td>\n</tr>\n</tbody></table>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-basics/images/diagram-event-iv-crush.png\" alt=\"کسی معروف ایونٹ تک پہنچنے کے دوران بڑھتا ہوا اتار چڑھاؤ اور پھر نتیجہ کے آنے کے لمحے کو کچل دیتا ہے، اس لیے پریمیم پہلے سے پھول جاتا ہے اور بعد میں گر جاتا ہے یہاں تک کہ جب اسٹاک خریدار کے حق میں جاتا ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>کسی معروف ایونٹ تک پہنچنے کے دوران بڑھتا ہوا اتار چڑھاؤ اور پھر نتیجہ کے آنے کے لمحے کو کچل دیتا ہے، اس لیے پریمیم پہلے سے پھول جاتا ہے اور بعد میں گر جاتا ہے یہاں تک کہ جب اسٹاک خریدار کے حق میں جاتا ہے۔</figcaption></figure>\n<h2 id=\"right-on-direction-still-in-the-red\">صحیح سمت میں، اب بھی سرخ رنگ میں</h2>\n<p>یہاں ایک ظالمانہ حصہ ہے، جو تاجروں کو ان کی اپنی آنکھوں پر عدم اعتماد کرتا ہے۔ آپ سمت کے بارے میں درست ہو سکتے ہیں اور پھر بھی پیسے کھو سکتے ہیں، کیونکہ چاہنے والا اس اقدام سے زیادہ واپس لے لیتا ہے۔</p>\n<p>RELIANCE کے ساتھ اس کے ذریعے چلیں۔ فرض کریں کہ نتائج آنے والے ہیں اور 1320 کال کی بولی تقریباً 50 روپے فی شیئر تک سوجی ہوئی IV پر لگائی گئی ہے۔ آپ اچھے نمبروں کی توقع رکھتے ہیں، آپ کال خریدتے ہیں، اور آپ صحیح ہیں۔ RELIANCE نتیجہ پر 1318 سے 1345 تک بڑھتا ہے۔ کال اب حقیقی طور پر 25 روپے فی شیئر کے حساب سے ہے، جو کہ حقیقی اندرونی قیمت ہے جو آپ کے پاس پہلے نہیں تھی۔ اور پھر بھی کال تقریباً 35 روپے فی شیئر پر ٹریڈنگ ہو سکتی ہے، کیونکہ مضمر اتار چڑھاؤ نے زیادہ تر وقت کی قیمت کو کچل دیا ہے اور چھین لیا ہے جو اوپر بیٹھی تھی۔ آپ نے تقریباً 50 روپے ادا کیے اور آپشن کی قیمت تقریباً 35 روپے ہے۔ آپ درست سمت میں تھے اور آپ نے پھر بھی تقریباً 15 روپے فی شیئر کا نقصان کیا، جو کہ 500 کی ایک لاٹ پر تقریباً 7500 روپے ہے۔</p>\n<p>یہ ایک مثال میں پورا واقعہ ٹریپ ہے۔ یہ اقدام حقیقی تھا، لیکن یہ اس اقدام سے چھوٹا تھا جس کی قیمت پہلے سے فلائی ہوئی پریمیم میں تھی۔ ہجوم نے پہلے ہی اصل میں پہنچنے والے سے بڑی چھلانگ کے لئے ادائیگی کر دی تھی، اور کچلنے والے نے اس زائد ادائیگی کو براہ راست بیچنے والے کے حوالے کر دیا۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>کسی معروف ایونٹ سے عین قبل مہنگا پریمیم خریدنا سب سے زیادہ قابل اعتماد طریقوں میں سے ایک ہے جس میں ایک ابتدائی شخص صحیح ہونے کے دوران پیسے کھو دیتا ہے۔ آپ فلائی ہوئی، اونچی IV قیمت ادا کرتے ہیں، ایونٹ گزر جاتا ہے، مضمر اتار چڑھاؤ کو کچل دیا جاتا ہے، اور پریمیم گرتا ہے حالانکہ اسٹاک آپ کے راستے میں چلا گیا ہے۔ مارکیٹ نے پہلے ہی متوقع اقدام کی قیمت مقرر کر دی تھی جو آپ نے ادا کی تھی۔</p>\n</div></div>\n<h2 id=\"how-sellers-try-to-use-the-crush\">بیچنے والے کس طرح کچلنے کی کوشش کرتے ہیں۔</h2>\n<p>اگر کرش خریداروں کو سزا دیتا ہے، تو آپ اندازہ لگا سکتے ہیں کہ بیچنے والے اس کے دوسری طرف کھڑے ہونے کی کوشش کرتے ہیں، اور وہ کرتے ہیں۔ ایک بیچنے والا چربی، پری ایونٹ پریمیم جمع کرتا ہے اور اس کا مقصد اس میں سے زیادہ تر کو برقرار رکھنا ہے کیونکہ IV بعد میں گر جاتا ہے۔ خوف کے ختم ہوجانے کے بعد امیر، واقعات سے بڑھے ہوئے اتار چڑھاؤ میں بیچنا اور سستی واپس خریدنا کتاب کے قدیم ترین ڈراموں میں سے ایک ہے۔</p>\n<p>لیکن یہ مفت پیسہ نہیں ہے، اور یہ صاف طور پر کہا جانا چاہئے. ایک برہنہ بیچنے والا جو بائنری ایونٹ میں آپشن کو شارٹ کرتا ہے اگر نتیجہ غلط سمت میں سخت حیرانی کا باعث بنتا ہے تو اسے مکمل حرکت میں لایا جاتا ہے۔ کچلنے سے صرف اس صورت میں مدد ملتی ہے جب اصل اقدام اس حد کے اندر رہتا ہے جس کی مارکیٹ میں پہلے سے قیمت ہے۔ اگر RELIANCE اس حد سے بہت آگے ہے، تو اس اقدام سے بیچنے والے کا نقصان جمع شدہ پریمیم کو کم کر سکتا ہے اور کچلنے والی مدد کو بونا کر سکتا ہے۔ یہی وجہ ہے کہ محتاط تاجر ایونٹ کے پریمیم کی کٹائی کرتے ہیں۔ <strong>طے شدہ خطرہ</strong> ڈھانچے، جہاں خریدا ہوا آپشن ننگے بیچنے کے بجائے بیچے جانے والے کے نقصان کو پورا کرتا ہے۔ ایک ننگے شارٹ انڈیکس آپشن پہلے سے ہی تقریباً 1.5 لاکھ سے 1.8 لاکھ روپے فی لاٹ مارجن کو روکتا ہے کیونکہ یہ خطرہ بڑا ہوتا ہے، اور ایک واقعہ اسے بڑا بنا دیتا ہے۔</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>کرش بیچنے والے کو تب ہی انعام دیتا ہے جب حقیقی اقدام اس اقدام کی قیمت سے چھوٹا ہو۔ یہی وجہ ہے کہ ایونٹ کی فروخت کا تعلق ایک متعین خطرے والے ڈھانچے میں ہے، نہ کہ ننگے شارٹ، اور یہ ابتدائی تجارت کیوں نہیں ہے۔</p>\n</div></div>\n<h2 id=\"trading-around-an-event-safely-or-not-at-all\">کسی ایونٹ کے ارد گرد محفوظ طریقے سے تجارت کرنا، یا بالکل نہیں۔</h2>\n<p>آپ کو ہر ایونٹ کی تجارت کرنے کی ضرورت نہیں ہے۔ درحقیقت سب سے زیادہ ابتدائی لوگوں کے لیے سب سے محفوظ جواب یہ ہے کہ آپ سب سے زیادہ شور مچاتے ہوئے ہاتھ پر ہاتھ دھرے بیٹھیں۔ لیکن اگر آپ مشغول ہونا چاہتے ہیں تو، چند عادتیں آپ کو پسندیدگی میں جانے سے روکتی ہیں۔</p>\n<ul>\n<li><strong>خریدنے سے پہلے کیلنڈر جانیں۔</strong> چیک کریں کہ آیا نتائج، ایک RBI پالیسی، بجٹ یا الیکشن آپ کی میعاد ختم ہونے سے پہلے۔ ایک ایسا اختیار جس کی زندگی کسی معروف واقعہ کو گھیرے میں لے جائے اس میں واقعہ کا خطرہ ہوتا ہے چاہے آپ اسے چاہیں یا نہیں۔</li>\n<li><strong>قیمت میں آنے والے اقدام کا احترام کریں۔</strong> اگر آپ کو کسی ایونٹ کے ذریعے خریدنا ضروری ہے، تو قبول کریں کہ آپ فلایا ہوا IV ادا کر رہے ہیں اور یہ کہ حقیقی اقدام کو جیتنے کے لیے متوقع اقدام کو شکست دینا ہے، نہ کہ صرف صحیح راستہ بتانا۔</li>\n<li><strong>ریمپ سے پہلے خریدیں، چوٹی پر نہیں۔</strong> اگر آپ کا نظریہ ہے تو، اتار چڑھاؤ کے پرسکون ہونے کے دوران پوزیشن حاصل کرنا ایک دن پہلے سوجن پریمیم میں خریدنے سے کہیں زیادہ سستا ہے۔</li>\n<li><strong>چاہنے والوں کے انتظار پر غور کریں۔</strong> اگر آپ کا نظریہ ایونٹ میں زندہ رہتا ہے، تو پریمیم سستا اور بعد میں پرسکون ہوتا ہے، ایک بار جب خوف ختم ہوجاتا ہے۔ ایسا کوئی اصول نہیں ہے جو کہتا ہو کہ آپ کو پہلے سے ہی اندر ہونا چاہیے۔</li>\n<li><strong>اگر آپ فروخت کرتے ہیں تو اپنے خطرے کی وضاحت کریں۔</strong> بائنری ایونٹ میں کبھی بھی برہنہ نہ ہوں۔ اگر نتیجہ حیرت زدہ ہو تو خریدے گئے آپشن کو نقصان کو کم کرنے دیں۔</li>\n</ul>\n<p>واقعات کا سب سے گہرا سبق یہ ہے کہ آپشن مارکیٹ بولی نہیں ہے۔ جب ہر کوئی کسی بڑے اقدام کی توقع رکھتا ہے، تو وہ توقع پہلے سے ہی اس قیمت پر بیٹھی ہوتی ہے جو آپ ادا کرتے ہیں۔ آپشن صرف خریدار کو انعام دیتا ہے اگر حقیقی اقدام پہلے سے ادا کیے گئے ہجوم سے بڑا ہو، اور زیادہ تر وقت ایسا نہیں ہوتا ہے۔ اس تال کو ذہن میں رکھیں اور آپ کمائی کے سیزن اور پالیسی کے دنوں کو آسان رقم سمجھنا بند کر دیں گے، اور ان کو اعلیٰ قیمت، اعلیٰ جال والے لمحات کے طور پر سمجھنا شروع کر دیں گے جو وہ واقعی ہیں۔ اگلا باب اس اور ہر دوسرے خطرے کو ایک جگہ جمع کرتا ہے: ابتدائی طور پر کیسے اڑتے ہیں، اور نظم و ضبط جو آپ کو کھیل میں رکھتا ہے۔</p>\n","toc":[{"level":2,"text":"اختیارات واقعات کے کیلنڈر پر رہتے ہیں۔","id":"options-live-on-a-calendar-of-events"},{"level":2,"text":"واقعہ سے پہلے: مضمر اتار چڑھاؤ پھیلتا ہے۔","id":"before-the-event-implied-volatility-expands"},{"level":2,"text":"ایونٹ کے بعد: IV کو کچلنا","id":"after-the-event-the-iv-crush"},{"level":2,"text":"صحیح سمت میں، اب بھی سرخ رنگ میں","id":"right-on-direction-still-in-the-red"},{"level":2,"text":"بیچنے والے کس طرح کچلنے کی کوشش کرتے ہیں۔","id":"how-sellers-try-to-use-the-crush"},{"level":2,"text":"کسی ایونٹ کے ارد گرد محفوظ طریقے سے تجارت کرنا، یا بالکل نہیں۔","id":"trading-around-an-event-safely-or-not-at-all"}],"imgCount":1,"hasContent":true},"25":{"html":"<p>کوئی بھی ایک بار غلط ہو کر اکاؤنٹ نہیں اڑاتا ہے۔ لوگ اس طریقے سے غلط ہو کر اڑا دیتے ہیں جو زندہ رہنے کے لیے بہت بڑی تھی، یا ایک چھوٹی غلطی کو دہراتے ہوئے جب تک کہ وہ بڑی نہ ہو جائے۔ تقریباً ہر ابتدائی طور پر جو آپشنز میں بری طرح سے ہار جاتا ہے وہ قابل گریز غلطیوں کی اسی مختصر فہرست کے ذریعے کرتا ہے، اور ان میں سے تقریباً ہر ایک غلطی خطرے سے متعلق ہے، سمت کے بارے میں نہیں۔ آپ ایک غریب پیشن گوئی کرنے والے ہو سکتے ہیں اور پھر بھی سالوں تک زندہ رہ سکتے ہیں اگر آپ کے خطرے پر قابو پالیا جائے۔ آپ ایک شاندار پیشن گوئی کرنے والے ہو سکتے ہیں اور اگر ایسا نہیں ہے تو ایک مہینے میں آپ کا صفایا ہو سکتا ہے۔ یہ باب دوبارہ پڑھنے کے لیے ہے، کیونکہ یہ صحیح ہونے کے بارے میں کم اور اچھا ہونے کے لیے کافی دیر تک زندہ رہنے کے بارے میں زیادہ ہے۔</p>\n<h2 id=\"size-the-position-by-the-premium-at-risk\">خطرے میں پریمیم کی طرف سے پوزیشن کا سائز</h2>\n<p>پہلا نظم سب سے آسان اور سب سے زیادہ نظر انداز کیا جاتا ہے۔ <strong>پوزیشن کا سائز</strong> اس کا مطلب یہ ہے کہ کسی اور چیز سے پہلے یہ فیصلہ کرنا کہ اس واحد تجارت کو کتنی رقم ضائع ہونے کی اجازت ہے۔ ایک طویل آپشن کے لیے، وہ نمبر آسان اور ظالمانہ ہے: آپ جو پورا پریمیم ادا کرتے ہیں وہ صفر تک جا سکتا ہے۔ ایک آپشن جو ختم ہونے پر پیسہ ختم کر دیتا ہے اس کی کوئی قیمت نہیں ہے، لہذا مکمل پریمیم حقیقی طور پر خطرے میں ہے، ہر بار۔</p>\n<p>یہ تبدیل کرتا ہے کہ آپ کو ایک ہی لاٹ کے بارے میں کس طرح سوچنا چاہئے۔ ایک RELIANCE 1320 آپشن کی قیمت تقریباً 31 روپے فی شیئر ہے، جو کہ 500 کی ایک لاٹ کے لیے تقریباً 15,590 روپے ہے، اور یہ سب ختم ہو سکتا ہے۔ اگر آپ کا ٹریڈنگ اکاؤنٹ 2 لاکھ روپے ہے، تو وہ ایک لاٹ پہلے ہی آپ کے پورے اکاؤنٹ کا تقریباً آٹھ فیصد ایک ہی آپشن پر رکھتا ہے جس کی میعاد ختم ہو سکتی ہے۔ تین لاٹ لگائیں اور آپ نے ایک شرط پر اپنے اکاؤنٹ کا تقریباً ایک چوتھائی حصہ خطرے میں ڈال دیا ہے جو کہ سمت، سائز اور وقت کے لحاظ سے ایک ساتھ درست ہونا چاہیے۔</p>\n<p>ایک سمجھدار اصول یہ ہے کہ آپ اپنے اکاؤنٹ کے ایک چھوٹے سے حصے میں، اکثر دو سے پانچ فیصد کے علاقے میں، کسی بھی ایک آپشن میں ڈالے گئے پریمیم کو محدود کر دیں، تاکہ اس تجارت پر ہونے والا کل نقصان ایک زخم ہو نہ کہ زخم۔ صحیح نمبر آپ کا انتخاب کرنا ہے۔ نقطہ یہ ہے کہ آپ اسے جان بوجھ کر منتخب کرتے ہیں، داخل ہونے سے پہلے، اور بعد میں گھبراہٹ میں نہیں۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>ایک طویل آپشن کے لیے، آپ کی پوزیشن کا سائز آپ کا زیادہ سے زیادہ نقصان ہے، کیونکہ پریمیم صفر تک جا سکتا ہے۔ پہلے فیصلہ کریں کہ آپ تجارت میں کیا کھونا چاہتے ہیں، پھر معلوم کریں کہ کتنی لاٹیں اس کی اجازت دیتی ہیں۔ اپنی مطلوبہ لاٹ خرید کر اور بعد میں خطرے کا پتہ لگا کر کبھی بھی آرڈر کو الٹ نہ کریں۔</p>\n</div></div>\n<h2 id=\"know-your-maximum-loss-before-you-enter\">داخل ہونے سے پہلے اپنے زیادہ سے زیادہ نقصان کو جان لیں۔</h2>\n<p>سائز سازی سے منسلک ایک عادت ہے جو تاجروں کو جواریوں سے الگ کرتی ہے: آپ کو یہ بتانے کے قابل ہونا چاہیے کہ آپ اپنا <strong>زیادہ سے زیادہ نقصان</strong> خریدنے پر کلک کرنے سے پہلے اونچی آواز میں۔ اس کورس کے ڈھانچے کے لیے یہ جاننا مشکل نہیں ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>پوزیشن</th>\n<th>آپ کیا کرتے ہیں</th>\n<th>داخلے سے پہلے زیادہ سے زیادہ نقصان</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>لمبی کال یا لمبی پوٹ</td>\n<td>پریمیم ادا کریں۔</td>\n<td>پریمیم ادا کیا گیا، تقریباً 15,590 روپے فی RELIANCE لاٹ، اور مزید نہیں</td>\n</tr>\n<tr>\n<td>مختصر کال (ننگی)</td>\n<td>پریمیم جمع کریں۔</td>\n<td>اسٹاک بڑھتے ہی بڑا اور مؤثر طریقے سے لامحدود</td>\n</tr>\n<tr>\n<td>شارٹ پٹ (ننگا)</td>\n<td>پریمیم جمع کریں۔</td>\n<td>بہت بڑا کیونکہ اسٹاک صفر کی طرف گرتا ہے۔</td>\n</tr>\n</tbody></table>\n<p>خریدار کا پہلو تسلی بخش ہے اور بیچنے والے کا پہلو پرسکون ہے، اور یہی ایماندارانہ تصویر ہے۔ ایک ننگا بیچنے والا صرف جمع شدہ پریمیم کا خطرہ نہیں رکھتا۔ ایک ننگے شارٹ انڈیکس آپشن تقریباً 1.5 لاکھ سے 1.8 لاکھ روپے فی لاٹ مارجن کو روکتا ہے کیونکہ نقصان موصول ہونے والے پریمیم سے کہیں زیادہ ہو سکتا ہے۔ اگر آپ داخل ہونے سے پہلے ایک جملے میں اپنا زیادہ سے زیادہ نقصان نہیں کہہ سکتے تو آپ تجارت لینے کے لیے تیار نہیں ہیں۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>اختیارات کو ننگا فروخت کرنا کیونکہ پریمیم آسان آمدنی کی طرح لگتا ہے کہ کس طرح ابتدائی افراد ایک چھوٹا سا، مستحکم کریڈٹ لیتے ہیں اور ایک دن میں اس رقم کو ایک ہی وقفے پر کئی گنا واپس کرتے ہیں۔ آپ جو پریمیم جمع کرتے ہیں وہ اس نقصان کے برابر ہے جو آپ نے قبول کیا ہے۔ اس وقت تک کبھی بھی برہنہ نہ بیچیں جب تک کہ آپ اس مارجن اور اس خطرے کو سمجھ نہ لیں جو آپ اٹھا رہے ہیں۔</p>\n</div></div>\n<h2 id=\"stop-loss-thinking-versus-a-defined-risk-structure\">سٹاپ لوس سوچ بمقابلہ طے شدہ خطرے کی ساخت</h2>\n<p>زیادہ تر تاجروں کو a کا استعمال کرنا سکھایا جاتا ہے۔ <strong>روکنے کا نقصان</strong>، نقصان کے ایک مقررہ سطح تک پہنچنے کے بعد باہر نکلنے کا حکم۔ اسٹاپ مفید ہیں، لیکن اختیارات اسٹاکس کے مقابلے میں بولی اسٹاپ کو سخت سزا دیتے ہیں۔ آپشن کی قیمتوں میں فرق، خاص طور پر غیر قانونی ہڑتالوں اور واقعات کے آس پاس، اس لیے آپ کا اسٹاپ آپ کے سیٹ کردہ لیول کے قریب کہیں بھی پُر نہیں ہو سکتا۔ ایک مخصوص پریمیم پر رکنا ایک خواہش ہے، ضمانت نہیں، جب مارکیٹ سیدھی چھلانگ لگاتی ہے۔</p>\n<p>مضبوط خیال تجارت میں ہی خطرے کی حد کو بڑھانا ہے۔ اے <strong>طے شدہ خطرہ</strong> ڈھانچہ وہ ہوتا ہے جہاں بدترین نتائج کا تعین پوزیشن کے ذریعے کیا جاتا ہے، نہ کہ کسی ایسے آرڈر کے ذریعے جسے وقت پر بھرنا پڑتا ہے۔ سب سے سادہ بیان کردہ خطرے کی تجارت جس کے بارے میں آپ پہلے سے جانتے ہیں صرف ایک آپشن خریدنا ہے: آپ کا نقصان پریمیم سے زیادہ نہیں ہو سکتا چاہے سٹاک کتنی ہی پرتشدد حرکت کرے، کیونکہ آپ کی ادائیگی سے زیادہ کچھ نہیں ہے۔ اگلا کورس اس آئیڈیا کو اسپریڈز کے ساتھ بناتا ہے، جہاں خریدا ہوا آپشن بیچنے والے کے نقصان کو محدود کرتا ہے، تاکہ ایک ننگی نظر آنے والی فروخت بھی ایک معروف، حد سے زیادہ نقصان کے ساتھ تجارت بن جائے۔ ابھی کے لیے سبق یہ ہے کہ ڈھانچہ قوت ارادی کو مات دیتا ہے۔ ایک نقصان جو پوزیشن کی طرف سے محدود ہے ایک تیز مارکیٹ یا سست انگلی سے چوڑا نہیں کیا جا سکتا.</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>کسی ایسے ڈھانچے کو ترجیح دیں جس کی خراب ترین صورت آپ کو سٹاپ لاس کے آرڈر میں داخل ہونے سے پہلے طے کر دی گئی ہو جسے تیزی سے مارکیٹ میں لاگو کرنا پڑتا ہے۔ بہترین رسک کنٹرول وہ ہے جو آپ کے دباؤ میں صحیح طریقے سے ردعمل ظاہر کرنے پر منحصر نہیں ہے۔</p>\n</div></div>\n<h2 id=\"avoid-revenge-trades-especially-on-expiry-day\">انتقامی تجارت سے گریز کریں، خاص طور پر ایکسپائری کے دن</h2>\n<p>سب سے مہنگی تجارت جذباتی ہوتی ہے۔ اے <strong>انتقامی تجارت</strong> وہی ہے جسے آپ جیتنے کے لیے لے جاتے ہیں جو نقصان آپ کو ابھی اٹھانا پڑا ہے، جس کا سائز بہت بڑا ہے اور بہت تیزی سے منتخب کیا گیا ہے، کیونکہ آپ تجزیاتی کے بجائے ناراض ہیں۔ مارکیٹ یہ نہیں جانتی یا اس کی پرواہ نہیں کرتی ہے کہ آپ نیچے ہیں، اور اسے آپ کو واپس کرنے کے لیے مجبور کرنے کی کوشش کرنا یہ ہے کہ کس طرح قابل انتظام نقصان ایک تباہ کن دن بن جاتا ہے۔</p>\n<p>ایکسپائری ڈے وہ ہے جہاں یہ مہلک ہو جاتا ہے۔ آخری دن، پیسے سے باہر سستے اختیارات ہر جگہ موجود ہیں، وقت کی قدر گھنٹے کے حساب سے گر رہی ہے، اور نقصان کی وصولی کے لیے لاٹری ٹکٹ پر دوگنا ہونے کا لالچ بہت زیادہ ہے۔ یہ بالکل غلط لمحہ ہے۔ تھیٹا انتہائی سفاکانہ ہے، دور کے آپشن پر مشکلات سب سے زیادہ خراب ہیں، اور آپ کا فیصلہ نقصان کے بعد سب سے کمزور ہے۔ نظم و ضبط سادہ ہے: جب آپ اسے فوری طور پر واپس کرنے کی خواہش محسوس کرتے ہیں، تو یہ دن کے لیے تجارت بند کرنے کا اشارہ ہے، نہ کہ سائز بڑھانے کا۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>ایک بڑی، تیز تجارت کے ساتھ نقصان کا پیچھا کرنا واحد سب سے عام طریقہ ہے جو ایک برا دن بن جاتا ہے۔ یہ معیاد ختم ہونے کے دن سب سے زیادہ خطرناک ہوتا ہے، جب سستے اختیارات اور وقت کی قدر میں کمی آپ کو فلیٹ پر واپسی کا جوا کھیلنے پر آمادہ کرتی ہے۔ اس کے بجائے اسکرین سے دور چلیں۔</p>\n</div></div>\n<h2 id=\"the-recurring-mistakes\">بار بار ہونے والی غلطیاں</h2>\n<p>تقریباً ہر ابتدائی آفت مٹھی بھر دہرائی جانے والی غلطیوں میں سے ایک ہے۔ انہیں نام سے پہچاننا سیکھیں اور آپ خود کو اس عمل میں پکڑ لیں گے۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-basics/images/diagram-common-mistakes.png\" alt=\"بار بار ہونے والی ابتدائی غلطیاں ایک ساتھ رکھی گئی ہیں، لاٹری کے بہت دور کے اختیارات خریدنے اور ہارنے والے کو اوسطاً کم کرنے سے لے کر ایکسپائری تک ہولڈنگ، IV کو نظر انداز کرنے، غیر قانونی ہڑتالوں کی تجارت اور مارجن کا احترام کیے بغیر برہنہ فروخت کرنا۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>بار بار ہونے والی ابتدائی غلطیوں کو ایک ساتھ پیش کیا گیا ہے، بہت دور لاٹری کے آپشنز خریدنے اور ہارنے والے کو اوسطاً کم کرنے سے لے کر ایکسپائری تک ہولڈنگ، IV کو نظر انداز کرنے، غیر قانونی ہڑتالوں کی تجارت اور مارجن کا احترام کیے بغیر برہنہ فروخت کرنا۔</figcaption></figure>\n<ul>\n<li><strong>پیسے سے باہر لاٹری کے اختیارات خریدنا۔</strong> وہ سستے ہیں کیونکہ ان کا امکان نہیں ہے۔ پریمیم ہر وقت کی قیمت اور امید ہے، اور بڑی اکثریت کی میعاد بے کار ہے۔ کبھی کبھار جیک پاٹ کی کہانی خاموش کل نقصانات کی ایک لمبی لائن کو چھپاتی ہے۔</li>\n<li><strong>کھونے والے آپشن پر اوسط کم کرنا۔</strong> گرنے والے آپشن میں مزید اضافہ کرنا پگھلنے والے، وقت کے زوال پذیر اثاثے میں رقم کا اضافہ کرنا ہے۔ حصص کے برعکس، ایک آپشن کی میعاد ختم ہوتی ہے، اور اگر یہ آخر میں پیسے سے باہر ہے تو اس کی کوئی قیمت نہیں ہے چاہے آپ کی اوسط قیمت کتنی ہی کم ہو۔</li>\n<li><strong>ایکسپائری ڈے کے آپشن کو آنکھیں بند کر کے رکھنا۔</strong> وقت کی قدر ختم ہو جاتی ہے، پیسے سے باہر ہونے والا آپشن بیکار ہو جاتا ہے، اور ایک اسٹاک آپشن جو پیسے کے اندر ہی ختم ہو جاتا ہے، آپ کو کئی لاکھ مالیت کی غیر مطلوبہ ڈیلیوری یا اسائنمنٹ کی ذمہ داری سونپ سکتا ہے۔ قریب آنے کی امید کرنے کے بجائے وقت پر چوکنا۔</li>\n<li><strong>IV کو نظر انداز کرنا۔</strong> کسی معروف ایونٹ سے پہلے مہنگا پریمیم خریدنا، پھر بعد میں مضمر اتار چڑھاؤ کو گرتا دیکھنا، آپ کی سمت درست ہونے پر بھی پیسہ ضائع ہو جاتا ہے۔ ایونٹ کیلنڈر کا احترام کریں۔</li>\n<li><strong>غیر قانونی ہڑتالوں کی تجارت۔</strong> بہت دور، بہت کم تجارت کی گئی سٹرائیک میں بولی اور پوچھنے کے درمیان کافی فاصلہ ہوتا ہے، لہذا آپ داخل ہونے کے لیے زیادہ ادائیگی کرتے ہیں اور باہر نکلنے کے لیے کم قیمت حاصل کرتے ہیں، اور تیز مارکیٹ میں آپ بالکل بھی باہر نہیں نکل پائیں گے۔</li>\n<li><strong>مارجن کو سمجھے بغیر ننگا بیچنا۔</strong> بڑے، غیر متعینہ خطرہ اور بھاری مارجن بلاک کو لے کر ایک چھوٹا پریمیم جمع کرنا بیچنے والے کا کلاسک ٹریپ ہے، اور ایک وقفہ مہینوں کے کریڈٹ کو مٹا سکتا ہے۔</li>\n</ul>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>یاد رکھیں کہ ان غلطیوں میں سے کوئی بھی غلط سمت کی پیش گوئی کرنے کے بارے میں نہیں ہے۔ ان میں سے ہر ایک خطرے کے انتظام میں ناکامی ہے: بہت زیادہ امید، بہت زیادہ سائز، بہت کم لیکویڈیٹی، یا وقت اور واقعات کا بہت کم احترام۔ خطرے کو ٹھیک کریں اور زیادہ تر ہارنے والے خود ہی ٹھیک کریں۔</p>\n</div></div>\n<h2 id=\"when-not-to-trade-options\">جب NOT تجارت کے اختیارات پر</h2>\n<p>نظم و ضبط ان تجارتوں کے بارے میں ہے جتنا آپ چھوڑتے ہیں جتنا آپ لیتے ہیں۔ جب ان میں سے کوئی بھی درست ہو تو آپشن اسکرین سے مکمل طور پر ہٹ جائیں۔</p>\n<ul>\n<li>آپ داخل ہونے سے پہلے، چارجز کے بعد، اپنے زیادہ سے زیادہ نقصان اور اپنے بریک ایون کو نہیں بتا سکتے۔</li>\n<li>آپ اس نقصان کو واپس جیتنے کی کوشش کر رہے ہیں جو آپ نے ابھی لیا ہے۔ یہ تجارت کی بدترین ممکنہ وجہ ہے۔</li>\n<li>بولی پوچھنے کے وسیع فرق اور پتلی حجم اور کھلی دلچسپی کے ساتھ ہڑتال غیر قانونی ہے۔ آپ باہر نکلنے کے قابل نہیں ہوسکتے ہیں۔</li>\n<li>ایک معروف واقعہ مضمر اتار چڑھاؤ کو کچلنے والا ہے اور آپ اس میں فلایا ہوا پریمیم خرید رہے ہوں گے۔</li>\n<li>یہ میعاد ختم ہونے والی دوپہر ہے اور آپ کو خوش قسمتی حاصل کرنے کے طریقے کے طور پر پیسے سے باہر کے سستے اختیارات کا لالچ دیا جاتا ہے۔</li>\n<li>آپ مارجن، اسائنمنٹ رسک اور سٹاک آپشن پر ڈیلیوری کی ذمہ داری کو سمجھے بغیر برہنہ فروخت کر رہے ہوں گے۔</li>\n<li>خطرے میں رقم وہ رقم ہے جس کی آپ کو درحقیقت ضرورت ہے، رہنے کے اخراجات کے لیے، قرض کے لیے، یا کسی ایسی چیز کے لیے جو ضائع نہ ہو سکے۔</li>\n</ul>\n<p>اس میں سے کوئی بھی آپ کو اختیارات سے خوفزدہ کرنے کے لیے نہیں ہے۔ کنٹرول کے ساتھ استعمال کیا جاتا ہے، ایک آپشن ان چند آلات میں سے ایک ہے جو آپ کو معلوم بدترین صورت کے ساتھ ایک تیز، متعین خطرے کا نظارہ کرنے دیتا ہے۔ خطرہ کبھی بھی ہتھیار نہیں ہوتا۔ یہ بغیر سائز کی شرط، بدلے کی تجارت، لاٹری ٹکٹ اور بغیر کسی احترام کے لیا گیا ننگا شارٹ ہے۔ خطرے کو صحیح طریقے سے حاصل کریں اور آپ اپنے آپ کو ایک چیز خریدیں جو درحقیقت وقت کے ساتھ ساتھ تاجروں کو اچھا بناتی ہے، جو کہ بقا ہے۔ آخری باب اس مستقبل کی طرف موڑتا ہے: اسپریڈز کس طرح آپ کو جان بوجھ کر خطرے کی وضاحت کرنے دیتے ہیں، اور آپ کی ہر تجارت سے پہلے چلانے کے لیے ایک سادہ چیک لسٹ۔</p>\n","toc":[{"level":2,"text":"خطرے میں پریمیم کی طرف سے پوزیشن کا سائز","id":"size-the-position-by-the-premium-at-risk"},{"level":2,"text":"داخل ہونے سے پہلے اپنے زیادہ سے زیادہ نقصان کو جان لیں۔","id":"know-your-maximum-loss-before-you-enter"},{"level":2,"text":"سٹاپ لوس سوچ بمقابلہ طے شدہ خطرے کی ساخت","id":"stop-loss-thinking-versus-a-defined-risk-structure"},{"level":2,"text":"انتقامی تجارت سے گریز کریں، خاص طور پر ایکسپائری کے دن","id":"avoid-revenge-trades-especially-on-expiry-day"},{"level":2,"text":"بار بار ہونے والی غلطیاں","id":"the-recurring-mistakes"},{"level":2,"text":"جب NOT تجارت کے اختیارات پر","id":"when-not-to-trade-options"}],"imgCount":1,"hasContent":true},"26":{"html":"<p>واپس دیکھو جہاں سے تم نے شروع کیا تھا۔ چند ابواب پہلے کے الفاظ کال اور پوٹ آپ کے لیے کوئی معنی نہیں رکھتے تھے۔ اب آپ RELIANCE28JUL261320CE جیسی علامت کو پڑھ سکتے ہیں، 31 روپے کے پریمیم کو اندرونی قدر اور وقت کی قدر میں تقسیم کر سکتے ہیں، 1351 پر بھی ایک لمبی کال بریکنگ کی تصویر بنا سکتے ہیں، اور اس بات کا احترام کر سکتے ہیں کہ ننگا مختصر آپشن کیوں نقصان پہنچا سکتا ہے۔ یہ حقیقی ترقی ہے، اور آپ نے اسے حاصل کیا ہے۔ یہ آخری باب دو چیزیں کرتا ہے۔ سب سے پہلے، یہ ان واحد اختیارات سے ایک مختصر پل بناتا ہے جو آپ نے اسپریڈز کی دنیا کے لیے سیکھے ہیں، جہاں سے اگلا کورس شروع ہوتا ہے۔ دوسرا، یہ آپ کو آرڈر دینے سے پہلے چلانے کے لیے ایک سادہ پری ٹریڈ چیک لسٹ فراہم کرتا ہے، اس لیے آپ نے جو نظم و ضبط یہاں بنایا ہے وہ آپ کے ساتھ ہر تجارت میں سفر کرتا ہے۔</p>\n<h2 id=\"from-one-leg-to-two-why-spreads-exist\">ایک ٹانگ سے دو تک: پھیلاؤ کیوں موجود ہے۔</h2>\n<p>اس کورس میں ہر تجارت نے ایک ہی آپشن استعمال کیا ہے، ایک کال یا ایک پٹ، خریدا یا بیچا۔ تاجر ہر ایک آپشن کو کال کرتے ہیں۔ <strong>ٹانگ</strong>. اے <strong>پھیلاؤ</strong> صرف دو ٹانگوں کو ایک پوزیشن میں ملا کر منتخب کیا جاتا ہے تاکہ وہ ایک ساتھ کام کریں۔</p>\n<p>زحمت کیوں؟ فروخت کے اختیارات پر واپس سوچیں۔ ایک ننگی شارٹ کال میں سٹرائیک کے اوپر لامحدود خطرہ ہوتا ہے، اور قیمت گرنے کے ساتھ ہی ننگے شارٹ پٹ میں بہت بڑا خطرہ ہوتا ہے۔ آپ جو پریمیم جمع کرتے ہیں وہ محدود ہے، لیکن نقصان نہیں ہے۔ یہ عدم توازن ہی ایک ابتدائی کے لیے ننگی فروخت کو خطرناک بناتا ہے، اور یہی وجہ ہے کہ ایک ننگے شارٹ انڈیکس آپشن ایک لاٹ کے لیے تقریباً 1.5 سے 1.8 لاکھ روپے کے مارجن کو روکتا ہے۔</p>\n<p>ایک اسپریڈ بالکل اس مسئلے کو ٹھیک کرتا ہے۔ آپ پریمیم جمع کرنے کے لیے ایک آپشن بیچتے ہیں، اور اسی وقت آپ بیک اسٹاپ کے طور پر کام کرنے کے لیے ایک اور آپشن خریدتے ہیں۔ آپ جو آپشن خریدتے ہیں وہ آپ کے بیچے گئے آپشن کے نقصان کو پورا کرتا ہے۔ آپ کا غیر متعینہ خطرہ بن جاتا ہے۔ <strong>طے شدہ خطرہ</strong> پوزیشن: ایک معلوم، مقررہ زیادہ سے زیادہ نقصان جو بڑھ نہیں سکتا چاہے مارکیٹ کتنی ہی دور چل رہی ہو۔ چونکہ خطرہ محدود ہے، اس لیے درکار مارجن میں بھی تیزی سے کمی آئی ہے۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>ایک اسپریڈ دو ٹانگوں کو جوڑتا ہے لہذا خریدا ہوا آپشن فروخت شدہ آپشن کے خطرے کو کم کرتا ہے۔ غیر متعینہ خطرے کی تجارت ایک متعین خطرہ بن جاتی ہے، جس میں داخل ہونے سے پہلے آپ کو زیادہ سے زیادہ نقصان معلوم ہوتا ہے۔</p>\n</div></div>\n<p>یہ واحد خیال، دوسری ٹانگ کے ساتھ خطرے کو محدود کرنا، تقریباً ہر آپشن کی حکمت عملی کی بنیاد ہے جس سے آپ کبھی ملیں گے۔</p>\n<h2 id=\"debit-spreads-and-credit-spreads\">ڈیبٹ اسپریڈز اور کریڈٹ اسپریڈز</h2>\n<p>اسپریڈز دو وسیع ذائقوں میں آتے ہیں، اور فرق صرف یہ ہے کہ جب آپ تجارت کھولتے ہیں تو رقم آپ کے اکاؤنٹ میں آتی ہے یا اس سے باہر ہوتی ہے۔</p>\n<p>اے <strong>ڈیبٹ پھیلاؤ</strong> وہ جگہ ہے جہاں آپ داخل ہونے کے لیے ادائیگی کرتے ہیں۔ آپ ایک آپشن خریدتے ہیں اور دوسرا سستا بیچتے ہیں، اس لیے آپ جو پریمیم بیچی ہوئی ٹانگ سے جمع کرتے ہیں وہ صرف جزوی طور پر اس پریمیم کو پورا کرتا ہے جو آپ خریدی ہوئی ٹانگ کے لیے ادا کرتے ہیں۔ آپ کو خالص رقم، ڈیبٹ ادا کرنا باقی ہے۔ بدلے میں، آپ کی لاگت اور آپ کا منافع دونوں محدود ہیں۔ آپ اکیلے آپشن خریدنے سے کم خرچ کرتے ہیں، اور وقت کی خرابی آپ کو کم تکلیف دیتی ہے، لیکن آپ لامحدود الٹا بھی چھوڑ دیتے ہیں۔ آپ انعام کی حد کے لیے ایک چھوٹی، سستی، پرسکون شرط کی تجارت کرتے ہیں۔</p>\n<p>اے <strong>کریڈٹ پھیلاؤ</strong> آئینہ ہے. آپ داخل ہونے کے لیے رقم وصول کرتے ہیں۔ آپ ایک آپشن بیچتے ہیں اور تحفظ کے لیے مزید سستا خریدتے ہیں، اس لیے آپ خالص پریمیم یعنی کریڈٹ رکھتے ہیں۔ آپ کو فائدہ ہوتا ہے اگر قیمت آپ کی توقع کے مطابق برتاؤ کرتی ہے، اکثر صرف آپ کی فروخت کی گئی ہڑتال کے دائیں جانب رہ کر، اور وقت کی کمی آپ کے حق میں کام کرتی ہے۔ آپ کا زیادہ سے زیادہ منافع وہ کریڈٹ ہے جو آپ نے جمع کیا ہے، اور آپ کے زیادہ سے زیادہ نقصان کو آپ نے خریدی ہوئی حفاظتی ٹانگ کے ذریعے محدود کیا ہے۔</p>\n<p>نیچے دی گئی جدول کسی بھی گہرائی میں جانے کے بغیر اس کے تضاد کو خاکہ بناتی ہے، کیونکہ نامزد حکمت عملیوں کی مکمل تعمیر اگلے کورس میں ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>فیچر</th>\n<th>ڈیبٹ پھیلاؤ</th>\n<th>کریڈٹ اسپریڈ</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>داخلے پر کیش</td>\n<td>آپ خالص پریمیم ادا کرتے ہیں۔</td>\n<td>آپ کو خالص پریمیم ملتا ہے۔</td>\n</tr>\n<tr>\n<td>زیادہ سے زیادہ منافع</td>\n<td>کیپڈ</td>\n<td>محدود، موصول ہونے والے کریڈٹ کے برابر</td>\n</tr>\n<tr>\n<td>زیادہ سے زیادہ نقصان</td>\n<td>کیپڈ، ادا کردہ ڈیبٹ کے برابر</td>\n<td>حفاظتی ٹانگ کی طرف سے کیپ</td>\n</tr>\n<tr>\n<td>وقت کا زوال</td>\n<td>آپ کے خلاف کام کرتا ہے، لیکن نرمی سے</td>\n<td>آپ کے حق میں کام کرتا ہے۔</td>\n</tr>\n<tr>\n<td>آپ قیمت چاہتے ہیں۔</td>\n<td>اپنا راستہ بڑھاؤ</td>\n<td>برتاؤ کریں، اکثر آپ کے خلاف حرکت نہ کریں۔</td>\n</tr>\n</tbody></table>\n<p>دونوں قسم کے پھیلاؤ ایک خوبصورت پراپرٹی کا اشتراک کرتے ہیں۔ زیادہ سے زیادہ نقصان طے ہوتا ہے اور اس وقت معلوم ہوتا ہے جب آپ پوزیشن کھولتے ہیں۔ یہی وجہ ہے کہ ایک ابتدائی شخص بالآخر ایک ٹانگوں سے پھیلنے تک گریجویٹ ہوتا ہے۔</p>\n<p>یہ وہ جگہ ہے جہاں اختیارات کا بنیادی کورس آپ کے حوالے کرتا ہے۔ اگلا کورس، /options-strategies کورس، ان دو خیالات کو لیتا ہے اور ان سے نامزد ڈھانچے بناتا ہے، عمودی، سٹرڈلز، آئرن کنڈورس اور مزید، ٹانگ بہ ٹانگ۔ اب آپ کے پاس وہ سب کچھ ہے جس کی آپ کو اسے شروع کرنے کی ضرورت ہے۔ آپ ایک زنجیر پڑھ سکتے ہیں، ایک ٹانگ کی قیمت لگا سکتے ہیں، ادائیگی کی تصویر بنا سکتے ہیں، اور سمجھ سکتے ہیں کہ دوسری ٹانگ کا خطرہ کیوں ہے۔ ابھی تک ان ڈھانچے کو چلانے کی کوشش نہ کریں۔ بس اتنا جان لیں کہ دروازہ کھلا ہے اور آپ اس سے گزرنے کے لیے تیار ہیں۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>کسی بھی حقیقی اسپریڈ کی تجارت کرنے سے پہلے، اسے پہلے سینڈ باکس ٹریڈنگ میں بنائیں (Analyzer mode in OpenAlgo) اور دیکھیں کہ دونوں ٹانگیں ایک ساتھ کیسے برتاؤ کرتی ہیں۔ مشترکہ ادائیگی کو ایک بار دیکھنا اس کے بارے میں دس بار پڑھنے سے زیادہ سکھاتا ہے۔</p>\n</div></div>\n<h2 id=\"the-pre-trade-checklist\">پری ٹریڈ چیک لسٹ</h2>\n<p>علم وہ چیز نہیں ہے جو آپ کے پیسے کی حفاظت کرے۔ نظم و ضبط ہے۔ جو تاجر زندہ رہتے ہیں وہ سب سے زیادہ چالاک نظریہ رکھنے والے نہیں ہوتے، وہ وہ ہوتے ہیں جو ہر ایک تجارت سے پہلے ایک ہی بورنگ چیک چلاتے ہیں۔ یہاں ایک ابتدائی ہے <strong>پری ٹریڈ چیک لسٹ</strong>. کسی بھی آپشن آرڈر، سنگل ٹانگ یا اسپریڈ کو دینے سے پہلے اس سب کو دوڑائیں۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-basics/images/diagram-pretrade-checklist.png\" alt=\"آٹھ پری ٹریڈ چیک ایک کلین کالم کے طور پر رکھے گئے ہیں، اوپر کی سمت سے لے کر نیچے کے ایگزٹ پلان تک، ہر آپشن آرڈر سے پہلے چلنے کا نظم۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>آٹھ پری ٹریڈ چیک ایک کلین کالم کے طور پر رکھے گئے ہیں، اوپر کی سمت سے لے کر نیچے کے ایگزٹ پلان تک، ہر آپشن آرڈر سے پہلے چلنے کا نظم۔</figcaption></figure>\n<table>\n<thead>\n<tr>\n<th>چیک کریں۔</th>\n<th>جواب دینے کا سوال</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>سمت</td>\n<td>مجھے کیا امید ہے، اور کب تک؟ اوپر، نیچے یا فلیٹ، اور کس تاریخ تک؟</td>\n</tr>\n<tr>\n<td>ہڑتال</td>\n<td>کون سی ہڑتال اس نقطہ نظر کے مطابق ہے؟ پیسے میں، پر یا باہر، اور وہ کیوں؟</td>\n</tr>\n<tr>\n<td>ختم</td>\n<td>کون سی میعاد اس اقدام کو کافی وقت دیتی ہے جس کی مجھے ضرورت نہیں ہے اس کی ادائیگی کے بغیر؟</td>\n</tr>\n<tr>\n<td>لیکویڈیٹی</td>\n<td>کیا یہ ہڑتال مائع ہے؟ ایک سخت بولی پوچھنے کا پھیلاؤ، حقیقی حجم اور کھلی دلچسپی؟</td>\n</tr>\n<tr>\n<td>زیادہ سے زیادہ نقصان</td>\n<td>اگر میں مکمل طور پر غلط ہوں تو میں اس پوزیشن پر سب سے زیادہ کیا کھو سکتا ہوں، روپے میں؟</td>\n</tr>\n<tr>\n<td>الزامات کے بعد بریک ایون</td>\n<td>تمام الزامات کی گنتی کے بعد بھی میرے لیے بنیادی چیز کہاں ہونی چاہیے؟</td>\n</tr>\n<tr>\n<td>واقعہ کا خطرہ</td>\n<td>کیا نتیجہ، پالیسی میٹنگ یا بجٹ میری میعاد ختم ہونے سے پہلے باقی ہے؟ یہ IV کا کیا کرے گا؟</td>\n</tr>\n<tr>\n<td>باہر نکلنے کا منصوبہ</td>\n<td>میں کس نفع یا نقصان پر نکلتا ہوں، اور کیا تجارت بند ہو جاتی ہے چاہے کچھ بھی ہو؟</td>\n</tr>\n</tbody></table>\n<p>ہر ایک کو ایمانداری سے چلنا۔</p>\n<p><strong>سمت</strong> سب سے پہلے ہے کیونکہ اس کے بغیر کوئی چیز اہمیت نہیں رکھتی۔ آپ صرف اوپر یا نیچے کا اندازہ نہیں لگا رہے ہیں، آپ ایک اقدام اور ایک آخری تاریخ کا ارتکاب کر رہے ہیں۔ RELIANCE 1320 کال صرف آپ کو انعام دیتی ہے اگر اسٹاک 28 جولائی سے پہلے 1351 کو صاف کرتا ہے۔ تاریخ کے بغیر ایک نقطہ نظر تجارت نہیں ہے، یہ ایک خواہش ہے.</p>\n<p><strong>ہڑتال</strong> سمت سے پیروی کرتا ہے. پیسے سے باہر کی ہڑتال سستی ہے کیونکہ یہ زیادہ تر امید ہے، اور اس طرح کے زیادہ تر اختیارات کی میعاد ختم ہوجاتی ہے۔ قریب کی ہڑتال کی قیمت زیادہ ہوتی ہے لیکن اس کا حقیقی موقع ہوتا ہے۔ اس سٹرائیک کا انتخاب کریں جو آپ کے نقطہ نظر سے مماثل ہو، نہ کہ وہ جو سب سے سستا نظر آئے۔</p>\n<p><strong>ختم</strong> وہ گھڑی ہے جو آپ کرائے پر لے رہے ہیں۔ قریبی ایکسپائری سستی ہے لیکن تیزی سے زوال پذیر ہوتی ہے اور فوری اقدام کا مطالبہ کرتی ہے۔ مزید میعاد ختم ہونے پر زیادہ لاگت آتی ہے لیکن منتقل ہونے کا کمرہ ملتا ہے۔ گھڑی کو اپنے نقطہ نظر کے ساتھ جوڑیں، اور ایکسپائری کو کبھی بھی کسی معروف واقعہ کو خاموشی سے گھیرنے نہ دیں جب تک کہ وہ واقعہ پوری شرط نہ ہو۔</p>\n<p><strong>لیکویڈیٹی</strong> چیک beginners کو چھوڑ دیں اور پھر افسوس ہے. غیر قانونی ہڑتال پر بولی مانگنے کا پھیلاؤ وسیع ہوتا ہے، اس لیے آپ زیادہ خریدتے ہیں اور کم فروخت کرتے ہیں، اور یہ فرق ایک حقیقی قیمت ہے جو آپ کے داخل ہونے پر ادا کی جاتی ہے۔ آپ کو حقیقی حجم اور کھلی دلچسپی کی بھی ضرورت ہے تاکہ آپ جب چاہیں باہر نکل سکیں، نہ صرف اس صورت میں جب مارکیٹ آپ کو اجازت دے۔</p>\n<p><strong>زیادہ سے زیادہ نقصان</strong> ایک نمبر ہونا چاہیے، احساس نہیں۔ خریدے گئے آپشن کے لیے یہ مکمل پریمیم ہے، ایک RELIANCE لاٹ کے لیے تقریباً 15,590 روپے، جس کا ہر پیسہ صفر تک جا سکتا ہے۔ اسپریڈ کے لیے یہ کیپڈ فگر ہے جو آپ نے داخل ہونے سے پہلے کام کیا تھا۔ اگر آپ روپے کی رقم بلند آواز میں نہیں کہہ سکتے ہیں، تو آپ آرڈر دینے کے لیے تیار نہیں ہیں۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>اگر آپ داخل ہونے سے پہلے روپے میں اپنے زیادہ سے زیادہ نقصان کو نہیں جانتے ہیں، تو آپ کے پاس کوئی تجارت نہیں ہے، آپ کے پاس جوا ہے۔ ایک لمبا آپشن مکمل طور پر بیکار ختم ہو سکتا ہے، اس لیے ہر پوزیشن کو اس کے مطابق سائز کریں جو آپ کھونے کے متحمل ہو سکتے ہیں، کبھی بھی اس کے مطابق نہیں جس کی آپ امید کرتے ہیں۔</p>\n</div></div>\n<p><strong>الزامات کے بعد بریک ایون</strong> breakeven کا ایماندار ورژن ہے۔ 1320 کال پر بریک بریک ایون 1351 ہے، اسٹرائیک کے علاوہ پریمیم فی شیئر۔ لیکن بروکریج، STT، ایکسچینج ٹرانزیکشن چارجز، 18 فیصد GST اور اسٹامپ ڈیوٹی سبھی آپ کے حقیقی بریک ایون کو تھوڑا دور دھکیل دیتے ہیں۔ ایک چھوٹی سی تجارت جو صرف پریمیم پر منافع بخش نظر آتی ہے چارجز کے بعد نقصان میں بدل سکتی ہے، اور STT جس آپشن کو آپ استعمال کرنے دیتے ہیں وہ ایک خاص ٹریپ ہے۔ جشن منانے سے پہلے چارجز گن لیں۔</p>\n<p><strong>واقعہ کا خطرہ</strong> سمت سے زیادہ وقت کے بارے میں ہے۔ معلوم واقعہ سے پہلے، مضمر اتار چڑھاؤ پھیلتا ہے اور اختیارات مہنگے ہو جاتے ہیں۔ اس کے بعد، غیر یقینی صورتحال ختم ہو جاتی ہے اور IV کو کچلتا ہے، پریمیم کو گرا دیتا ہے چاہے آپ نے سمت کا صحیح اندازہ لگایا ہو۔ جانیں کہ آپ کی میعاد ختم ہونے سے پہلے کیا واجب الادا ہے، اور دوسری طرف کے انتظار کو سمجھے بغیر کبھی بھی کسی ایونٹ میں مہنگا پریمیم نہ خریدیں۔</p>\n<p><strong>باہر نکلنے کا منصوبہ</strong> وہ چیک ہے جو لوپ کو بند کرتا ہے۔ داخل ہونے سے پہلے فیصلہ کریں کہ آپ کہاں منافع لیتے ہیں اور کہاں نقصان کم کرتے ہیں۔ قیمت یا روپیہ کا اعداد و شمار لکھیں جس سے تجارت ختم ہو۔ بدترین خروج وہ ہیں جو اس وقت ایجاد ہوئے ہیں، خاص طور پر ایکسپائری ڈے پر انتقامی تجارت۔ ایک متعین خطرے کا ڈھانچہ یہاں مدد کرتا ہے، کیونکہ باہر نکلنے کا کچھ حصہ پہلے ہی اندر بنا ہوا ہے۔</p>\n\n<div class=\"callout example\"><span class=\"callout-tag\">حقیقی مثال</span><div><p>ایک ہی سانس میں ایک مکمل ابتدائی منصوبہ۔ میرے خیال میں اگلے تین ہفتوں میں RELIANCE بڑھ جائے گا، اس لیے میں ایک 1320 کال تقریباً 15,590 روپے میں خریدتا ہوں، میرا زیادہ سے زیادہ نقصان یہ ہے کہ 15,590 روپے، چارجز کے بعد میرا بریک ایون 1351 سے تھوڑا اوپر ہے، 28 جولائی سے پہلے کوئی نتیجہ باقی نہیں ہے، اور اگر پریمیم پہلے دوگنا ہو جائے یا آدھا ہو جائے تو میں باہر نکل جاتا ہوں۔ آرڈر کے اندر جانے سے پہلے ہر باکس پر ٹک کیا جاتا ہے۔</p>\n</div></div>\n<h2 id=\"where-you-started-and-where-you-are-now\">آپ نے کہاں سے آغاز کیا، اور اب آپ کہاں ہیں۔</h2>\n<p>اس فاصلے کو دیکھیں جو آپ نے طے کیا ہے۔ آپ کو معلوم نہیں تھا کہ آپشن کیا ہے۔ آپ نے سیکھا کہ کال خریدنے کا حق ہے اور ایک پوٹ بیچنے کا حق ہے، یہ کہ ایک پریمیم اندرونی قدر اور وقت کی قدر میں تقسیم ہوتا ہے، وہ وقت کا زوال خریداروں کو گرا دیتا ہے جب کہ یہ بیچنے والوں کو خاموشی سے کھانا کھلاتا ہے، اور یہ کہ چار یونانی بیان کرتے ہیں کہ ایک پریمیم واقعی کس طرح حرکت کرتا ہے۔ آپ نے ادائیگی کا خاکہ پڑھا اور سمجھ لیا کہ ایٹ-ایکسپائری لائن اور آج کا وکر کیوں متفق نہیں ہیں۔ آپ نے دیکھا کہ زیادہ تر خریدار کیوں ہار جاتے ہیں، بیچنے والے بڑے مارجن کیوں پوسٹ کرتے ہیں، اور کیسے چارجز، لیکویڈیٹی اور واقعات خاموشی سے نتائج کا فیصلہ کرتے ہیں۔ اور اب آپ دیکھ سکتے ہیں کہ دو ٹانگیں ایک کو کیوں ہرا سکتی ہیں۔</p>\n<p>یہ ایک حقیقی تعلیم ہے، ٹپ شیٹ نہیں۔ یہ ہر تجارت کو فاتح نہیں بنائے گا، کیونکہ کچھ نہیں ہوتا۔ یہ آپ کو جو کچھ دیتا ہے وہ ہے اپنے خطرے کو سائز دینے کی صلاحیت، جو آپ اصل میں خرید رہے ہیں اسے پڑھیں، اور خراب تجارت کو تباہی بننے سے پہلے اس سے دور چلے جائیں۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>بازار صبر کا بدلہ دیتا ہے اور جلد بازی کو سزا دیتا ہے۔ چھوٹی تجارت کریں، داخل ہونے سے پہلے اپنے زیادہ سے زیادہ نقصان کو جان لیں، ہر بار چیک لسٹ چلائیں، اور نظم و ضبط کو رہنے دیں، حوصلہ نہیں، فیصلہ کریں۔ اگلا کورس انتظار کر رہا ہے، اور آپ اس کے لیے تیار ہیں۔</p>\n</div></div>\n<p>آپ کے پاس اب بنیاد ہے۔ اس پر احتیاط سے تعمیر کریں، پہلے اپنے سرمائے کی حفاظت کریں، اور اسکل کمپاؤنڈ کو تجارت کے ذریعے تجارت کرنے دیں۔ آپ کے اختیارات کے سفر کے حقیقی آغاز میں خوش آمدید۔</p>\n","toc":[{"level":2,"text":"ایک ٹانگ سے دو تک: پھیلاؤ کیوں موجود ہے۔","id":"from-one-leg-to-two-why-spreads-exist"},{"level":2,"text":"ڈیبٹ اسپریڈز اور کریڈٹ اسپریڈز","id":"debit-spreads-and-credit-spreads"},{"level":2,"text":"پری ٹریڈ چیک لسٹ","id":"the-pre-trade-checklist"},{"level":2,"text":"آپ نے کہاں سے آغاز کیا، اور اب آپ کہاں ہیں۔","id":"where-you-started-and-where-you-are-now"}],"imgCount":1,"hasContent":true}}
